MultiLanguageItemData['de'][133948] = {name = "[q6]Fäuste der Himmel", additional_info = "Alra'ed\nWird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Faustwaffe}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Mönch\n[q]\"Es gab einen großen Lichtblitz und einen Windstoß, und dann war es schon getan - Irmaat konnte seine Waffen spüren. Al'burq und Alra'ed bebten mit der Macht der Elemente.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133955] = {name = "BC Crystal", additional_info = "Questgegenstand"}
MultiLanguageItemData['de'][133956] = {name = "Instabiler Zauberfokus", additional_info = "Questgegenstand\n[q]\"Summt vor Energie.\""}
MultiLanguageItemData['de'][133957] = {name = "Zauberfokusfragment", additional_info = "Questgegenstand\nEinzigartig (10)\n[q2]Benutzen: Fügt 10 Zauberfokusfragmente zu einem instabilen Zauberfokus zusammen."}
MultiLanguageItemData['de'][133958] = {name = "[q6]Geheimnisse der Leere", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Tempowertung um + 1.\nKlassen: Priester\n[q]\"Als ich die Klinge berührte, erklang ein Name in meinem Verstand: Xal'atath. Ich wusste, dass ich den Dolch nicht vernichten konnte. Noch nicht. Wie kann man eine Macht bezwingen, die man nicht versteht?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133959] = {name = "[q6]Herz des Phönix", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Tempowertung um + 1.\nKlassen: Magier\n[q]\"Als das Kämpfen ein Ende gefunden hatte, war Dath'Remar mit Dämonenblut bedeckt. Mit Einbruch der Nacht wurde uns klar, dass noch mehr Schlachten bevorstünden. Und dennoch, dieser Elf mit seiner Klinge gab uns Hoffnung, dass der Sieg in Reichweite lag.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133960] = {name = "Hackschwanzaugapfel", additional_info = "Questgegenstand\n[q]\"In diesen Augäpfeln befindet sich eine erstaunliche Menge Flüssigkeit.\""}
