MultiLanguageItemData['de'][133968] = {name = "Siegel der Mondwache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Träger dieses gravierten Talismans haben sich als außergewöhnlich fähige Zauberer erwiesen.\""}
MultiLanguageItemData['de'][133970] = {name = "[q5]Reise der Zann'esu", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Magier\n[q2]Anlegen: 'Hagel' erhöht den Schaden Eures nächsten Einsatzes von 'Blizzard' um 35%. Bis zu 5-mal stapelbar.\n[q]\"Die Magier vom Klan der Zann'esu verließen ihr Heimatdorf Brunnhildar auf der Suche nach der perfekten Magie, um den Lichkönig zu besiegen. Sie kehrten nie zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133971] = {name = "[q5]Zenk'aram, Iridis Anadem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Priester\n[q2]Anlegen: In Leerengestalt verursacht Ihr 3% mehr Zauberschaden und die Heilung von 'Vampirumarmung' wird um 250% erhöht.\n[q]\"Dieses aus feinstem Teufelsstoff hergestellte Anadem gab Iridi die notwendige Kraft, um Dargonax zu besiegen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133972] = {name = "Basiliskenfleisch", additional_info = "Questgegenstand\n[q]\"Das rohe Echsenfleisch ist zäh und giftig und muss vor dem Verzehr gekocht werden.\""}
MultiLanguageItemData['de'][133973] = {name = "[q5]Die schmerzhafte Berührung der Zwillinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Tempowertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Priester\n[q2]Anlegen: Bei Eurem ersten Einsatz von [ Gedankenstachel : 'Gedankenstachel' / 'Gedankenschinden'] in Leerengestalt springt 'Schattenwort: Schmerz' und 'Vampirberührung' auf 3 Gegner innerhalb von 10 Metern von Eurem Ziel über.\n[q]\"Schluss mit diesen Kugeln, Fjola. Erledigen wir diese Herausforderer endlich. - Eydis Nachtbann\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133974] = {name = "[q5]Lana'thels Wehklagen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 9.\n[q2]+ 5 Vielseitigkeit\n\n[q0]Prismatischer Sockel\n\nKlassen: Todesritter\n[q2]Anlegen: Während Ihr Euch im Effektbereich Eurer Fähigkeit 'Tod und Verfall' befindet, ist Euer verursachter Schaden um 5% sowie Eure erhaltene Heilung um 5% erhöht.\n[q]\"Lana'thel weinte bitterlich um die Leben ihrer elfischen Brüder und Schwestern, die sie auf ihrem Kriegszug nach Nordend zu verlieren erwartete. Dass sie selbst zahlreiche weitere Opfer fordern würde, wusste sie damals noch nicht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133975] = {name = "Gnopettos Tagebuch", additional_info = "Questgegenstand\n[q]\"Der Großteil der Seiten ist verschmiert, aber manche Abschnitte sind dennoch gerade so lesbar.\""}
MultiLanguageItemData['de'][133976] = {name = "[q5]Cinidaria der Symbiont", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schurke , Mönch , Druide , Dämonenjäger\n[q2]Anlegen: Eure Angriffe fügen Gegnern mit mehr als 90% Gesundheit 30% zusätzlichen Schaden zu und heilen Euch um 100% des verursachten Schadens.\n[q]\"Dieser dämonische Symbiont hat sich angepasst, um Kraft aus der Hitze des Gefechts zu schöpfen. Manchmal imitiert er sogar die Handlungen seines Wirtes.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133977] = {name = "[q5]Belo'virs letztes Gefecht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Stoff}\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 200 / 200\nKlassen: Magier\n[q2]Anlegen: Nach dem Einsatz von [ Flimmern : 'Flimmern' / 'Blinzeln'] erhaltet Ihr 15 Sek. lang einen Absorptionsschild in Höhe von 20% Eurer maximalen Gesundheit.\n[q]\"Die letzte Tat von Belo'vir Salonar, Großmagister von Quel'Thalas während des Dritten Krieges, bestand darin, Lady Liadrin an einen sicheren Ort zu teleportieren, als die Stadt fiel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][133978] = {name = "Teile eines stationären Kugelspenders", additional_info = "Questgegenstand\nEinzigartig (15)\n[q]\"Sie sind von Ranken ganz umschlungen und von den Dornen zerkratzt.\""}
