MultiLanguageItemData['de'][133984] = {name = "Nachtgeborenenverkleidung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Hüllt Euch in betörende Magie, um Euch die Erscheinung eines Nachtgeborenen zu geben.\n\n Funktioniert nur im Stadtbereich von Suramar.\n[q]\"Ein Stapel Kleidung und anderer Dinge, die Euch helfen werden, Euch Eurer Umgebung anzupassen.\""}
MultiLanguageItemData['de'][133985] = {name = "Hochprozentiger Drog", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Desorientiert alle im ausgewählten Gebiet für 5 Sek.\n Kann nur am Hochberg genutzt werden. (1 Min Abklingzeit)\n[q]\"Warnung: Kann Blindheit verursachen.\"\nVerkaufspreis:"}
