MultiLanguageItemData['de'][136820] = {name = "Nythendras Herz", additional_info = "Questgegenstand\n[q]\"Das verderbte Herz des grünen Drachen Nythendra. Während die Verderbnis ihr äußeres Feuer erlöschen ließ, brennt ihr inneres Feuer noch immer so heiß wie die Sonne.\""}
MultiLanguageItemData['de'][136821] = {name = "Leypigmente", additional_info = "Questgegenstand\n[q]\"Ein glitzerndes, violettes Pigment, das für Tätowierungen verwendet werden kann.\""}
