MultiLanguageItemData['de'][136825] = {name = "Glyphe 'Wildes Chamäleon'", additional_info = "Klassen: Druide\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Katzengestalt annehmt, wird Eure verwandelte Gestalt zufällig ausgewählt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][136826] = {name = "Glyphe 'Herbstliches Wachstum'", additional_info = "Klassen: Druide\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt Euer 'Blühendes Leben' zu einer üppigen Herbstblume aufblühen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][136827] = {name = "Yseras Traumtrank", additional_info = "Questgegenstand\n[q]\"Ein altes Nachtelfengebräu, von dem man sagt, dass es die Augen für eine unsichtbare Welt öffnet.\""}
MultiLanguageItemData['de'][136831] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Paladin\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][136832] = {name = "Unlesbare Schriften", additional_info = "Questgegenstand\n[q]\"Der auf diese Schriftrollen gekritzelte Text ist ohne Hilfe nicht zu entziffern.\""}
MultiLanguageItemData['de'][136833] = {name = "Seherkugel des Orakels", additional_info = "Questgegenstand\n[q]\"Das scheint die Kugel zu sein, die es dem Orakel gestattet, die Schriften der verlorenen Priesterinnen zu entziffern.\""}
MultiLanguageItemData['de'][136834] = {name = "Mächtiger Seelensplitter", additional_info = "Questgegenstand\n[q]\"Er spiegelt nicht das Gesicht des Betrachters wider, sondern das Gesicht der im Inneren gefangenen Seele.\""}
