MultiLanguageItemData['de'][136836] = {name = "Fläschchen der Nachtgeborenen", additional_info = "Questgegenstand\n[q2]Benutzen: Mischt 5 Traumlaub und Blätter der Träumerträne, um Yseras Traumtrank herzustellen."}
