MultiLanguageItemData['de'][137014] = {name = "[q5]Achor, der ewige Hunger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Leder}\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 200 / 200\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Rachsüchtiger Rückzug' heilt Euch um 25% Eurer maximalen Gesundheit und gewährt Euch 8 Sek. lang 20% Lebensraub.\n[q]\"Dämonenjäger stehen - was die Kampfeslust angeht - den Legionen ihres meistgehassten Feindes in nichts nach.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137015] = {name = "[q5]Ekogespenst, Erschaffer von Welten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Leder}\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 200 / 200\nKlassen: Druide\n[q2]Anlegen: Erhöht die Effekte von 'Dickes Fell', 'Astraler Einfluss', 'Schnelligkeit der Wildnis' und 'Yseras Gabe' um 75%.\n[q]\"Wir konnten nicht nur das Gefühl eines eigenen Ortes, sondern tatsächlich einen solchen Ort selbst für uns erzeugen. Und alles, was jemals existiert hat, schwimmt auf der Oberfläche unseres Traums. Nun hört, was ich höre.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137016] = {name = "[q5]Sal'salabims verlorene Tunika", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Leder}\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Mönch\n[q2]Anlegen: Wenn Ihr 'Fasshieb' einsetzt, wird die verbleibende Abklingzeit von 'Feuerodem' abgeschlossen.\n[q]\"Sal'salabim könnte das verloren haben, als er für sechs Stunden besinnungslos war...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137017] = {name = "[q5]Brustplatte der goldenen Val'kyr", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Platte}\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]+ 4 Vielseitigkeit\nHaltbarkeit 200 / 200\nKlassen: Paladin\n[q2]Anlegen: Durch jeden mit 'Schild des Rächers' getroffenen Gegner wird die verbleibende Abklingzeit von 'Wächter der Uralten Könige' um 3 Sek. verringert.\n[q]\"Das Überbleibsel einer großen Kommandantin, die gleißend wie die Sonne aus dem Himmel auf ihre Feinde herabstieß.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137018] = {name = "[q5]Schicksalgeber", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Platte}\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Krieger\n[q2]Anlegen: Abgefangene Angriffe gewähren Euch und dem Ziel Eurer Fähigkeit 'Abfangen' einen Absorptionsschild, der 10 Sek. lang Schaden in Höhe von 50% des vom Angreifer verursachten Schadens absorbiert.\n[q]\"Unterwerft die Zeit selbst Eurem Willen, um die Welt vor der Zerstörung zu schützen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137019] = {name = "[q5]Cenedril, Spiegel des Hasses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nKlassen: Mönch\n[q2]Anlegen: 'Karmaberührung' verursacht 150% mehr Schaden.\n[q]\"Kennt Ihr den Feind und auch Euch selbst, gibt es keinen Grund, je wieder eine Schlacht zu fürchten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137020] = {name = "[q5]Flüstern der Nathrezim", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 2.\nKlassen: Paladin\n[q2]Anlegen: 'Urteil des Templers' und 'Göttlicher Sturm' erhöhen den Schaden Eures nächsten Einsatzes von 'Urteil des Templers' oder 'Göttlicher Sturm' innerhalb von 4 Sek. um 15%.\n[q]\"Erbärmlich... Mehr habt Ihr nicht zu bieten?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137021] = {name = "[q5]Die List des Schreckenslords", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nKlassen: Schurke\n[q2]Anlegen: Meucheln, Gesetzlosigkeit\n Erhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Dolchfächer' um 35%. Bis zu 30-mal stapelbar.\n\nTäuschung\n Erhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Shurikensturm' um 25%. Bis zu 30-mal stapelbar.\n[q]\"Ich habe Euch erwartet, junger Prinz. Ich bin Mal'Ganis. Wie Ihr sehen könnt, gehört Euer Volk jetzt mir.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137022] = {name = "[q5]Das Opfer von Loramus Thalipedes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Teufelsrausch' verursacht pro getroffenem Ziel 10% mehr Schaden.\n[q]\"Nur diese Stiefel blieben übrig, als Rakh'likh durch das Steinmesser des Versiegelns im Körper von Loramus dem Entweihten eingekerkert wurde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137023] = {name = "[q5]Versprechen Elunes, der Mondgöttin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Druide\n[q2]Anlegen: 'Lunarschlag' und 'Solarzorn' verursachen 8% mehr Schaden und gewähren den Effekt 'Macht Elunes', der die Heilung Eures nächsten Einsatzes von 'Nachwachsen' um 30% erhöht und seine Zauberzeit um 5% verringert. Bis zu 20-mal stapelbar.\n[q]\"Wenn andere Leben und Energie von Euch erhalten, schenke ich Euch dafür einen Teil meines Lebens und meiner Energie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137024] = {name = "[q5]Feline Schleicher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Druide\n[q2]Anlegen: Gewährt alle 15 Sek. eine Aufladung von 'Schnelligkeit des Raubtiers'. Außerdem ist die Fähigkeit jetzt bis zu 3-mal stapelbar.\n[q]\"Es heißt, der Wahnsinn von Marl Wurmdorn hätte diese Stiefel mit Macht erfüllt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137025] = {name = "[q5]Skysecs Trutz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Druide\n[q2]Anlegen: 'Rasende Regeneration' heilt Euch im Verlauf von 3 Sek. um zusätzliche 12% Eurer maximalen Gesundheit.\n[q]\"Während der Schlacht um den Hyjal widerstand Skysec, der Wächter von Nordrassil, endlosen Wellen der Geißel und der Legion. Am Ende gab er voller Stolz sein Leben für die Verteidigung des uralten Weltenbaums.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137026] = {name = "[q5]Essenz der Infusion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Druide\n[q2]Anlegen: 'Gelassenheit' verursacht bei Zielen, deren Gesundheit unter 60% liegt, um 60% erhöhte Heilung.\n[q]\"Fühlt, wie die Natur durch Eure Adern fließt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137027] = {name = "[q5]Feuersteinläufer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Mönch\n[q2]Anlegen: Jeder von Eurem 'Feuerodem' getroffene Gegner verringert die Abklingzeit von 'Stärkendes Gebräu' um 2 Sek., bis zu einem Maximum von 6 Sek.\n[q]\"Bruder Adam und Bruder David waren brillante Mathematiker und Mönche. Ständig plapperten sie von Abaki und Parabeln. - Braumeisterin Brynild\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137028] = {name = "[q5]Ei'thas, Mondgleiter von Eramas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Mönch\n[q2]Anlegen: Erhöht die von 'Beleben' hervorgerufene Heilung um 10%.\n[q2]Anlegen: 'Erhebende Trance' erhöht die Heilung Eurer Fähigkeit 'Beleben' zusätzlich um 10% und lässt sie 1 zusätzliches Ziel heilen.\n[q]\"Eramas Leuchtfeuer hat immer wieder erwähnt, wie bequem diese Prachtstücke sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137029] = {name = "[q5]Katsuos Finsternis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Mönch\n[q2]Anlegen: Verringert die Kosten von 'Furorfäuste' um 1 Chi.\n[q]\"So sprach Kaulder zu seinem Bruder Katsuo: Mit der Zeit und durch langes Üben verbessern sich Eure Reflexe und Eure Fäuste schlagen härter zu, als Eure Gegner aushalten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137030] = {name = "[q5]Fußpolster des Dämmergängers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schurke\n[q2]Anlegen: Die verbleibende Abklingzeit von 'Vendetta' wird pro 65 verbrauchter Energie um 1 Sek. verringert.\n[q]\"Wenn Euch eine SI:7-Agentin wie Caelvana ins Visier nimmt, solltet Ihr besser laufen. Schnell, sofort und so weit die Füße tragen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137031] = {name = "[q5]Thraxis trickreiche Treter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schurke\n[q2]Anlegen: 'Tötung' verursacht zusätzlichen Schaden in Höhe von 20% Eurer erhöhten Bewegungsgeschwindigkeit.\n[q]\"Thraxi verkleidete sich oft als Braumeistermönch, um ihre Feinde zu täuschen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137032] = {name = "[q5]Gang der Schattensatyrn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schurke\n[q2]Anlegen: 'Schattenschlag' regeneriert 3 Energie und zusätzlich 1 Energie pro 3 Meter zwischen Euch und Eurem Ziel.\n[q]\"Obwohl über die Entstehung der Schattensatyrn nichts Genaues bekannt ist, steht eine Tatsache fest: Es sind körperlose Kreaturen, die man nicht nur im Smaragdgrünen Alptraum antrifft, sondern auch auf Azeroth.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137033] = {name = "[q5]Ullrs Federschneeschuhe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Jäger\n[q2]Anlegen: Jeder Schaden verursachende Schuss verringert die verbleibende Abklingzeit von 'Volltreffer' um 0.8 Sek.\n[q]\"Sie verliehen der Jägerin ein Gefühl der Schwerelosigkeit - eine Ruhe und Gleichmut inmitten des Sturms.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137034] = {name = "[q5]Nesingwarys Fallentreter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Jäger\n[q2]Anlegen: Wenn eine Eurer Fallen ausgelöst wird, werden 25 Fokus erzeugt.\n[q]\"Etwas ziemlich Großes mit ebenso großen Zähnen wollte sich einen Happen von diesen Stiefeln abbeißen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137035] = {name = "[q5]Der Blutpakt des Betrügers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schamane\n[q2]Anlegen: Es besteht eine Chance von 20%, dass 'Erdschock' den gesamten aufgezehrten Mahlstrom zurückerstattet. (Procchance: 20%)\n[q]\"Ner'zhul, Schamanenältester vom Schattenmondklan, wollte sein Volk retten und sich endlich die Macht und den Respekt sichern, nach denen er sich immer gesehnt hatte. Doch er wurde betrogen...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137036] = {name = "[q5]Elementare Ausgleicher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Schamane\n[q2]Anlegen: Verbündete, die sich innerhalb des Effektbereichs Eures Zaubers 'Heilender Regen' aufhalten, erhalten 10% mehr Heilung durch Eure anderen Heilzauber.\n[q]\"Ursprünglich wurden diese Prachtstücke von einer mächtigen Verdammniswache eingesetzt, um Feinde mit einem feurigen Regen zu vernichten. Später hat man sie als Ausgleich für die zuvor angerichtete Zerstörung einem edleren Zweck zugeführt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137037] = {name = "[q5]Uvanimor, die Unschönheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Todesritter\n[q2]Anlegen: Nahkampfangriffe [ Schlickspucker : Eurer Monstrosität / Eures Ghuls] haben eine Chance von 10%, eine Eurer Runen zu aktivieren.\n[q]\"Die verderbende Macht des Nachtbrunnens fließt durch diesen Ring, sodass sein Träger die Mächte aller anzapfen kann, die unter seinem Befehl stehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137038] = {name = "[q5]Zorn der Halbriesen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Tempowertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Dämonenjäger\n[q2]Anlegen: [ Dämonenklingen : 'Dämonenklingen' / 'Dämonenbiss'] erzeugt zusätzliche 1-14 Jähzorn.\n[q]\"Diese überdimensionierten Vrykul sind sicherlich nicht die ersten Bewohner von Nordend, denen man über den Weg laufen will. Versucht es lieber mit den Untoten der boreanischen Tundra.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137039] = {name = "[q5]Makellose Teufelsessenz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Druide\n[q2]Anlegen: Die verbleibende Abklingzeit von [ Inkarnation: Erwählter der Elune : 'Inkarnation: Erwählter der Elune' / 'Himmlische Ausrichtung'] wird pro 12 verbrauchter Astraler Macht um 1 Sek. verringert.\n[q]\"Die Druiden des Smaragdkreises manipulierten die Teufelsenergie in diesem Stein, um ihren Einklang mit der Wildnis zu steigern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137040] = {name = "[q5]Schillerndes Signet", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Tempowertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Druide\n[q2]Anlegen: Erhöht in Katzengestalt Eure Energieregeneration um 5% und Eure maximale Energie um 100.\n[q]\"Das innere Feuer Leyaras hat dieses Signet verzaubert. Ihr spürt, dass sie endlich Frieden gefunden hat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137041] = {name = "[q5]Doppelte Entschlossenheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Druide\n[q2]Anlegen: 'Überlebensinstinkte' erhält 1 zusätzliche Aufladung und wird 15% schneller wieder aufgeladen.\n[q]\"Druiden der Klaue können sich verwandeln, um somit schneller oder zäher zu werden. Für gewöhnlich entscheiden sie sich für die zweite Variante.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137042] = {name = "[q5]Tränenstein der Elune", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Druide\n[q2]Anlegen: Durch Euren Zauber 'Wildwuchs' geheilte Verbündete erhalten eine Chance von 15%, um auch den Effekt 'Verjüngung' zu erhalten. (Procchance: 15%)\n[q]\"Der sich um Elune, eine der wenigen wahren Gottheiten von Azeroth, rankende Mythos legt nahe, dass ihre wahre Identität noch immer nicht gänzlich erfasst wurde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137043] = {name = "[q5]Frizzos Fingerfalle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Jäger\n[q2]Anlegen: Erhöht den Schaden von [ Schlachten : 'Schlachten' / 'Zerlegen'] um 10%.\n[q2]Anlegen: Wenn Ihr 'Zerlegen' gegen einen Gegner einsetzt, der von 'Aufschlitzen' betroffen ist, springt 'Aufschlitzen' auf 1 anderes Ziel über, das von 'Zerlegen' getroffen wurden.\n[q]\"Mit etwas Butter geht die auch problemlos wieder ab.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137044] = {name = "[q5]Juwel der Verlorenen Abtei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Mönch\n[q2]Anlegen: Erhöht die Dauer der Staffelung um 3.0 Sek.\n[q]\"Dieses Kleinod war ursprünglich ein Geschenk des Magiers Veri'thas, wurde aber angeblich nach einem Konflikt zwischen den Mönchen und den Elfen aus der Verlorenen Abtei gestohlen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137045] = {name = "[q5]Auge von Collidus dem Sphärenwächter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Mönch\n[q2]Anlegen: Jedes Mal, wenn 'Beruhigender Nebel' heilt, wird die Absorptionsmenge Eures nächsten Einsatzes von 'Lebenskokon' um 3% erhöht. Bis zu 50-mal stapelbar.\n[q]\"Zumindest eines seiner Augen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137046] = {name = "[q5]Ilterendi, Kronjuwel von Silbermond", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Paladin\n[q2]Anlegen: 'Richturteil' erhöht Eure Heilung 5 Sek. lang um 15%.\n[q]\"Silbermond wurde aus weißem Stein erbaut und mit karminroten Wandbehängen geschmückt. Aber die Stadt war nicht nur für ihre Schönheit bekannt, sondern auch als Zentrum magischer Ausbildung. Viele meisterliche Manipulatoren des Mana haben dort ihren Sitz.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137047] = {name = "[q5]Heathcliffs Unsterblichkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Paladin\n[q2]Anlegen: Während Ihr Euch im Effektbereich Eurer 'Weihe' aufhaltet, erleidet Ihr 4% weniger Schaden.\n[q]\"Heathcliff, auch bekannt als Unsterbliches Objekt, war angeblich gegen jegliche schweren Wunden immun. Manche fragten sich, ob die Standhaftigkeit des Blutritters nicht sogar den Naturgesetzen der Welt selbst trotzte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137048] = {name = "[q5]Liadrins entfesselter Zorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Tempowertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Paladin\n[q2]Anlegen: Während 'Zornige Vergeltung' aktiv ist, erhaltet Ihr alle 6 Sek. 1 Heilige Kraft.\n[q]\"Wir wurden von dem Mann verraten, den wir unseren Prinzen nannten. Ich verpflichte die Klingen meiner Blutritter der Bezwingung Kil'jaedens und der Wiederherstellung Silbermonds. Wir werden an Eurer Seite kämpfen, A'dal.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137049] = {name = "[q5]Insigne von Rabenholdt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Tempowertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Schurke\n[q2]Anlegen: Eure Combopunkte erzeugenden Einzelzielangriffe fügen Zielen innerhalb von 15 Metern vor Euch 15% zusätzlichen Schaden als Schattenschaden zu.\n[q]\"Dieses Insigne wird nur an jene verliehen, die sich als Meister über die Schatten erwiesen und im Dienste Rabenholdts getötet haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137050] = {name = "[q5]Auge des Wirbelnden Nethers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Schamane\n[q2]Anlegen: Wenn Ihr Gegnern mit Euren Feuer-, Frost- oder Naturzaubern Schaden zufügt, wird Euer verursachter Schaden 8 Sek. lang um 1.5% erhöht. Jedes weitere Element gewährt eine eigene Anwendung.\n[q]\"Nirgends ist die Macht der Elemente stärker als im Nether - obwohl sie dort verzerrt und nur schwer als solche erkennbar sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137051] = {name = "[q5]Fokussierer von Jonat dem Ältesten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Tempowertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Schamane\n[q2]Anlegen: 'Welle der Heilung' und 'Heilende Woge' erhöht die Heilung Eures nächsten Einsatzes von 'Kettenheilung' um 10%. Dieser Effekt ist bis zu 5-mal stapelbar.\n[q]\"Unter der Ausbildung von Jonat Han meisterten neue Schamanen des Drachenschinderklans die Künste des Wassers - um den einen sowie auch die vielen zu heilen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137052] = {name = "[q5]Ayalas steinernes Herz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Krieger\n[q2]Anlegen: Eure Angriffe haben eine Chance, dass Euer nächster Einsatz von 'Hinrichten' keine Wut kostet und gegen jedes Ziel, ungeachtet seiner prozentualen Gesundheit, eingesetzt werden kann.\n[q]\"In Valhalas streckte der Grubenkämpfer Ayala der Unerbittliche Feind um Feind nieder auf seinem Weg zum Legendentum. Je schwächer seine Gegner wurden, desto letaler wurde seine Präzision. Selbst wenn die Feinde ihn schon besiegt wähnten, hatte er immer ein Ass im Ärmel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137053] = {name = "[q5]Kazzalax, Fujiedas Zorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Stärke\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nKlassen: Krieger\n[q2]Anlegen: 'Blutdurst' erhöht Euren verursachten Schaden und Eure erhaltene Heilung 10 Sek. lang um 1%. Bis zu 4-mal stapelbar.\n[q]\"Die Jinyu erzählen von dem großen Krieger Fujieda, der viele Stunden in einem flachen Tümpel auf der Lauer lag, um einen mächtigen Teufelsdämon zu erschlagen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137054] = {name = "[q5]Die Mauern fielen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Tempowertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Krieger\n[q2]Anlegen: 'Schildschlag' erzeugt 2 zusätzliche Wut und verringert die verbleibende Abklingzeit von 'Schildwall' um 4 Sek.\n[q]\"Als inmitten des Dritten Krieges die Mauern der Verteidiger von Kalimdor zu Fall gebracht wurden, weigerte sich Shaka, das Urtum des Krieges, es ihnen gleichzutun.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137055] = {name = "[q5]Zevrims Hunger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Jäger\n[q2]Anlegen: Erhöht sämtlichen verursachten Schaden um 3%.\n[q2]Anlegen: 'Im Visier' hat eine Chance von 15%, 'Mal des Jägers' nicht zu entfernen.\n[q]\"Diese Kraft wurde aus Jägern gewonnen, die in Düsterbruch geopfert wurden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137056] = {name = "[q5]Luffawickel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\n[q2]Anlegen: Erhöht Schaden und Reichweite von 'Hauen' um 25%.\n[q]\"Es geht eben nichts über einen guten Luffaschwamm.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137057] = {name = "[q5]Verbotene Berührung des verborgenen Meisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\n[q2]Anlegen: 'Berührung des Todes' verursacht 40% mehr Schaden und kann innerhalb von 5 Sek. ein zweites Mal eingesetzt werden, bevor die Abklingzeit ausgelöst wird.\n[q]\"Uralte Erkenntnisse über die Einflussnahme auf den Fluss der Lebensenergie wurden über Jahrtausende im Geheimen von Meister zu Meister weitergegeben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137058] = {name = "[q5]Gezeitenrufer des Prätorianers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: Erhöht die Dauer Eures Totems des heilenden Flusses, Eures Totems der Heilungsflut und Eures Totems der Geistverbindung um 20%.\n[q]\"Um gemeinsam gegen Azeroths größte Feinde zu bestehen, trafen sich die größten Denker zu einem Forum, das der intellektuellen Diskussion aller Probleme und der strategischen Planung gewidmet war, während ihre Champions an der Front kämpften.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137059] = {name = "[q5]Tyrs Hand des Glaubens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Paladin\n[q2]Anlegen: Verringert die Abklingzeit von 'Handauflegung' um 70%.\n[q]\"Nachdem er durch den riesigen Protodrachen Galakrond seine Hand verloren hatte, fertigte Jotun eine neue für Tyr.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137060] = {name = "[q5]Archavons schwere Hand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Krieger\n[q2]Anlegen: Verringert die Wutkosten von 'Tödlicher Stoß' um 8.\n[q]\"Tief unten in der von Tausendwinter geschützten Kammer lauerte Archavon der Steinwächter voller Hass auf alle Eindringlinge.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137061] = {name = "[q5]Raddons Kaskadenblick", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Dämonenjäger\n[q2]Anlegen: Die verbleibende Abklingzeit von 'Augenstrahl' wird pro getroffenem Gegner um 0.3 Sek. verringert, bis maximal um 20 Sek.\n[q]\"Die Welt... zieht vorbei... und wir bestehen in Ewigkeit.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137062] = {name = "[q5]Der Smaragdgrüne Traumfänger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Druide\n[q2]Anlegen: 'Sternensog' verringert 5 Sek. lang die benötigte Astrale Macht für 'Sternensog' um 5. Bis zu 2-mal stapelbar.\n[q]\"Ysera träumt und die Welt erbebt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137063] = {name = "[q5]Der Blick für das Wesentliche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Mönch\n[q2]Anlegen: 'Zenmeditation' klingt 50% schneller ab und wird nicht mehr durch Bewegung oder erlittene Nahkampftreffer abgebrochen.\n[q]\"Lehnt Euch zurück, entspannt Euch und nehmt die Welt um Euch wahr.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137064] = {name = "[q5]Voodoomaske des Schattenjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Kette}\n9 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Jäger\n[q2]Anlegen: 'Totstellen' heilt Euch bei Aktivierung um 20% Eurer maximalen Gesundheit und danach 10 Sek. lang pro Sekunde um zusätzliche 5% Eurer maximalen Gesundheit, solange Ihr Euch weiter totstellt.\n[q]\"Wenn die mich kalt machen wollen, dann besser richtig und beim ersten Versuch. Am besten, wenn ich schlafe. - Vol'jin nach dem missglückten Mordversuch durch Garrosh.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137065] = {name = "[q5]Blick der Gerechtigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Platte}\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Paladin\n[q2]Anlegen: Wenn das Ziel mehr als 75% Gesundheit hat, verursacht 'Hammer der Gerechtigkeit' 204% Heiligschaden, erzeugt 1 Heilige Kraft und die Abklingzeit ist um 75% verringert.\n[q]\"Dieser Helm schützte einst das Haupt von Hochlord Alexandros Mograine und wäre - wären die Dinge anders verlaufen - wohl als Erbstück an seine Söhne Renault und Darion Mograine gegangen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137066] = {name = "[q5]Umhang der Teufelsflammen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]+ 2 Vielseitigkeit\nKlassen: Dämonenjäger\n[q2]Anlegen: Ihr erleidet 15% weniger Magieschaden, solange 'Feuerbrandaura' aktiv ist.\n[q]\"Obwohl er so aussieht wie all die anderen Exemplare, die man in den geschmolzenen Tiefen findet, scheint dieses Prachtstück etwas intensiver zu brennen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137067] = {name = "[q5]Elizes ewigwährende Einhüllung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Leder}\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Druide\n[q2]Anlegen: 'Hauen' kann bis zu 2 zusätzliche Male gestapelt werden.\n[q]\"Während der Zerschlagung war '100% naturbelassene Wut' eine zutreffende Beschreibung des Besitzers.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137068] = {name = "[q5]Gamaschen der Schwarzen Flamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Leder}\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Mönch\n[q2]Anlegen: 'Donnerfokustee' gewährt 1 zufällige zusätzliche Aufladung von 'Überschwang', 'Einhüllender Nebel', 'Essenzborn', 'Erneuernder Nebel' oder 'Beleben'.\n[q]\"Seien es seltene Artefakte, Gladiatorenkämpfe oder lukratives Glücksspiel, die Schwarze Flamme hat sich darauf spezialisiert, nur die besten Dienstleistungen und Unterhaltungsmöglichkeiten anzubieten, die für Geld zu haben sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137069] = {name = "[q5]Valeeras Wille", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Leder}\n7 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 145 / 145\nKlassen: Schurke\n[q2]Anlegen: 'Finte' heilt Euch im Verlauf von 5 Sek. um 20% Eurer maximalen Gesundheit.\n[q]\"In jungen Jahren überlebte Valeera den Tod ihrer Eltern, ihre Gefangennahme und die Sklaverei. All ihre Feinde unterschätzten stets ihren Überlebenswillen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137070] = {name = "[q5]Tyelca, Statur von Ferren Marcus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Platte}\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Paladin\n[q2]Anlegen: 'Schild des Rächers' verursacht 20% mehr Schaden und springt auf 2 zusätzliche Ziele über.\n[q]\"Macht erwächst aus Stärke und wahre Stärke erwächst aus kräftigen Beinen, die Euch wie Wurzeln auf dem Boden verankern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137071] = {name = "[q5]Schulterstücke des Runenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Leder}\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Metamorphose' schließt die Abklingzeit von all Euren Zeichen ab. Gewährt Euch außerdem eine Aufladung von 'Dämonenstachel'.\n[q]\"Molgeim von der Versammlung des Eisens verstand es, Runen für ein gewaltiges Arsenal zerstörerischer Effekte einzusetzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137072] = {name = "[q5]Aman'thuls Weisheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Leder}\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Druide\n[q2]Anlegen: Wenn 'Verjüngung' ein Ziel heilt, das bei voller Gesundheit ist, wird die Dauer um 3 Sek. erhöht, bis zu einer maximalen Erhöhung von 9 Sek. pro Einsatz.\n[q]\"Ihr seid mit der großen Aufgabe betraut worden, die Reinheit der Zeit aufrechtzuerhalten. Wisst, dass es nur eine wahre Zeitlinie geben kann, auch wenn es jene gibt, die nach anderem trachten. Ihr müsst sie bewahren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137073] = {name = "[q5]Schiftung des Einklangs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Leder}\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Mönch\n[q2]Anlegen: 'Beruhigender Nebel' heilt einen zweiten verletzten Verbündeten innerhalb von 15 Metern um 50% der ursprünglichen Menge.\n[q]\"All die Orte, die Ihr Euch je vorgestellt habt - sie sind alle real. Es ist eine fiktive Stadt in Eurem Geist, und Ihr kennt jedes Haus und jede Gasse. Euer Verstand ist eine Welt. Jeder von uns ist ein Ort.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137074] = {name = "[q5]Echos der Großen Zerschlagung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Kette}\n8 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Schamane\n[q2]Anlegen: 'Erdschock' gewährt je nach verbrauchtem Mahlstrom eine Chance von bis zu 50%, dass Euer nächster Einsatz von 'Erdbeben' kostenlos ist und 100% mehr Schaden verursacht.\n[q]\"Der Brunnen der Ewigkeit implodierte vor 10.000 Jahren, doch die Auswirkungen spürt man selbst heute noch.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137075] = {name = "[q5]Tak'theritrix' Schulterpolster", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Platte}\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\n[q2]Anlegen: 'Dunkle Transformation' verstärkt auch [ Dunkle Richterin : Eure Dunkle Richterin / Euren Gargoyle] und 'Armee der Toten' 30 Sek. lang und erhöht ihren Schaden um 40%.\n[q]\"Im Verlauf der ersten Invasion von Azeroth spielte der Legionskommandant Tak'theritrix eine Schlüsselrolle bei der Auslöschung der ersten Verteidigungslinie der Nachtelfen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137076] = {name = "[q5]Obsidiansteinschiftung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Platte}\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Paladin\n[q2]Anlegen: 30% der auf Euch gewirkten Heilung, wird zusätzlich gleichmäßig auf alle Ziele aufgeteilt, die unter dem Effekt Eurer 'Flammen' stehen.\n[q]\"Von diesem Rüstungsteil geht dieselbe Macht aus wie vom Dunklen Portal.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137077] = {name = "[q5]Gewicht der Erde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Platte}\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Krieger\n[q2]Anlegen: Der Effektradius von 'Heldenhafter Sprung' ist um 100% erhöht und davon getroffene Gegner werden zusätzlich mit 'Kolossales Schmettern' belegt.\n[q]\"Alle lebenden Kreaturen vertrauen in die Ruhe der Erde. Sie wissen nichts von den Strömen, die sich unter ihrer Oberfläche bewegen. Sie verstehen ihr Gewicht nicht. Sie können ihre Macht nicht verstehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137078] = {name = "[q5]Der Rat des Dunklen Titanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\n[q2]Anlegen: Erhöht die Endheilung von 'Blühendes Leben' um 200%. Die regelmäßige Heilung von 'Blühendes Leben' hat eine Chance von 5%, so viel Gesundheit wiederherzustellen wie die Endheilung.\n[q]\"Habt Geduld. Ihr seid noch jung, aber eines Tages bekommt Ihr, was Euch zusteht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137079] = {name = "[q5]Gai Plins lindernde Schärpe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Mönch\n[q2]Anlegen: 'Reinigendes Gebräu' heilt Euch sofort um 25% des entfernten gestaffelten Schadens.\n[q]\"Gai Plin extrahierte die heilenden Kräfte des Ru'shanflusses und durchtränkte damit diesen Gürtel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137080] = {name = "[q5]Brüllen der sieben Löwen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\n[q2]Anlegen: 'Zorn des Wildtiers' verringert die Fokuskosten all Eurer Fähigkeiten um 15%.\n[q]\"Tyven, Schildwache der Nachtelfen, fertigte diesen Gürtel aus den Mähnen der legendären sieben Löwen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137081] = {name = "[q5]Kriegsgürtel der Schildwachenarmee", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\n[q2]Anlegen: Der Schaden Eures nächsten Einsatzes von 'Gezielter Schuss' wird für jeden Gegner, den Ihr mit 'Mehrfachschuss' trefft, um 10% erhöht, bis zu einem Maximum von 20 Treffern.\n[q]\"Schildwachen sind die Meisterschützen und Elitekämpfer der Nachtelfen. Nur wenige Krieger können mit der Geschwindigkeit und Gerissenheit der stolzen Bogenschützinnen mithalten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137082] = {name = "[q5]Helgischt, Strick des Nebelmarodeurs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Jäger\n[q2]Anlegen: Euer verursachter Schaden gegen das erste von 'Harpune' getroffene Ziel wird für 10 Sek. um bis zu 30% erhöht, basierend auf Eurer Entfernung zum Ziel.\n[q]\"Ein geisterhaftes Heulen schallt durch die Nebel, noch lange nachdem Helheim sein nächstes Opfer gefordert hat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137083] = {name = "[q5]Makelloser Protoschuppengurt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: 'Lavaeruption' verursacht im Verlauf von 6 Sek. zusätzlich (13.5% der Zaubermacht) Schaden. Bis zu 5-mal stapelbar.\n[q]\"Wurde aus der Schuppe eines riesigen Protodrachen gefertigt, die uralt aussieht, sich aber immer noch heiß anfühlt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137084] = {name = "[q5]Akainus absolute Gerechtigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: Wenn Eure Waffen sowohl mit 'Flammenzunge' als auch 'Frostbrand' verzaubert sind, verursacht 'Lavapeitsche' 50% mehr Schaden.\n[q]\"Seine geschmolzene Macht vermochte ganze Landstriche zu formen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137085] = {name = "[q5]Intakte Nazjatarhaut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: Wenn Ihr 'Springflut' auf ein Ziel mit weniger als 40% Gesundheit wirkt, wird die Abklingzeit des Zaubers sofort abgeschlossen.\n[q]\"Die Naga von Nazjatar sind Meister der Magie und leben in den Tiefen des Ozeans. Es ist also nicht verwunderlich, dass diejenigen, die eine ihrer abgestreiften Häute tragen, mehr Gewalt über die Gezeiten erhalten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137086] = {name = "[q5]Thrayns Kette", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Paladin\n[q2]Anlegen: Heilig\n 'Zornige Vergeltung' erhöht die hervorgerufene Heilung um zusätzlich 25% und den verursachten Schaden um zusätzlich 10%.\n\nSchutz\n 'Zornige Vergeltung' erhöht die hervorgerufene Heilung um zusätzlich 50% und den verursachten Schaden um zusätzlich 10%.\n\nVergeltung\n 'Zornige Vergeltung' erhöht die hervorgerufene Heilung um zusätzlich 50% und den verursachten Schaden um zusätzlich 10%.\n[q]\"Das Gebet eines uralten Champions aus den Hallen der Tapferkeit erklingt durch diese Glieder: Wer mit dem Licht ist, ist niemals allein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137087] = {name = "[q5]Naj'entus' Rückgrat", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Krieger\n[q2]Anlegen: Wenn 'Wirbelwind' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen.\n[q]\"Nur wenige Naga waren so stark wie Naj'entus, der Champion von Lady Vashj und Diener von Illidan Sturmgrimm.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137088] = {name = "[q5]Stürmer von Ceann-Ar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Platte}\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Krieger\n[q2]Anlegen: Jedes Mal, wenn Ihr in einen Wutzustand verfallt, erhaltet Ihr 8 Wut.\n[q]\"Legendäre Kämpfer stellen sich ihren Gegnern immer Auge in Auge.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137089] = {name = "[q5]Wucht des Donnergotts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]+ 3 Vielseitigkeit\nHaltbarkeit 70 / 70\nKlassen: Krieger\n[q2]Anlegen: Für jeden von 'Donnerknall' getroffenen Gegner wird die verbleibende Abklingzeit von 'Demoralisierender Ruf' um 3 Sek. verringert.\n[q]\"Und der Gott des Donners strafte die Unfolgsamen mit großem Zorn und furchtbarer Rache...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137090] = {name = "[q5]Bionische Stabilisatoren der Mo'arg", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Gleve werfen' verursacht pro getroffenem Gegner 25% mehr Schaden.\n[q]\"Wenn Ihr eine Säge stabilisieren könnt, könnt Ihr auch eine Gleve stabilisieren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137091] = {name = "[q5]Verlorene Unterarmschienen des Entweihers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n[q2]+ 3 Vermeidung\nHaltbarkeit 70 / 70\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Seelenspalter' verringert die Abklingzeit eines zufälligen Zeichens um 8 Sek. (500ms Abklingzeit)\n[q]\"Während der Schlacht mit Loramus Thalipedes auf der Anhöhe des Entweihers wurden diese Unterarmschienen von Razelikhs Gelenken gerissen und in Richtung des Dunklen Portals geschleudert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137092] = {name = "[q5]Oneths Intuition", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Druide\n[q2]Anlegen: 'Sternensog' und 'Sternenregen' haben eine Chance von 20%, den jeweils anderen Zauber kostenlos zu machen. (Procchance: 20%)\n[q]\"Aglaya hätte es wohl Oneths Vermessenheit genannt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137094] = {name = "[q5]Die Umklammerung des Wildformers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\n[q2]Anlegen: Kritische Treffer Eurer Blutungseffekte haben eine Chance von 30%, 'Urfuror' auszulösen. (Procchance: 30%)\n[q]\"Die verderbten Druiden der Wildhufe hofften, eines Tages die Macht zu erlangen, die Alzzin diesen Prachtstücken verlieh.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137095] = {name = "[q5]Edraith, Bindungen von Aglaya", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Druide\n[q2]Anlegen: 'Rasche Heilung' verlängert die Dauer Eurer aktiven regelmäßigen Heilungseffekte auf dem Ziel um 10 Sek.\n[q]\"Aus dem Balg eines uralten Bullen hergestellt, der mit ewiger Glückseligkeit gesegnet war.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137096] = {name = "[q5]Petrichorgeschenk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Mönch\n[q2]Anlegen: Jedes Wirken von 'Erneuernder Nebel' verringert die verbleibende Abklingzeit von 'Belebung' um 2.0 Sek.\n[q]\"Ah... es riecht heute nach Regen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137097] = {name = "[q5]Trinkhorndeckel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\n[q2]Anlegen: Die Dauer von 'Sturm, Erde und Feuer' wird pro verbrauchtem Chi um 0.4 Sek. erhöht. (100ms Abklingzeit)\n[q]\"Die hartgesottenen Vrykul Nordends vermochten jeglichem Wetter zu widerstehen, solange sie nur genug zu trinken hatten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137098] = {name = "[q5]Trainingsfesseln der Familie Zoldyck", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\n[q2]Anlegen: Eure Gifte und Blutungseffekte fügen Zielen mit weniger als 30% Gesundheit 30% mehr Schaden zu.\n[q]\"Die Mitglieder der Familie Zoldyck werden von Geburt an in der Kunst des Meuchelns geschult. In den Kellergewölben ihres Anwesens werden sie gelehrt, tödlichste Gifte zu nutzen und ihnen zu widerstehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137099] = {name = "[q5]Grünhauts durchnässte Handfesseln", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schurke\n[q2]Anlegen: 'Zwischen die Augen' hat eine Chance von 20% pro Combopunkt, den Schaden Eures nächsten Einsatzes von 'Pistolenschuss' um 200% zu erhöhen.\n[q]\"In einer gesetzlosen Welt voller Tavernenschlägereien und spontaner Duelle ist Treffsicherheit oberstes Gebot.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137100] = {name = "[q5]Leugnung der Halbriesen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\n[q2]Anlegen: Eure Finishing-Moves erhöhen die Dauer von 'Schattenklingen' pro verbrauchtem Combopunkt um 0.2 Sek.\n[q]\"Wenn Ihr glaubt, ein Tauren, der sich im Schatten verstecken will, wäre ein lächerlicher Anblick, solltet Ihr einmal sehen, wie diese Vrykulhalbriesen am helllichten Tag durch die Gegend schleichen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137101] = {name = "[q5]Ruf der Wildnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Jäger\n[q2]Anlegen: Verringert die Abklingzeit aller Aspekte um 35%.\n[q]\"Jäger haben eine machtvolle Verbindung zur Wildnis: die Fähigkeit, Tieraspekte herbeizurufen, um sich selbst erstarken zu lassen und mit den wildesten Kreaturen anzufreunden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137102] = {name = "[q5]Al'Akirs Verbitterung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: 'Kettenblitzschlag' fügt jedem weiteren Ziel 5% mehr Schaden zu.\n[q]\"Blitze fahren immer noch durch diese Fesseln. Eure Macht scheint unendlich zu sein und immer weiter anzuwachsen...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137103] = {name = "[q5]Sturmböen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: Gegner, die von Eurem 'Sturmschlag' getroffen wurden, sind für 15 Sek. elektrisch geladen und versetzen einem Gegner in der Nähe alle 1 Sek. einen Schlag in Höhe von 5% Naturschaden.\n[q]\"Diese aus den Schuppen eines uralten Sturmdrachen hergestellte Bindung entfesselt unkontrollierbare magische Energien gegen alles in der näheren Umgebung.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137104] = {name = "[q5]Nobundos Erlösung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: 'Kettenheilung' verringert die Manakosten Eures nächsten Einsatzes von 'Heilende Woge' um 50%.\n[q]\"Scharfseher Nobundo hat die Stadt als Zerschlagener verlassen, doch kehrte er mit der Macht der Elemente zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137105] = {name = "[q5]Uthers Schutz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Paladin\n[q2]Anlegen: Erhöht die Dauer Eurer Fähigkeiten 'Segen der Freiheit' [ Segen der Aufopferung : 'Segen der Aufopferung' ] und [ Segen des Zauberschutzes : 'Segen des Zauberschutzes' / 'Segen des Schutzes'] um 50%. Außerdem heilen sie das Ziel um 15% seiner maximalen Gesundheit.\n[q]\"Uther der Lichtbringer, Anführer der Silbernen Hand, hatte solch eine Ausstrahlung auf dem Schlachtfeld, dass seine Ritter zuweilen gleichermaßen unbezwingbar und unaufhaltbar schienen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137107] = {name = "[q5]Mannoroths Aderlassfesseln", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]+ 4 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Krieger\n[q2]Anlegen: Ihr werdet pro 10 verbrauchter Wut um 1% Eurer maximalen Gesundheit geheilt.\n[q]\"Kommt und trinkt von meinem Blut, auf dass Ihr Euch schon bald am Blut Eurer Feinde laben könnt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137108] = {name = "[q5]Kakushans Sturmschuppenstulpen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Krieger\n[q2]Anlegen: [ Verwüster : Eure automatischen Angriffe erhöhen / 'Verwüsten' erhöht] den verursachten Schaden und die erzeugte Wut Eures nächsten Einsatzes von 'Schildschlag' oder 'Donnerknall' um 20%.\n[q]\"Der große Krieger Kakushan fertigte sie aus den Häuten von Sturmschuppennaga, nachdem er und Ivagont ihre Dörfer an der Dunkelküste verwüstet hatten. Während die Naga voller Entsetzen flohen, tranken die Vrykul das Blut ihrer Stammesbrüder.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137109] = {name = "[q5]X'anshi, Schleier von Erzbischof Benedictus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nKlassen: Priester\n[q2]Anlegen: Wenn Euer Geist der Erlösung abläuft, werdet Ihr mit bis zu 100% Gesundheit wiederbelebt, abhängig davon, wie effektiv Ihr als Geist der Erlösung wart. Nach Eurer Wiederbelebung kann der Geist der Erlösung 10 Min. lang nicht erneut ausgelöst werden.\n[q]\"Ist es möglich, ohne jeden Akt des Verrats seine Ziele zu erreichen?\"\nVerkaufspreis:"}
