MultiLanguageItemData['de'][137220] = {name = "[q5]Marsch der Legion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Mönch\n[q2]Anlegen: 'Windlaufen' erhöht die Bewegungsgeschwindigkeit um zusätzliche 15%.\n[q]\"Von seinem Platz auf Kil'jaedens Thron erhob Verdammnislord Kazzak sein Schwert und hieß die Dämonenarmee, in den Krieg zu ziehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][137221] = {name = "[q2]Verzaubertes Rabensiegel", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein verzaubertes Siegel, das mit dem Wappen von Lord Rabenkrone geziert wird.\""}
MultiLanguageItemData['de'][137222] = {name = "Blutrote Phiole", additional_info = "Herbeigezauberter Gegenstand\nEinzigartig: Blutrote Phiole (3)\n[q2]Benutzen: Trinkt ein alchemistisches Gemisch, das Euch im Verlauf von 6 Sek. um 30% Eurer maximalen Gesundheit heilt. (5 Min Abklingzeit)"}
MultiLanguageItemData['de'][137223] = {name = "[q5]Siegel der Nekrofantasie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Todesritter\n[q2]Anlegen: [ Hungernde Runenwaffe : 'Hungernde Runenwaffe' / 'Runenwaffe verstärken'] erhält 1 zusätzliche Aufladung und lädt sich 10% schneller wieder auf.\n[q]\"Dunkles Flüstern aus dem Wirbelnden Nether lässt vermuten, dass dieses Siegel vor dem Dritten Krieg von den Nathrezim geschmiedet und dann einem der mächtigsten Leutnants der Geißel verliehen wurde.\"\nVerkaufspreis:"}
