MultiLanguageItemData['de'][137537] = {name = "[q3]Tirathons Verrat", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\n[q2]Benutzen: Stärkt Euch mit dunkler Energie, durch die Eure Angriffe eine Chance haben, zusätzlich 19 Schattenschaden zu verursachen und Euch einen Schild zu gewähren, der 21 Schaden absorbiert.\n\n Hält 15 Sek. lang an. (1 Min, 15 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][137538] = {name = "[q3]Kugel der Qual", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Benutzen: Schwächt für 20 Sek. die Seele Eures Ziels, wodurch Ihr um 50% Eures dem Ziel zugefügten Schadens geheilt werdet, bis zu einer Gesamtheilung von 3008 Gesundheit. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][137539] = {name = "[q3]Fehlerhafte Gegenmaßnahme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Benutzen: Hüllt Eure Waffen für 30 Sek. in Eis, durch das Eure Nahkampfangriffe eine Chance haben, zusätzlich 45 Frostschaden zu verursachen und die Bewegungsgeschwindigkeit des Ziels für 8 Sek. um 20% zu verringern. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][137540] = {name = "[q3]Konkave Reflexionslinse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Anlegen: Eure Heilzauber haben eine Chance, den Effekt 'Impuls' auf Euer Ziel abzufeuern, der es um 52 Gesundheilt heilt und auf bis zu 3 zusätzliche Ziele überspringt.\nVerkaufspreis:"}
