MultiLanguageItemData['de'][137570] = {name = "[q4]Blutfangkokon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie Ihr eine Blutzahnwitwe beschwört.\n[q2]Beschwört einen reitbare Blutfangwitwe oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Von ihren langen, gezackten Extremitäten tropft das Blut ihrer Feinde und/oder ihres Männchens.\"\nVerkäufer:\nDer verrückte Händler"}
MultiLanguageItemData['de'][137571] = {name = "Erzmagier Vargoths Notizen", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ein brandneues Notizbuch mit dem Titel 'Der Seelenstein der Nachtgeborenen'.\""}
MultiLanguageItemData['de'][137572] = {name = "Zoargs Kopf", additional_info = "Questgegenstand\n[q]\"Ohne seine zweite Reihe messerscharfer Zähne könnte man diesen Dämon nicht von anderen Teufelshunden unterscheiden.\""}
MultiLanguageItemData['de'][137573] = {name = "[q4]Llothienstreuner", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen Llothienstreuner beschwört.\n[q2]Beschwört Euren Llothienstreuner oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese geschmeidigen Füchse können trotz ihrer Größe geräuschlos über frisch gefallene Blätter streifen.\"\nQuest:\nDer scheue Volpin\nZone:\nSuramar"}
MultiLanguageItemData['de'][137574] = {name = "[q4]Lebender Höllenkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie Ihr eine Teufelsfeuerhöllenbestie beschwört.\n[q2]Teufelsfeuerhöllenbestie : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\n[q]\"Die Illidari konnten eine dieser wilden Bestien zähmen, um sie als unaufhaltbares, furchtloses Reittier gegen die Legion einzusetzen.\"\nBeute von:\nGul'dan\nZone:\nDie Nachtfestung"}
MultiLanguageItemData['de'][137575] = {name = "[q4]Dämonischer Höllenfeuerkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie Ihr eine Höllenfeuerbestie beschwört.\n[q2]Beschwört Eure Höllenfeuerbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\n[q]\"Aus den Tiefen des Nethers wird eine Kreatur heraufbeschworen, die aus purem Hass besteht und danach trachtet, alles Leben auf ihrem Wege auszulöschen.\"\nBeute von:\nGul'dan (Mythisch)\nZone:\nDie Nachtfestung"}
MultiLanguageItemData['de'][137576] = {name = "[q4]Schwach leuchtender Kaltflammenkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie Ihr eine Kaltflammenhöllenbestie beschwört.\n[q2]Beschwört Eure Kaltflammenhöllenbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die eigenartigen, eisigen Flammen lassen Euch gleichzeitig schwitzen und frieren.\"\nHandelsposten"}
MultiLanguageItemData['de'][137577] = {name = "[q4]Räuberischer Blutstarrer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Räuberischer Blutstarrer : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die schiere Menge an rohen roten Beeren, die diese Allesfresser verschlingen, verleiht ihnen ihre bemerkenswerte Augenfarbe.\"\nQuest:\nBlutstarrerwiedersehen"}
MultiLanguageItemData['de'][137578] = {name = "[q4]Schneefederreißer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Schneefederreißer : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Tiere können sich unter einer Nebelbank verstecken, bis sich die Beute nähert, und dann herausspringen und das Opfer mit einem einzigen Krallenhieb aufschlitzen.\"\nQuest:\nSchneefederwiedersehen"}
MultiLanguageItemData['de'][137579] = {name = "[q4]Prächtiger Düsterschnabel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Prächtiger Düsterschnabel : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die schimmernde Haut dieser ebenso wilden wie koordiniert agierenden Bestien dient dazu, ihre Beute zu verwirren und orientierungslos zu machen.\"\nQuest:\nDüsterschnabelwiedersehen"}
MultiLanguageItemData['de'][137580] = {name = "[q4]Viridianscharfkralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Viridianscharfkralle : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dank ihrer Tarnungsfähigkeiten können sie sich in magischen Wäldern, wie man sie beispielsweise auf den Verheerten Inseln findet, perfekt an die Umgebung anpassen.\"\nQuest:\nScharfkrallenwiedersehen"}
MultiLanguageItemData['de'][137582] = {name = "[q6]Aschenbringer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n9 - 17 Schaden Geschwindigkeit 3.60\n(3.6 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Heilig Artefakt Relikt Slot\n[q0]Feuer Artefakt Relikt Slot\n[q2]Benutzen: Lässt den Aschenbringer in weitem Bogen herumwirbeln, fügt allen Gegnern innerhalb von 12 Metern vor Euch (174.3% der Angriffskraft)% Strahlenschaden zu und verringert ihre Bewegungsgeschwindigkeit für 6 Sek. um 50%.\n\n Wenn Dämonen und Untote von 'Aschewelle' getroffen werden, werden sie für 6 Sek. betäubt.\n[q]\"Klinge des Scharlachroten Hochlords\""}
