MultiLanguageItemData['de'][137680] = {name = "Pläne: Leysteinbeinschützer", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man Leysteinbeinschützer herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung von Leysteinbeinschützern.\nBenötigt Schmiedekunst der Verheerten Inseln (1)\n\n\n[q3]Leysteinbeinschützer\nWird beim Anlegen gebunden\n{Beine} {Platte}\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Leysteinerz (24), Fuchsblumenfluxus (2)\n Optionale Reagenzien: [] (#49)"}
MultiLanguageItemData['de'][137681] = {name = "Muster: Bluttotemsatteldecke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Bluttotemsatteldecke herstellt.\n[q2]Stellt eine seidengewebte Satteldecke her.\nBenötigt Schneiderei der Verheerten Inseln (100)\n\n\nBluttotemsatteldecke\nBenutzen: Platziert eine Satteldecke auf Eurem Reittier, durch die das Reiten für 2 Stunden weitaus komfortabler wird.\n\n\n Die Dauer dieses Effekts ist für Schneider vervierfacht.\nBenötigt Shal'doreiseide (25)"}
MultiLanguageItemData['de'][137686] = {name = "[q4]Stahlgebundenes Geschirr", additional_info = "Reittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen stahlgebundenen Verschlinger beschwört.\n[q2]Stahlgebundener Verschlinger: beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur die stärksten Ketten können diese Bestie im Zaum halten.\"\nBeruf:\nSchmiedekunst"}
MultiLanguageItemData['de'][137687] = {name = "Pläne: Teufelskernhundharnisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Teufelskernhundharnisch herstellt.\n[q2]Stellt einen Teufelskernhundharnisch her.\nBenötigt Schmiedekunst der Verheerten Inseln (100)\n[q4]Stahlgebundenes Geschirr\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen stahlgebundenen Verschlinger beschwört.\n[q2]Stahlgebundener Verschlinger: beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur die stärksten Ketten können diese Bestie im Zaum halten.\"\nBeruf:\nSchmiedekunstBenötigt Dämonenstahlbarren (100), Blut von Sargeras (50), Infernoschwefel (10), Teufelsbalg (10)"}
MultiLanguageItemData['de'][137690] = {name = "Blutopfer", additional_info = "Questgegenstand\n[q2]Benutzen: Bringt das dämonische Blutopfer dar, um das Ritual abzuschließen und mit der Seele von Illidan Sturmgrimm Verbindung aufzunehmen. (15 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][137691] = {name = "Bauplan: Intradalaranischer Wurmlochgenerator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen intradalaranischen Wurmlochgenerator herstellt.\n[q2]Stellt einen intradalaranischen Wurmlochgenerator her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q3]Intradalaranischer Wurmlochgenerator\n[q2]Benutzen: Teleportiert Euch an einen bis zu 90 Meter entfernten Punkt. Kann nur in Dalaran verwendet werden.\nVerkaufspreis: \nBenötigt Leysteinerz (150), Chaosblaster , Teufelswurz (3)"}
MultiLanguageItemData['de'][137692] = {name = "Bauplan: Blingtron-Schaltplandesignanleitung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Blingtron-Schaltplandesignanleitung herstellt.\n[q2]Stellt eine Blingtron-Schaltplandesignanleitung her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q3]Blingtron-Schaltplandesignanleitung\nSpielzeug\n[q2]Benutzen: Spielt ein Kabelentwirrungsspiel.\nVerkaufspreis: \nBenötigt Leysteinerz (50), Teufelsschiefer (50), Infernoschwefel (5)"}
MultiLanguageItemData['de'][137693] = {name = "Bauplan: Reaves-Modul: Fehlschlagdetektormodus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Reaves-Modul: Fehlschlagdetektormodus herstellt.\n[q2]Stellt ein Reaves-Modul: Fehlschlagdetektormodus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q3]Reaves-Modul: Fehlschlagdetektormodus\n[q2]Benutzen: Lehrt Reaves, den Fehlschlagdetektormodus zu aktivieren.\nVerkaufspreis: \nBenötigt Teufelsschiefer (80), Anti-Höllenbestien-Raketenwerfer (2)"}
MultiLanguageItemData['de'][137694] = {name = "Bauplan: Reaves-Modul: Reparaturmodus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Reaves-Modul: Reparaturmodus herstellt.\n[q2]Stellt ein Reaves-Modul: Reparaturmodus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q3]Reaves-Modul: Reparaturmodus\n[q2]Benutzen: Lehrt Reaves, den Reparaturmodus zu aktivieren.\nVerkaufspreis: \nBenötigt Teufelsschiefer (80), Automatikhammer (5)"}
