MultiLanguageItemData['de'][137705] = {name = "Bauplan: Stationärer Kugelspender", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen stationären Kugelspender herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines stationären Kugelspenders.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \nStationärer Kugelspender\n[q2]Benutzen: Stellt einen Geschützturm auf, der Euch im Kampf unterstützt. (2 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nBenötigt Leysteinerz (40), Schrotflinte des Teufelsgebrabbels , Scharfschützenzielfernrohr"}
MultiLanguageItemData['de'][137706] = {name = "Bauplan: Schwarzpulverladung", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Schwarzpulverladung herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung einer Schwarzpulverladung.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nSchwarzpulverladung\n[q2]Benutzen: Fügt einem Gegner innerhalb von bis zu 40 Metern ( 810 + 485 ) Feuerschaden zu. (5 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Leysteinerz , Übergroße Sprengkapsel (30)"}
MultiLanguageItemData['de'][137707] = {name = "Bauplan: Repetierbandagenflinte", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Repetierbandagenflinte herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung einer Repetierbandagenflinte.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \nRepetierbandagenflinte\n[q2]Benutzen: Heilt einen Verbündeten innerhalb von bis zu 40 Metern um ( 300 + 300 * 3) Gesundheit. (1 Min Abklingzeit)\n20 Aufladungen\nVerkaufspreis: \nBenötigt Leysteinerz (40), Schrotflinte des Teufelsgebrabbels , Echteisengewehrlauf"}
MultiLanguageItemData['de'][137708] = {name = "Bauplan: Waffenpaket", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Waffenpaket herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines Waffenpakets.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \nWaffenpaket\n[q2]Benutzen: Schnallt Euch einige geladene Schusswaffen auf den Rücken. (15 Sek. Abklingzeit)\nVerkaufspreis: \nBenötigt Leysteinerz (8), Schrotflinte des Teufelsgebrabbels (3), Anti-Höllenbestien-Raketenwerfer"}
MultiLanguageItemData['de'][137709] = {name = "Bauplan: Automatikhammer", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Automatikhammer herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines Automatikhammers.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q2]Automatikhammer\n[q2]Benutzen: Stellt einen automatisierten Hammer auf, den alle nutzen können, um ihre Ausrüstung zu reparieren.\nVerkaufspreis: \nBenötigt Leysteinerz (18), Übergroße Sprengkapsel (10), Lockerer Abzug"}
MultiLanguageItemData['de'][137710] = {name = "Bauplan: Fehlschlagdetektorpylon", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Fehlschlagdetektorpylon herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines Fehlschlagdetektorpylonen.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q2]Fehlschlagdetektorpylon\n[q2]Benutzen: Platziert einen elektrischen Pylonen auf dem Boden, der alle Gruppen- oder Schlachtzugsmitglieder innerhalb von 5 Metern nach dem Ende des Kampfes wiederbelebt.\n\n Funktioniert nicht bei Spielercharakteren ab Stufe 0 oder bei jenen, deren Geist freigelassen wurde. (3 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Teufelsschiefer (4), Chaosblaster (2)"}
