MultiLanguageItemData['de'][137725] = {name = "Bauplan: Akustischer Stimmungsverbesserer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen akustischen Stimmungsverbesserer herstellt.\n[q2]Stellt einen akustischen Stimmungsverbesserer her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q3]Akustischer Stimmungsverbesserer\n[q2]Benutzen: Spielt Musik.\n\n Ihr könnt die Musik ändern, indem Ihr Liederrollen einsetzt, die von Inschriftenkundigen gefertigt werden.\nVerkaufspreis: \nBenötigt Leysteinerz (50), Teufelsschiefer (50), Teufelswurz"}
MultiLanguageItemData['de'][137726] = {name = "Bauplan: Leysteinboje", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Leysteinboje herstellt.\n[q2]Stellt eine Leysteinboje her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \nLeysteinboje\n[q2]Benutzen: Dies könnt Ihr nur unter Wasser benutzen. Besonders hilfreich, wenn Euch jeden Moment die Luft ausgeht.\nVerkaufspreis: \nBenötigt Leysteinerz (3)"}
MultiLanguageItemData['de'][137727] = {name = "Bauplan: Mechanische Prägungsmatrix", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine mechanischen Prägungsmatrix herstellt.\n[q2]Stellt eine mechanische Prägungsmatrix her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis: \n[q2]Mechanische Prägungsmatrix\nKlassen: Jäger\n[q2]Benutzen: Gestattet es Euch, Haustiere aus der Mechanoidenfamilie zu zähmen und aufzuspüren.\n[q2]Gestattet es Euch, Haustiere aus der Mechanoidenfamilie zu zähmen.\n[q2]Zeigt alle mechanischen Einheiten in der Nähe auf der Minikarte an.\nVerkaufspreis:\nBenötigt Leysteinerz (5), Blut von Sargeras (20), Teufelswurz"}
MultiLanguageItemData['de'][137728] = {name = "Technik: Schriftrolle des vergessenen Wissens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Schriftrolle des vergessenen Wissens herstellt.\n[q2]Stellt eine Schriftrolle des vergessenen Wissens her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nSchriftrolle des vergessenen Wissens\n[q2]Benutzen: Lest die Schriftrolle und lernt etwas.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Rosenrote Pigmente (35)"}
MultiLanguageItemData['de'][137729] = {name = "[q3]Technik: Kodex des ruhigen Gemüts", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Kodex des ruhigen Gemüts herstellt.\n[q2]Stellt einen Kodex des ruhigen Gemüts her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nKodex des ruhigen Gemüts\n[q2]Benutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln. Funktioniert nicht bei Zielen über Stufe 50.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Fahle Pigmente (5), Rosenrote Pigmente (25)"}
MultiLanguageItemData['de'][137730] = {name = "Technik: Glyphe 'Geisterhaftes Verblassen'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Geisterhaftes Verblassen' herstellt.\n[q2]Stellt eine Glyphe 'Geisterhaftes Verblassen' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Geisterhaftes Verblassen'\nKlassen: Priester\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verblasst nun noch stärker in einen geisterhaften Zustand.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (2), Rosenrote Pigmente (70)"}
