MultiLanguageItemData['de'][138933] = {name = "[q0]Münze von Allari der Seelenfresserin", additional_info = "Wird beim Aufheben gebunden\n[q]\"Fische haben keine Seelen. Das hier ist zwecklos.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138934] = {name = "[q0]Münze von Altruis dem Leidenden", additional_info = "Wird beim Aufheben gebunden\n[q]\"Denkt selbst und macht Euch ein eigenes Bild.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138935] = {name = "[q0]Cyana Nachtgleves Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünschte, ich wäre stärker.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138936] = {name = "[q0]Falara Nachtweises Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich erinnere mich an die Zeit, als Suramar wunderschön und ruhig war... bevor Azshara und ihre Hochgeborenen alles zerstört haben. Wünsche bringen nur eines: Bedauern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138937] = {name = "[q0]Izal Weißmonds Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Magier ließen mich hier landen. Die meisten betrachten einen mit Argwohn, Abscheu oder Schlimmerem, doch manche können über Äußerlichkeiten hinwegsehen. Ich wünsche mir, dass wir alle zusammen gegen unseren wahren Feind stehen: die Brennende Legion.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138938] = {name = "[q0]Jace Düsterwebers Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"In meinem früheren Leben hätte ich liebend gern all meine Zeit in diesem schwebenden Wunder verbracht. Den ganzen Tag hätte ich entweder in diesem magischen Brunnen geangelt oder mich in den arkanen Künsten geübt. Diese Zeiten sind längst vorbei.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138939] = {name = "[q0]Kayn Sonnenzorns Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Nur mit einer starken Führung und einer klaren Sicht der Dinge erringt man den Sieg.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138940] = {name = "[q0]Kor'vas Blutdorns Münze", additional_info = "Wird beim Aufheben gebunden\n\"Angeln und Wünschen? Den Luxus kann ich mir nicht leisten. Es gibt immer noch Dämonen, die ich töten muss.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138941] = {name = "[q0]Die Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Erhaltet 1 Manakristall nur für diesen Zug.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138942] = {name = "[q0]Blingtrons Botmünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Das Wunschmodul ist aktuell ausgelastet. Bitte versucht es später erneut. (Fehler 37)\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138943] = {name = "[q0]Lady Liadrins Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Möge das Licht dieses Land in all seiner Herrlichkeit erleuchten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138944] = {name = "[q0]Lunaras Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Was ist der Ruf der Natur? Ich wünschte wirklich, mir würde mal jemand erklären, was 'Ruf der Natur' eigentlich bedeutet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138945] = {name = "[q0]Illidans Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Auf das Ende der Brennenden Legion.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138946] = {name = "[q0]Königliches Siegel von Königin Azshara", additional_info = "Wird beim Aufheben gebunden\n[q]\"Bald schon werdet Ihr ALLE meinen Zorn zu spüren bekommen!!!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138947] = {name = "[q0]Gallywix' Münze an der Schnur", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ja! So erfüllt sich mein Wunsch UND ich kann meine Münze behalten. Ha! Oh, nein! Die Schnur ist gerissen! Dämlicher Brunnen, gib mir sofort meine Münze wieder...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138948] = {name = "[q0]Li Lis Münze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ich wünsche mir, dass immer wieder neue Kontinente entdeckt werden, die ich erforschen kann.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138949] = {name = "[q5]Kirel narak", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Dämonenjäger\n[q2]Anlegen: Der Initialschaden von 'Feuerbrandaura' verringert die verbleibende Abklingzeit von 'Flammendes Brandmal' für jeden getroffenen Gegner um 2 Sek.\n[q]\"Vergeht in den Flammen, die zahllose Welten verschlungen haben. Alles muss im Feuer der Legion verbrennen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138951] = {name = "Überrest des Feuers", additional_info = "Questgegenstand\n[q]\"Beweis für Eure Befehlsgewalt über das Element Feuer.\""}
MultiLanguageItemData['de'][138952] = {name = "Überrest der Luft", additional_info = "Questgegenstand\n[q]\"Beweis für Eure Befehlsgewalt über das Element Luft.\""}
MultiLanguageItemData['de'][138953] = {name = "Überrest des Wassers", additional_info = "Questgegenstand\n[q]\"Beweis für Eure Befehlsgewalt über das Element Wasser.\""}
MultiLanguageItemData['de'][138954] = {name = "[q3]Illusion: Vergiftet", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schurke\n[q2]Benutzen: Sammelt die Waffenillusionsvorlage 'Vergiftet'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138955] = {name = "[q3]Illusion: Rune des schneidenden Eises", additional_info = "Wird beim Aufheben gebunden\nKlassen: Todesritter\n[q2]Benutzen: Sammelt die Waffenillusionsvorlage 'Rune des schneidenden Eises'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138956] = {name = "Hypermagnetischer Köder", additional_info = "Einzigartig\n[q2]Benutzen: Befestigt den Köder an Eurer Angelrute. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138957] = {name = "Auriphage Sardine", additional_info = "Einzigartig\n[q2]Benutzen: Befestigt den münzfressenden Fisch an Eurer Angelrute. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138958] = {name = "Klecks echt klebrigen Leims", additional_info = "Einzigartig\n[q2]Benutzen: Bringt den Kleber an Eurem Angelhaken an. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138959] = {name = "Mikrovortexgenerator", additional_info = "Einzigartig\n[q2]Benutzen: Befestigt das Gerät an Eurer Angelrute, das an Eurem Angelort einen kleinen Strudel erzeugt. Es kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138960] = {name = "Wunschkristall", additional_info = "Einzigartig\nBenutzen: Befestigt den Kristall an Eurer Angelrute. Einige Angler der Draenei glauben, dies würde beim Angeln von Münzen aus Springbrunnen helfen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138961] = {name = "Alchemistisches Haftmittel", additional_info = "Einzigartig\n[q2]Benutzen: Verteilt das Haftmittel auf Eurem Angelhaken, sodass er sich besser mit Metall verbindet. Das kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138962] = {name = "Seestern mit Faden", additional_info = "Einzigartig\n[q2]Benutzen: Bindet den Seestern an Eure Angelrute. Er kann Euch mit seinen Saugnäpfen dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138963] = {name = "Winzig kleines Greifgerät", additional_info = "Einzigartig\n[q2]Benutzen: Befestigt den Apparat an Eurer Angelrute. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138965] = {name = "Zauberstab des Entzugs", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht den Leichen der Nachtgeborenen in Suramar Nachtbrunnenenergie. (5 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][138966] = {name = "Bergbeeren", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kann beim Verzehr minimale Sättigung gewähren.\n[q]\"Farbenfrohe Früchte, die am Hochberg wachsen und einen beißenden Geruch verbreiten.\""}
MultiLanguageItemData['de'][138967] = {name = "Großer Brunnengoldfisch", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 2550 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:"}
MultiLanguageItemData['de'][138968] = {name = "Glitzernde Halskette", additional_info = "Questgegenstand\n[q]\"Gewebt aus dem Licht tausender Sterne.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138969] = {name = "Handvoll uralte goldene Scheiben", additional_info = "Questgegenstand\n[q]\"Sie leuchten schwach.\""}
MultiLanguageItemData['de'][138970] = {name = "[q3]Helm der bekräftigten Bestimmung", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 85 / 85\nKlassen: Dämonenjäger\nVerkaufspreis:"}
MultiLanguageItemData['de'][138971] = {name = "Fass mit Honigbräu", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Duftet nach Sonnenlicht und Lachen.\""}
MultiLanguageItemData['de'][138972] = {name = "Eingemachte Bilbeeren", additional_info = "[q2]Benutzen: Solange sie noch nicht verdorben ist, stellt diese Nahrung im Verlauf von 20 Sek. 38462 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Dieser Behälter enthält ein Beerenmus, bedeckt von einer grünen 'Schutzschicht'.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138973] = {name = "Beißend riechender Schimmelgamalost", additional_info = "[q2]Benutzen: Solange sie noch nicht verdorben ist, stellt diese Nahrung im Verlauf von 20 Sek. 38462 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Allgemein wird angenommen, dass die grünen Bestandteile dem Schutz dienen. Ihr solltet diese Teile auf keinen Fall essen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138974] = {name = "Verbrutzeltes Urhorn", additional_info = "[q2]Benutzen: Solange sie noch nicht verdorben ist, stellt diese Nahrung im Verlauf von 20 Sek. 38462 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Bis zur Unkenntlichkeit verbrannt, damit niemand daran erinnert wird, was das einmal war.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138975] = {name = "Gletscherwasser vom Hochberg", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n[q]\"Es war makellos am Tag, als es eingesammelt wurde, obwohl seit jenem Tag wohl schon einige Zeit vergangen ist...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][138976] = {name = "Altbackene Donnertotemreiswaffel", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 4250 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Trotz des abgelaufenen Haltbarkeitsdatums haben die Kauzfüße hier ein Superangebot. Dieses Gebäck wird nämlich anscheinend niemals schlecht.\"\nVerkaufspreis:"}
