MultiLanguageItemData['de'][138986] = {name = "Kurds Joghurt", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 7500 / 5 * 20) Gesundheit und ( 3750 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Ein Gemisch nach azsunianischer Art.\"\nVerkaufspreis:"}
