MultiLanguageItemData['de'][138990] = {name = "[q4]Edelkostümset: \"Grommash\"", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Verkleidet Euch als Grommash. (10 Sek. Abklingzeit)\n50 Aufladungen\n[q]\"Eine aufwendige Replik von Grommash – inklusive aufblasbarem Blutschrei!\""}
