MultiLanguageItemData['de'][139002] = {name = "Winstone Wolf", additional_info = "Questgegenstand\n[q]\"Winstone Wolf kommt in Eure Ordenshalle und ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\""}
MultiLanguageItemData['de'][139003] = {name = "[q0]Defektes Begleiterportal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Setzt das Haustiermaximum für Eure Kriegsmeute auf 1.500. Pro Kriegsmeute nur einmal nutzbar. Wird bei Nutzung verbraucht.\n[q]\"Dieses Objekt scheint nicht mehr zu funktionieren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139004] = {name = "Stab der Verwandlung - Banshee", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Verkleidet das anvisierte Gruppenmitglied als Banshee.\n5 Aufladungen"}
MultiLanguageItemData['de'][139010] = {name = "[q3]Versteinertes Seidengewebe", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht die Gesundheit Eurer Verdorrtentrupps um 25%.\n\n Dieser Effekt ist dauerhaft und wird ausgelöst, wenn Ihr das Szenario \"Der Kollaps\" das nächste Mal betretet."}
MultiLanguageItemData['de'][139011] = {name = "[q4]Berserkerhelm von Ondry'el", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ein Mitglied Eurer Verdorrtenarmee kann den Helm tragen, wodurch es zu einem mächtigen verdorrten Berserker wird.\n\n Dieser Effekt ist dauerhaft und wird ausgelöst, wenn Ihr das Szenario \"Der Kollaps\" das nächste Mal betretet."}
MultiLanguageItemData['de'][139012] = {name = "[q0]Dunkle Gleve", additional_info = "Wird beim Aufheben gebunden\nWaffenhand Kriegsgleve\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nVerkaufspreis:"}
