MultiLanguageItemData['de'][139320] = {name = "[q4]Verheerte Samenkapsel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Benutzen: Kontaminiert für 10 Sek. den Boden unter Euren Füßen, der Gegnern im Effektbereich pro Sekunde 63 Schattenschaden zufügt. Während Ihr Euch in diesem Bereich aufhaltet, erhaltet Ihr 9 Lebensraub. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][139321] = {name = "[q4]Schwärmender Pestbau", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Anlegen: Eure Schadenszauber haben eine Chance, einen Aasschwarm herbeizurufen, der Euer Ziel einhüllt und ihm im Verlauf von 10 Sek. 68 Naturschaden zufügt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139322] = {name = "[q4]Kokon der erzwungenen Einsamkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\n[q2]Benutzen: Hüllt Euch selbst in einen Kokon, wodurch Ihr für 10 Sek. in einen traumlosen Schlaf verfallt. Während dieser Zeit stellt Ihr 51 Mana pro Sekunde wieder her. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][139323] = {name = "[q4]Wirbelnder Wind", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Intelligenz]\n[q2]Anlegen: Eure Distanzangriffe und Zauber haben eine Chance, für 10 Sek. einen quälenden Zyklon an der Position des Ziels zu erzeugen, der pro Sekunde 5 Schattenschaden verursacht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139324] = {name = "[q4]Becher mit Alptraumsekret", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Beim Erleiden von Schaden besteht eine Chance, dass in der Nähe ein Alptraumsekret erschaffen wird. Das Absorbieren dieses Sekrets erhöht Eure Vielseitigkeit für 10 Sek. um 19 .\nVerkaufspreis:"}
MultiLanguageItemData['de'][139325] = {name = "[q4]Spontane Gliedmaßen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, für 12 Sek. Tentakel zu erzeugen, die Gegner in der Nähe angreifen und ihnen alle 0.75 Sek. 10 körperlichen Schaden zufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139326] = {name = "[q4]Zuckende Sehne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Benutzen: Erhaltet 10 Aufladungen 'Unerträgliches Flüstern'. Eure Schadenszauber übertragen für 30 Sek. je eine Aufladung 'Unerträgliches Flüstern' auf das Ziel. Dieser Effekt kann nur ein Mal alle 0.5 Sek. auftreten. Wenn alle Aufladungen übertragen wurden, verursacht jede von ihnen 22 Schattenschaden. (500ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][139327] = {name = "[q4]Ungezügelte Wut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Benutzen: Erhöht Eure maximale Gesundheit um 182 und Eure Rüstung um 1 . Hält 30 Sek. lang an. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][139328] = {name = "[q4]Ursocs reißende Pranke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\n[q2]Anlegen: Eure kritischen automatischen Angriffe gewähren eine Chance, dass das Ziel im Verlauf von 8 Sek. 15 körperlichen Blutungsschaden erleidet.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139329] = {name = "[q4]Blutrünstiger Instinkt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\n[q2]Anlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, 10 Sek. lang Euer Tempo um 21 zu erhöhen. Dieser Effekt tritt häufiger im Kampf gegen Ziele mit niedriger Gesundheit auf.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139330] = {name = "[q4]Geschärfte Sinne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Eure Heilzauber haben eine Chance, Euer Tempo um 9 und Eure Intelligenz um 13 zu erhöhen. Hält 12 Sek. lang an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139332] = {name = "[q4]Geschwärzte Portalsteinhalskette", additional_info = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Tempowertung um + 5.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139333] = {name = "[q4]Horn des Cenarius", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Benutzen: Beschwört einen Irrwisch, um einen Verbündeten zu unterstützen. Wenn der Irrwisch die Position Eures Ziels erreicht, detoniert er und ruft innerhalb von 8 Metern 33 Heilung hervor. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][139334] = {name = "[q4]Der Ruf der Natur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, Euch für 10 Sek. einen Segen eines der Verbündeten der Natur zu gewähren.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139335] = {name = "[q4]Groteske Statue", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Anlegen: Gewährt eine Chance, dass die Seelen von Gegnern, die Euch angreifen, verdunkelt werden und sie Euch 20 Sek. lang (- 0 )% weniger Schaden zufügen. Weitere Anwendungen erhöhen die Effektivität von 'Verdunkelnde Seele', setzen jedoch nicht die Effektdauer zurück.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139336] = {name = "[q4]Zweig der Verderbnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Anlegen: Eure Schaden verursachenden Zauber haben eine Chance, das Ziel für 20 Sek. mit 'Alptraumverderbnis' zu infizieren, durch die Eure Zauber bis zu 2 zusätzlichen Schaden als Schattenschaden verursachen. Alle 2 Sek. versucht 'Alptraumverderbnis', sich auf einen Gegner in der Nähe auszubreiten. Wenn sich keine nicht infizierten Gegner in der Nähe befinden, steigt die Intensität der Verderbnis an. (20s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][139337] = {name = "[q3]Winterhauchwegwerfkleidung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Stellt eine Kleidertruhe auf, damit Eure Schlachtzugs- oder Gruppenmitglieder etwas anprobieren können.\n Während des Winterhauchfests ist die Abklingzeit verringert. (2 Std. Abklingzeit)\n[q]\"Für die fröhliche Feststimmung an jedem Tag des Jahres!\""}
