MultiLanguageItemData['de'][139447] = {name = "[q2]Phiole des reinen Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Beschwört eine Lichtbrut, die für 10 Min. an Eurer Seite kämpft.\n\n Die Lichtbrut ist sehr ausdauernd und verspottet alle Gegner in der Nähe.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139448] = {name = "[q2]Phiole der dunklen Schatten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Beschwört einen Gesichtslosen, der für 10 Min. an Eurer Seite kämpft.\n\n Der Gesichtslose ist sehr ausdauernd und verspottet alle Gegner in der Nähe.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139449] = {name = "[q2]Essenz der Naaru", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Fokussiert das Licht der Naaru, um alle Gegner innerhalb von 15 Metern zwei Mal über einen Zeitraum von 4 Sek. mit (2000% der Zaubermacht) Heiligschaden zu verbrennen.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139450] = {name = "[q2]Sphäre der Leere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Ruft zwei Tentakel aus der Leere herbei, die auf alle Gegner innerhalb von 8 Metern vor Euch hinabschmettern und ihnen (2000% der Zaubermacht) Schattenschaden zufügen.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139451] = {name = "[q2]Wirbelnder Leerentrank", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Trinkt von dem dunklen Trank, um Euren Geist der Leere zu opfern.\n\n Erzeugt im Verlauf der nächsten 10 Min. 10 Wahnsinn pro Sekunde.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139452] = {name = "[q2]Essenz des Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Entfesselt die Energie des Lichts, wodurch alle Gruppenmitglieder alle 2 Sek. um 5% ihrer maximalen Gesundheit geheilt werden.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
