MultiLanguageItemData['de'][139457] = {name = "[q3]Odyns Herausforderung", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Odyn persönlich lädt die mächtigsten Champions von Azeroth dazu ein, seine Hallen zu betreten und sich mit seinen Kriegern zu messen.\""}
MultiLanguageItemData['de'][139458] = {name = "Salbe gegen Teufelsfledermaustoxin", additional_info = "Questgegenstand\n[q]\"Wirkt dem Toxin entgegen, das bei Bissen von Teufelsfledermäusen zu Eiter und Fäulnis führt.\""}
MultiLanguageItemData['de'][139459] = {name = "[q2]Segen des Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Gewährt beim Einsatz 'Segen des Lichts'. Wenn Ihr tödlichen Schaden erleidet, lässt das Licht Euch mit voller Gesundheit zurückkehren und alle umgebenden Gegner zurückstoßen.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139460] = {name = "Siegel des verheerten Schicksals", additional_info = "[q]\"Verändert Euer Schicksal und gibt Euch die Möglichkeit, im Smaragdgrünen Alptraum oder in der Nachtfestung zusätzliche Schätze zu erhalten.\""}
MultiLanguageItemData['de'][139461] = {name = "[q2]Rune der Dunkelheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 18 std.\n[q2]Benutzen: Aktiviert die Rune, um 'Umhüllung der Dunkelheit' zu erhalten. Wenn Ihr tödlichen Schaden erleidet, lässt die Dunkelheit Euch mit voller Gesundheit zurückkehren und alle umgebenden Gegner zurückstoßen.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139463] = {name = "Salbe gegen Teufelsfledermaustoxin", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Verabreicht Eurem Ziel eine einzelne Dosis Gegengift für Teufelsfledermaustoxin. (4 Sek. Abklingzeit)\n[q]\"Wirkt dem Toxin entgegen, das bei Bissen von Teufelsfledermäusen zu Eiter und Fäulnis führt.\""}
