MultiLanguageItemData['de'][139471] = {name = "[q3]Schreiben an die Rabenwehr", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Lord Rabenkrone, die Legion stimmt Euren Bedingungen zu. Die Verstärkung wird wie erwartet eintreffen. Vergesst nicht, Euren Teil des Pakts zu erfüllen.\""}
MultiLanguageItemData['de'][139472] = {name = "[q3]Einladung zu einer glamourösen Feier", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Ihr seid herzlich auf das Juwelenverzierte Anwesen eingeladen, wo Euch ergötzliche Leckereien und Getränke und womöglich sogar ein Überraschungsgast erwarten...\""}
MultiLanguageItemData['de'][139473] = {name = "[q3]Phiole mit vergiftetem Blut", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Blut, das einer unglückseligen verderbten Kreatur im Finsterherzdickicht abgezapft wurde.\""}
MultiLanguageItemData['de'][139474] = {name = "[q3]Gravierte Muschelschale", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Wenn Ihr sie Euch ans Ohr haltet, hört Ihr eine bösartige Stimme in der Ferne.\""}
MultiLanguageItemData['de'][139475] = {name = "[q3]Durchnässter Brief", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Meine Liebste, ich fürchte, meine schlechten Taten haben mich nun endlich eingeholt. Mir steht eine Ewigkeit in der Unterwelt bevor, in der ich über das Meer segele und Helyas Gnade unterworfen bin. Vergiss mich nicht.\""}
MultiLanguageItemData['de'][139476] = {name = "[q3]Gesprungene Drachenschuppe", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Die Drogbar haben sie an einem besonderen Platz aufgehoben, als Erinnerung an die Macht, die Todesschwinge einst innewohnte.\""}
