MultiLanguageItemData['de'][139494] = {name = "Vergessene Formeln der Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Verzauberkunstformeln neu, die Ihr durch das Erfüllen von Quests auf den Verheerten Inseln erhalten habt, doch nach einem Berufswechsel vergessen habt.\nBenötigt Verzauberkunst (1)"}
MultiLanguageItemData['de'][139495] = {name = "Vergessene Baupläne der Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Ingenieurskunstbaupläne neu, die Ihr durch das Erfüllen von Quests auf den Verheerten Inseln erhalten habt, doch nach einem Berufswechsel vergessen habt.\nBenötigt Ingenieurskunst (1)"}
MultiLanguageItemData['de'][139496] = {name = "Vergessene Techniken der Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Inschriftenkundetechniken neu, die Ihr durch das Erfüllen von Quests auf den Verheerten Inseln erhalten habt, doch nach einem Berufswechsel vergaßt.\nBenötigt Inschriftenkunde (1)"}
MultiLanguageItemData['de'][139497] = {name = "Vergessene Vorlagen der Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erlernt alle Juwelenschliffvorlagen neu, die Ihr durch das Erfüllen von Quests auf den Verheerten Inseln erhalten habt, doch nach einem Berufswechsel vergessen habt.\nBenötigtJuwelierskunst\n(1)"}
MultiLanguageItemData['de'][139498] = {name = "Vergessene Muster der Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Lederverarbeitungsmuster neu, die Ihr durch das Erfüllen von Quests auf den Verheerten Inseln erhalten habt, doch nach einem Berufswechsel vergessen habt.\nBenötigt Lederverarbeitung (1)"}
MultiLanguageItemData['de'][139499] = {name = "Vergessene Muster der Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Schneidereimuster neu, die Ihr durch das Erfüllen von Quests auf den Verheerten Inseln erhalten habt, doch nach einem Berufswechsel vergessen habt.\nBenötigt Schneiderei (1)"}
MultiLanguageItemData['de'][139500] = {name = "Hippogryphenfeder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verringert für 20 Sek. Eure Fallgeschwindigkeit.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139501] = {name = "Frostklippentrommeln", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Schlagt die Trommeln, um Jorhuttam zu seinem Fütterungsbereich zu locken."}
MultiLanguageItemData['de'][139502] = {name = "[q3]Zügel des Todesstreitrosses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\n[q2]Benutzen: Beschwört ein Todesstreitross der Schwarzen Klinge, das im Kampf geritten werden kann, oder gibt es wieder frei.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][139503] = {name = "Bluttotemsatteldecke", additional_info = "Benutzen: Platziert eine Satteldecke auf Eurem Reittier, durch die das Reiten für 2 Stunden weitaus komfortabler wird.\n\n\n Die Dauer dieses Effekts ist für Schneider vervierfacht."}
MultiLanguageItemData['de'][139505] = {name = "[q3]Zügel des Streitrosses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\n[q2]Benutzen: Beschwört ein Streitross der Silbernen Hand, das im Kampf geritten werden kann, oder gibt es wieder frei.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\nVerkaufspreis:"}
