MultiLanguageItemData['de'][139536] = {name = "[q6]Emanation der Winde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Donnerzorn, Geweihte Klinge des Windfürsten\" für die Schreckensklingen frei.\n[q]\"Geheimnisse elementarer Macht schlummern in der berühmten Klinge von Donneraan dem Windlord.\""}
MultiLanguageItemData['de'][139537] = {name = "Zopf des Unterkönigs", additional_info = "Questgegenstand\n[q]\"Dieser magische, schamanistische Zopf wurde seit den ersten Tagen von jedem der Unterkönige getragen.\""}
MultiLanguageItemData['de'][139538] = {name = "Alptraumpeitsche", additional_info = "Questgegenstand\n[q]\"Diese Peitsche wurde aus der dunklen Energie von Xavius selbst erschaffen.\""}
MultiLanguageItemData['de'][139539] = {name = "Uralte Wellenskornklinge", additional_info = "Questgegenstand\n[q]\"Die hoch angesehene Waffe eines längst verstorbenen Wellenskornkriegers.\""}
MultiLanguageItemData['de'][139540] = {name = "Seite aus Aponis Tagebuch", additional_info = "Questgegenstand\n[q]\"Hastig geschrieben.\""}
MultiLanguageItemData['de'][139541] = {name = "Siegel der Befehlsgewalt", additional_info = "Questgegenstand\n[q2]Benutzen: Teleportiert zur Dämonenwelt Niskara. (3 Sek. Abklingzeit)\n[q]\"Leuchtet in der Gegenwart eines Legionsportals.\""}
MultiLanguageItemData['de'][139542] = {name = "[q0]Streifen Segeltuch", additional_info = "Wird beim Aufheben gebunden\n[q]\"Vermutlich kann nicht einmal ein Schneider etwas damit anfangen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139543] = {name = "[q0]Zerbrochene Pinne", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein talentierter Schiffsbauer könnte dies vielleicht weiterverwerten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139544] = {name = "[q0]Verfallendes Kriegsbanner der Wellenskorn", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wehte einst stolz an den Masten der Vrykullangschiffe.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139545] = {name = "[q0]Verrostete Schiffsglocke", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wurde verwendet, um bei dichtem Nebel andere Schiffe zu warnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139546] = {name = "[q6]Verzerrendes Anima der Seelen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Berührung des Untodes\" für den Schlund der Verdammten frei.\n[q]\"Ein fehlgeschlagenes Experiment, bei dem sich jemand auf magische Weise an der Macht der längst Verstorbenen bereichern wollte. Das Ergebnis zuckt und bebt noch immer auf beunruhigende Art und Weise.\""}
MultiLanguageItemData['de'][139547] = {name = "[q6]Runen der Verdunkelung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Dunkle Runenklinge\" für die Klingen des gefallenen Prinzen frei.\n[q]\"Obwohl sie in einer uralten Sprache verfasst sind, an die sich heute keine lebende Seele mehr erinnert, scheinen Euch diese Worte wie auf die Zunge zu springen. So, als wollten sie, dass man sie ausspricht.\""}
MultiLanguageItemData['de'][139548] = {name = "[q6]Der Haken des Knochenernters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Todesritter\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Knochenernter\" für Apokalypse frei.\n[q]\"Diese primitive und brutale Waffe wurde durch die stetige Energieablagerung aus der Eiskronenzitadelle genährt und lässt sich ohne Weiteres in ein Werkzeug des Todes verwandeln.\""}
MultiLanguageItemData['de'][139549] = {name = "[q6]Tarnung des Todeswandlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Dämonenjäger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Todeswandler\" für die Zwillingsklingen des Betrügers frei.\n[q]\"Die dunkle Waffe eines längst verstorbenen Meisters. Auch heute dürstet sie noch nach Blut.\""}
MultiLanguageItemData['de'][139550] = {name = "[q6]Bollwerk des Eisernen Wächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Dämonenjäger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Eiserner Wächter\" für die Kriegsklingen der Aldrachi frei.\n[q]\"Einst ein unbeugsames Konstrukt der Draenei, dann ein Werkzeug der Zerstörung in den Händen der Legion. Dieser Eiserne Wächter fiel vor langer Zeit bei der Invasion der Heimatwelt der Aldrachi.\""}
MultiLanguageItemData['de'][139551] = {name = "[q6]Die Sonnenblüte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Hand des Sonnenhüters\" für die Sichel von Elune frei.\n[q]\"Eine seltene Blume aus dem Smaragdgrünen Traum, die seit dem Krieg der Ahnen niemand mehr auf Azeroth gesehen hat.\""}
MultiLanguageItemData['de'][139552] = {name = "[q6]Feder des Mondgeistes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Mondgeist\" für die Fänge von Ashamane frei.\n[q]\"Eine einzelne Feder von einer wilden Gottheit, die nur wenige je zu Gesicht bekommen haben. Damit können Druiden der Klaue eine bisher nie gesehene Gestalt meistern.\""}
MultiLanguageItemData['de'][139553] = {name = "[q6]Mal des Lichtungswächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Wächter der Lichtung\" für Ursocs Klauen frei.\n[q]\"Mit diesem mächtigen Mal verleiht Ursol allen Bären große Kräfte, die in Zeiten der Not die Wildnis vor Gefahr schützen sollen.\""}
MultiLanguageItemData['de'][139554] = {name = "[q6]Eichel des Unendlichen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Krone des Wächters\" für G'Hanir, den Mutterbaum frei.\n[q]\"Diese magischen Eicheln stammen von einem der ältesten Bäume im Traum und konnten in Sicherheit gebracht werden, bevor er dem Alptraum anheimfiel.\""}
MultiLanguageItemData['de'][139555] = {name = "[q6]Entwürfe des großen Architekten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Arm der Titanen\" für Titanenblitz frei.\n[q]\"Detaillierte Pläne für ein wahres Meisterwerk technomagischer Bogenbaukunst, dessen Kern eine mächtige, von Titanen geschmiedete Energiequelle birgt. Wie diese Pläne den Weg aus Mimirons Archiv gefunden haben, ist unbekannt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139556] = {name = "[q6]Syriel Sichelsturz' Notizen: Rabenwächter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Rabenwächter\" für Thas'dorah, Erbstück von Haus Windläufer frei.\nBenötigtFarondis' Hofstaat\n- Respektvoll\n[q]\"Ausführliche Pläne für die Herstellung einer eleganten und mächtigen Armbrust, die in der Zeit verschollen gingen, da die benötigten Materialien nicht existiert haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][139557] = {name = "[q6]Letzter Atem des Waldes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Kraft der Bärenseele\" für Fangklaue, Speer der wilden Götter frei.\n[q]\"Zweimal opferte Ursoc der Wildnis sein Leben. Aber er hinterließ ein Vermächtnis, für das andere noble Verteidiger in seiner Abwesenheit eintreten sollten.\""}
MultiLanguageItemData['de'][139558] = {name = "[q6]Die Bürde des Wollomanten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Die Bürde des Wollomanten\" für Aluneth frei.\n[q]\"Cote 'der Hirte' Metcalf konnte die Rätsel dieses geheimnisvollen blökenden Stabs nicht ergründen.\""}
MultiLanguageItemData['de'][139559] = {name = "[q6]Entwurf der Sterne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Entwurf der Sterne\" für Felo'melorn frei.\n[q]\"Ein Plan der Nachtgeborenen für eine Zauberklinge zu Ehren eines Sternbilds, das von ihrem Volk verehrt wird.\""}
MultiLanguageItemData['de'][139560] = {name = "[q6]Immerflammenkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Frostfeuerangedenken\" für Schwarzfrost frei.\n[q]\"Ein gefrorener Kristall, erleuchtet von einem ewigen Feuer, das keinerlei Wärme erzeugt. Ihr könnt ihn ruhig berühren, denn er sieht nicht aus, als würde er jemals schmelzen.\""}
MultiLanguageItemData['de'][139561] = {name = "[q6]Legende des Affenkönigs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Uralter Bräuhüter\" für Fu Zan, Gefährte des Wanderers frei.\n[q]\"Ein ziemlich starkes und besonderes Gebräu, das angeblich vom Affenkönig höchstpersönlich hergestellt wurde. Das Fass sieht kostbar aus und ließe sich vielleicht auch noch für etwas anderes einsetzen als die Lagerung von Gebrautem...\""}
MultiLanguageItemData['de'][139562] = {name = "[q6]Atem der unsterblichen Schlange", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Atem der unsterblichen Schlange\" für Sheilun, Stab der Nebel frei.\n[q]\"Ein wirbelnder Quell magischer Energie, der angeblich aus dem Bauch eines Großdrachen stammt, der älter ist als die Zeit selbst.\""}
MultiLanguageItemData['de'][139563] = {name = "[q6]Die Fäuste des Sturms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Fäuste des Sturms\" für die Fäuste der Himmel frei.\n[q]\"Über die Entstehung der Sturmfaust ist nur wenig bekannt, aber die darin enthaltene Macht scheint sowohl von Therazane als auch von Al'Akir zu stammen – eine eher unerwartete Verbindung.\""}
MultiLanguageItemData['de'][139564] = {name = "[q6]Verlorene Edikte des Behüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Waffen des Wächters\" für die Silberne Hand frei.\n[q]\"Wir haben geschworen, dieser gepeinigten Welt die Hoffnung zurückzugeben, Tyrannei und Unrecht auszulöschen, wo immer wir sie antreffen, und den Hammer der Gerechtigkeit auf jene niederfahren zu lassen, die sich mit dem Bösen eingelassen haben.\""}
MultiLanguageItemData['de'][139565] = {name = "[q6]Funken des gefallenen Exarchen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Bollwerk des Verteidigers\" für den Wahrheitshüter frei.\n[q]\"Als Exarch Kelios fiel, schwand auch die letzte Hoffnung, den Tempel halten zu können. Die Legion hatte gesiegt. Nur ein Gedanke ließ sie jetzt noch Frieden finden: der Gedanke an alle, die entkommen waren. Aber auch das würde ihnen die Legion bald nehmen.\""}
MultiLanguageItemData['de'][139566] = {name = "[q6]Herz der Verderbnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Verderbtes Andenken\" für den Aschenbringer frei.\n[q]\"Ein düsterer Einblick in eine Vergangenheit, die der Aschenbringer hinter sich ließ und von der viele hofften, dass sie niemals wiederaufleben würde.\""}
MultiLanguageItemData['de'][139567] = {name = "[q6]Schriftstücke des Endes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Spitze des Foliantwächters\" für den Zorn des Lichts frei.\n[q]\"Diese Worte, zusammengetragen aus den Folianten des Archivars, ergeben eine düstere Prophezeiung.\""}
MultiLanguageItemData['de'][139568] = {name = "[q6]Stab der Lichtgeborenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Krone der Lichtgeborenen\" für T'uure, Fanal der Naaru frei.\n[q]\"Die Macht der Valkyra lässt den Stab in sanften Tönen schwingen. Berührt man ihn, verstummt er jedoch.\""}
MultiLanguageItemData['de'][139569] = {name = "[q6]Klaue von N'Zoth", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Klaue von N'Zoth\" für Xal'atath, Klinge des Schwarzen Imperiums frei.\n[q]\"Blinzelnde Augen. Pulsierendes Fleisch. Es ist eindeutig am Leben.\""}
MultiLanguageItemData['de'][139570] = {name = "[q6]Die Chiffre des gebrochenen Knochens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Knochenbrecher\" für die Königsmörder frei.\n[q]\"Die Geheimnisse einer längst verstorbenen Assassine, die alle nur 'Die Knochenbrecherin' nannten. Es heißt, sie hätte ihren Opfern stets die Beine gebrochen, nachdem eines von ihnen von den Toten zurückgekehrt war, um sich an ihr zu rächen.\""}
MultiLanguageItemData['de'][139571] = {name = "[q6]Foliant der außerweltlichen Gifte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Giftbiss\" für die Reißzähne des Verschlingers frei.\n[q]\"Ein Text, der über viele Generationen von den Schattenjägern der Zandalari vererbt wurde. Er behandelt ausführlich die exotischen Waffen und Gifte, mit denen sie sich ihrer Feinde entledigten.\""}
MultiLanguageItemData['de'][139572] = {name = "[q6]Verlorener Kodex der Amani", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Stolz der Amani\" für die Faust des Ra-den frei.\n[q]\"Ein lange verlorener Trolltext über den Aufstieg und Fall der Anführer vieler Generationen. Ein großer Teil ist einem Troll namens Atai'natha und der mächtigen magischen Klaue gewidmet, mit der er seinen Befehlen Nachdruck verlieh.\""}
MultiLanguageItemData['de'][139573] = {name = "[q6]Der Kriegskolben von Shirvallah", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Champion der Zandalari\" für den Schicksalshammer frei.\n[q]\"Trotz seiner zierreichen Konstruktion hat dieser brutale Streitkolben viele das Leben gekostet – und das alles zu Ehren der wilden Gottheit Shirvallah. Vor langer Zeit ging die Waffe im Meer verloren, gemeinsam mit dem Hohepriester, der sie einst trug.\""}
MultiLanguageItemData['de'][139574] = {name = "[q6]Spule der ertränkten Königin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Schlangenschlinge\" für Sharas'dal, Szepter der Gezeiten frei.\n[q]\"Nun, da sie sich wie Schlangen unter den Wellen wanden, hatten die Hochgeborenen nichts mehr mit ihrer einstigen Gestalt gemein. Sie waren nun eins mit der Tiefe und dienten etwas Finsterem, das dort lauerte...\""}
MultiLanguageItemData['de'][139575] = {name = "[q6]Essenz des Scharfrichters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Des Schicksals Ende\" für Ulthalesh, Sense der Totenwinde frei.\n[q]\"Diese aus den Schädeln von großen Champions destillierte Essenz verspricht große Macht – sofern man bereit ist, den finsteren Preis zu bezahlen.\""}
MultiLanguageItemData['de'][139576] = {name = "[q6]Gesicht des ersten Erweckers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Thal'kiels Fratze\" für den Schädel der Man'ari frei.\n[q]\"Zu den bekanntesten Phrenologen dieser Zeit gehörten Thal'kiel und Archimonde. Besonders Thal'kiel war für seinen markanten Schädel bekannt – den Inbegriff eines Zaubererhauptes.\""}
MultiLanguageItemData['de'][139577] = {name = "[q6]Das brennende Juwel des Sargeras", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Legionsschrecken\" für das Szepter des Sargeras frei.\n[q]\"Ein dunkles Feuer brennt in den Tiefen dieses blutroten Juwels. Gierig züngeln die Flammen an seinen Kanten empor, als Ihr Euch nähert.\""}
MultiLanguageItemData['de'][139578] = {name = "[q6]Arkanitklingenbrecher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Arkanitklingenbrecher\" für Strom'kar den Kriegsbrecher frei.\n[q]\"Echte Handarbeit von Helgar, dem Meisterschmied der Himmelsfeste. Diese Axt ist wohl mächtiger als jede auf Azeroth hergestellte stählerne Klinge.\""}
MultiLanguageItemData['de'][139579] = {name = "[q6]Die Drachenschlächter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Schneide des Drachentöters\" für die Kriegsschwerter der Valarjar frei.\n[q]\"Zwei furchteinflößende Äxte – hergestellt aus von den Vrykul verzaubertem Runenholz und gekrönt mit den Schädeln erschlagener Großdrachen. Beim Anblick dieser Waffen jubelt das Kriegerherz.\""}
MultiLanguageItemData['de'][139580] = {name = "[q6]Brennende Plattenrüstung des Weltenbrechers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Schaltet die Artefaktvorlage \"Letzter Atem des Weltenbrechers\" für die Schuppe des Erdwächters frei.\n[q]\"In den Rillen fließt dunkles geschmolzenes Blut von Neltharion höchstpersönlich, das seit unzähligen Jahren in seinem einstigen Hort schwelt und darauf wartet, endlich wieder mit einer Schuppe der gleichen Herkunft vereint zu werden.\""}
MultiLanguageItemData['de'][139583] = {name = "Dämonische Rune", additional_info = "Questgegenstand\n[q]\"Auf dem Stein sind unverständliche Zeichen eingraviert.\""}
MultiLanguageItemData['de'][139584] = {name = "[q2]Haftbomben", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft Eurem Ziel eine Haftbombe entgegen, die nach 5 Sek. detoniert und allen Gegnern innerhalb von 5 Metern (375% der Angriffskraft) Schaden zufügt.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden. (30 Sek. Abklingzeit)\n15 Aufladungen"}
MultiLanguageItemData['de'][139585] = {name = "[q2]Rauchpulver", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft das Rauchpulver auf den Boden und verbirgt Euch in einem Rauch, der Euch verschwinden lässt.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden.\n10 Aufladungen"}
MultiLanguageItemData['de'][139586] = {name = "[q2]Disteltee", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt 100 Energie wieder her.\n\n Kann nur auf den Verheerten Inseln genutzt werden. (5 Sek. Abklingzeit)\n10 Aufladungen"}
MultiLanguageItemData['de'][139587] = {name = "[q3]Verdächtige Kiste", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Schurke\n[q2]Benutzen: Verkleidet Euch als eine hölzerne Kiste. (30 Min Abklingzeit)"}
MultiLanguageItemData['de'][139588] = {name = "[q2]Rucksack voller Kampftränke", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Trinkt einen nützlichen Schlachttrank aus dem persönlichen Vorrat eines der Ungekrönten.\n\n Kann nur auf den Verheerten Inseln und Argus verwendet werden. (30 Sek. Abklingzeit)\n6 Aufladungen"}
