MultiLanguageItemData['de'][140094] = {name = "[q6]Von uralter Magie und ihrer Anwendung, ohne die Welt zu zerstören", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eine Sammlung des Wissens vieler großer Erzmagier der Kirin Tor. Enthält genaue Beschreibungen der Torheiten, die fahrlässige Magier vergangener Zeiten begangen haben.\""}
