MultiLanguageItemData['de'][140096] = {name = "[q6]Der Teufelsfoliant von Vorgalus Dor", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Dämonische Aufzeichnungen des verstorbenen Hexenmeisters Vorgalus Dor, die Berichte über viele uralte und mächtige Waffen aus fernen Welten der Legion enthalten.\""}
