MultiLanguageItemData['de'][140098] = {name = "[q6]Die Letzten der Illidari", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eine Abhandlung über Illidans Niederlage am Schwarzen Tempel sowie Spekulation über die Schicksale der vermissten Dämonenjäger, die von ihm ausgebildet wurden.\""}
MultiLanguageItemData['de'][140099] = {name = "[q6]Der Kodex der Toten", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ein Text der Nathrezim, der für die sterblichen Völker Azeroths kaum zu entziffern ist.\""}
