MultiLanguageItemData['de'][140109] = {name = "[q6]Meditation inmitten eines Hurrikans", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Mönch\n[q]\"Eine Anleitung für die Kunst, sich selbst inmitten größten Tumults mit Frieden zu umgeben. Verfasst von Meister Xunsu.\""}
MultiLanguageItemData['de'][140110] = {name = "[q6]Liber Monasterii", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eine heilige Schrift, von der insgesamt nur zwölf Exemplare geschaffen wurden. Von vielen davon nimmt man mittlerweile an, dass sie zerstört wurden.\""}
MultiLanguageItemData['de'][140111] = {name = "[q6]Der Krieg der Winterskorn", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Übersetzungen mehrerer Texte auf irdenen Tafeln, die einen Vrykulkrieg in grauer Vorzeit beschreiben.\""}
MultiLanguageItemData['de'][140112] = {name = "[q6]Das Zeitalter des Galakrond", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Interessante Erzählungen der Historikerin Evelyna über die ersten Drachen, die Hüter von Ulduar und die Ermächtigung der fünf Drachenaspekte.\""}
MultiLanguageItemData['de'][140113] = {name = "[q6]Legenden der Silbernen Hand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n[q]\"Historisch fundierte und von Historikerin Evelyna nacherzählte Legenden über den vermuteten Ursprung der Paladine und ihr Verhältnis zum Licht, die bis an die Wurzeln der Menschheit zurückreichen.\""}
MultiLanguageItemData['de'][140114] = {name = "[q6]Berührung des Abgrunds", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Verbotene Lehren darüber, wie man die Mächte der Leere anzapft und die ihnen innewohnenden Gefahren zu Waffen macht. Verfasst von Natalie Seline.\""}
MultiLanguageItemData['de'][140115] = {name = "[q6]Die Verderbnis der Eredar und die Flucht der Draenei", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ein uralter Text, den die Draenei mit nach Azeroth gebracht hatten, der aber in den ersten Monaten außerhalb der Exodar verloren ging.\""}
MultiLanguageItemData['de'][140116] = {name = "[q6]Modguds Untergang", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eine düstere Geschichte über eine Dunkeleisenzauberin, die ein Werkzeug der Alten Götter erlangte und unweigerlich seiner Verderbnis erlag.\""}
