MultiLanguageItemData['de'][140337] = {name = "Importiertes zähes Stockfleisch", additional_info = "[q2]Benutzen: Stellt im Verlauf von 18 Sek. ( 38 * 18 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Die übermäßige Verwendung von Salz macht dieses Fleisch sehr beliebt in den kleinen ländlichen Städten Azeroths.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][140338] = {name = "Manaumwickelte Pastete aus Geiferzahnleber", additional_info = "[q2]Benutzen: Stellt im Verlauf von 21 Sek. ( 38 * 21 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 1 Ausdauer und Vielseitigkeit.\n[q]\"Diese Pastete wurde in einem Land namens Westfall hausgemacht und zur Frischhaltung mit Mana umwickelt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][140339] = {name = "Hormonfreier Alteraclochkäse", additional_info = "[q2]Benutzen: Stellt im Verlauf von 30 Sek. ( 375 * 30 / 5) Gesundheit wieder her.\n Ihr müsst beim Essen sitzen bleiben.\n[q]\"Der Verkäufer hat behauptet, dies wäre ein Lieblingsgericht am berühmtem Hof von Alterac gewesen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][140340] = {name = "Flasche Sprudelwasser", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 917 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n[q]\"Irgendwie haben sie es geschafft, das Wasser ohne die Nutzung von Magie mit Blasen zu versetzen...\"\nVerkaufspreis:"}
