MultiLanguageItemData['de'][140652] = {name = "[q6]Saat des Solarfeuers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Kombiniert die Saat des Solarfeuers mit einem reinen Tropfen von Shaladrassils Harz, um eine seltene Sonnenblüte zu erschaffen.\nBenötigtDie Traumweber\n- Ehrfürchtig\n[q]\"Ein hell schimmernder Samen aus den Tiefen des Smaragdgrünen Traums. Die Traumweber konnten nie herausfinden, wie man ihn erblühen lässt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][140653] = {name = "[q6]Reiner Tropfen von Shaladrassils Harz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Kombiniert die Saat des Solarfeuers mit einem reinen Tropfen von Shaladrassils Harz, um eine seltene Sonnenblüte zu erschaffen.\n[q]\"Ein einzelner Tropfen leuchtenden Harzes, das angeblich sogar in so gut wie toten Überresten den Funken des Lebens neu entfachen kann.\""}
MultiLanguageItemData['de'][140654] = {name = "Modriger Balg von Nythendra", additional_info = "Questgegenstand\n[q]\"Dieser Balg wurde fast vollständig von Insekten zerfressen.\""}
