MultiLanguageItemData['de'][140656] = {name = "[q6]Rute des Aufgestiegenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Kombiniert die Krone der Lichtgeborenen mit der Rute des Aufgestiegenen, um den Stab der Lichtgeborenen zu erschaffen.\nBenötigtValarjar\n- Ehrfürchtig\n[q]\"Ein exquisiter Stab, der für einen längst vergessenen Vrykulmystiker geschaffen wurde, um große Macht zu kanalisieren. Ohne das richtige Kopfstück ist der Stab jedoch inaktiv.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][140657] = {name = "[q6]Krone der Lichtgeborenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\n[q2]Benutzen: Kombiniert die Krone der Lichtgeborenen mit der Rute des Aufgestiegenen, um den Stab der Lichtgeborenen zu erschaffen.\n[q]\"Ein verziertes Kopfstück, erfüllt von pulsierender heiliger Kraft. Mit dem richtigen Instrument, um seine Macht zu kanalisieren, wäre dies eine mächtige Waffe des Lichts.\""}
MultiLanguageItemData['de'][140658] = {name = "[q6]Schädel von Nithogg", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Fügt den Griff des Gottkönigs mit dem Schädel von Shar'thos und dem Schädel von Nithogg zusammen, um die Drachenschlächter zu erschaffen.\n[q]\"Ein gewaltiger Drachenschädel, in dem Nithoggs donnernde Macht immer noch knistert.\""}
MultiLanguageItemData['de'][140659] = {name = "[q6]Schädel von Shar'thos", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Fügt den Griff des Gottkönigs mit dem Schädel von Shar'thos und dem Schädel von Nithogg zusammen, um die Drachenschlächter zu erschaffen.\n[q]\"Ein gewaltiger Drachenschädel, in dem Shar'thos' alptraumhafte Macht immer noch vibriert.\""}
MultiLanguageItemData['de'][140660] = {name = "[q6]Griff des Gottkönigs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\n[q2]Benutzen: Fügt den Griff des Gottkönigs mit dem Schädel von Shar'thos und dem Schädel von Nithogg zusammen, um die Drachenschlächter zu erschaffen.\n[q]\"Ein gewaltiger Griff für eine Großaxt, aber ohne Axtklinge. Das Holz ist mit mystischen Vrykulrunen verziert. Der Griff ist eindeutig für Vrykulkrieger gemacht, aber er ist so segmentiert, dass man ihn in Schäfte für zwei Äxte teilen könnte...\""}
