MultiLanguageItemData['de'][140789] = {name = "[q4]Animiertes Exoskelett", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Ausdauer\n[q2]Benutzen: Verringert für 15 Sek. sämtlichen erlittenen Schaden um 30%, bis insgesamt [ 248 * (1 + Vielseitigkeit)] Schaden verhindert wurden. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][140790] = {name = "[q4]Klaue des kristallinen Skorpiden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\n[q2]Anlegen: Eure Angriffe haben eine Chance, eine Schaden verursachende Schockwelle auszulösen, die Gegnern vor Euch 34 körperlichen Schaden zufügt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][140791] = {name = "[q4]Königliches Dolchheft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Anlegen: Absorbiert bis zu 6587 Schaden eines Angriffs, der Euch töten würde. Wenn dieser Effekt auftritt, werdet Ihr sofort um 178 Gesundheit geheilt und erleidet danach im Verlauf von 10 Sek. den gesamten verhinderten Schaden. Dies kann nur einmal alle 6 Min. geschehen.\n[q]\"Sand rieselt aus der gesprungenen Glaskugel am Ende des Griffs.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][140792] = {name = "[q4]Unstetes Metronom", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\n{[q2]Anlegen: Eure Schaden}szauber haben eine Chance, Euch 12 Sek. lang 4 {Tempo zu gewähren. Dieser Effekt ist bis zu 5-mal stapelbar. Die einzelnen Stapel erneuern nicht die Effektdauer.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][140793] = {name = "[q4]Perfekt erhaltener Kuchen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Benutzen: Erschafft für 20 Sek. ein magisches Festmahl. Bis zu 5 Verbündete, die am Festmahl teilnehmen, absorbieren 12 Sek. lang 179 Schaden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][140794] = {name = "[q4]Finger des Arkanogolems", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, alle Gegner vor Euch zu zerfetzen und ihnen 14 Arkanschaden zuzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][140795] = {name = "[q4]Aluriels Spiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Anlegen: Eure Heilzauber haben eine Chance, dem Ziel 'Gelassenheit des Nachtbrunnens' zu gewähren, die im Verlauf von 12 Sek. 60 Gesundheit regeneriert. Das Heilen eines Ziels, das von 'Gelassenheit des Nachtbrunnens' betroffen ist, kann eine Detonation auslösen, die Verbündete in der Nähe um 10 Gesundheit heilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][140796] = {name = "[q4]Verschlungene Elementarfokusse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Euch für 20 Sek. eine Feuer-, Frost- oder Arkanverzauberung zu gewähren.\nVerkaufspreis:"}
