MultiLanguageItemData['de'][140798] = {name = "[q4]Ikone des Verrottens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Anlegen: Eure Distanzangriffe und Zauber haben eine Chance, einen Aasschwarm zu entfesseln, der alle Gegner in einer Linie vor Euch infiziert und ihnen im Verlauf von 8 Sek. ( 21 * 4) Schattenschaden zufügt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][140799] = {name = "[q4]Macht von Krosus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\n[q2]Benutzen: Entfesselt ein kolossales Schmettern, das immer kritisch trifft und 119 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. Wenn Ihr weniger als 3 Ziele trefft, wird die Abklingzeit der Fähigkeit um 15 Sek. verringert. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][140800] = {name = "[q4]Pharameres verbotenes Grimoire", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Benutzen: Entsendet eine Sphäre der Zerstörung zur Position Eures Ziels in mindestens 10 Metern Entfernung, die nach 4 Sek. allen Gegnern innerhalb von 20 Metern 137 Schattenschaden zufügt. Ziele, die sich näher an der Explosion befinden, erleiden mehr Schaden. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][140801] = {name = "[q4]Zorn des brennenden Himmels", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Anlegen: Eure Distanzangriffe und Zauber haben eine Chance, an der Position Eures Ziels einen Solarkollaps hervorzurufen, der nach 3 Sek. Gegnern in der Nähe 63 Feuerschaden zufügt. (3s Abklingzeit)\nVerkaufspreis:"}
