MultiLanguageItemData['de'][141040] = {name = "Technik: Glyphe 'Wildes Chamäleon'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Wildes Chamäleon' herstellt.\n[q2]Stellt eine Glyphe 'Wildes Chamäleon' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Wildes Chamäleon'\nKlassen: Druide\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Katzengestalt annehmt, wird Eure verwandelte Gestalt zufällig ausgewählt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)"}
MultiLanguageItemData['de'][141041] = {name = "Technik: Glyphe 'Waldpfad'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Waldpfad' herstellt.\n[q2]Stellt eine Glyphe 'Waldpfad' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Waldpfad'\nKlassen: Druide\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Spurt' hinterlässt nun eine Spur von Blättern.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)"}
