MultiLanguageItemData['de'][141043] = {name = "Technik: Glyphe 'Arachnophobie'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Arachnophobie' herstellt.\n[q2]Stellt eine Glyphe 'Arachnophobie' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Arachnophobie'\nKlassen: Jäger\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Alphatier' werden öfter Spinnen herbeigerufen. Warum? Weil einfach jeder Angst vor Spinnen hat. Exklusiv mit: Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel' Glyphe 'Killerbienen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)"}
MultiLanguageItemData['de'][141044] = {name = "Technik: Glyphe 'Nesingwarys Nemesis'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Nesingwarys Nemesis' herstellt.\n[q2]Stellt eine Glyphe 'Nesingwarys Nemesis' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Nesingwarys Nemesis'\nKlassen: Jäger\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Alphatier' werden oft Wildtiere herbeigerufen, die für gewöhnlich Opfer des berühmten Jägers sind. Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Alpharudel' Glyphe 'Killerbienen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)"}
MultiLanguageItemData['de'][141045] = {name = "[q0]Veraltete Technik", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\n[q]\"Es sieht zwar aus, als wäre dieses Rezept entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][141046] = {name = "Technik: Glyphe 'Alpharudel'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Alpharudel' herstellt.\n[q2]Stellt eine Glyphe 'Alpharudel' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Alpharudel'\nKlassen: Jäger\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Alphatier' ruft häufig Alphavarianten Eurer Begleiter im Stall herbei. Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Nesingwarys Nemesis' Glyphe 'Killerbienen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)"}
