MultiLanguageItemData['de'][141054] = {name = "Technik: Glyphe 'Qualmen'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Qualmen' herstellt.\n[q2]Stellt eine Glyphe 'Qualmen' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Qualmen'\nKlassen: Magier\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nNach dem Einsatz von 'Einäschern' qualmt ihr nun für einige Sekunden.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)"}
MultiLanguageItemData['de'][141055] = {name = "Technik: Glyphe 'Yu'lons Anmut'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Glyphe 'Yu'lons Anmut' herstellt.\n[q2]Stellt eine Glyphe 'Yu'lons Anmut' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nGlyphe 'Yu'lons Anmut'\nKlassen: Mönch\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert die Farbe der Kugeln Eurer 'Gabe des Ochsen' in das Grün von Yu'lon.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)"}
