MultiLanguageItemData['de'][141294] = {name = "[q3]Zeichen von Orgrimmar", additional_info = "Wird beim Aufheben gebunden\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n[q]\"Wird den Kriegern der Horde verliehen, die sich mutig in die Schlacht an der Verheerten Küste stürzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][141295] = {name = "[q2]Außerordentlich dickes Mojo", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Trinkt das Mojo, um 5 Min. lang alle 3 Sek. 5% Gesundheit wiederherzustellen und Angreifern Naturschaden zuzufügen. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\n[q]\"Riecht frisch.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][141296] = {name = "[q3]Uraltes Manabecken", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Erschafft für 2 Min. ein schwebendes Manabecken. Gruppen- und Schlachtzugsmitglieder können das Becken verwenden, um einen Manakatalysator zu erhalten, der den Effekt herbeigezauberter Nahrung sowie in Suramar gekaufter magischer Nahrung erhöht. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][141297] = {name = "[q3]Arkandusche", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Stellt für 2 Min. die Arkandusche auf. Die arkanen Ströme reinigen nicht nur durch Kleidung hindurch, sie reinigen die Kleidung auch gleich mit! (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][141298] = {name = "[q3]Entrückender Meditationsstein", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Fokussiert Euch auf den Stein und denkt an etwas Schönes. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][141299] = {name = "[q3]Lichtkugel der Kaldorei", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Platziert für 1 Min. eine Lichtkugel der Kaldorei. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][141300] = {name = "[q3]Fokussierkristall der Magier", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Fokussiert das, was einst ein mächtiger Arkanstrahl war, auf Ziele vor Euch. (3 Min Abklingzeit)"}
MultiLanguageItemData['de'][141301] = {name = "[q3]Instabile Puderdose", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Öffnet die ominös leuchtende Puderdose."}
