MultiLanguageItemData['de'][141331] = {name = "[q3]Phiole mit grünem Schleim", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Bespritzt Euch selbst mit dem Schleim, der Euch in einen Lepragnom verwandelt. (10 Min Abklingzeit)\n[q]\"Es ist umkehrbar. Vielleicht hat Thermadraht ja tatsächlich an einem Heilmittel gearbeitet...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][141332] = {name = "[q6]Die Annalen von Licht und Schatten", additional_info = "Wird beim Aufheben gebunden\nKlassen: Priester\n[q]\"Die zwölf Bände beschreiben detailreich alles Wissenswerte über die Konklave und ihre Mitglieder. Archivar Tintenschmiede scheint sehr daran interessiert zu sein, die komplette Sammlung zu bergen.\""}
MultiLanguageItemData['de'][141333] = {name = "Kodex des ruhigen Gemüts", additional_info = "[q2]Benutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln. Funktioniert nicht bei Zielen über Stufe 50.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][141334] = {name = "Mächtiger Sauereientferner", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Trinkt das Gebräu, das Euch sofort verschwinden und für 10 Sek. in Verstohlenheit übergehen lässt. Jede Aktion bricht den Effekt ab. Kann nur im Kampf eingesetzt werden.\n[q]\"Praktisch zum Entfernen von unbeabsichtigten Sauereien. Auch praktisch zum Entfernen der eigenen Person vom Schauplatz unbeabsichtigter Sauereien.\""}
MultiLanguageItemData['de'][141335] = {name = "[q6]Verlorene Forschungsnotizen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lesen, um neues Wissen über Euer Artefakt zu erlangen und die Rate zu erhöhen, mit der Ihr Artefaktmacht erlangt.\n[q]\"Diese einwandfrei erhaltenen Notizen über uralte Waffen stammen vom alten Fillmaff und wurden von einem nachlässigen Kurier fallen gelassen.\""}
