MultiLanguageItemData['de'][142225] = {name = "[q4]Ban-Lu, Begleiter des Großmeisters", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Begleiter Ban-Lu oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Xuens Kind Ban-Lu hat jedem Großmeister viele Jahre treu gedient.\"\nQuest:\nDie Prüfung des Ban-Lu"}
MultiLanguageItemData['de'][142226] = {name = "[q4]Vertrauen eines wilden Wolfsfalken", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen reitbaren wilden Wolfsfalken des Meisterjägers beschwört.\n[q2]Beschwört Euren wilden Wolfsfalken des Meisterjägers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Knäuel aus Krallen und Klauen, das fliegen und schwimmen kann. Niemand ist davor sicher.\"\nVerkäufer:\nPan die sanfte Hand\nZone:\nDie Volltrefferhütte"}
MultiLanguageItemData['de'][142227] = {name = "[q4]Vertrauen eines treuen Wolfsfalken", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen reitbaren treuen Wolfsfalken des Meisterjägers beschwört.\n[q2]Beschwört Euren treuen Wolfsfalken des Meisterjägers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Geist des großen Jägers hat Euch als würdig erachtet. Seine Kinder werden von nun an auf ewig Eurem Ruf folgen.\"\nQuest:\nNacht der Wildnis"}
MultiLanguageItemData['de'][142228] = {name = "[q4]Vertrauen eines schrecklichen Wolfsfalken", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen reitbaren schrecklichen Wolfsfalken des Meisterjägers beschwört.\n[q2]Beschwört Euren schrecklichen Wolfsfalken des Meisterjägers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Apportiert mit hoher Wahrscheinlichkeit den Kopf eines kleinen Säugetiers oder Humanoiden.\"\nVerkäufer:\nPan die sanfte Hand\nZone:\nDie Volltrefferhütte"}
MultiLanguageItemData['de'][142231] = {name = "[q4]Verrottende Zügel des Giftbrutbezwingers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen Giftbrutbezwinger des Todesgebieters beschwört.\n[q2]Beschwört Euren Giftbrutbezwinger des Todesgebieters oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein mächtiger roter Großdrache, der von seiner eigenen Lebensenergie zum Untod erweckt wurde. Wahrhaft eine Verhöhnung des Lebens.\"\nQuest:\nDer Verlorene Gletscher"}
MultiLanguageItemData['de'][142232] = {name = "[q4]Eiserne Zügel des blutrünstigen Kriegswyrms", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen blutrünstigen Kriegswyrm des Schlachtenfürsten beschwört.\n[q2]Beschwört Euren blutrünstigen Kriegswyrm des Schlachtenfürsten oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Hört auch auf \"Herr Beißi\".\"\nQuest:\nDie Prüfung des Zorns"}
