MultiLanguageItemData['de'][142400] = {name = "[q2]Fortgeschrittene Zielfindungskugel", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Befehlt Euren widerstandsfähigen Verdorrten, ihren Widerstand gegen Teufelsmagie auf die Probe zu stellen. (5 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][142401] = {name = "Telemantische Kugeln", additional_info = "Einzigartig\n[q2]Benutzen: Schleudert eine telemantische Kugel an den Zielort und ruft dort hungernde Verdorrte herbei. Funktioniert nur im Adelsviertel von Suramar. (45 Sek. Abklingzeit)\n[q]\"Ein Trupp aus Verdorrten, der sofort erscheint.\""}
MultiLanguageItemData['de'][142402] = {name = "[q3]Pläne: Leichte erdgeschmiedete Klinge", additional_info = "[q2]Benutzen: Lehrt Euch die Herstellung einer leichten erdgeschmiedeten Klinge.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\n[q3]Leichte erdgeschmiedete Klinge\nWird beim Aufheben gebunden\n{Einhändig} {Schwert}\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Mithrilbarren (12), Erdenkern (4)\n Optionale Reagenzien: [] (#31)"}
MultiLanguageItemData['de'][142403] = {name = "[q4]Bulliger Basilisk des Grubenkämpfers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren bulligen Basilisken des Grubenkämpfers oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Stacheln auf dieser Bestie können Plattenrüstungen mit Leichtigkeit durchdringen. Nur die bestausgebildetsten Reiter können überhaupt daran denken, auf diesem tödlichen Nadelkissen zu sitzen.\"\nVerkäufer:\nQuackenbusch\nZone:\nDie Tiefenbahn\nKosten:\n\nVerkäufer:\nPaul Norden\nZone:\nShlae'gararena\nKosten:"}
