MultiLanguageItemData['de'][142406] = {name = "[q2]Trommeln des Berges", additional_info = "[q2]Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\n Wenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\n Wirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][142407] = {name = "Muster: Trommeln des Berges", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung von Trommeln des Berges.\n[q2]Stellt Trommeln des Berges her.\nBenötigt Lederverarbeitung der Verheerten Inseln (1)\nVerkaufspreis:\n[q2]Trommeln des Berges\n[q2]Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\n Wenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\n Wirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Steinbalgleder (10), Intakte Kralle (5), Intakter Zahn (5)"}
MultiLanguageItemData['de'][142408] = {name = "Muster: Trommeln des Berges", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung von Trommeln des Berges.\n[q2]Verringert die erforderlichen Materialien zur Herstellung von Trommeln des Berges.\nBenötigt Lederverarbeitung der Verheerten Inseln (1)\nBenötigtDer Hochbergstamm\n- Respektvoll\nVerkaufspreis:\n[q2]Trommeln des Berges\n[q2]Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\n Wenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\n Wirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Steinbalgleder (8), Intakte Kralle (3), Intakter Zahn (3)"}
