MultiLanguageItemData['de'][143478] = {name = "[q3]Arenaeinladung", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Eine sorgfältig mit dem Blut der Gefallenen verfasste Notiz.\""}
MultiLanguageItemData['de'][143479] = {name = "[q0]Ausgefranstes Banner", additional_info = "Wird beim Aufheben gebunden\n[q]\"Blutverschmiert und zerrissen, doch das macht es nur noch prächtiger.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143486] = {name = "[q0]Barriere des Arkusformers", additional_info = "Wird beim Aufheben gebunden\n[q]\"Der Arkusformer gab sich bei dem Kristall viel Mühe. Die Macht kann unterdrückt werden, aber selbst dann ist sie noch stark.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143487] = {name = "[q0]Verzauberte Dämmerlilie", additional_info = "Wird beim Aufheben gebunden\n[q]\"Gelegentlich findet man Dämmerlilien von großer Macht. Vermutlich ist das auch der Grund, warum sie zu einem so bedeutenden Symbol geworden sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143488] = {name = "[q0]Verzauberte Nachtgeborenenmünze", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Münze wurde seit Generationen weitergegeben und enthält nachklingendes Wissen seiner ehemaligen Besitzer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143489] = {name = "[q4]Totem des wütenden Sturms", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen wütenden Sturm des Scharfsehers beschwört.\n[q2]Beschwört Euren wütenden Sturm des Scharfsehers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Windzorn. Überladung: (2).\"\nQuest:\nZorn der Stürme"}
MultiLanguageItemData['de'][143490] = {name = "[q4]Blutige Zügel des düsteren Vorboten", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein blutrotes Omen der Schattenklinge beschwört.\n[q2]Beschwört Euer blutrotes Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Auf ihm sieht man das Blut Eurer Feinde gar nicht erst.\"\nVerkäufer:\nZan Messerritzel\nZone:\nDalaran"}
MultiLanguageItemData['de'][143491] = {name = "[q4]Verpestete Zügel des düsteren Vorboten", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein unheilvolles Omen der Schattenklinge beschwört.\n[q2]Beschwört Euer unheilvolles Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Für die giftig Veranlagten.\"\nVerkäufer:\nZan Messerritzel\nZone:\nDalaran"}
MultiLanguageItemData['de'][143492] = {name = "[q4]Nachtschwarze Zügel des düsteren Vorboten", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein tödliches Omen der Schattenklinge beschwört.\n[q2]Beschwört Euer tödliches Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Euch wird niemand kommen hören.\"\nVerkäufer:\nZan Messerritzel\nZone:\nDalaran"}
MultiLanguageItemData['de'][143493] = {name = "[q4]Klingengesäumte Zügel des düsteren Vorboten", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein mörderisches Omen der Schattenklinge beschwört.\n[q2]Beschwört Euer mörderisches Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das ideale Fortbewegungsmittel für Meuchelmörder, da es beim Fliegen geräuschlos bleibt. Nützlich, wenn man sich anschleichen möchte.\"\nQuest:\nVor aller Augen verborgen"}
MultiLanguageItemData['de'][143494] = {name = "Eine geheimnisvolle Notiz", additional_info = "Questgegenstand\n[q]\"Stammt anscheinend von einem der Kultisten, von denen Karam sprach.\"\n[q2]<Zum Lesen rechtsklicken>"}
