MultiLanguageItemData['de'][143498] = {name = "[q0]Finger des aufgeladenen Konstrukts", additional_info = "Wird beim Aufheben gebunden\n[q]\"Die Magistrix wird langsam leichtsinnig. Schon der kleine Finger dieses Dings verfügt über genug Macht, um den halben Palast einzureißen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143499] = {name = "[q0]Überladene Maske des Infiltrators", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Maske wurde unter Zeitdruck gefertigt und mit zu viel Macht erfüllt. Sie ist kurz davor zu platzen.\"\nVerkaufspreis:"}
