MultiLanguageItemData['de'][143502] = {name = "[q4]Schimmernde Zügel des goldenen Streitrosses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein goldenes Streitross des Hochlords beschwört.\n[q2]Beschwört Euer goldenes Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das vornehmste aller Rösser.\"\nQuest:\nSuche in den Schatten"}
MultiLanguageItemData['de'][143503] = {name = "[q4]Strenge Zügel des rachsüchtigen Streitrosses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein rachsüchtiges Streitross des Hochlords beschwört.\n[q2]Beschwört Euer rachsüchtiges Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Es ist unklar, warum genau es so auf Rache aus ist.\"\nVerkäufer:\nKreuzfahrerlord Dalfors\nZone:\nDas Sanktum des Lichts"}
MultiLanguageItemData['de'][143504] = {name = "[q4]Stoische Zügel des wachsamen Streitrosses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein wachsames Streitross des Hochlords beschwört.\n[q2]Beschwört Euer wachsames Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der ausdruckslose Blick dieses Rosses ist in Wahrheit ein Zeichen von \"Wachsamkeit\".\"\nVerkäufer:\nKreuzfahrerlord Dalfors\nZone:\nDas Sanktum des Lichts"}
MultiLanguageItemData['de'][143505] = {name = "[q4]Heraldische Zügel des tapferen Streitrosses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man ein tapferes Streitross des Hochlords beschwört.\n[q2]Beschwört Euer tapferes Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Verfügt über viele Punkte, die für seine Tapferkeit sprechen.\"\nVerkäufer:\nKreuzfahrerlord Dalfors\nZone:\nDas Sanktum des Lichts"}
