MultiLanguageItemData['de'][143533] = {name = "[q0]Machterfüllter Grubenlordhauer", additional_info = "Wird beim Aufheben gebunden\n[q]\"Rozzeleth war schon immer ein mächtiger Dämon, doch während seiner Stationierung in Suramar hat er wohl viel uraltes Mana aufgenommen. Nach der Trennung von seinem dämonischen Körper summt der Hauer noch immer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143534] = {name = "[q3]Zauberstab des simulierten Lebens", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Fokussiert Arkanmagie, um ein lebendes Konstrukt zu erschaffen. Es ist unbekannt, was für Formen dieses annehmen kann.\n[q]\"Von Magus Willem West hergestellt.\""}
