MultiLanguageItemData['de'][143537] = {name = "Manafokus", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Während das Licht diesen Gegenstand durchdringt, wird es auf merkwürdige Art und Weise gebrochen und verzerrt.\""}
MultiLanguageItemData['de'][143538] = {name = "[q0]Umschlungene telemantische Kugel", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält gleichzeitig alle möglichen Telemantieergebnisse. Theoretisch könnte es Euch an jeden beliebigen Ort bringen. Tatsächlich schien es jedoch nur dem Ruf der Natur zu folgen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143539] = {name = "[q2]Versteckter Gürtel", additional_info = "Kosmetisch\nTaille Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][143540] = {name = "[q0]Fehlkonfigurierter Abstimmungskristall", additional_info = "Wird beim Aufheben gebunden\n[q]\"Lasst Euch nicht täuschen, auch wenn es nicht den Leylinienmanipulator ausschalten konnte, ist es äußerst mächtig.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143542] = {name = "[q2]Allheilmittelchen der Firma Krone", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: \"Heilt\" alle Gifte, Krankheiten, Flüche, Verhexungen, Geister, Verzauberungen, magischen Effekte und Kahlköpfigkeit. (1 Min Abklingzeit)\n[q]\"Dieser Trank wurde nicht vom Amt für Alchemie zugelassen. Durch Einnahme dieses Tranks übernimmt der Trinker jegliche Verantwortung für dessen Auswirkungen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][143543] = {name = "[q4]Zwölfsaitige Gitarre", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Schlägt die Saiten ein paar Mal an und spielt eine unheimliche und unvergessliche Melodie. (1 Stunde, 6 Min Abklingzeit)"}
MultiLanguageItemData['de'][143544] = {name = "[q3]Schädel der Verderbnis", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Dämonenjäger\n[q2]Benutzen: Sinnt über die Macht nach, die aus dem dämonischen Schädel dringt. (30 Sek. Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n[q]\"Nicht alle Magie eines Dämons kehrt in den Wirbelnden Nether zurück.\""}
