MultiLanguageItemData['de'][144236] = {name = "[q5]Mantel des Meisterassassinen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Leder}\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Schurke\n[q2]Anlegen: Erhöht in Verstohlenheit und 5 Sek. nach dem Verlassen der Verstohlenheit Eure kritische Trefferchance um 100%.\n[q]\"Fürchtet nicht das, was Ihr sehen könnt. Fürchtet das, was Ihr nicht kommen seht. – Mathias Shaw, SI:7\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144238] = {name = "Uralte Knochen", additional_info = "Questgegenstand\n[q]\"Nicht identifizierte und undatierte Überreste.\""}
MultiLanguageItemData['de'][144239] = {name = "[q5]Der kaiserliche Kondensator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Leder}\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Mönch\n[q2]Anlegen: Chi verbrauchende Fähigkeiten erhöhen den Schaden Eures nächsten Einsatzes von 'Knisternder Jadeblitz' um 100% und verringern seine Kosten um 5%. Bis zu 20-mal stapelbar.\n[q]\"Gestohlen vom hohen Hüter Ra-den, dem gefallenen Hüter der Stürme.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144240] = {name = "Verwüstete Vorräte", additional_info = "Questgegenstand\n[q]\"Von nur wenig Teufelsschleim bedeckt. Vermutlich noch in Ordnung.\""}
MultiLanguageItemData['de'][144241] = {name = "Teufelserfüllte Überreste", additional_info = "Questgegenstand\n[q]\"Teufelsenergien haben diesen Knochen schwer zugesetzt.\""}
MultiLanguageItemData['de'][144242] = {name = "[q5]X'onis Umarmung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Leder}\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Druide\n[q2]Anlegen: 'Eisenborke' klingt 20% schneller ab. Außerdem erhalten von Eurer 'Eisenborke' geschützte Verbündete zusätzlich 75% der Heilung all Eurer Effekte von 'Verjüngung', die derzeit aktiv sind.\n[q]\"X'onis bloße Präsenz erfüllte ihre Verbündeten mit Lebensfreude. Obwohl sie eine der mächtigsten Druidinnen aller Zeiten war, erlernte sie viele ihrer Fertigkeiten von der legendären Priesterin Phyrix.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144243] = {name = "[q4]Arsenal: Waffen des bösartigen Gladiators", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt die Vorlagen des Waffensets des bösartigen Gladiators."}
MultiLanguageItemData['de'][144244] = {name = "[q5]Kam Xi'raff", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Priester\n[q2]Anlegen: Verringert die Kosten Eurer Heilzauber um 3%.\n[q2]Anlegen: Der Einsatz von 'Zorn des Lichts' verringert die Manakosten Eurer Zauber 1 Sek. lang um 50%. Hält 1 Sek. länger für jeden Verbündeten an, der mit Eurer 'Abbitte' belegt ist.\n[q]\"Benannt nach einem unvergleichlichen Priester, dessen Namen niemand je aussprechen konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144245] = {name = "[q4]Arsenal: Waffen des tyrannischen Gladiators", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt die Vorlagen des Waffensets des tyrannischen Gladiators."}
