MultiLanguageItemData['de'][144247] = {name = "[q5]Rammals Hintergedanke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Wenn 'Gebet der Besserung' heilt, belegt es den Verbündeten 10 Sek. lang mit 'Rammals Hintergedanke' und erhöht damit den Effekt Eures nächsten Einsatzes von 'Blitzheilung', 'Heilung' oder 'Segenswort: Epiphanie', das Ihr auf ihn wirkt, um 20%.\n[q]\"Nachdem Rammal seine wahre Gestalt enthüllte, erkannte Verius schon bald seine Beweggründe.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144248] = {name = "[q4]Arsenal: Waffen des stolzen Gladiators", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt die Vorlagen des Waffensets des stolzen Gladiators."}
MultiLanguageItemData['de'][144249] = {name = "[q5]Archimondes wiedergeborener Hass", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]+ 4 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n[q2]Benutzen: Verleiht Euch 10 Sek. lang einen Absorptionsschild, der 30% Eurer maximalen Gesundheit entspricht. Wenn der Schild verbraucht ist oder abläuft, wird 75% der absorbierten Menge gleichmäßig unter Gegnern in der Nähe als Schaden aufgeteilt. (1 Min, 15 Sek. Abklingzeit)\n[q]\"Archimonde der Entweiher, Heerführer der Legionsarmee, kontrolliert grenzenlose Mächte und vernichtete zahllose Welten in der Unendlichkeit der Universen.\"\nVerkaufspreis:"}
