MultiLanguageItemData['de'][144273] = {name = "[q5]Maraads letzter Atemzug", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nKlassen: Paladin\n[q2]Anlegen: Die Heilung von 'Licht der Morgendämmerung' bewirkt, dass Euer nächster Einsatz von 'Licht des Märtyrers' zusätzlich Eure 'Flamme des Glaubens' heilt. Jeder von 'Licht der Morgendämmerung' geheilte Verbündete erhöht die Heilung von 'Licht des Märtyrers' um 10%.\n[q]\"Im Licht sind wir eins.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144274] = {name = "[q5]Gravitationsspirale", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Magier\n[q2]Anlegen: Verleiht Eurer Fähigkeit 'Hervorrufung' 1 zusätzliche Aufladung.\n[q]\"Die Existenz und Rekombination verschiedener Kräfte und Energien erschafft oft mächtige Manawirbel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144275] = {name = "[q5]Saruans Entschlossenheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Platte}\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]+ 6 Vielseitigkeit\nHaltbarkeit 120 / 120\nKlassen: Paladin\n[q2]Anlegen: 'Licht des Beschützers' erhält 1 zusätzliche Aufladung und klingt 10% schneller ab.\n[q]\"Entgegen der Lügen von Matis dem Grausamen blieb Saruan bis zu seinem Abschied vom Licht standhaft.\"\nVerkaufspreis:"}
