MultiLanguageItemData['de'][144277] = {name = "[q5]Ambossgehärtete Gelenkbänder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\n[q2]Anlegen: Wenn Ihr ausweicht oder ein Gegner Euch verfehlt, wird die verbleibende Abklingzeit Eurer Gebräue jedes Mal um 1.0 Sek. verringert. (1s Abklingzeit)\n\"Einst gehörten sie Wei Schnellbräu, Meister der Brau- und Schmiedekunst.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144279] = {name = "[q5]Größenwahn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Leder}\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Dämonenjäger\n[q2]Anlegen: Verringert die verbleibende Abklingzeit von 'Metamorphose' pro 30 verbrauchtem Jähzorn um 1 Sek.\n[q]\"Mehr Macht... um jeden Preis.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144280] = {name = "[q5]Todesmarsch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Platte}\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\n[q2]Anlegen: 'Todesstoß' und 'Todesmantel' verursachen 10% mehr Schaden und verringern die verbleibende Abklingzeit von [ Entweihen : 'Entweihen' / 'Tod und Verfall'] um 2.0 Sek.\n[q]\"In dieser Welt ist nichts gewiss, außer dem Tod.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][144281] = {name = "[q5]Schädelblumes Hämostase", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Platte}\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]+ 3 Vielseitigkeit\nHaltbarkeit 120 / 120\nKlassen: Todesritter\n[q2]Anlegen: 'Siedendes Blut' erhöht den verursachten Schaden sowie die hervorgerufene Heilung Eures nächsten Einsatzes von 'Todesstoß' um 20%. Bis zu 5-mal stapelbar. (500ms Abklingzeit)\n[q]\"Blut um Blut.\"\nVerkaufspreis:"}
