MultiLanguageItemData['de'][147004] = {name = "[q4]Meeresstern der Tiefenmutter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Euer Gruppenheilzauber hat eine Chance, Euch 'Umarmung des Ozeans' zu gewähren, wodurch Euer nächster verletzter Verbündeter innerhalb von 15 Metern 8 Sek. lang alle 0.25 Sek. um 7 Gesundheit geheilt wird. Gilt für Heilerspezialisierungen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][147005] = {name = "[q4]Kelch des Mondlichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\n[q2]Anlegen: Eure Heilzauber haben eine Chance, Euren kritischen Trefferwert oder Euer Tempo für 12 Sek. um 22 zu erhöhen. Dieser Effekt gewährt tagsüber kritischen Trefferwert und nachts Tempo.\nVerkaufspreis:"}
MultiLanguageItemData['de'][147006] = {name = "[q4]Archiv des Glaubens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Benutzen: Kanalisiert eine läuternde Matrix in einen Verbündeten, die ihn im Verlauf von 3 Sek. um 439 Gesundheit heilt. Wenn die Kanalisierung vollständig abgeschlossen wird, erhält das Ziel zusätzlich für 10 Sek. einen Schild, der 160 Schaden verhindert. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][147007] = {name = "[q4]Des Betrügers großer Plan", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Benutzen: Markiert einen verbündeten Spielercharakter mit 'Leitende Hand' und heilt ihn so 2 Min. lang alle 3.0 Sek. um 22 Gesundheit. Falls seine Gesundheit unter 35% fällt, wird 'Leitende Hand' aufgezehrt und gewährt ihm einen Schild, der 15 Sek. lang [(1 + Vielseitigkeit) * 379 ] Schaden verhindert (2 Min. Wiederaufladezeit, 2 Aufladungen).\nVerkaufspreis:"}
MultiLanguageItemData['de'][147009] = {name = "[q4]Höllenasche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, zusätzlich 20 Feuerschaden zu verursachen. Die kritische Trefferchance dieses Schadens wird für jeden Verbündeten innerhalb von 10 Metern, der diesen Gegenstand trägt, um 10% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][147010] = {name = "[q4]Wiege des Kummers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Anlegen: Solange Ihr bei mehr als 80% Gesundheit seid, erhaltet Ihr je nach Spezialisierung 1 Stärke oder Beweglichkeit pro Sekunde. Dieser Effekt ist bis zu 10-mal stapelbar. Wenn Eure Gesundheit unter 50% fällt, endet dieser Effekt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][147011] = {name = "[q4]Phiole des unablässigen Toxins", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Fügt einem Gegner in Nahkampfreichweite 56 Schattenschaden sowie zusätzlich im Verlauf von 20 Sek. 91 Schaden zu. Wenn der Gegner stirbt, während der Effekt aktiv ist, wird die Abklingzeit dieser Fähigkeit um 45 Sek. verringert. (1 Min Abklingzeit)\n[q]\"Diese toxischen Wellen ebben niemals ab.\"\nVerkaufspreis:"}
