MultiLanguageItemData['de'][147864] = {name = "[q3]Banner der Legionsrichter", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert ein Banner der Legionsrichter auf dem Boden. Auf den Verheerten Inseln verringert es den erlittenen Schaden von Spielercharakteren innerhalb von 30 Metern um 5%. (1 Stunde Abklingzeit)\nBenötigtDie Legionsrichter\n- Wohlwollend\nVerkaufspreis:"}
MultiLanguageItemData['de'][147867] = {name = "[q3]Gestohlener Feger", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Platziert Euren gestohlenen Feger auf dem Boden. Er hat sehr wenig Energie und wird nicht lange durchhalten. (5 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\n[q]\"Die Wyrmzungen auf Suramars goldene Straßen loszulassen war nicht die beste Idee. Sie selbst fanden es allerdings großartig.\"\nVerkaufspreis:"}
