MultiLanguageItemData['de'][147893] = {name = "[q4]Angriffssignal: Sturmgepeitschtes Vorgebirge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 15 min (Realzeit)\n[q2]Benutzen: Beschwört dämonische Invasionstruppen. Kann nur im Sturmgepeitschten Vorgebirge in Sturmheim verwendet werden."}
