MultiLanguageItemData['de'][147897] = {name = "Wachstumshormon für Terrorhörner", additional_info = "Questgegenstand\n[q2]Benutzen: Füttert ein Terrorhornjungtier, um ein schnelles Wachstum zu fördern.\n[q]\"Ölig, mit einem widerlichen Geruch.\""}
MultiLanguageItemData['de'][147899] = {name = "Truhengegenstand einer sequenziellen Quest", additional_info = "Questgegenstand\n[q]\"Hallo Robert! :)\""}
MultiLanguageItemData['de'][147900] = {name = "[q3]Zwielix", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Zwielix beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][147901] = {name = "[q4]Leuchtender Sternensucher", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren leuchtenden Sternensucher oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die energiegeladenen Panthara von Argus spüren bei der Jagd die Energie in Lebewesen auf. Wenn sie sich einer starken Energiequelle nähern, ändern sie sichtlich ihre Farbe und werden aufgeregt.\"\nWoW-Shop"}
MultiLanguageItemData['de'][147904] = {name = "Käfigschlüssel", additional_info = "Inseln\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Öffnet etwas Verschlossenes.\n[q]\"Öffnet einen Käfig auf dieser Insel.\""}
MultiLanguageItemData['de'][147905] = {name = "[q2]Truhe mit Championausrüstung", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält wertvolle Ausrüstung für Eure Champions.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][147906] = {name = "[q3]Teufelsherz von Argus", additional_info = "Questgegenstand\n[q]\"Das Teufelsherz von Argus war das Geheimnis hinter der Unsterblichkeit von Hochinquisitor Raalgar. Die Brunnen, die es mit Argus verbanden, wurden zwar vernichtet, doch schützt es auf Argus immer noch jene, die magisch mit ihm in Verbindung stehen.\""}
MultiLanguageItemData['de'][147907] = {name = "[q2]Herzförmige Schachtel", additional_info = "Wird beim Aufheben gebunden\nBenötigtLiebe liegt in der Luft\n[q]\"Enthält Zeichen der Liebe und eine Chance auf andere Preise. Bei der ersten Schachtel, die Eure Kriegsmeute an einem Tag verdient, besteht eine zusätzliche Chance auf seltene Belohnungen.\"\n[q2]<Zum Öffnen rechtsklicken>"}
