MultiLanguageItemData['de'][151607] = {name = "[q4]Astraler Alchemistenstein", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151608] = {name = "Lichtblutelixier", additional_info = "[q2]Benutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\n Kann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151609] = {name = "Tränen der Naaru", additional_info = "[q2]Benutzen: Zeigt 30 Min. lang den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151610] = {name = "Vantusrune: Antorus, der Brennende Thron", additional_info = "[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:"}
