MultiLanguageItemData['de'][151617] = {name = "[q4]Abfangjäger von Orgrimmar", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Abfangjäger von Orgrimmar oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Durch eine nach vorne gerichtete Kanone in Form eines Wolfskopfs ist dieser Jagdflieger besonders gut für Luftkämpfe geeignet.\"\nBlizzCon 2017"}
MultiLanguageItemData['de'][151618] = {name = "[q4]Himmelsjäger von Sturmwind", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Himmelsjäger von Sturmwind oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Gebt mir so viele Motoren, wie Ihr habt.\" - Ingenieur Zahnrad\nBlizzCon 2017"}
