MultiLanguageItemData['de'][151636] = {name = "[q5]Seele des Erzdruiden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n\n[q0]Prismatischer Sockel\n\nKlassen: Druide\n[q2]Anlegen: Erhaltet das Talent 'Seele des Waldes'.\n[q]\"Der Zirkel des Cenarius ist im Hain der Träume zu finden. Sie sind die Hüter der Natur, die Bewahrer des Gleichgewichts und die Beschützer allen Lebens.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151638] = {name = "[q2]Verseuchter Beutel mit Haustierbedarf", additional_info = "Wird beim Aufheben gebunden\n[q]\"Teile dieses Beutels zerfallen.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][151639] = {name = "[q5]Seele des Rächers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Dämonenjäger\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nVerwüstung Erstes Blutvergießen\nRachsucht: Kollateralschaden\n[q]\"Die Illidari sind in der Teufelshammer zu finden. Sie kontrollieren die verbotenen Kräfte der Dämonen, die sie vernichten, um damit die Mächte des Chaos zu bekämpfen – und dabei scheuen sie vor nichts zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151640] = {name = "[q5]Seele des Todesgebieters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Todesritter\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nBlut: 'Übles Bollwerk'\nFrost: 'Aufziehender Sturm'\nUnheilig: 'Platzende Geschwüre'\n[q]\"Die Ritter der Schwarzen Klinge sind in Acherus, der Schwarzen Festung, zu finden. Einst waren sie die Champions der Geißel. Nun sind sie die Verdammten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151641] = {name = "[q5]Seele des Meisterjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Jäger\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nTierherrschaft: 'Jagdfieber'\nTreffsicherheit: 'Sichern und Laden'\nÜberleben: 'Viperngift'\n[q]\"Der Unsichtbare Pfad ist in der Volltrefferhütte zu finden. Sie sind die Augen in der Wildnis. Sie sind die Schwingen im Wind. Sie beschreiten den einsamen Weg.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151642] = {name = "[q5]Seele des Erzmagiers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Magier\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nArkan: 'Amplifikation'\nFeuer: 'Flammeninferno'\nFrost: 'Eiskalte Berührung'\n[q]\"Die Tirisgarde ist in der Halle des Wächters zu finden. Sie besteht aus Elitemagierwachen von Dalaran, die schon früher dem Ruf des Rats von Tirisfal folgten, um in Abwesenheit des Wächters Schlachten zu schlagen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151643] = {name = "[q5]Seele des Großmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Mönch\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nBraumeister: 'Nehmerqualitäten'\nNebelwirker: 'Nebelhülle'\nWindläufer: 'Auge des Tigers'\n[q]\"Der Orden des Verheerten Tempels ist im Tempel der Fünf Sonnenaufgänge zu finden. Er trägt die Strahlen der Hoffnung in eine scheinbar düstere Zukunft.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151644] = {name = "[q5]Seele des Hochlords", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Paladin\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nHeilig: 'Göttliche Bestimmung'\nSchutz: 'Heiliger Schild'\nVergeltung: 'Göttliche Bestimmung'\n[q]\"Der Orden der Silbernen Hand ist im Sanktum des Lichts zu finden. Er repräsentiert die geeinte Macht des Argentumkreuzzugs, der Hand von Argus, der Sonnenläufer und der Blutritter.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151645] = {name = "[q3]Modell 8U-DD-L3R", additional_info = "[q2]Benutzen: Lehrt Euch, wie man Buddler beschwört und wieder freigibt.\n[q2]Mit Rechtsklick Buddler beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][151646] = {name = "[q5]Seele des Hohepriesters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Prismatischer Sockel\n\nKlassen: Priester\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nDisziplin: 'Schicksalshafte Wendung'\nHeilig: 'Woge des Lichts'\nSchatten: 'Schicksalshafte Wendung'\n[q]\"Die Konklave ist im Netherlichttempel zu finden. Sie sind die Meister des Lichts und öffnen sich der Leere – denn ohne Dunkelheit gibt es kein Licht und ohne Licht keine Dunkelheit.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151647] = {name = "[q5]Seele des Scharfsehers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Schamane\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nElementar: Echo der Elemente\nVerstärkung: Erdrutsch\nWiederherstellung: Echo der Elemente\n[q]\"Der Irdene Ring ist im Herzen von Azeroth zu finden. Sie sind in der Lage, die mächtigen elementaren Kräfte zu bändigen und halten sie im Gleichgewicht. Sie sind die wahren Meister der Elemente.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151648] = {name = "Geschwollene Raptorteile", additional_info = "Questgegenstand\n[q]\"Tortollaner müssen widerstandsfähige Mägen haben, wenn Kajosh bereit ist, rohes Raptorfleisch zu essen.\""}
MultiLanguageItemData['de'][151649] = {name = "[q5]Seele des Netherfürsten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n\n[q0]Prismatischer Sockel\n\nKlassen: Hexenmeister\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nGebrechen: 'Seelenverbindung'\nDämonologie: 'Seelenverbindung'\nZerstörung: 'Ausrottung'\n[q]\"Der Rat der Schwarzen Ernte ist in der Schreckensnarbe zu finden. Sie sind die Ernter der Seelen, Feldherren ganzer Dämonenscharen und Meister der dunklen Künste.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151650] = {name = "[q5]Seele des Schlachtenfürsten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n\nKlassen: Krieger\n[q2]Anlegen: Erhaltet je nach Spezialisierung eins der folgenden Talente:\n\nWaffen: 'Aggressionsmanagement'\nFuror: 'Massaker'\nSchutz: 'Blutrache'\n[q]\"Die Valarjar sind in der Himmelsfeste zu finden. Sie sind die mächtigen, aufgestiegenen Champions von Odyn, die die Welt vor jeglichem Unheil beschützen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151651] = {name = "Gravitationsverringerungspantoffeln", additional_info = "[q2]Benutzen: Bringt die Gravitationsverringerungspantoffeln an Eurem aktuellen Schuhwerk an, um höher springen zu können. Hält 3 Min. lang an.\n\n Kann nur im Freien auf den Verheerten Inseln und auf Argus verwendet werden. (15 Min Abklingzeit)"}
MultiLanguageItemData['de'][151652] = {name = "[q3]Wurmlochgenerator: Argus", additional_info = "Wird bei Benutzung gebunden\nSpielzeug\n[q2]Benutzen: Teleportiert den Spielercharakter an einen zufälligen Ort auf Argus. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\n[q]\"Der Benutzer ist für die letztendlichen Teleportationszielorte allein verantwortlich und nicht berechtigt, rechtliche Schritte gegen den Hersteller dieses Geräts einzuleiten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151653] = {name = "[q2]Rezeptfetzen von den Verheerten Inseln", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q2]Benutzen: Fügt 10 Rezeptfetzen von den Verheerten Inseln zusammen, um ein Kochrezept zu erhalten, das Ihr noch nicht entdeckt habt."}
MultiLanguageItemData['de'][151654] = {name = "Vantusrunentechnik: Antorus, der Brennende Thron", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Antorus, der Brennende Thron herstellt.\n[q2]Erschafft eine Vantusrune: Antorus, der Brennende Thron.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nVantusrune: Antorus, der Brennende Thron\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis: \nBenötigt Fahle Pigmente (10), Rosenrote Pigmente (30)"}
MultiLanguageItemData['de'][151655] = {name = "Vantusrunentechnik: Antorus, der Brennende Thron", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Antorus, der Brennende Thron effizienter herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Antorus, der Brennende Thron.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nVantusrune: Antorus, der Brennende Thron\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis: \nBenötigt Fahle Pigmente (8), Rosenrote Pigmente (30)"}
MultiLanguageItemData['de'][151656] = {name = "Vantusrunentechnik: Antorus, der Brennende Thron", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Antorus, der Brennende Thron effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Antorus, der Brennende Thron.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis: \nVantusrune: Antorus, der Brennende Thron\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis: \nBenötigt Fahle Pigmente (6), Rosenrote Pigmente (30)"}
MultiLanguageItemData['de'][151657] = {name = "Rezept: Lichtblutelixier", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Lichtblutelixier herstellt.\n[q2]Stellt ein Lichtblutelixier her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nLichtblutelixier\n[q2]Benutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\n Kann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (25), Ursargerit , Kristallphiole"}
MultiLanguageItemData['de'][151658] = {name = "Rezept: Lichtblutelixier", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Lichtblutelixier effizienter herstellt.\n[q2]Stellt ein Lichtblutelixier effizienter her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nLichtblutelixier\n[q2]Benutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\n Kann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (20), Kristallphiole"}
MultiLanguageItemData['de'][151659] = {name = "Rezept: Lichtblutelixier", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Lichtblutelixier noch effizienter herstellt, und gewährt eine Chance auf die Herstellung mehrerer Tränke.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nLichtblutelixier\n[q2]Benutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\n Kann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (15), Kristallphiole"}
