MultiLanguageItemData['de'][151783] = {name = "[q5]Karma des Chamäleons", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Druide\n[q2]Anlegen: 'Wildwuchs' hat eine Chance von 15%, Euch für 12 Sek. 'Inkarnation: Baum des Lebens' zu gewähren.\n[q]\"Die Hüter bewahren den Frieden mit dem Wissen, dass nichts ewig währt – nicht der Baum, nicht die Liebe, nicht einmal ein gewaltsamer Tod.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151784] = {name = "[q5]Pforte ins Nirgendwo", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nKlassen: Mönch\n[q2]Anlegen: 'Essenzborn' hat eine Chance von 20%, für bis Abbruch Chi-Ji zu beschwören.\n[q]\"Zwei Wege boten sich im Nebel dar. / Ich nahm den dritten, der weniger begangen war.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151785] = {name = "[q5]Flammen der Tiefe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Kette}\n12 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Schamane\n[q2]Anlegen: 'Heilender Regen' hat eine Chance von 15%, für 6 Sek. 'Aszendenz' auszulösen.\n[q]\"Und der Dämonen Zorn sei ihrer Geltung Schmach; / und in des Erden Schrein lagen die Götzen brach.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151786] = {name = "[q5]Innerer Lichtschein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Priester\n[q2]Anlegen: 'Machtwort: Glanz' hat eine Chance von 35%, Euch 9 Sek. lang 'Seele der Macht' zu gewähren.\n[q]\"Leiht mir Eure Macht, und die Unsterblichkeit wird unser sein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151787] = {name = "[q5]Die Alabasterlady", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Priester\n[q2]Anlegen: 'Gebet der Besserung' hat eine Chance von 15%, für 8 Sek. 'Apotheose' auszulösen.\n[q]\"Als der Sterne Speere schossen / und Tränen in den Himmel gossen, / sah lächelnd sie ihr Werk vor sich?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151788] = {name = "[q5]Sturmbräus letzter Atemzug", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Leder}\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]+ 4 Vielseitigkeit\nHaltbarkeit 120 / 120\nKlassen: Mönch\n[q2]Anlegen: 'Fasshieb' erhält 1 zusätzliche Aufladung und verursacht 25% mehr Schaden.\n[q]\"Warum kämpfen wir? Um Heimat und Familie zu beschützen... Um Gleichgewicht zu wahren und Harmonie zu schaffen.\"\nVerkaufspreis:"}
