MultiLanguageItemData['de'][151795] = {name = "[q5]Verderbnis des Seelenschinders", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Platte}\n18 Rüstung\n+5 Stärke\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Todesritter\n[q2]Anlegen: Erhöht den Schaden und die Heilung von 'Blutseuche' um 100%.\n[q]\"Die Herkunft des Seelenschinders bleibt ein Rätsel. In den Annalen der Titanen findet sich keinerlei Eintrag über ihn.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151796] = {name = "[q5]Kaltes Herz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Platte}\n18 Rüstung\n+5 Stärke\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Todesritter\n[q2]Anlegen: Gewährt Euch alle 2 Sek. einen Stapel von 'Kaltes Herz', wodurch Euer nächster Einsatz von 'Eisketten' (21% der Angriffskraft) Schattenfrostschaden verursacht. Bis zu 20-mal stapelbar.\n\n Wenn Ihr beim Einsatz von 'Eisketten' 20 Stapel von 'Kaltes Herz' habt, wird das Ziel außerdem für 4 Sek. betäubt und in einen Eisblock eingeschlossen.\n[q]\"Das Schlagen eines gefrorenen Herzens ist auch in weiter Ferne noch hörbar und erinnert alles Lebende an die Unausweichlichkeit des Todes.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151798] = {name = "[q5]Chaostheorie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 3.\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Klingentanz' hat eine Chance von 10%, Euch 6 Sek. lang 'Chaosklingen' zu gewähren. (500ms Abklingzeit)\n[q]\"Das Chaos birgt Wiederholung, Rückkopplungsschleifen und zugrundeliegende Muster.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151799] = {name = "[q5]Umarmung des Vergessens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Leder}\n7 Rüstung\n+5 Beweglichkeit\n+7 Ausdauer\n[q2]+ 5 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 145 / 145\nKlassen: Dämonenjäger\n[q2]Anlegen: 'Dämonenstachel' erhält 1 zusätzliche Aufladung.\n[q]\"Es gibt keinen besseren Ratgeber für die Welt als Vergessen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151800] = {name = "[q5]Strahlendes Mondlicht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nKlassen: Druide\n[q2]Anlegen: 'Vollmond' wird nach dem Einsatz noch einmal zu 'Vollmond', bevor der Zyklus auf 'Neumond' zurückgesetzt wird.\n[q]\"Zweifelt an der Sonne Klarheit,Zweifelt an der Sterne Licht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151801] = {name = "[q5]Kopfputz des Ungetüms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Druide\n[q2]Anlegen: Finishing-Moves verlängern die Dauer von 'Tigerfuror' pro verbrauchtem Combopunkt um 0.5 Sek. (100ms Abklingzeit)\n[q]\"Schlafende Tiger soll man nicht wecken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151802] = {name = "[q5]Furor der Natur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nKlassen: Druide\n[q2]Anlegen: In Bärengestalt verursacht Ihr 30% mehr Natur- und Arkanschaden und werdet um 30% Eures verursachten Natur- und Arkanschadens geheilt.\n[q]\"Ein Gleichgewicht zwischen den natürlichen und übernatürlichen Kräften mag schwer zu erreichen sein, doch es führt zu wahrer Größe.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151803] = {name = "[q5]Schnelligkeit der Windläufer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nKlassen: Jäger\n[q2]Anlegen: Erhöht Euer Tempo um 3%.\n[q2]Anlegen: 'Windstoß' erhöht 6 Sek. lang Euer Tempo um 15%.\n[q]\"'Dein Herz flog geradlinig wie ein Pfeil mit dem Wind, Schwester. Du warst die Strahlendste unseres Ordens. Du warst die Teuerste unserer Sippe.' - Sylvanas an Alleria\"\nVerkaufspreis:"}
