MultiLanguageItemData['de'][151805] = {name = "[q5]Die Parselzunge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Kette}\n12 Rüstung\n+5 Beweglichkeit\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Jäger\n[q2]Anlegen: 'Kobraschuss' erhöht 8 Sek. lang Euren verursachten Schaden und den Eurer Begleiter um 1% sowie Euren Lebensraub um 2%. Dieser Effekt ist bis zu 4-mal stapelbar. (500ms Abklingzeit)\n[q]\"Eine seltene Fähigkeit, die jene besitzen, die Umgang mit Schlangen haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151806] = {name = "[q2]Elegantes Kleid", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\nBrust Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][151807] = {name = "[q5]Umhang des unsichtbaren Raubtiers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nKlassen: Jäger\n[q2]Anlegen: Erhöht sämtlichen verursachten Schaden um 3%.\n[q2]Anlegen: Erhöht Eure kritische Trefferchance gegen Ziele, die von dem Effekt Eurer 'Sprengfalle' betroffen sind, um 10%.\n[q]\"Selbst der mächtigste Gegner hat eine Schwäche. Sie muss nur aufgedeckt werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151808] = {name = "[q5]Mantel der Ersten der Kirin Tor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Magier\n[q2]Anlegen: 'Arkanbeschuss' hat pro verbrauchter Arkaner Aufladung eine Chance von 10%, eine 'Arkane Kugel' vor Euch abzufeuern.\n[q]\"Vor tausenden Jahren unterwiesen die Hochelven von Quel'Thalas die Menschen in den arkanen Künsten, woraufhin diese die Kirin Tor gründeten und schließlich über Dalaran herrschten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151809] = {name = "[q5]Gebändigter Höllenbestienkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Magier\n[q2]Anlegen: Nachdem Ihr 30-mal 'Feuerball' oder 'Pyroschlag' gewirkt habt, wird ein 'Meteor' auf Euer Ziel gestürzt.\n[q]\"Der Höllenbestienkern entlädt sich häufig in explosiven Flammenstrahlen so heiß, dass sie selbst widerstandsfähigste Materialien schmelzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151810] = {name = "[q5]Zerschmetterte Fragmente von Sindragosa", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Magier\n[q2]Anlegen: Nachdem Ihr 15-mal 'Frostblitz' oder 'Hagel' gewirkt habt, geht ein 'Kometenhagel' auf Euer Ziel nieder.\n[q]\"Wurde aus den Trümmern gefertigt, die Arthas nach seiner Verwüstung bei Sindragosas Sturz hinterließ, und jagt seinem Träger einen Schauer über den Rücken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151811] = {name = "[q5]Der Wind weht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Mönch\n[q2]Anlegen: Erhöht Euren verursachten Schaden um 3%.\n[q2]Anlegen: Verringert die Abklingzeit von 'Schlag des Windlords' um 20% und hebt die Chikosten Eures nächsten Einsatzes von 'Blackout-Tritt' auf. (1s Abklingzeit)\n[q]\"Die Sonne geht auf, der Wind weht und die Mächtigen fallen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151812] = {name = "[q5]Säulen des innersten Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Platte}\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Paladin\n[q2]Anlegen: Verringert die Abklingzeit von 'Unermüdlicher Verteidiger' um 25%.\n[q2]Anlegen: 'Auge von Tyr' verursacht 300% mehr Schaden und die Abklingzeit ist um 25% verringert.\n[q]\"Das Licht brennt am hellsten in jenen, die es verschlingt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151813] = {name = "[q5]Bann des scharlachroten Inquisitors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Platte}\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Paladin\n[q2]Anlegen: Erhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Göttlicher Sturm' um 6%. Bis zu 30-mal stapelbar.\n[q]\"Versteht Ihr es nicht, Brüder und Schwestern? Es gibt nur einen Weg, die Geißel vom Antlitz Azeroths zu fegen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151814] = {name = "[q5]Herz der Leere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Stoff}\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Priester\n[q2]Anlegen: 'Leereneruption' verursacht 75% mehr Schaden und heilt Euch um 25% des verursachten Schadens.\n[q]\"Die Leere ist keinesfalls leer. Sie ist voll von Bosheit, Verzweiflung und Tod.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151815] = {name = "[q5]Die leere Krone", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Leder}\n6 Rüstung\n+5 Beweglichkeit\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Schurke\n[q2]Anlegen: Energieregeneration um 1 pro Sekunde erhöht. (500ms Abklingzeit)\n[q2]Anlegen: 'Königsmord' erzeugt im Verlauf von 5 Sek. 40 Energie. (500ms Abklingzeit)\n[q]\"Es ist schwer, einen Hund an die Leine zu legen, wenn man ihm einmal eine Krone auf seinen Kopf gesetzt hat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151816] = {name = "Hordebanner", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Platziert ein Hordenbanner auf dem Leichnam eines Zanchuliverräters in der Nähe."}
MultiLanguageItemData['de'][151817] = {name = "[q5]Der Fluch der Ruhelosigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nKlassen: Schurke\n[q2]Anlegen: 'Ruhlose Klingen' verringert pro verbrauchtem Combopunkt die Abklingzeit von 'Adrenalinrausch' um 0.5 Sek.\n[q2]Anlegen: 'Ruhlose Klingen' verringert pro verbrauchtem Combopunkt die Abklingzeit von 'Fluch der Schreckensklingen' um 0.25 Sek.\n[q]\"Wer rastet, der rostet... und wird gemeuchelt!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151818] = {name = "[q5]Der erste Tote", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Leder}\n5 Rüstung\n+4 Beweglichkeit\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\n[q2]Anlegen: Für 2 Sek. nach der Aktivierung von 'Symbole des Todes' erzeugt 'Schattenschlag' 3 zusätzliche Combopunkte und 'Meucheln' 4 zusätzliche Combopunkte. (500ms Abklingzeit)\n[q]\"Am Ende findet der Tod uns alle...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151819] = {name = "[q5]Schwelendes Herz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Kette}\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\n[q2]Anlegen: Gewährt Euch pro verbrauchtem Punkt Mahlstrom eine Chance von [ Sturmschlag : 0.12% / 0.10%], für 10 Sek. 'Aszendenz' auszulösen.\n[q]\"Diese Handschuhe wurden erfüllt mit der Essenz von tausenden lodernden Elementaren – und doch fühlen sie sich seltsam kalt an.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151821] = {name = "[q5]Der Meister der Ernte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Stoff}\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Hexenmeister\n[q2]Anlegen: Dämonologie\n Jeder Seelensplitter, den Ihr verbraucht, hat eine Chance von 3%, Euch 8 Sek. lang 'Seelenernte' zu gewähren.\n\nZerstörung\n Jeder Seelensplitter, den Ihr verbraucht, hat eine Chance von 6%, Euch 8 Sek. lang 'Seelenernte' zu gewähren.\n\nGebrechen\n Jeder Seelensplitter, den Ihr verbraucht, hat eine Chance von 9%, Euch 8 Sek. lang 'Seelenernte' zu gewähren.\n[q]\"Aus Leid geht die stärkste aller Seelen hervor.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151822] = {name = "[q5]Ararats Blutspiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Platte}\n16 Rüstung\n+5 Stärke\n+7 Ausdauer\n[q2]+ 5 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 145 / 145\nKlassen: Krieger\n[q2]Anlegen: Gewährt 'Schildblock' und 'Zauberreflexion' 1 zusätzliche Aufladung.\n[q]\"Sein Blut tränkt den glänzenden Stahl, vergossen von Drachen, Göttern und Dämonen. Selbst von der anderen Seite beschützt er seine Freunde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151823] = {name = "[q5]Das Auge des großen Sturms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Platte}\n13 Rüstung\n+5 Stärke\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Krieger\n[q2]Anlegen: 'Klingensturm' erhöht 6 Sek. lang Eure Bewegungsgeschwindigkeit um 10% und Euren verursachten Schaden um 2%. Dieser Effekt wird in regelmäßigen Abständen stärker und ist bis zu 6-mal stapelbar.\n[q]\"Im Auge des Tornados gibt es kein hoch oder tief, keinen Boden, keinen Himmel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151824] = {name = "[q5]Berserker der Valarjar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Platte}\n16 Rüstung\n+5 Stärke\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Krieger\n[q2]Anlegen: Kritische Treffer mit 'Toben' gegen das Primärziel erzeugen 6 Wut.\n[q]\"Fingerspitzengefühl ist nicht unbedingt ihr hervorstechendstes Merkmal.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][151825] = {name = "[q2]Hatuuns Horn", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Beschwört Krokulgratpirscher aus den Schatten, die Euch im Kampf unterstützen. (30 Sek. Abklingzeit)\n[q]\"Lasst den Ruf der Schlacht erklingen. Wir schlagen vereint zu!\""}
MultiLanguageItemData['de'][151826] = {name = "Geistermaske", additional_info = "Questgegenstand\n[q2]Benutzen: Benutzt die Geistermaske, um in das Geisterreich überzugehen."}
MultiLanguageItemData['de'][151828] = {name = "[q3]Nie alternder Bronzedrache", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick Euren Protowelpen beschwören oder wieder freigeben.\n80 ( 80)\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][151829] = {name = "[q3]Bronzener Protowelpe", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick Euren Protowelpen beschwören oder wieder freigeben.\n80 ( 80)\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][151830] = {name = "[q3]Urteil des Lichts", additional_info = "[q2]Benutzen: Ruft die Vindikaar, damit sie einen Strahl heiligen Lichts auf Eure Gegner abfeuert, der Gegnern innerhalb von 15 Metern 100 Heiligschaden zufügt und sie für 5 Sek. betäubt.\n\n Kann nur auf Argus eingesetzt werden. (2 Min Abklingzeit)"}
MultiLanguageItemData['de'][151837] = {name = "Anrufungsrelais", additional_info = "Questgegenstand\n[q]\"Diese langen und dünnen Kristalle fokussieren Licht zu mächtigen Explosionen und sind daher recht begehrt.\""}
MultiLanguageItemData['de'][151838] = {name = "Urteilskern", additional_info = "Questgegenstand\n[q]\"Man sagt, dass der Urteilskern den krönenden Erfolg der Konstrukteure der Armee des Lichts darstellt.\""}
MultiLanguageItemData['de'][151839] = {name = "Verteidigerpanzerung", additional_info = "Questgegenstand\n[q]\"Die lichtgeschmiedete Rüstung der Großen Armee ist darauf ausgelegt, ihre Verteidiger vor der Teufelsmagie der Legion zu schützen.\""}
MultiLanguageItemData['de'][151842] = {name = "[q2]Krokulrüstungsset", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Setzt die Machtstufe eines Champions auf 900.\nVerkaufspreis:"}
