MultiLanguageItemData['de'][151849] = {name = "Schriftrolle des Infernos", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Liest eine magische Schriftrolle, um profane Totems in der Nähe zu zerstören. (5 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][151851] = {name = "Makelloser Teufelskern", additional_info = "Questgegenstand\n[q]\"Das mit chaotischer Energie erfüllte Herz eines reinen Teufelswesens.\""}
MultiLanguageItemData['de'][151852] = {name = "Edikte des Gral", additional_info = "Questgegenstand\n[q]\"Der Text dieser Schriftrolle ist in einem uralten Trolldialekt verfasst und mithilfe eines besonderen Codes verschlüsselt. Man könnte ein Leben damit verbringen, ihn zu entschlüsseln.\""}
MultiLanguageItemData['de'][151853] = {name = "Wellen der Macht", additional_info = "Questgegenstand\n[q]\"Mithilfe uralter Zauberei wurde diese Schriftrolle mit Symbolen verziert, die für Euch unbegreiflich sind.\""}
MultiLanguageItemData['de'][151854] = {name = "Schriftrolle des Läuterns", additional_info = "Questgegenstand\n[q]\"Auf dieser uralten Schriftrolle ist nur der Titel des Zaubers lesbar.\""}
MultiLanguageItemData['de'][151855] = {name = "Artefakt von Gral", additional_info = "Questgegenstand\n[q]\"Für Laien sieht dieses Relikt nur wie ein hübsches Stück einer Ruine aus.\""}
MultiLanguageItemData['de'][151856] = {name = "Verwelkte Astralwinde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Eine nicht verwendbare Form des Krauts.\""}
MultiLanguageItemData['de'][151857] = {name = "Junge Astralwinde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein Astralwindenschössling.\""}
MultiLanguageItemData['de'][151858] = {name = "Astralwindenwurzelballen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein kleiner, an einen Kokon erinnernder Wurzelballen, aus dessen Inneren Energie zu dringen scheint.\""}
MultiLanguageItemData['de'][151859] = {name = "Schriftrolle der Illusion", additional_info = "Questgegenstand\n[q2]Benutzen: Maskiert eine Antiquität von Gral.\n[q]\"Die Zauber auf dieser Seite sind sehr speziell und wurden so vereinfacht, dass selbst die schlichtesten Gemüter sie anwenden können.\""}
MultiLanguageItemData['de'][151860] = {name = "Brocken eines Empyriumvorkommens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Oberfläche dieses Erzes glitzert wie die Sterne.\""}
MultiLanguageItemData['de'][151861] = {name = "Empyriumstaub", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Kleine Überreste von Empyriumerz.\""}
MultiLanguageItemData['de'][151862] = {name = "Unbrauchbarer Empyriumkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein zerbrochener Empyriumerzkern.\""}
MultiLanguageItemData['de'][151863] = {name = "Brocken eines Empyriumflözes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Oberfläche dieses Erzes glitzert wie die Sterne.\""}
MultiLanguageItemData['de'][151864] = {name = "Eingebettetes Empyriumerz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein Brocken Empyriumerz mit großen Teilen nicht verwendbaren Gesteins.\""}
