MultiLanguageItemData['de'][151866] = {name = "Besudelte Fetzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Diese Fetzen von infernalischem Leder scheinen verderbt zu sein und verbreiten einen sehr üblen Gestank.\""}
MultiLanguageItemData['de'][151867] = {name = "Verdorbenes infernalisches Leder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die von dem Tier ausgehende Verderbnis hat dieses Stück Leder verdorben.\""}
MultiLanguageItemData['de'][151868] = {name = "Verderbter Zahn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Verderbnis dieses Tiers hat seinen Zahn erreicht und ihn nutzlos gemacht.\""}
MultiLanguageItemData['de'][151870] = {name = "[q2]Schriftrolle des Gral", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Nimmt die Gestalt eines Hais an."}
MultiLanguageItemData['de'][151871] = {name = "Kiste mit Teufelsschiefer", additional_info = "Questgegenstand\n[q]\"Eine große Kiste mit Teufelsschiefererz.\""}
