MultiLanguageItemData['de'][151874] = {name = "Leuchtgarnwebstuhl", additional_info = "Questgegenstand\n[q]\"Ein dekorativer Webstuhl mit goldener Gravur.\""}
MultiLanguageItemData['de'][151875] = {name = "[q3]Ruf zum Licht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ruft einen Champion des Lichts herbei, der 12 Sek. lang für Euch kämpft."}
MultiLanguageItemData['de'][151876] = {name = "Vorels Vorlagenbuch", additional_info = "Questgegenstand\n[q]\"Ein großer Foliant mit verschiedenen Juwelenschliffdesigns.\""}
MultiLanguageItemData['de'][151877] = {name = "[q3]Fass mit Augenklappen", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Schurke\n[q2]Benutzen: Beschwört ein Fass voller geheimnisvoller Augenklappen für Euch und all Eure Freunde. Das Resultat wird kaum zu FASSen sein! (1 Stunde Abklingzeit)\n[q]\"So viel Spaß auf einmal! Ihr werdet gaaarrr nicht wissen, was Ihr zuerst damit anstellen sollt.\""}
MultiLanguageItemData['de'][151878] = {name = "Empyriumkrone", additional_info = "Questgegenstand\n[q]\"Jeder Edelstein in dieser Krone ist so platziert, dass er wie ein Stern glitzert.\""}
MultiLanguageItemData['de'][151879] = {name = "Geläutertes infernalisches Leder", additional_info = "Questgegenstand\n[q]\"Die geläuterte Variante dieses Leders stinkt nicht mehr und Ihr fühlt Euch auch nicht mehr unwohl, wenn Ihr es haltet.\""}
MultiLanguageItemData['de'][151880] = {name = "Enstraas Gerböl", additional_info = "Questgegenstand\n[q2]Benutzen: Kombiniert 1 infernalisches Leder und 1 lichtgewirktes Tuch mit Enstraas Gerböl.\n[q]\"Eine kleine Phiole mit einer klaren, goldenen Flüssigkeit. Wenn Ihr sie öffnet, entweicht ein blumiger Duft.\""}
