MultiLanguageItemData['de'][151962] = {name = "[q4]Prototyp eines Personaldezimierers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Anlegen: Eure Distanzangriffe und Zauber haben eine Chance, eine Zielsuchrakete auszulösen, wenn Euer Ziel mindestens 10 Meter entfernt ist. Sie fügt allen Gegnern innerhalb von 20 Metern 28 Feuerschaden zu. Ziele, die sich näher am Einschlagsort befinden, erleiden mehr Schaden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][151963] = {name = "[q4]Fabrikator des Schmiedeschreckens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Anlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Feuerminen zu Füßen des Gegners abzulegen. Feuerminen detonieren nach 15 Sek. und fügen allen Gegnern innerhalb von 12 Metern 15 Feuerschaden zu.\n[q2]Benutzen: Detoniert alle Feuerminen. (30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151964] = {name = "[q4]Triefende Geißelschwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, dem Ziel 39 Schattenschaden zuzufügen. Wenn sich keine weiteren Gegner innerhalb von 8 Metern um das Ziel befinden, erleidet es zusätzlich 17 Schattenschaden.\nVerkaufspreis:"}
