MultiLanguageItemData['de'][151969] = {name = "[q4]Signalfeuer des Terminus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n[q2]Benutzen: Ruft ein Legionsschiff herbei, das die Position des Ziels 9 Sek. lang bombardiert und allen Zielen innerhalb von 12 Metern, einschließlich des Schiffs, 30 Feuerschaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151970] = {name = "[q4]Vitalitätsresonator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Benutzen: Lenkt die Lebenskraft eines Gegners um und erhöht Eure Intelligenz 15 Sek. lang um bis zu 18 . Gewährt beim Einsatz gegen Ziele mit hoher Gesundheit mehr Intelligenz. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151971] = {name = "[q4]Hülle von Asara", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\n[q2]Anlegen: Eure Schaden verursachenden Zauber haben eine Chance, 6 Schattenklingen zu beschwören. Nach 2 Sek. beginnen die Klingen, vorwärts zu fliegen. Jede fügt dem ersten getroffenen Gegner in ihrem Weg 16 Schattenschaden zu und erhöht den durch weitere Schattenklingen erlittenen Schaden 3 Sek. lang um 10%, bis zu maximal 50%. (6s Abklingzeit)\nVerkaufspreis:"}
