MultiLanguageItemData['de'][151974] = {name = "[q4]Auge von Shatug", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Augen der Hunde (1)\nSchmuck\n[q2]Anlegen: Gewährt einem Verbündeten mit Tankspezialisierung in der Nähe, der das entgegengesetzte Auge trägt, zusätzlich 1 Rüstung oder 2 Vielseitigkeit.\n[q2]Benutzen: Transformiert in das Auge . (30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151975] = {name = "[q4]Apokalypseeinheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Benutzen: Verringert den Schaden der nächsten 10 gegen Euch geführten Nahkampfangriffe um bis zu jeweils 38 Schaden. Hält bis zu 20 Sek. lang an.\n\n Das Erleiden von Nahkampfangriffen verringert die Abklingzeit dieser Fähigkeit um 1 Sek. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151976] = {name = "[q4]Kodex der Risswelt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Anlegen: Beim Erleiden von Schaden besteht eine Chance, dass ein Portal zu einer anderen Welt geöffnet wird. Entweder heilt es Euch, gewährt einen Absorptionsschild oder ermächtigt Euch mit Schattenflammenmagie. (4s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][151977] = {name = "[q4]Diimas Frostaegis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Erhöht Eure Rüstung 12 Sek. lang um 2 , fügt Gegnern innerhalb von 12 Metern 65 Frostschaden zu und verringert 12 Sek. lang ihre Bewegungsgeschwindigkeit um 70%. (1 Min Abklingzeit)\nVerkaufspreis:"}
