MultiLanguageItemData['de'][152554] = {name = "[q3]Entweihtes Seetanghemd", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nHemd\nBenötigt den Ruf 'Guter Freund' bei Wichtlus."}
MultiLanguageItemData['de'][152555] = {name = "[q2]Geisterhai", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren Geisterhai beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt den Ruf 'Guter Freund' bei Ilyssia von den Wassern."}
MultiLanguageItemData['de'][152556] = {name = "[q3]Fischerboottotem", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört ein Fischerboottotem, das 2 Min. lang die Angelfertigkeit aller Spielercharaktere in der Nähe um 4 erhöht. (5 Min Abklingzeit)\nBenötigt den Ruf 'Guter Freund' bei Akule Flusshorn.\nVerkaufspreis:"}
MultiLanguageItemData['de'][152557] = {name = "Stahlhauttrank", additional_info = "[q2]Benutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 269 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][152558] = {name = "Stück Kirschkuchen", additional_info = "[q2]Benutzen: Stellt im Verlauf von 30 Sek. ( 910 * 30 / 5) Gesundheit wieder her.\n Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:"}
MultiLanguageItemData['de'][152559] = {name = "Trank des drohenden Todes", additional_info = "[q2]Benutzen: Ermächtigt Euch für 25 Sek. mit Schattenmagie. Sie verleiht Euren Schaden verursachenden Distanzfähigkeiten eine Chance, einen Todesblitz abzufeuern, dessen Schaden sich mit der zurückgelegten Strecke erhöht und der bis zu 331209 Schattenschaden verursacht. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][152560] = {name = "Trank der Bluteruption", additional_info = "[q2]Benutzen: Erfüllt Euer Blut für 25 Sek. mit Hitze, die Euren Nahkampfangriffen eine Chance gewährt, eine Blutexplosion auszulösen, die 5371 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][152561] = {name = "Trank der Erfrischung", additional_info = "[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 601 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][152564] = {name = "Festmahl der Fische", additional_info = "[q2]Benutzen: Richtet ein Festmahl der Fische her, das bis zu 50 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\n Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet alle Eigenschaften eines Fischs.\nVerkaufspreis:"}
MultiLanguageItemData['de'][152565] = {name = "Rezept: Festmahl der Fische", additional_info = "Rang 1\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Zubereitung eines Festmahls der Fische.\n[q2]Bereitet ein Festmahl der Fische zu.\nBenötigt Kochkunst der Verheerten Inseln (1)\nBenötigt den Ruf 'Guter Freund' bei Hüterin Raynae.\nVerkaufspreis:\nFestmahl der Fische\n[q2]Benutzen: Richtet ein Festmahl der Fische her, das bis zu 50 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\n Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet alle Eigenschaften eines Fischs.\nVerkaufspreis:\nBenötigt Verfluchter Königinnenfisch , Mooskiemenbarsch , Hochberglachs , Sturmrochen , Runenschuppenkoi , Schwarzer Barrakuda"}
