MultiLanguageItemData['de'][153113] = {name = "[q3]Seelenstein eines Dämons", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Zermalmt den Stein, tötet den Dämon dauerhaft und erhöht den Ruf bei den Fraktionen der Verheerten Inseln und auf Argus um 1000.\n\n Kann nur auf Argus genutzt werden."}
MultiLanguageItemData['de'][153114] = {name = "[q2]Nathrezimfoliant der Manipulation", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Lest die Seiten, um etwas über subtile Arten zu erfahren, die Euch Umstehenden zu beeinflussen. Erhöht den Rufgewinn bei den Fraktionen der Verheerten Inseln 2 Stunden lang um 200%.\n\n Kann über Stufe 49 nicht eingesetzt werden."}
