MultiLanguageItemData['de'][153188] = {name = "[q2]Großer gesegneter Verband", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Legt den Verband an, um 30 Min. lang alle 3 Sek. 5% Gesundheit wiederherzustellen und Angreifern Heiligschaden zuzufügen. Kann nur auf den Verheerten Inseln und Argus verwendet werden. (1s Abklingzeit) (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][153189] = {name = "[q2]Zerschmettertes Lichtschwert", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Bittet demütig, dass ein aufgestiegener Verteidiger nach Azeroth zurückkehrt, um 10 Min. lang an Eurer Seite zu kämpfen. Kann nur auf den Verheerten Inseln und Argus eingesetzt werden. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][153190] = {name = "Teufelsgeflecktes Ei", additional_info = "Wird beim Aufheben gebunden\nDauer: 5 tagen (Realzeit)\n[q]\"Aus diesem Ei wird etwas schlüpfen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153191] = {name = "Gesprungenes teufelsgeflecktes Ei", additional_info = "Wird beim Aufheben gebunden\n[q]\"Aus diesem Ei ist etwas geschlüpft!\"\n[q2]<Zum Öffnen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][153192] = {name = "Sonnenglut", additional_info = "[q2]Benutzen: Ein leicht leuchtendes Getränk. (Procchance: 20%, 15s Abklingzeit)\n[q]\"Beliebt bei der Armee des Lichts, um die Moral zu stärken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153193] = {name = "[q3]Baarut der Blitz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Beschwört auf Argus einen reitbaren spektralen Talbuk. Das ist ein sehr, SEHR schnelles Reittier. (20 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][153194] = {name = "[q3]Kommunikationskugel der Legion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Lässt Euch weit in die Ferne blicken und gewährt die Fähigkeit, dort Signalfeuer zu beschwören, die die Streitkräfte der Legion anziehen. (10 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar."}
MultiLanguageItemData['de'][153195] = {name = "[q3]Uunas Puppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man Uuna beschwört.\n[q2]Mit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar."}
