MultiLanguageItemData['de'][153485] = {name = "[q4]Dunkelmond-Minizeppelin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Mit Rechtsklick Euren Dunkelmond-Minizeppelin beschwören oder wieder freigeben. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Silas hatte erwägt, seine Zeppelinflotte für Vermarktungszwecke einzusetzen, entschied dann aber, dass es die beste Form von Werbung wäre, sie einfach direkt an den Mann zu bringen.\"\nVerkäufer:\nLhara\nZone:\nDunkelmond-Insel\nKosten:\n1000"}
MultiLanguageItemData['de'][153486] = {name = "Intakter Giftdorn", additional_info = "Questgegenstand\n[q]\"Wird an Harpunen der Sturmtakler befestigt, um große Tiere zu betäuben.\""}
