MultiLanguageItemData['de'][153565] = {name = "Fesseln", additional_info = "Questgegenstand\n[q2]Benutzen: Fesselt Euer Ziel, wenn es über weniger als 50% Gesundheit verfügt.\n\n Kann nur gegen Sethrak innerhalb des Tempelübergriffs verwendet werden."}
MultiLanguageItemData['de'][153566] = {name = "[q0]\"Glitzernder\" Stein", additional_info = "[q]\"Der hier schön. Schön nutzlos! HAH! Nicht zu viel zu gebrauchen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153567] = {name = "[q0]\"Polierter\" Stein", additional_info = "[q]\"Spiegelt so, dass Ihr Hut sehen könnt, den Ihr von Scha'poh gekauft habt. Bin guter Querverkaufsoger.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153568] = {name = "[q0]\"Fliegender\" Stein", additional_info = "[q]\"Ich kleinen Gnom treffen, der ihn 'bäro-dünna-misch' genannt, der Name aber dumm. Kommt nicht gut an bei Steinkäufern. Der gut zum Werfen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153569] = {name = "[q0]\"Harter\" Stein", additional_info = "[q]\"Der Verkaufsschlager! Weil der sein am besten zum Schlagen. Für zu Hause, die Arbeit und überhaupt alles!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153570] = {name = "[q0]\"Magischer\" Stein", additional_info = "[q]\"Der hier besonders magisch. Mein Häuptling mir das sagen. Magie versprochen, sonst Geld zurück!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153571] = {name = "Vergifteter Blaspfeil", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Verringert die maximale Gesundheit eines Kriegsreiters der Blutjäger um 90% und seinen Schaden um 50%."}
MultiLanguageItemData['de'][153572] = {name = "Naglas Kopf", additional_info = "Questgegenstand\n[q]\"Der abgetrennte Kopf von Kriegsmatrone Nagla.\""}
MultiLanguageItemData['de'][153573] = {name = "Elektroschocker zur Reittiermotivierung", additional_info = "[q2]Benutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\n\n Nicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n[q]\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153574] = {name = "Gewöhnliche Hutschachtel", additional_info = "[q]\"Eine Doppelhutschachtel.\"\n[q2]<Zum Öffnen rechtsklicken>\nVerkaufspreis:"}
