MultiLanguageItemData['de'][153591] = {name = "Gürtelverzauberung: Schreckenshologrammprojektor", additional_info = "[q2]Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\n Nur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden."}
MultiLanguageItemData['de'][153592] = {name = "Gürtelverzauberung: Ellbogenfreiheit", additional_info = "[q2]Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr Euer aktuelles Ziel zurückstoßen könnt. Teilt sich die Abklingzeit mit Tränken.\n\n Nur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden."}
MultiLanguageItemData['de'][153593] = {name = "Riesiger Rippenknochen von Blutkrone", additional_info = "Questgegenstand"}
MultiLanguageItemData['de'][153594] = {name = "[q4]Xiwyllag-Flugfahrboot", additional_info = "Reittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man das Xiwyllag-Flugfahrboot fährt.\n[q2]Beschwört Euer Xiwyllag-Flugfahrboot oder gibt es wieder frei. Dieses Fahrzeug passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Man sagt, dass diese Erfindung dem Aussehen eines sehr reichen Goblins nachempfunden wurde. Andere sehen allerdings keine Ähnlichkeit.\"\nBeruf:\nSchmiedekunst & Ingenieurskunst"}
MultiLanguageItemData['de'][153595] = {name = "Klebriger Bienenhonig", additional_info = "Questgegenstand"}
MultiLanguageItemData['de'][153596] = {name = "Ziegenschere", additional_info = "Questgegenstand\n[q2]Benutzen: Rasiert eine Ziege mit nur \"minimalen\" Ritzern und Schrammen! (5 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][153597] = {name = "Stationärer Umkleider", additional_info = "[q2]Benutzen: Beschwört ein Gerät, mit dem Ihr das Aussehen Eurer Rüstung verändern könnt. Das Gerät bleibt bis zu 2 Min. lang bestehen.\n[q]\"Hinweis: Aufgrund der Funktionsweise dieses Geräts sind leichte Kopfschmerzen, Übelkeit sowie Wechsel von Volkszugehörigkeit und/oder Geschlecht nicht auszuschließen. Mit Vorsicht zu verwenden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][153598] = {name = "[q3]Dunkelmond-Karte des Krieges", additional_info = "[q]\"Irgendeine Dunkelmond-Karte des Krieges. Sammelt das ganze Set, um eine Belohnung zu erhalten.\""}
MultiLanguageItemData['de'][153599] = {name = "Des Toten letzter Krug", additional_info = "Questgegenstand\n[q2]Benutzen: Trinkt mich.\n[q]\"Kleine Bläschen dringen wie Fäden an die Oberfläche, bevor sie sich zu zartem Schaum sammeln.\""}
MultiLanguageItemData['de'][153600] = {name = "Ziegenmilch", additional_info = "Questgegenstand\n[q2]Benutzen: Trinkt mich.\n[q]\"Gut für die Knochen! Nur nicht fürs Holzbein.\""}
