MultiLanguageItemData['de'][154172] = {name = "[q5]Aman'thuls Vision", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]+ 6 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n[q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, Eure Geschwindigkeit, Eure Vermeidung und Euren Lebensraub 12 Sek. lang um 9 zu erhöhen.\n\nAman'thuls Pracht\n Wenn Euch das Pantheon Macht verleiht, wird Eure Intelligenz 15 Sek. lang um 6 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][154173] = {name = "[q4]Aggramars Überzeugung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Erlittener Schaden hat eine Chance, Eure Vielseitigkeit 14 Sek. lang um 27 zu erhöhen.\n\nAggramars Seelenstärke\n Wenn Euch das Pantheon Macht verleiht, wird Eure maximale Gesundheit 15 Sek. lang um 94 erhöht und Ihr werdet um 988 Gesundheit geheilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][154174] = {name = "[q4]Golganneths Lebenskraft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 Beweglichkeit\n[q2]Anlegen: Eure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 10 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\n Wenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 5 ] Naturschaden zufügt. Hält 15 Sek. lang an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][154175] = {name = "[q4]Eonars Mitgefühl", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 Intelligenz\n[q2]Anlegen: Eure Heileffekte haben eine Chance, in der Nähe eine Smaragdblüte wachsen zu lassen, die einen zufälligen verletzten Verbündeten alle 2 Sek. um 16 Gesundheit heilt. Hält 12 Sek. lang an.\n\nEonars tiefgrüne Umarmung\n Wenn Euch das Pantheon Macht verleiht, gewähren Eure nächsten 4 Einsätze von direkter Heilung dem Ziel einen Schild, der 30 Sek. lang 24 Schaden verhindert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][154176] = {name = "[q4]Khaz'goroths Kühnheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 Stärke\n{[q2]Anlegen: Eure Schaden verursachenden Angriffe haben eine Chance, Eure Waffe durch die Flammen von Khaz'goroths Schmiede 12 Sek. lang erglühen zu lassen, wodurch Eure automatischen Angriffe zusätzlich ( 1 * Haupthandwaffen-Min-Grundgeschwindigkeit * 8 ) Feuerschaden} verursachen.\n\nKhaz'goroths Schmiedeschlag\n Wenn Euch das Pantheon Macht verleiht, wird Euer kritischer Trefferwert, Euer {Tempo, Eure Meisterschaft oder Eure Vielseitigkeit 15 Sek. lang um 26 erhöht. Khaz'goroth erhöht immer Euren höchsten Wert.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][154177] = {name = "[q4]Norgannons Heldenmut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 8.\n[q2]Anlegen: Eure Schaden verursachenden Zauber haben eine Chance, Eure Intelligenz 12 Sek. lang um 22 zu erhöhen.\n\nNorgannons Befehl\n Wenn Euch das Pantheon Macht verleiht, erhaltet Ihr 15 Sek. lang 6 Aufladungen von 'Norgannons Befehl'. Eure Schaden verursachenden Zauber verbrauchen eine Aufladung, um dem Ziel zusätzlich 13 Schaden durch eine zufällige Magieart zuzufügen.\nVerkaufspreis:"}
