MultiLanguageItemData['de'][155819] = {name = "[q2]Dreimal eingelegtes Dreschadonomelett", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Beschwört Hubert, der Euch 10 Min. lang beschützt.\n\n Nur im Sturmsangtal.\n[q]\"Huberts Lieblingsmahlzeit. Die gibt dem Hündchen richtig Kraft.\""}
MultiLanguageItemData['de'][155820] = {name = "[q2]Stachelbombe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Wirft einen mit Stacheleberstacheln gespickten Sprengsatz, der allen Gegnern innerhalb von 10 Metern 3775 körperlichen Schaden zufügt und sie für 3 Sek. betäubt. (2 Min Abklingzeit)\n[q]\"Randvoll mit Stacheleberstacheln.\""}
MultiLanguageItemData['de'][155821] = {name = "[q2]Phiole mit zähflüssigem Schleim", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bedeckt Euch mit zähflüssigem Schleim, der den Effekt von 'Pfählstacheln' der Klingenstacheleber abschwächt.\n[q]\"Honig in einer Mischung mit Salben und Ölen. Riecht jedoch noch immer süß!\""}
MultiLanguageItemData['de'][155822] = {name = "[q2]Betäubungsstachel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Verschießt einen mit einem starken Betäubungsmittel bedeckten Stachel, der einen Klingenstacheleber für 30 Sek. in einen tiefen Schlaf versetzt. Erlittener Schaden unterbricht diesen Effekt. (3 Sek. Abklingzeit)\n[q]\"Dieser Stachel wurde in ein kräftiges Gebräu getaucht und könnte nun selbst den stärksten Borstenrücken in Schlaf versetzen.\""}
MultiLanguageItemData['de'][155823] = {name = "Eisiger Schneeball", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Werft mich! (30 Sek. Abklingzeit)\n[q]\"Schneeballschlacht!\""}
MultiLanguageItemData['de'][155824] = {name = "[q2]Fläschchen mit erzürnenden Dämpfen", additional_info = "Questgegenstand\nEinzigartig\n{[q2]Benutzen: Trinkt den Trank. Dadurch verursacht Ihr 15% mehr Schaden} und Euer {Tempo wird um 10% erhöht.}\n[q]\"Wenn Ihr so riechen würdet, wärt Ihr auch wütend.\""}
