MultiLanguageItemData['de'][156631] = {name = "[q4]Silas' Sphäre der Transmutation", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Hebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\n[q2]Benutzen: Konzentriert Euch auf die Sphäre, um sie für 1 Stunde in ein anderes Objekt zu verwandeln.\nBenötigtAlchemie von Kul Tiras\n(150)\n[q]\"Die Oberfläche der Sphäre verändert sich ständig und zeigt verschiedene Bilder für jeweils einen Augenblick, aber nie lang genug, um sie genau zu erkennen.\""}
MultiLanguageItemData['de'][156632] = {name = "[q4]Silas' Transportstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\n[q2]Hebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\n[q2]Benutzen: Beschwört ein allsehendes Auge, das Euch unverzüglich an einen sicheren Ort in der Nähe teleportieren kann. Kann nur im Freien von Kul Tiras oder Zandalar eingesetzt werden. Bleibt 2 Min. lang bestehen. (9 Min Abklingzeit)\nBenötigtAlchemie von Kul Tiras\n(1)"}
MultiLanguageItemData['de'][156633] = {name = "[q4]Silas' Trank des Wohlstands", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\n[q2]Hebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\n[q2]Benutzen: Erhöht die Chance, zusätzliche Alchemiegegenstände von Kul Tiras herzustellen. (20 Min Abklingzeit)\nBenötigtAlchemie von Kul Tiras\n(1)"}
MultiLanguageItemData['de'][156634] = {name = "[q4]Silas' Phiole der steten Genesung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\n[q2]Hebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\n[q2]Benutzen: Stellt mithilfe Eurer nie endenden, immer fließenden Phiole der steten Genesung 8000 Gesundheit wieder her! (5 Min Abklingzeit)\nBenötigtAlchemie von Kul Tiras\n(1)"}
