MultiLanguageItemData['de'][162135] = {name = "Rezept: Fläschchen des Tiefensogs", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen des Tiefensogs effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Fläschchen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtGlutorden\n- Respektvoll\nVerkaufspreis: \nFläschchen des Tiefensogs\n[q2]Benutzen: Erhöht die Stärke 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Akundas Biss (10), Sirenenpollen (15), Kristallphiole"}
MultiLanguageItemData['de'][162136] = {name = "Rezept: Endlose Tinktur des erneuerten Kampfgeists", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine endlose Tinktur des erneuerten Kampfgeists effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tinkturen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtTortollanische Sucher\n- Respektvoll\nVerkaufspreis: \n[q2]Endlose Tinktur des erneuerten Kampfgeists\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 9 Vielseitigkeit\n[q2]Anlegen: Stellt 696 Gesundheit wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt.\nVerkaufspreis:\nBenötigt Sirenenpollen (18), Flussknospe (18), Expulsom , Kristallphiole\n Optionale Reagenzien: [] (#47)"}
MultiLanguageItemData['de'][162137] = {name = "Rezept: Alchemistenstein der Sirene", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Alchemistenstein der Sirene effizienter herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines Alchemistensteins der Sirene noch weiter.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtTortollanische Sucher\n- Respektvoll\nVerkaufspreis: \n[q2]Alchemistenstein der Sirene\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 9 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie von Kul Tiras\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Meeresstängel (16), Sternmoos (16), Expulsom\n Optionale Reagenzien: [] (#47)"}
MultiLanguageItemData['de'][162138] = {name = "Rezept: Endlose Tinktur der bruchstückhaften Macht", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine endlose Tinktur der bruchstückhaften Macht effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tinkturen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis: \n[q3]Endlose Tinktur der bruchstückhaften Macht\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 9 Vielseitigkeit\n[q2]Benutzen: Kopiert den Stärkungseffekt des aktuellen Fläschchens des Trägers, jedoch nur zu einem Bruchteil der Wirksamkeit. Hält 12 Sek. lang an. (1 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Fläschchen der Ströme , Fläschchen der unendlichen Tiefe , Fläschchen des weiten Horizonts , Fläschchen des Tiefensogs , Expulsom (6)"}
MultiLanguageItemData['de'][162139] = {name = "Rezept: Wallender Alchemistenstein", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen wallenden Alchemistenstein effizienter herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines wallenden Alchemistensteins noch weiter.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis: \n[q3]Wallender Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 9 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 24 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie von Kul Tiras\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis: \nBenötigt Ankerkraut (12), Akundas Biss (32), Winterkuss (32), Expulsom (16)"}
MultiLanguageItemData['de'][162140] = {name = "[q2]Kampferprobtes Rüstungsset", additional_info = "Das Arathihochland\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verstärkt die Rüstung eines Verbündeten und verringert für 10 Min. seinen erlittenen Schaden um 10%.\n5 Aufladungen"}
