MultiLanguageItemData['de'][162255] = {name = "Rezept: Heiltrank der Küste", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Heiltrank der Küste effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtDie Sturmwacht\n- Respektvoll\nVerkaufspreis: \nHeiltrank der Küste\n[q2]Benutzen: Stellt 8000 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (2), Kristallphiole"}
MultiLanguageItemData['de'][162256] = {name = "Rezept: Verjüngungstrank der Küste", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Verjüngungstrank der Küste effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtGlutorden\n- Respektvoll\nVerkaufspreis: \nVerjüngungstrank der Küste\n[q2]Benutzen: Stellt 8000 Gesundheit und 2000 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Heiltrank der Küste , Manatrank der Küste"}
MultiLanguageItemData['de'][162257] = {name = "Rezept: Demitris Destillat der Täuschung", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man Demitris Destillat der Täuschung effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Destillate.\nBenötigtAlchemie von Kul Tiras\n(1)\nVerkaufspreis: \nDemitris Destillat der Täuschung\n[q2]Benutzen: Gewährt dem Trinkenden 18 Sek. lang Unsichtbarkeit. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sandschleicher (5), Meeresstängel (5), Kristallphiole"}
MultiLanguageItemData['de'][162258] = {name = "Rezept: Trank der Leichtfüßigkeit", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der Leichtfüßigkeit effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nVerkaufspreis: \nTrank der Leichtfüßigkeit\n[q2]Benutzen: Erhöht die Bewegungsgeschwindigkeit 8 Sek. lang um 150%. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternmoos (10), Kristallphiole"}
MultiLanguageItemData['de'][162259] = {name = "Rezept: Meeresnebeltrank", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Meeresnebeltrank effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nVerkaufspreis: \nMeeresnebeltrank\n[q2]Benutzen: Verwandelt den Trinkenden in eine Wolke, was langsamen Fall und das Schweben über Wasser gewährt. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Meeresstängel (10), Kristallphiole"}
MultiLanguageItemData['de'][162260] = {name = "Rezept: Trank der Verhüllung", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der Verhüllung effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nVerkaufspreis: \nTrank der Verhüllung\n[q2]Benutzen: Bewahrt den Trinkenden davor, entdeckt zu werden, solange er stillsteht. Hält 3 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (10), Kristallphiole"}
