MultiLanguageItemData['de'][162339] = {name = "Bauplan: XA-1000 Wellengleiter", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen XA-1000 Wellengleiter effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines XA-1000 Wellengleiters.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis: \nXA-1000 Wellengleiter\n[q2]Benutzen: Setzt ein Boot ein, das sofort losfährt und sich 25 Sek. lang über das Wasser bewegt. Funktioniert nicht an Land. (30 Sek. Abklingzeit)\nVerkaufspreis: \nBenötigt Moneliterz (10), Sturmsilbererz (5), Isoliertes Kabel (4)"}
MultiLanguageItemData['de'][162340] = {name = "Bauplan: Elektroschocker zur Reittiermotivierung", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Elektroschocker zur Reittiermotivierung effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines Elektroschockers zur Reittiermotivierung.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis: \nElektroschocker zur Reittiermotivierung\n[q2]Benutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\n\n Nicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n[q]\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"\nVerkaufspreis:\nBenötigt Moneliterz (8), Sturmsilbererz (4), Isoliertes Kabel (6)"}
MultiLanguageItemData['de'][162341] = {name = "Bauplan: Interdimensionales Begleiterrepositorium", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein interdimensionales Begleiterrepositorium effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines interdimensionalen Begleiterrepositoriums.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigtDie Sturmwacht\n- Respektvoll\nVerkaufspreis: \nInterdimensionales Begleiterrepositorium\n[q2]Benutzen: Beschwört einen tragbaren Stallmeister, mit dem Jäger bis zu 2 Min. lang interagieren können.\nVerkaufspreis: \nBenötigt Moneliterz (5), Sturmsilbererz (4), Isoliertes Kabel (5)"}
MultiLanguageItemData['de'][162342] = {name = "Bauplan: Stationärer Umkleider", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen stationären Umkleider effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines stationären Umkleiders.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigtDie Sturmwacht\n- Respektvoll\nVerkaufspreis: \nStationärer Umkleider\n[q2]Benutzen: Beschwört ein Gerät, mit dem Ihr das Aussehen Eurer Rüstung verändern könnt. Das Gerät bleibt bis zu 2 Min. lang bestehen.\n[q]\"Hinweis: Aufgrund der Funktionsweise dieses Geräts sind leichte Kopfschmerzen, Übelkeit sowie Wechsel von Volkszugehörigkeit und/oder Geschlecht nicht auszuschließen. Mit Vorsicht zu verwenden.\"\nVerkaufspreis:\nBenötigt Moneliterz (5), Sturmsilbererz (4), Isoliertes Kabel (5)"}
MultiLanguageItemData['de'][162343] = {name = "Bauplan: Zielfernrohr des Ausgucks", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Zielfernrohr des Ausgucks effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines Zielfernrohrs des Ausgucks.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis: \n[q3]Zielfernrohr des Ausgucks\n[q2]Benutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 194 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\n Durch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Moneliterz (10), Sturmsilbererz (5)"}
MultiLanguageItemData['de'][162344] = {name = "Bauplan: Monelitzielfernrohr des Eifers", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Monelitzielfernrohr des Eifers effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines Monelitzielfernrohrs des Eifers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis: \n[q3]Monelitzielfernrohr des Eifers\n[q2]Benutzen: Bringt dauerhaft eine spezielle Vorrichtung an einer Distanzwaffe an, sodass manchmal das Tempo 12 Sek. lang um 194 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\n Durch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Moneliterz (10), Sturmsilbererz (5)"}
MultiLanguageItemData['de'][162345] = {name = "Bauplan: Präzisionsgesinnungswandler", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Präzisionsgesinnungswandler effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines Präzisionsgesinnungswandlers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis: \n[q3]Präzisionsgesinnungswandler\nWird beim Anlegen gebunden\n{Einhändig} {Streitkolben}\n4 - 5 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 110 / 110\n[q]\"Die optimale Nutzung sieht Hiebe vor, bis das Ziel keine Widerrede mehr bieten kann.\"\nVerkaufspreis:\nBenötigt Sturmsilbererz (20), Platinerz (8), Expulsom (5)\n Optionale Reagenzien: [] (#49)"}
MultiLanguageItemData['de'][162346] = {name = "Bauplan: Präzise abgestimmter Sturmstahlvernichter", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen präzise abgestimmten Sturmstahlvernichter effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung eines präzise abgestimmten Sturmstahlvernichters.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis: \nHorde\n[q3]Präzise abgestimmter Sturmstahlvernichter\nWird beim Anlegen gebunden\n{Distanz} {Schusswaffe}\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nAllianz\n[q3]Präzise abgestimmter Sturmstahlvernichter\nWird beim Anlegen gebunden\n{Distanz} {Schusswaffe}\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Sturmsilbererz (20), Platinerz (8), Chemische Sprengkapsel (5), Expulsom (5)\n Optionale Reagenzien: [] (#49)"}
