MultiLanguageItemData['de'][162623] = {name = "[q3]Foliant der Verhexung: Sehnenreißer der Zandalari", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schamane\n[q2]Benutzen: Lehrt 'Verhexen: Sehnenreißer der Zandalari'.\n[q2]Verwandelt den Gegner für 1 Min. in einen Sehnenreißer der Zandalari. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nBenötigtZandalariimperium\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][162624] = {name = "[q3]Foliant der Verhexung: Weidenköter", additional_info = "Wird beim Aufheben gebunden\nKlassen: Schamane\n[q2]Benutzen: Lehrt 'Verhexen: Weidenköter'.\n[q2]Verwandelt den Gegner für 1 Min. in einen Weidenköter. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nBenötigtGlutorden\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][162625] = {name = "[q3]Foliant der Verwandlung: Terrorhorn", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]Benutzen: Lehrt 'Verwandlung: Terrorhorn'.\n[q2]Verwandelt den Gegner in ein Terrorhornjunges, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt ab. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nBenötigtZandalariimperium\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][162626] = {name = "[q3]Foliant der Verwandlung: Hummel", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]Benutzen: Lehrt 'Verwandlung: Hummel'.\n[q2]Verwandelt den Gegner in eine Hummel, die 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nBenötigtDie Sturmwacht\n- Respektvoll\nVerkaufspreis:"}
