MultiLanguageItemData['de'][162691] = {name = "Rezept: Stahlhauttrank", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Stahlhauttrank effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtDie Eidgebundenen\n- Respektvoll\nVerkaufspreis: \nStahlhauttrank\n[q2]Benutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 269 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Meeresstängel (10), Flussknospe (8), Kristallphiole"}
MultiLanguageItemData['de'][162692] = {name = "Rezept: Trank der Erfrischung", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der Erfrischung effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtZandalariimperium\n- Respektvoll\nVerkaufspreis: \nTrank der Erfrischung\n[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 601 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (10), Sternmoos (8), Kristallphiole"}
MultiLanguageItemData['de'][162693] = {name = "Rezept: Trank der Bluteruption", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der Bluteruption effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtTalanjis Expedition\n- Respektvoll\nVerkaufspreis: \nTrank der Bluteruption\n[q2]Benutzen: Erfüllt Euer Blut für 25 Sek. mit Hitze, die Euren Nahkampfangriffen eine Chance gewährt, eine Blutexplosion auszulösen, die 5371 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (8), Flussknospe (6), Kristallphiole"}
MultiLanguageItemData['de'][162694] = {name = "Rezept: Trank des drohenden Todes", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank des drohenden Todes effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtVoldunai\n- Respektvoll\nVerkaufspreis: \nTrank des drohenden Todes\n[q2]Benutzen: Ermächtigt Euch für 25 Sek. mit Schattenmagie. Sie verleiht Euren Schaden verursachenden Distanzfähigkeiten eine Chance, einen Todesblitz abzufeuern, dessen Schaden sich mit der zurückgelegten Strecke erhöht und der bis zu 331209 Schattenschaden verursacht. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Meeresstängel (8), Sternmoos (6), Kristallphiole"}
MultiLanguageItemData['de'][162695] = {name = "Rezept: Fläschchen der Ströme", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen der Ströme effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Fläschchen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtDie Eidgebundenen\n- Respektvoll\nVerkaufspreis: \nFläschchen der Ströme\n[q2]Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Akundas Biss (10), Meeresstängel (15), Kristallphiole"}
MultiLanguageItemData['de'][162696] = {name = "Rezept: Fläschchen der unendlichen Tiefe", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen der unendlichen Tiefe effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Fläschchen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtZandalariimperium\n- Respektvoll\nVerkaufspreis: \nFläschchen der unendlichen Tiefe\n[q2]Benutzen: Erhöht die Intelligenz 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Winterkuss (10), Flussknospe (15), Kristallphiole"}
MultiLanguageItemData['de'][162697] = {name = "Rezept: Fläschchen des weiten Horizonts", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen des weiten Horizonts effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Fläschchen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtTalanjis Expedition\n- Respektvoll\nVerkaufspreis: \nFläschchen des weiten Horizonts\n[q2]Benutzen: Erhöht die Ausdauer 1 Stunde lang um 107 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Winterkuss (10), Sternmoos (15), Kristallphiole"}
MultiLanguageItemData['de'][162698] = {name = "Rezept: Fläschchen des Tiefensogs", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen des Tiefensogs effektiver herstellt.\n[q2]Chance auf die Herstellung mehrerer Fläschchen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtVoldunai\n- Respektvoll\nVerkaufspreis: \nFläschchen des Tiefensogs\n[q2]Benutzen: Erhöht die Stärke 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Akundas Biss (10), Sirenenpollen (15), Kristallphiole"}
MultiLanguageItemData['de'][162701] = {name = "Rezept: Endlose Tinktur der bruchstückhaften Macht", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine endlose Tinktur der bruchstückhaften Macht effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tinkturen.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtDie Eidgebundenen\n- Respektvoll\nVerkaufspreis: \n[q3]Endlose Tinktur der bruchstückhaften Macht\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 9 Vielseitigkeit\n[q2]Benutzen: Kopiert den Stärkungseffekt des aktuellen Fläschchens des Trägers, jedoch nur zu einem Bruchteil der Wirksamkeit. Hält 12 Sek. lang an. (1 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Fläschchen der Ströme , Fläschchen der unendlichen Tiefe , Fläschchen des weiten Horizonts , Fläschchen des Tiefensogs , Expulsom (6)"}
MultiLanguageItemData['de'][162702] = {name = "Rezept: Wallender Alchemistenstein", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen wallenden Alchemistenstein effizienter herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung eines wallenden Alchemistensteins noch weiter.\nBenötigtAlchemie von Kul Tiras\n(1)\nBenötigtDie Eidgebundenen\n- Respektvoll\nVerkaufspreis: \n[q3]Wallender Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 9 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 24 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie von Kul Tiras\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis: \nBenötigt Ankerkraut (12), Akundas Biss (32), Winterkuss (32), Expulsom (16)"}
