MultiLanguageItemData['de'][163640] = {name = "Klarer Huangtzewhisky", additional_info = "[q2]Benutzen: Ein starkes alkoholisches Getränk.\n[q]\"Ein delikates Tröpfchen aus dem Tal der Vier Winde. Seine einzigartigen Geschmacksnoten werden angeblich einzig durch das vom Grund der Huangtzekaskade gesammelte Wasser erzielt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][163641] = {name = "Kristallklarer Brunnhildar", additional_info = "[q2]Benutzen: Ein starkes alkoholisches Getränk.\n[q]\"Diese aus im Holzofen gebranntem Getreide destillierte Spirituose bietet nach einem einzigartigen Kaltfiltrierverfahren eine Balance aus reinem Malz und Rauch.\"\nVerkaufspreis:"}
