MultiLanguageItemData['de'][163714] = {name = "[q0]Verbotenes Seemannslied der munteren Meute", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Liedzeilen sollen die Mannschaft aufheitern und sie zu reger Arbeit motivieren, aber es ist offensichtlich, dass keiner von ihnen mehr am Leben ist.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][163715] = {name = "[q0]Verbotenes Seemannslied des Früchtezählens", additional_info = "Wird beim Aufheben gebunden\n[q]\"Zunächst klingt es wie das Lied eines einfachen Hafenarbeiters, doch dann wird Euch klar, dass dieser Arbeiter der Tod ist, der Seelen einsammelt und sich das Ende seiner eigenen Existenz herbeisehnt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][163716] = {name = "[q0]Verbotenes Seemannslied des Zechens", additional_info = "Wird beim Aufheben gebunden\n[q]\"Beim Zuhören denkt man zunächst, dieses Seemannslied handle von einer Besatzung, die einem betrunkenen Besatzungsmitglied einige lustige Streiche spielt. Aber je länger man über den Text nachdenkt, desto verstörender wird er.\"\nVerkaufspreis:"}
