MultiLanguageItemData['de'][163741] = {name = "[q3]Magischer Spaßstein", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Wirft den Stein einem freundlich gesinnten Spielercharakter zu. Wenn möglich, wirft er ihn automatisch zurück. (30 Sek. Abklingzeit)\n[q]\"Der NEUE lustige Spaßstein, jetzt mit 100% mehr GLITZER!\""}
