MultiLanguageItemData['de'][164740] = {name = "[q4]Üb3r-Schrauber", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Ermöglicht dem Ingenieur, Üb3r-Konstrukte anzufertigen.\n[q2]Benutzen: Beschwört ein Üb3r-Konstrukt, das den Zaubernden 20 Sek. lang unterstützt. Wenn kein Üb3r-Konstrukt festgelegt ist, erscheint ein zufälliges. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (150)"}
MultiLanguageItemData['de'][164741] = {name = "Unbeständige Azeritgranate", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 5 min (Realzeit)\n[q2]Benutzen: Fügt allen Gegnern innerhalb von 7 Metern um den Einschlagsort 10 bis 16 Arkanschaden zu. (5 Sek. Abklingzeit)\n[q2]Gewährt die Fähigkeit 'Azeritgranate'."}
