MultiLanguageItemData['de'][164772] = {name = "Pfeife des Kul Tiranischen Waisenkindes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Das Waisenkind rufen und fortschicken, dessen Beaufsichtigung Ihr während der Kinderwoche übernommen habt.\nBenötigtKinderwoche"}
MultiLanguageItemData['de'][164773] = {name = "Gryzix' Dekodierer", additional_info = "Questgegenstand\n[q]\"Kann verschlüsselte Dokumente von Azshara bis Zangamarschen dechiffrieren. Kann verwendet werden, um den Bauplan des Üb3r-Schraubers zu entschlüsseln.\""}
