MultiLanguageItemData['de'][165019] = {name = "[q4]Boshafter schwarzer Kriegssäbler", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren boshaften schwarzen Kriegssäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Diese großen Katzen bringen als Geschenk nur die abgetrennten Gliedmaßen Eurer Gegner heim.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1"}
MultiLanguageItemData['de'][165020] = {name = "[q4]Boshaftes schwarzes Knochenross", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares boshaftes schwarzes Knochenross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Diese Skelettrösser kennen keine Furcht, brauchen kein Futter und können unvorstellbar große Distanzen zurücklegen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1"}
