MultiLanguageItemData['de'][165568] = {name = "[q4]Anrufung von Yu'lon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\n[q2]Benutzen: Befiehlt einer Beschwörung von Yu'lon, Euer Ziel anzugreifen. Sie verursacht 191 Naturschaden, der auf das Ziel und alle Gegner in der Nähe aufgeteilt wird. Der Schaden wird erhöht, wenn mehrere Gegner getroffen werden. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165569] = {name = "[q4]Zauberschutz der Umhüllung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\n[q2]Benutzen: Hüllt bis zu 5 Verbündete im Zielbereich 10 Sek. lang in geteilte Schilde, die für alle Ziele zusammen bis zu [ 458 * (1 + Vielseitigkeit)] Schaden verhindern. Je mehr Verbündete geschützt werden, desto mehr Schaden wird insgesamt verhindert. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165570] = {name = "[q4]Anker der ewigen Kälte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\n[q2]Anlegen: Eure Nahkampffähigkeiten, die Schaden verursachen, belegen das Ziel mit 'Ewige Kälte'. Dies verursacht alle 3 Sek. 1 Frostschaden und verringert die Bewegungsgeschwindigkeit um 2%. Bis zu 10-mal stapelbar. Hält 12 Sek. lang an. (750ms Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165571] = {name = "[q4]Strahlender Span", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\n[q2]Anlegen: Solange sich keine Verbündeten innerhalb von 5 Metern um Euch befinden, erhaltet Ihr alle 2 Sek. 1 kritischen Trefferwert. Bei 10 Stapeln erhaltet Ihr zusätzlich 4 Meisterschaft. Diese Effekte verfallen langsam, wenn Verbündete in der Nähe sind, die diesen Gegenstand nicht tragen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][165572] = {name = "[q4]Piepsender oszillierender Wirbelenergiereaktor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\n[q2]Anlegen: Euer kritischer Trefferwert wird alle 2 Sek. um 3 erhöht, bis auf einen maximalen kritischen Trefferwert von ( 3 * 6), der 6 Sek. lang anhält. Danach verringert er sich, bis das Gerät sich für 6 Sek. ausschaltet. Dieser Zyklus wiederholt sich alle 32 Sek.\n[q2]Benutzen: Behält für 6 Sek. Eure derzeitige Oszillation bei. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165573] = {name = "[q4]Diamantbeschichtetes Refraktionsprisma", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Verleiht Euch alle 10 Sek. einen Absorptionsschild in Höhe von [ 82 * (1 + Vielseitigkeit)], bis zu einer maximalen Absorption von [( 82 * (1 + Vielseitigkeit)) * 5].\nVerkaufspreis:"}
MultiLanguageItemData['de'][165574] = {name = "[q4]Grongs Urfuror", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\n[q2]Benutzen: Verfällt in eine Dschungelwut und verursacht im Verlauf von 4 Sek. ( 93 * 5) körperlichen Schaden, der auf Gegner in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. Während die Wut anhält, könnt Ihr Euch weder bewegen noch Fähigkeiten einsetzen. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165576] = {name = "[q4]Kodex des Gezeitensturms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\n[q2]Benutzen: Entfesselt eine Welle von 6 Gezeitenelementaren, die über Euer Ziel hereinbrechen, explodieren und dabei jeweils 52 Frostschaden verursachen, der unter allen Gegnern in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. (1.5Min. Abklingzeit) (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165577] = {name = "[q4]Bwonsamdis Handel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Absorbiert bis zu 2236 Schaden eines Angriffs, der Euch töten würde. Wenn dieser Effekt auftritt, werdet Ihr sofort um 434 Gesundheit geheilt und erhaltet dann 'Bwonsamdis Handel', wodurch Heilung in Höhe von 60% des ursprünglich verhinderten Schadens absorbiert wird. Dies kann nur einmal alle 6 Min. geschehen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][165578] = {name = "[q4]Spiegel des geteilten Schicksals", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\n[q2]Benutzen: Stellt beim Ziel 4580 Gesundheit wieder her, aber verflucht Euch dabei selbst, wodurch die nächsten 136 erhaltene Heilung absorbiert werden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165579] = {name = "[q4]Kimbuls messerscharfe Kralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\n[q2]Anlegen: Eure Schaden verursachenden Angriffe haben eine Chance, das Ziel mit Klauen zu schlagen und ihm im Verlauf von 6 Sek. 20 körperlichen Blutungsschaden zuzufügen. Wenn Ihr das Ziel von hinten mit den Klauen trefft, entzieht Ihr ihm 50% des verursachten Schadens als Gesundheit. (6s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][165580] = {name = "[q4]Rasant ausschlagende gigavoltgeladene Erfindung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\n[q2]Benutzen: Erhöht Euer Tempo um 4 und Eure Geschwindigkeit um 1 . Dieser Effekt ist im Verlauf von 10 Sek. bis zu 15-Mal stapelbar. Die Stapel erhöhen sich immer schneller, je mehr die gigavoltgeladene Erfindung beschleunigt. Die Erfindung läuft insgesamt 18 Sek. lang. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
