MultiLanguageItemData['de'][167002] = {name = "[q0]Bauplan: Unterjustierte Corgibrille", additional_info = "[q]\"Ein fehlkonzipiertes Gerät, das dazu dienen sollte, Freunde niedlich aussehen zu lassen. Tatsächlich macht die Brille dem Träger lediglich bewusst, dass es Corgis wirklich gibt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][167003] = {name = "[q0]Bauplan: Echteisenofenhandschuhe", additional_info = "[q]\"Instruktionen zur Herstellung von Echteisenofenhandschuhen. Ein Zusatz am Ende der Anleitung besagt: '... umständlich in der Handhabung, sehr schwer, steif und schützen nur bedingt vor hohen Temperaturen.'\"\nVerkaufspreis:"}
