MultiLanguageItemData['de'][167832] = {name = "Elritzen in der Dose", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 13200 / 5 * 20) Gesundheit und ( 8000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Eure Bewegungsgeschwindigkeit wird innerhalb von Mechagon 1 Stunde lang um 46 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167833] = {name = "[q4]Klafterflossen", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Stoff}\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]+ 2 Vielseitigkeit\nHaltbarkeit 55 / 55\n[q2]Anlegen: Gewährt Euch pro 10000 verbrauchtem Mana 8 Sek. lang einen Schild, der [ 15 * (1 + Vielseitigkeit)] Schaden absorbiert, bis maximal [ 147 * (1 + Vielseitigkeit)] Schaden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167834] = {name = "[q4]Sturmgleiterschritte", additional_info = "Wird beim Aufheben gebunden\n{Füße} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]+ 5 Vielseitigkeit\nHaltbarkeit 80 / 80\n[q2]Anlegen: Eure automatischen Angriffe gewähren Euch 15 Sek. lang 'Unberührbar' (bis zu 10 - mal stapelbar). 'Unberührbar' gewährt 1 kritischen Trefferwert. Jeglicher erlittene Schaden entfernt sämtliche Stapel von 'Unberührbar'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167835] = {name = "[q4]Beinwickel des missgestalteten Herolds", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Stoff}\n5 Rüstung\n+6 Intelligenz\n+9 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\nHaltbarkeit 120 / 120\n{[q2]Benutzen: Öffnet für 12 Sek. einen Leerenriss unter Euch, der Euer {Tempo um 26 erhöht. Wenn Ihr den Riss verlasst, bricht er Zusammen und Ihr erleidet 532 Schattenschaden}. (1 Min Abklingzeit)}\nVerkaufspreis:"}
MultiLanguageItemData['de'][167836] = {name = "[q3]Bauplan: Elritzen in der Dose", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Durch die sorgfältige Konservierung bleibt der eklige Geschmack auf ewig erhalten.\""}
MultiLanguageItemData['de'][167837] = {name = "[q4]Sucherkette des Aufständischen", additional_info = "Wird beim Aufheben gebunden\n{Taille} {Kette}\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 55 / 55\n[q2]Anlegen: Das Töten einer Entartung inspiriert 4 Verbündete und gewährt ihnen 20 Sek. lang 3 kritischen Trefferwert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167838] = {name = "[q4]Gamaschen des abtrünnigen Gezeitenweisen", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Leder}\n8 Rüstung\n+6 [Beweglichkeit oder Intelligenz]\n+9 Ausdauer\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\n[q2]Anlegen: Bei über 60% Gesundheit haben Eure Schadensfähigkeiten eine geringe Chance, Euer Ziel mit einem Blitz zu treffen, der [ 117 * (1 + Vielseitigkeit)] Naturschaden verursacht. Bei unter 60% Gesundheit haben Eure Schadensfähigkeiten eine geringe Chance, im Verlauf von 10 Sek. [ 32 * 6 * (1 + Vielseitigkeit)] Gesundheit wiederherzustellen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167839] = {name = "[q4]Handschutz des verlorenen Verstands", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Kette}\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\nHaltbarkeit 55 / 55\n[q2]Anlegen: Bei über 90% Gesundheit haben Eure Schadensfähigkeiten eine sehr hohe Chance, Euch und Eurem Ziel 24 Schattenschaden zuzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167840] = {name = "[q4]Unsäglicher Schnallengürtel des Gedankendiebs", additional_info = "Wird beim Aufheben gebunden\n{Taille} {Platte}\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 55 / 55\n[q2]Anlegen: Wenn Eure Gesundheit unter 25% fällt, werdet Ihr sofort um [ 495 * (1 + Vielseitigkeit)] geheilt. Danach erleidet Ihr im Verlauf von 10 Sek. 495 Schattenschaden. Dieser Effekt kann nur einmal alle 3 Min. auftreten.\nVerkaufspreis:"}
MultiLanguageItemData['de'][167841] = {name = "[q4]Stulpen des abyssischen Sprechers", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Platte}\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 55 / 55\n{[q2]Anlegen: Eure Fähigkeiten haben eine Chance, Euch einen Schild zu gewähren, der 1 Min. lang [ 442 * (1 + Vielseitigkeit)] Schaden} absorbiert. Während der Schild hält, ist Euer {Tempo um 11 erhöht.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][167842] = {name = "[q4]Fathuuls Flutschützer", additional_info = "Wird beim Aufheben gebunden\n{Beine} {Kette}\n12 Rüstung\n+6 [Beweglichkeit oder Intelligenz]\n+9 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 120 / 120\n[q2]Anlegen: Bei über 90% Gesundheit haben Eure Schadensfähigkeiten eine hohe Chance, eine Welle auf Euer Ziel zu entfesseln, die [ 39 * (1 + Vielseitigkeit)] Frostschaden verursacht. Bei unter 90% Gesundheit haben Eure Schadensfähigkeiten eine hohe Chance, [ 59 * (1 + Vielseitigkeit)] Gesundheit wiederherzustellen.\nVerkaufspreis:"}
