MultiLanguageItemData['de'][168022] = {name = "[q3]Pläne: Khaz'gorischer Schmiedehammer", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Khaz'gorischen Schmiedehammers.\n[q2]Erschafft einen khaz'gorischen Hammer.\nBenötigt Schmiedekunst von Kul Tiras (150)\nVerkaufspreis: \n[q4]Khaz'gorischer Schmiedehammer\nWird beim Aufheben gebunden\nEinzigartig\nWerkzeug für Schmiedekunst[q2]Beim Erschaffen von Schmiederüstung oder -waffen besteht eine Chance, dass sie mit der Eigenschaft 'Unzerstörbar' belegt werden.\n[q2]Benutzen: Gestattet es dem Benutzer, einen Ausrüstungsgegenstand sofort zu reparieren. (1 Stunde Abklingzeit)\nAnlegen: +4 Schmiedekunstfertigkeit.\nBenötigt Schmiedekunst von Kul Tiras (150)\n[q]\"Dieser Hammer kann anstelle eines normalen Schmiedehammers für Handwerksprojekte verwendet werden.\"\nBenötigt Blut des Titanen (30), Werkzeuge zum Präzisionssegnen , Azerokks Faust , Sturmsilbererz (30), Platinerz (20), Expulsom (10)"}
MultiLanguageItemData['de'][168023] = {name = "Kaputtes Transportrelais", additional_info = "Wird beim Aufheben gebunden"}
MultiLanguageItemData['de'][168024] = {name = "[q3]Formel: Iwens Verzauberungsrute", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung einer Iwens Verzauberungsrute.\n[q2]Stellt Iwens Verzauberungsrute her.\nBenötigt Verzauberkunst von Kul Tiras (150)\nVerkaufspreis: \n[q4]Iwens Verzauberungsrute\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Gewährt beim Entzaubern zusätzliche Ressourcen.\n[q2]Benutzen: Verbraucht einen trüben Kristall, um einen inaktiven Golem zum Leben zu erwecken. (5 Sek. Abklingzeit)\nBenötigt Verzauberkunst von Kul Tiras (150)\n[q]\"Vor lauter Drustmagie surrt diese Rute. Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"\nBenötigt Greifender Weidenarm , Runenstein von Thros , Verweilende Drustessenz (50), Umbralsplitter (20), Trüber Kristall (10), Expulsom (10)"}
MultiLanguageItemData['de'][168025] = {name = "[q3]Bauplankompendium: Üb3r-Schrauber", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Ingenieurskunstbaupläne neu, die Ihr durch das Erfüllen von Quests für Euer Handwerkszeug erhalten, aber nach einem Berufswechsel vergessen habt.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nVerkaufspreis:"}
MultiLanguageItemData['de'][168026] = {name = "[q3]Buch der Techniken: Lana'thels blutiger Federkiel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erlernt alle Inschriftentechniken neu, die Ihr durch das Erfüllen von Quests für Euer Handwerkszeug erhalten, aber nach einem Berufswechsel vergessen habt.\nBenötigt Inschriftenkunde von Kul Tiras (150)\nVerkaufspreis:"}
MultiLanguageItemData['de'][168027] = {name = "[q3]Vorlage: Fokus des Juwelenhammers", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fokus des Juwelenhammers.\n[q2]Schleift eine Fokuslinse.\nBenötigtJuwelierskunst von Kul Tiras\n(150)\nVerkaufspreis: \n[q4]Fokus des Juwelenhammers\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Ermöglicht dem Träger, mit Schreinen in Kul Tiras und Zandalar zu interagieren. Er kann das Licht der Zone mithilfe der Linse bündeln und so eine Edelsteingeode erschaffen.\n[q2]Benutzen: Entfernt mithilfe des Fokus sorgfältig einen gesockelten Edelstein aus einem Eurer Gegenstände.\nBenötigtJuwelierskunst von Kul Tiras\n(150)\nBenötigt Harlans diamantenübersätes Fernrohr , Unbearbeitete Azeritgeode , Feines Azeritpulver (50), Krakenauge (5), Expulsom (10)"}
MultiLanguageItemData['de'][168028] = {name = "[q3]Muster: Schlägel der donnernden Häute", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Schlägels der donnernden Häute.\n[q2]Stellt einen Schlägel der donnernden Häute her.\nBenötigt Lederverarbeitung von Kul Tiras (150)\nVerkaufspreis: \n[q4]Schlägel der donnernden Häute\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Ermöglicht Euch, mit Trommeln der Urmacht zu interagieren, die Euch mit Geschwindigkeit, Macht oder Widerstandskraft segnen.\n[q2]Benutzen: Erhöht Euer Tempo um 15%. Hält 40 Sek. lang an.\n\n Wenn der Effekt endet, seid Ihr erschöpft und könnt 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren. (10 Min Abklingzeit)\nBenötigt Lederverarbeitung von Kul Tiras (150)\n[q]\"Nützlich zur Formung von Lederstücken und als Schlaginstrument.\"\nBenötigt Lange majestätische Sehne (4), Geist des Geschlagenen (15), Blutbefleckter Knochen (50), Sturmbalg (50), Gehärteter Sturmbalg (25), Expulsom (10)"}
MultiLanguageItemData['de'][168029] = {name = "[q3]Muster: Synchronfaden", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Synchronfadens.\n[q2]Synchronfaden herstellen.\nBenötigt Schneiderei von Kul Tiras (150)\nVerkaufspreis: \n[q4]Synchronfaden\nWird beim Aufheben gebunden\nEinzigartig\n[q2]In der Zeit verschobener Stoff aus Kul Tiras und Zandalar erscheint öfter in der Welt.\n[q2]Benutzen: Ermöglicht Synchronschneidern, in Kul Tiras und Zandalar Risse im Gewebe der Zeit zu flicken.\nBenötigt Schneiderei von Kul Tiras (150)\n[q]\"Ein Stich zur rechten Zeit sorgt dafür, dass die Welt nicht auseinanderfällt.\"\nBenötigt Essenz der Trolldynastie , Essenz des majestätischen Loa , Essenz der Tiefen , Essenz der Sande , Gischtvernebeltes Leinen (75), Nylonfaden (75), Expulsom (10)"}
