MultiLanguageItemData['de'][168436] = {name = "[q6]Konzentrierte Sternenspitze", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nGroße Macht:\n Geist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit. \n Geringe Macht:\n Ergebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist, wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 3-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168439] = {name = "[q6]Wirbelnder Sternenstaub", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nGroße Macht:\n Geist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit. Bis zu 6 andere Verbündete im Strahl werden alle 0.6 Sek. um [ 145 * (1 + Vielseitigkeit)] Gesundheit geheilt. \n Geringe Macht:\n Ergebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist', wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 5-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168440] = {name = "[q6]Schimmernder Sternensplitter", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nErlernt Rang 3 einer Essenz von den Rajani oder dem Abkommen von Uldum auf einem anderen Charakter, um diese Essenz freizuschalten.\nBenötigt einen respektvollen Ruf bei den Rajani. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Geist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit. Bis zu 6 andere Verbündete im Strahl werden alle 0.6 Sek. um [ 145 * (1 + Vielseitigkeit)] Gesundheit geheilt.\n\n Immer wenn 'Geist der Bewahrung' das Primärziel heilt, erhaltet Ihr einen Stapel von 'Ergebener Geist'. \n Geringe Macht:\n Ergebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist, wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 5-mal stapelbar.\n\n Jeder verbrauchte Stapel von 'Ergebener Geist' erhöht die kritische Trefferchance Eures nächsten Einsatzes von ' Schnellheilung ' innerhalb von 15 Sek. um 20%.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168442] = {name = "[q6]Brodelndes Blut der Bezwungenen", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\n{Große Macht:\n Blut des Feindes\nSofort 2 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden} zu. Ihr gewinnt 10 Sek. lang 25% kritische Trefferchance gegen die Ziele hinzu . \n Geringe Macht:\n Blutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 {Tempo.}"}
MultiLanguageItemData['de'][168443] = {name = "[q6]Aufgewühltes Blut der Beherrschten", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\nErfordert den Erfolg \"Schlachtfeldraufbold\". (Kauf nicht möglich, wenn bereits bekannt)\n{Große Macht:\n Blut des Feindes\nSofort 1.5 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden} zu. Ihr gewinnt 10 Sek. lang 25% kritische Trefferchance gegen die Ziele hinzu. \n Geringe Macht:\n Blutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 {Tempo.\n\n Jeder Stapel von 'Blutgetränkt' gewährt 2 kritischen Trefferwert.}"}
MultiLanguageItemData['de'][168444] = {name = "[q6]Brodelndes Blut der Eroberten", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\nErfordert den Erfolg \"Schlachtfeldtaktiker\". (Kauf nicht möglich, wenn bereits bekannt)\nErlernt Rang 3 vom Blut des Feindes, des Kunstwerks der Zeit oder der Sphäre der Unterdrückung auf einem anderen Charakter, um diese Essenz freizuschalten.\n{Große Macht:\n Blut des Feindes\nSofort 1.5 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden} zu. Ihr erhaltet 10 Sek. lang 25% zusätzliche kritische Trefferchance gegen die Ziele und Euer kritischer Trefferschaden wird 5 Sek. lang um 25% erhöht. \n Geringe Macht:\n Blutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Jeder Stapel von 'Blutgetränkt' erhöht den kritischen Trefferwert um 2 . Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 {Tempo.\n\n Es besteht eine Chance von 25%, dass 'Blutgetränkt' nur 30 Stapel verbraucht.}"}
