MultiLanguageItemData['de'][168533] = {name = "[q3]Bauplan: Üb3r-Modul: P.O.G.O.", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Üb3r-Modul: P.O.G.O. herstellt.\n[q2]Erschafft ein Üb3r-Modul: P.O.G.O.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nBenötigtRostbolzenwiderstand\n- Respektvoll\n\n\nÜb3r-Modul: P.O.G.O.\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Garantiert, dass Eure Üb3r-Erfindungen P.O.G.O.s sind.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nBenötigt Moneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)"}
MultiLanguageItemData['de'][168534] = {name = "[q3]Bauplan: Üb3r-Modul: Üb3r-Spule", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Üb3r-Modul: Üb3r-Spule herstellt.\n[q2]Erschafft ein Üb3r-Modul: P.O.G.O.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nBenötigtRostbolzenwiderstand\n- Respektvoll\n\n\nÜb3r-Modul: Üb3r-Spule\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Garantiert, dass Eure Üb3r-Erfindungen Üb3r-Spulen sind.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nBenötigt Moneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)"}
MultiLanguageItemData['de'][168535] = {name = "[q3]Bauplan: Üb3r-Modul: Schrottkanone", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man ein Üb3r-Modul: Schrottkanone herstellt.\n[q2]Erschafft ein Üb3r-Modul: Schrottkanone.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nBenötigtRostbolzenwiderstand\n- Respektvoll\n\n\nÜb3r-Modul: Schrottkanone\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Garantiert, dass Eure Üb3r-Erfindungen Schrottkanonen sind.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nBenötigt Moneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)"}
MultiLanguageItemData['de'][168536] = {name = "[q6]Rekristallisierende Azeritformation", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nGroße Macht:\n Azeroths unsterbliches Geschenk\nSofort 45 sek. Abklingzeit Verringert 4 Sek. lang sämtlichen von Euch erlittenen Schaden um 20%. \n Geringe Macht:\n Verhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 8 Sek. 799 Rüstung.\n\n Dieser Effekt kann nur einmal alle 120 Sek. auftreten. (2.5Min. Abklingzeit)"}
MultiLanguageItemData['de'][168537] = {name = "[q6]Gehärtete Azeritformation", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nErlernt Rang 3 der Kondensierten Lebenskraft, der Vitalitätsverbindung oder von Azeroths unsterblichem Geschenk auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\n Azeroths unsterbliches Geschenk\nSofort 45 sek. Abklingzeit Verringert 2 Sek. lang sämtlichen von Euch erlittenen Schaden um 40% sowie danach 2 Sek. lang um 20%. \n Geringe Macht:\n Verhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr 4 Sek. lang ( 799 * 200 / 100) Rüstung sowie danach 4 Sek. lang 799 Rüstung.\n\n Dieser Effekt kann nur einmal alle 120 Sek. auftreten. (2.5Min. Abklingzeit)"}
MultiLanguageItemData['de'][168538] = {name = "[q6]Blendende Azeritformation", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Todesritter , Mönch , Druide , Dämonenjäger\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nGroße Macht:\n Azeroths unsterbliches Geschenk\nSofort 45 sek. Abklingzeit Verringert 2 Sek. lang sämtlichen von Euch erlittenen Schaden um 40% sowie danach 2 Sek. lang um 20%. \n Geringe Macht:\n Verhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr 4 Sek. lang ( 799 * 200 / 100) Rüstung sowie danach 4 Sek. lang 799 Rüstung.\n\n Dieser Effekt kann nur einmal alle 120 Sek. auftreten. (2.5Min. Abklingzeit)"}
