MultiLanguageItemData['de'][168558] = {name = "[q6]Fetisch der tiefen Verliese", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nGroße Macht:\n Anima des Todes\nSofort 2 min Abklingzeit Ihr nutzt Eure Lebenskraft, um Gegner zu verbrennen. Ihr fügt allen Gegnern in der Nähe 10% Eurer maximalen Gesundheit als Feuerschaden zu und werdet pro getroffenem Gegner um 5% Eurer maximalen Gesundheit geheilt, bis zu 25% Eurer maximalen Gesundheit. \n Geringe Macht:\n Anima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar.\n\n Gewährt Euch einen Stapel von 'Anima des Lebens', wenn Ihr einen Gegner besiegt, der Erfahrung oder Ehre gewährt.\n\n Dieser Effekt endet, wenn Eure Gesundheit unter 35% fällt."}
MultiLanguageItemData['de'][168559] = {name = "[q6]Fetisch der verborgenen Labyrinthe", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nErlernt Rang 3 der Essenz der Fokussierungsiris, der Invokation der Lebensbinderin oder der Anima von Leben und Tod auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\n Anima des Todes\nSofort 2 min Abklingzeit Ihr nutzt Eure Lebenskraft, um Gegner zu verbrennen. Ihr fügt allen Gegnern in der Nähe 10% Eurer maximalen Gesundheit als Feuerschaden zu und werdet pro getroffenem Gegner um 10% Eurer maximalen Gesundheit geheilt, bis zu 50% Eurer maximalen Gesundheit. \n Geringe Macht:\n Anima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar. Während Ihr über maximale Stapel verfügt, werdet Ihr alle 5 Sek. um 185 Gesundheit geheilt.\n\n Gewährt Euch einen Stapel von 'Anima des Lebens', wenn Ihr einen Gegner besiegt, der Erfahrung oder Ehre gewährt.\n\n Dieser Effekt endet, wenn Eure Gesundheit unter 35% fällt."}
MultiLanguageItemData['de'][168560] = {name = "[q6]Fetisch der vergoldeten Katakomben", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nGroße Macht:\n Anima des Todes\nSofort 2 min Abklingzeit Ihr nutzt Eure Lebenskraft, um Gegner zu verbrennen. Ihr fügt allen Gegnern in der Nähe 10% Eurer maximalen Gesundheit als Feuerschaden zu und werdet pro getroffenem Gegner um 10% Eurer maximalen Gesundheit geheilt, bis zu 50% Eurer maximalen Gesundheit. \n Geringe Macht:\n Anima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar. Während Ihr über maximale Stapel verfügt, werdet Ihr alle 5 Sek. um 185 Gesundheit geheilt.\n\n Gewährt Euch einen Stapel von 'Anima des Lebens', wenn Ihr einen Gegner besiegt, der Erfahrung oder Ehre gewährt.\n\n Dieser Effekt endet, wenn Eure Gesundheit unter 35% fällt."}
MultiLanguageItemData['de'][168566] = {name = "[q6]Nullkraftkühler", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nErfordert einen wohlwollenden Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Verstärkte Nullbarriere\nSofort 2.25 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert. \n Geringe Macht:\n Nullbarriere\nGewährt alle 15 Sek. eine Nullbarriere. Diese absorbiert die nächsten [ 2268 * (1 + Vielseitigkeit)] Magieschaden, die Ihr innerhalb von 10 Sek. erleidet."}
MultiLanguageItemData['de'][168568] = {name = "[q6]Nullkraftnullifizierer", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nErfordert einen respektvollen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Rostbolzenwiderstand, um diese Essenz freizuschalten.\nGroße Macht:\n Verstärkte Nullbarriere\nSofort 2.25 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert, und entfernt sofort alle schädlichen Magie-, Fluch-, Gift- und Krankheitseffekte von Euch. \n Geringe Macht:\n Nullbarriere\nGewährt alle 15 Sek. eine Nullbarriere. Diese absorbiert die nächsten [ 2268 * (1 + Vielseitigkeit)] Magieschaden, die Ihr innerhalb von 10 Sek. erleidet.\n\n Wenn 'Nullbarriere' abläuft, implodiert sie und verursacht Schattenschaden in Höhe des insgesamt absorbierten Schadens, der auf alle Gegner in der Nähe aufgeteilt wird."}
MultiLanguageItemData['de'][168569] = {name = "[q6]Nullkraftvisualisierer", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nGroße Macht:\n Verstärkte Nullbarriere\nSofort 2.25 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert, und entfernt sofort alle schädlichen Magie-, Fluch-, Gift- und Krankheitseffekte von Euch. \n Geringe Macht:\n Nullbarriere\nGewährt alle 15 Sek. eine Nullbarriere. Diese absorbiert die nächsten [ 2268 * (1 + Vielseitigkeit)] Magieschaden, die Ihr innerhalb von 10 Sek. erleidet.\n\n Wenn 'Nullbarriere' abläuft, implodiert sie und verursacht Schattenschaden in Höhe des insgesamt absorbierten Schadens, der auf alle Gegner in der Nähe aufgeteilt wird."}
MultiLanguageItemData['de'][168573] = {name = "[q6]Todesresistentes Blatt", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nGroße Macht:\n Berührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 20% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\n Dieser Effekt kann nur ein Mal alle 10 Min. auftreten. \n Geringe Macht:\n Überlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 30% länger an . Dieser Effekt kann nur ein Mal alle 1.5 Min. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n[q]\"Gedeiht im Wind.\""}
MultiLanguageItemData['de'][168574] = {name = "[q6]Versteinerte lebende Rinde", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nGroße Macht:\n Berührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 40% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\n Dieser Effekt kann nur ein Mal alle 10 Min. auftreten. \n Geringe Macht:\n Überlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 30% länger an . Dieser Effekt kann nur ein Mal alle 60 Sek. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168575] = {name = "[q6]Ast der verjüngenden Ringe", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nErlernt Rang 3 einer Essenz von den Rajani oder dem Abkommen von Uldum auf einem anderen Charakter, um diese Essenz freizuschalten.\nBenötigt einen respektvollen Ruf bei den Rajani. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Berührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 40% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\n Wenn Euer Tod verhindert wird, wird die Abklingzeit von ' Schildwall ' abgeschlossen.\n\n Dieser Effekt kann nur ein Mal alle 10 Min. auftreten. \n Geringe Macht:\n Überlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 50% länger an . Dieser Effekt kann nur ein Mal alle 60 Sek. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168576] = {name = "[q6]Wurzeln der wunderbaren Wiederbelebung", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nGroße Macht:\n Berührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 40% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\n Wenn Euer Tod verhindert wird, wird die Abklingzeit von ' Schildwall ' abgeschlossen.\n\n Dieser Effekt kann nur ein Mal alle 10 Min. auftreten. \n Geringe Macht:\n Überlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 50% länger an . Dieser Effekt kann nur ein Mal alle 60 Sek. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168577] = {name = "Magiegetränkte Perle", additional_info = "Questgegenstand\n[q]\"Energie flackert im Inneren.\""}
MultiLanguageItemData['de'][168578] = {name = "[q6]Sphäre der unterdrückten Kraft", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nGroße Macht:\n Unterdrückungsimpuls\nSofort 1 min Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert. \n Geringe Macht:\n Sphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn Euch ein Gegner im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 5 Sek. lang 64 Tempo ."}
MultiLanguageItemData['de'][168579] = {name = "[q6]Sphäre der ungezügelten Wut", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nErfordert den Erfolg \"Schlachtfeldraufbold\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Unterdrückungsimpuls\nSofort 45 sek. Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert. \n Geringe Macht:\n Sphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn ein Gegner Euch im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 7 Sek. lang 64 Tempo$?a294920[ und Geschwindigkeit]."}
MultiLanguageItemData['de'][168580] = {name = "[q6]Sphäre der geschröpften Mobilität", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nErfordert den Erfolg \"Schlachtfeldtaktiker\". (Kauf nicht möglich, wenn bereits bekannt)\nErlernt Rang 3 vom Blut des Feindes, des Kunstwerks der Zeit oder der Sphäre der Unterdrückung auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\n Unterdrückungsimpuls\nSofort 45 sek. Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert.\n\n Wenn Ihr einen Gegner trefft, erhaltet Ihr 8 Sek. lang 50% Bewegungsgeschwindigkeit. \n Geringe Macht:\n Sphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn ein Gegner Euch im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 7 Sek. lang 64 Tempo und Geschwindigkeit."}
MultiLanguageItemData['de'][168581] = {name = "[q6]Sphäre der lodernden Neutralisierung", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nGroße Macht:\n Unterdrückungsimpuls\nSofort 45 sek. Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert.\n\n Wenn Ihr einen Gegner trefft, erhaltet Ihr 8 Sek. lang 50% Bewegungsgeschwindigkeit. \n Geringe Macht:\n Sphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn ein Gegner Euch im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 7 Sek. lang 64 Tempo und Geschwindigkeit."}
