MultiLanguageItemData['de'][168611] = {name = "[q6]Versteinerte kohlschwarze Schuppe", additional_info = "Rang 1\nQuestgegenstand\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nGroße Macht:\n Konzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen.\n\n Immer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt. \n Geringe Macht:\n Uralte Flamme\nCa. 3 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch ( 351 * 5) Feuerschaden im Verlauf von 10 Sek., Verbündete werden um ( 351 * 5) Gesundheit im Verlauf von 10 Sek. geheilt.\n[q]\"Diese uralte Schuppe verkörpert die Erde und wurde in kohlschwarzem Feuer gehärtet.\""}
MultiLanguageItemData['de'][168612] = {name = "[q6]Traumglanzdrachenschuppe", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nGroße Macht:\n Konzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\n Immer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt. \n Geringe Macht:\n Uralte Flamme\nCa. 1.25 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [ 351 * 5 * (1.25)] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [ 351 * 5 * (1.25)] Gesundheit im Verlauf von 10 Sek. geheilt.\n[q]\"Aus der wiederhergestellten Schuppe strahlt das Leuchten des Smaragdgrünen Traums und die Essenz des grünen Drachenschwarms.\""}
MultiLanguageItemData['de'][168613] = {name = "[q6]Gehärtete Schuppe der feuerroten Brutmutter", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nErlernt mit einem anderen Charakter 'Rang 3 - Schmelztiegel der Flammen', um diese Essenz freizuschalten.\nGroße Macht:\n Konzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\n Immer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nMaximal 2 Aufladungen. \n Geringe Macht:\n Uralte Flamme\nCa. 1.25 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [ 351 * 5 * (1.25)] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [ 351 * 5 * (1.25)] Gesundheit im Verlauf von 10 Sek. geheilt. Bis zu 3-mal stapelbar.\n[q]\"Die Flammen der Lebensbinderin züngeln und tanzen über diese Schuppe, in der Lebensenergie sprudelt.\""}
MultiLanguageItemData['de'][168614] = {name = "[q6]Aufgeladene Schuppe des Blauen Aspekts", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nGroße Macht:\n Konzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\n Immer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nMaximal 2 Aufladungen. \n Geringe Macht:\n Uralte Flamme\nCa. 1.25 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [ 351 * 5 * (1.25)] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [ 351 * 5 * (1.25)] Gesundheit im Verlauf von 10 Sek. geheilt. Bis zu 3-mal stapelbar.\n[q]\"Blaue Magie knistert um die Schuppe und verkörpert den einst großen Aspekt.\""}
MultiLanguageItemData['de'][168615] = {name = "[q6]Flüchtige Weltader", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nGroße Macht:\n Resonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 2 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 12 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\n Erhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 8 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren. \n Geringe Macht:\n Lebensblut\nAlle 18-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 12 Sek. lang bestehen bleibt.\n\n Lebensblutsplitter\n Der Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n[q]\"Die Azerit anziehende Energie dieser Weltader ist förmlich spürbar und stellt für jeden, der damit umzugehen versteht, eine große Unterstützung dar.\""}
MultiLanguageItemData['de'][168616] = {name = "[q6]Starke Weltader", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nGroße Macht:\n Resonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\n Erhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 8 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren. \n Geringe Macht:\n Lebensblut\nAlle 18-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\n Lebensblutsplitter\n Der Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 8 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n[q]\"Diese Weltader ist sehr robust und scheint das anliegende Azerit zu verstärken.\""}
MultiLanguageItemData['de'][168617] = {name = "[q6]Wogende Weltader", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nErlernt mit einem anderen Charakter 'Rang 3 - Resonanz der Weltader', um diese Essenz freizuschalten.\nGroße Macht:\n Resonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\n Erhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 12 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren. \n Geringe Macht:\n Lebensblut\nAlle 1-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\n Lebensblutsplitter\n Der Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n[q]\"Diese Weltader weist eine viel schnellere innere Vibration auf und wird Azeritsplitter viel häufiger anziehen.\""}
MultiLanguageItemData['de'][168618] = {name = "[q6]Strahlende Weltader", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nGroße Macht:\n Resonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\n Erhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 12 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren. \n Geringe Macht:\n Lebensblut\nAlle 1-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\n Lebensblutsplitter\n Der Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n[q]\"Die Strahlkraft und Intensität dieser Weltader ist Ehrfurcht gebietend.\""}
