MultiLanguageItemData['de'][168620] = {name = "[q6]Konvexlinse der Fokussierungsiris", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\n{Große Macht:\n Fokussierter Azeritstrahl\nWirken in 2 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 757 * 10) Feuerschaden} zuzufügen. \n Geringe Macht:\n Fokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang 5 {Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses {Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen. (500ms Abklingzeit)}\n[q]\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\""}
MultiLanguageItemData['de'][168621] = {name = "[q6]Vergrößernde Linse der Fokussierungsiris", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\n{Große Macht:\n Fokussierter Azeritstrahl\nWirken in 1.333 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden} zuzufügen. \n Geringe Macht:\n Fokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [ 5 * (1.5)] {Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses {Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.}\n[q]\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\""}
MultiLanguageItemData['de'][168622] = {name = "[q6]Stabilisierende Linse der Fokussierungsiris", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\nErlernt Rang 3 der Essenz der Fokussierungsiris, der Invokation der Lebensbinderin oder der Anima von Leben und Tod auf einem anderen Charakter, um diese Essenz freizuschalten.\n{Große Macht:\n Fokussierter Azeritstrahl\nWirken in 1.333 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden} zuzufügen. Kann aus der Bewegung heraus eingesetzt werden. \n Geringe Macht:\n Fokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [ 5 * (1.5)] {Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses {Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\n Wenn Ihr keine Stapel von 'Fokussierte Energie' habt, gewährt Euer erster Einsatz eines Schadenszaubers oder einer Schadensfähigkeit Euch 3 Stapel.}\n[q]\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\""}
MultiLanguageItemData['de'][168623] = {name = "[q6]Bikonkave Linse der Fokussierungsiris", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\n{Große Macht:\n Fokussierter Azeritstrahl\nWirken in 1.333 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden} zuzufügen. Kann aus der Bewegung heraus eingesetzt werden. \n Geringe Macht:\n Fokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [ 5 * (1.5)] {Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses {Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\n Wenn Ihr keine Stapel von 'Fokussierte Energie' habt, gewährt Euer erster Einsatz eines Schadenszaubers oder einer Schadensfähigkeit Euch 3 Stapel.}\n[q]\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\""}
