MultiLanguageItemData['de'][168842] = {name = "[q6]Mechaperfektionsmotor", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\n Vision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 25% der Grunddauer zu aktivieren . \n Geringe Macht:\n Streben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% .\n[q]\"Der Motor wurde aus einem uralten Titanengerät weiterentwickelt und ist ein Triumph gnomischer Erfindungsgabe. Er ermöglicht mechanischen Wesen, Höchstleistungen zu erreichen.\""}
MultiLanguageItemData['de'][168843] = {name = "[q6]Perfekt eingestelltes Differential", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\n Vision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren . \n Geringe Macht:\n Streben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%.\n\n Das Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit."}
MultiLanguageItemData['de'][168844] = {name = "[q6]Leistungsperfektionsgetriebe", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nErlernt mit einem anderen Charakter 'Rang 3 - Vision der Perfektion', um diese Essenz freizuschalten.\nGroße Macht:\n Vision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren .\n\n Wenn 'Vision der Perfektion' aktiviert wird, erhaltet Ihr und bis zu 2 Verbündete in der Nähe 10 Sek. lang 24 Tempo. \n Geringe Macht:\n Streben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% und erhöht Eure Vielseitigkeit um 18 .\n\n Das Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit."}
MultiLanguageItemData['de'][168845] = {name = "[q6]Mechaperfektionsturbo", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\n Vision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren .\n\n Wenn 'Vision der Perfektion' aktiviert wird, erhaltet Ihr und bis zu 2 Verbündete in der Nähe 10 Sek. lang 24 Tempo. \n Geringe Macht:\n Streben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% und erhöht Eure Vielseitigkeit um 18 .\n\n Das Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit.\n[q]\"Dieser Turbo verbessert den Mechaperfektionsmotor und hat das Potenzial, gewaltige Mengen an Titanenenergie auf einen Schlag freizusetzen.\""}
MultiLanguageItemData['de'][168846] = {name = "[q6]Perle der Klarträume", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nGroße Macht:\n Erinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Hält 12 Sek. lang an. \n Geringe Macht:\n Klarträume\nEure Zauber und Fähigkeiten haben eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten und Euch um [ 764 * (1 + Vielseitigkeit)] Gesundheit zu heilen ."}
MultiLanguageItemData['de'][168847] = {name = "[q6]Perle manifestierter Ambitionen", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nErfordert den Erfolg \"Reise durch die Tiefen\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Erinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Hält 15 Sek. lang an. \n Geringe Macht:\n Klarträume\nEure Zauber und Fähigkeiten haben eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten und Euch um [ 764 * 1.5 * (1 + Vielseitigkeit)] Gesundheit zu heilen ."}
MultiLanguageItemData['de'][168848] = {name = "[q6]Perle einleuchtender Absichten", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nErlernt mit einem anderen Charakter 'Rang 3 - Erinnerung an den Klartraum', um diese Essenz freizuschalten.\nErfordert den Erfolg \"Nautische Kampfausbildung\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Erinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Zusätzlich erhaltet Ihr 66 Lebensraub. Hält 15 Sek. lang an. \n Geringe Macht:\n Klarträume\nEure Zauber und Fähigkeiten haben [eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten], Euch um [ 764 * (1.5) * (1 + Vielseitigkeit)] Gesundheit zu heilen und Eure Vielseitigkeit 8 Sek. lang um 74 zu erhöhen."}
MultiLanguageItemData['de'][168849] = {name = "[q6]Perle illustrer Pläne", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nGroße Macht:\n Erinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Zusätzlich erhaltet Ihr 66 Lebensraub. Hält 15 Sek. lang an. \n Geringe Macht:\n Klarträume\nEure Zauber und Fähigkeiten haben [eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten], Euch um [ 764 * (1.5) * (1 + Vielseitigkeit)] Gesundheit zu heilen und Eure Vielseitigkeit 8 Sek. lang um 74 zu erhöhen."}
MultiLanguageItemData['de'][168850] = {name = "[q6]Zeitverlorenes Schlachtfeldandenken", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nGroße Macht:\n Raumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 4 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu. \n Geringe Macht:\n Realitätsverschiebung\nWenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 15 Sek. lang 47 Primärwert .\n\n Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten.\n[q]\"Die Erinnerungen an die Vergangenheit bergen eine tiefsitzende Kraft, die uns zu Momenten von großer Wichtigkeit zurückversetzt.\""}
MultiLanguageItemData['de'][168851] = {name = "[q6]Robustes Schlachtfeldandenken", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nErfordert den Erfolg \"Krieg an zwei Fronten\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Raumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 2 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu. \n Geringe Macht:\n Realitätsverschiebung\nWenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 20 Sek. lang 47 Primärwert .\n\n Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten."}
MultiLanguageItemData['de'][168852] = {name = "[q6]Bruchfestes Schlachtfeldandenken", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nErlernt mit einem anderen Charakter 'Rang 3 - Raumwelle', um diese Essenz freizuschalten.\nIhr habt nicht genug Auszeichnungen des Rufs zu den Waffen, um diesen Gegenstand zu kaufen.\nGroße Macht:\n Raumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 2 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu.\n\n Nach der Versetzung erleidet Ihr 10 Sek. lang 10% weniger Schaden. \n Geringe Macht:\n Realitätsverschiebung\nEure Bewegungsgeschwindigkeit wird um 5% erhöht, und wenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 20 Sek. lang 47 Primärwert .\n\n Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten."}
MultiLanguageItemData['de'][168853] = {name = "[q6]Glitzerndes Schlachtfeldandenken", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nGroße Macht:\n Raumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 2 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu.\n\n Nach der Versetzung erleidet Ihr 10 Sek. lang 10% weniger Schaden. \n Geringe Macht:\n Realitätsverschiebung\nEure Bewegungsgeschwindigkeit wird um 5% erhöht, und wenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 20 Sek. lang 47 Primärwert .\n\n Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten."}
MultiLanguageItemData['de'][168854] = {name = "[q6]Belebtes Elementarherz", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nGroße Macht:\n Wächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit)] Feuerschaden verursachen. \n Geringe Macht:\n Kondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit)] Feuerschaden zufügt.\n[q]\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\""}
MultiLanguageItemData['de'][168855] = {name = "[q6]Pulsierendes Elementarherz", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nGroße Macht:\n Wächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden zufügen. \n Geringe Macht:\n Kondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden zufügt.\n[q]\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\""}
MultiLanguageItemData['de'][168856] = {name = "[q6]Resonierendes Elementarherz", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nErlernt Rang 3 der Kondensierten Lebenskraft, der Vitalitätsverbindung oder von Azeroths unsterblichem Geschenk auf einem anderen Charakter, um diese Essenz freizuschalten.\n{Große Macht:\n Wächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden} verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden} zufügen.\n\n Jedes Mal, wenn der Wächter von Azeroth einen Zauber wirkt, erhaltet Ihr 2% {Tempo (bis zu 5 - mal stapelbar). Dieser Effekt endet, wenn der Wächter von Azeroth verschwindet. \n Geringe Macht:\n Kondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden} zufügt.\n\n Wenn ein Azeritstachel Schaden verursacht, wird sämtlicher Schaden, den Ihr diesem Ziel zufügt, 6 Sek. lang um 3% erhöht.}\n[q]\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\""}
MultiLanguageItemData['de'][168857] = {name = "[q6]Funkelndes Elementarherz", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\n{Große Macht:\n Wächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden} verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden} zufügen.\n\n Jedes Mal, wenn der Wächter von Azeroth einen Zauber wirkt, erhaltet Ihr 2% {Tempo (bis zu 5 - mal stapelbar). Dieser Effekt endet, wenn der Wächter von Azeroth verschwindet. \n Geringe Macht:\n Kondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden} zufügt.\n\n Wenn ein Azeritstachel Schaden verursacht, wird sämtlicher Schaden, den Ihr diesem Ziel zufügt, 6 Sek. lang um 3% erhöht.}\n[q]\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\""}
MultiLanguageItemData['de'][168858] = {name = "[q6]Titanenreinigungsprotokolle", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nErfordert einen freundlichen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Läuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht.\n\n Vom Strahl getroffene Entartungen werden für 3 Sek. betäubt. \n Geringe Macht:\n Reinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die jedem Gegner innerhalb von 8 Metern [ 563 * (1 + Vielseitigkeit)] Feuerschaden zufügt .\n\n 'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n[q]\"Die Titanen haben Protokolle für die diversen Verderbnisse erstellt, die Azeroth befallen könnten.\""}
MultiLanguageItemData['de'][168859] = {name = "[q6]Gezielte Reinigungsprotokolle", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nErfordert einen wohlwollenden Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Läuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\n Alle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt. \n Geringe Macht:\n Reinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n 'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n[q]\"Wenn extreme Präzision gefragt ist.\""}
MultiLanguageItemData['de'][168860] = {name = "[q6]Verstärkte Reinigungsprotokolle", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nErfordert einen respektvollen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Rostbolzenwiderstand, um diese Essenz freizuschalten.\nGroße Macht:\n Läuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\n Wenn ein Gegner innerhalb des Strahls stirbt, wird Euer Schaden 8 Sek. lang um 10% erhöht.\n\n Alle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt. \n Geringe Macht:\n Reinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1.25) * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n 'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n[q]\"Wenn bisherige Protokolle wirkungslos blieben.\""}
MultiLanguageItemData['de'][168861] = {name = "[q6]Ultimative Reinigungsprotokolle", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nGroße Macht:\n Läuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\n Wenn ein Gegner innerhalb des Strahls stirbt, wird Euer Schaden 8 Sek. lang um 10% erhöht.\n\n Alle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt. \n Geringe Macht:\n Reinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1.25) * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n 'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n[q]\"Wenn alles andere versagt.\""}
MultiLanguageItemData['de'][168862] = {name = "[q3]F.L.U.G.-Peilsender", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nVölker: Gnom\n[q2]Benutzen: Erbittet Abholung zum nächsten Flugmeister.\n\n Kann nur in Gebieten eingesetzt werden, in denen Ihr die Nutzung der Flugpfeife freigeschaltet habt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][168863] = {name = "[q6]Ungebundene Azeritspäne", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nErfordert einen freundlichen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen freundlichen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Die Ungezügelte Kraft\n40 Meter Reichweite Sofort 1 min Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [( 155 * (7.06061) + 155 )] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%. \n Geringe Macht:\n Tollkühne Kraft\nCa. 20 Procs pro Minute Wenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 4 Sek. lang um 50% erhöht."}
MultiLanguageItemData['de'][168864] = {name = "[q6]Scharfe Azeritspäne", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nErfordert einen wohlwollenden Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen wohlwollenden Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Die Ungezügelte Kraft\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [( 155 * (7.06061) + 155 )] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%. \n Geringe Macht:\n Tollkühne Kraft\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 4 Sek. lang um 70% erhöht."}
MultiLanguageItemData['de'][168865] = {name = "[q6]Polarisierte Azeritspäne", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Ruf in Nazjatar, um diese Essenz freizuschalten.\nErfordert einen respektvollen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen respektvollen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Die Ungezügelte Kraft\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [( 155 * (7.06061) + 155 )] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.\n\n Bei jedem kritischen Treffer durch 'Die Ungezügelte Kraft' wird das Ziel sofort von einem zusätzlichen Azeritsplitter getroffen (bis zu maximal 5 Splitter). \n Geringe Macht:\n Tollkühne Kraft\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 6 Sek. lang um 70% erhöht."}
