MultiLanguageItemData['de'][168899] = {name = "[q4]Orgozoas lähmender Stachel", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Schwert}\n7 - 13 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]+ 4 Vielseitigkeit\nHaltbarkeit 110 / 110\n[q2]Benutzen: Durchbohrt Eure Haut mit lähmenden Stacheln, die Euren verursachten und erlittenen Schaden 15 Sek. lang um 10% verringern. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][168900] = {name = "[q4]Tauchertorheit", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Axt}\n6 - 14 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 110 / 110\n[q2]Anlegen: Eure automatischen Angriffe haben eine sehr geringe Chance, die Tauchertorheit zu aktivieren. Für 12 Sek. wird 5% Eures Schadens als bioelektrische Ladung gespeichert. Beim Entladen der Tauchertorheit erleiden 3 Gegner in der Nähe Naturschaden in Höhe der Ladung.\nVerkaufspreis:"}
MultiLanguageItemData['de'][168901] = {name = "[q4]Streitaxt der königlichen Schuppenwache", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Axt}\n6 - 14 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 110 / 110\nVerkaufspreis:"}
MultiLanguageItemData['de'][168902] = {name = "[q4]Traumes Ende", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Axt}\n6 - 14 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 110 / 110\n[q2]Anlegen: Erhöht Euer Angriffstempo für jeden weiteren automatischen Angriff gegen dasselbe Ziel um 1%, bis zu maximal 7%. (100ms Abklingzeit)\nVerkaufspreis:"}
