MultiLanguageItemData['de'][168908] = {name = "[q3]Bauplan: Experimentelles Abenteureraccessoire", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigtRostbolzenwiderstand\n- Neutral\n[q]\"Erschafft einen Ring oder ein Schmuckstück für Eure Spezialisierung.\""}
MultiLanguageItemData['de'][168909] = {name = "[q4]Subroutine: Notreparatur", additional_info = "Rote Lochkarte\nWird beim Aufheben gebunden\nAnlegen: Beim Heilen von Verbündeten mit unter 50% Gesundheit besteht die Chance , dass im Verlauf von 4 Sek. 155 Mana regeneriert wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][168912] = {name = "[q4]Subroutine: Optimierung", additional_info = "Rote Lochkarte\nWird beim Aufheben gebunden\nAnlegen: Eure Zauber haben eine Chance , Eure Werte basierend auf Euer angelegten Hauptplatine neu zu konfigurieren.\nVerkaufspreis:"}
