MultiLanguageItemData['de'][168920] = {name = "[q6]Azeritüberkrusteter Zeitquarz", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\n{Große Macht:\n Stillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 4 Sek. lang 34942 Schaden} und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden} und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten . \n Geringe Macht:\n Kunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 6 Sek. 72 {Tempo zu gewähren.}\n[q]\"Es gibt immer Zeit für eine Kampfpause.\""}
MultiLanguageItemData['de'][168921] = {name = "[q6]Azeritversetzter Zeitquarz", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\nErfordert den Erfolg \"Schlachtfeldraufbold\". (Kauf nicht möglich, wenn bereits bekannt)\n{Große Macht:\n Stillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 6 Sek. lang 34942 Schaden} und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden} und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten . \n Geringe Macht:\n Kunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 8 Sek. 86 {Tempo zu gewähren.}\n[q]\"Es gibt immer Zeit für eine Kampfpause.\""}
MultiLanguageItemData['de'][168922] = {name = "[q6]Azeritbetriebener Zeitquarz", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\nErfordert den Erfolg \"Schlachtfeldtaktiker\". (Kauf nicht möglich, wenn bereits bekannt)\nErlernt Rang 3 vom Blut des Feindes, des Kunstwerks der Zeit oder der Sphäre der Unterdrückung auf einem anderen Charakter, um diese Essenz freizuschalten.\n{Große Macht:\n Stillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 6 Sek. lang 34942 Schaden} und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden} und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten und der Schaden} wird um 20% verringert. \n Geringe Macht:\n Kunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 8 Sek. 86 {Tempo und 72 Geschwindigkeit zu gewähren.}\n[q]\"Es gibt immer Zeit für eine Kampfpause.\""}
MultiLanguageItemData['de'][168923] = {name = "[q6]Unbelasteter Azeritzeitquartz", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\n{Große Macht:\n Stillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 6 Sek. lang 34942 Schaden} und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden} und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten und der Schaden} wird um 20% verringert. \n Geringe Macht:\n Kunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 8 Sek. 86 {Tempo und 72 Geschwindigkeit zu gewähren.}\n[q]\"Es gibt immer Zeit für eine Kampfpause.\""}
MultiLanguageItemData['de'][168924] = {name = "[q6]Pralle Saat des Lebens", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nGroße Macht:\n Invokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 30 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\n Samen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 . \n Geringe Macht:\n Samen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 12 Sek. lang bestehen bleibt.\n\n Samen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n[q]\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\""}
MultiLanguageItemData['de'][168925] = {name = "[q6]Reproduzierende Saat des Überflusses", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nGroße Macht:\n Invokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 40 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\n Samen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 . \n Geringe Macht:\n Samen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 15 Sek. lang bestehen bleibt.\n\n Samen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n[q]\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\""}
MultiLanguageItemData['de'][168926] = {name = "[q6]Verbleibende Saat der Erneuerung", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nErlernt Rang 3 der Essenz der Fokussierungsiris, der Invokation der Lebensbinderin oder der Anima von Leben und Tod auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\n Invokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 40 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\n Wenn Samen ungenutzt ablaufen, wird die Abklingzeit dieser Fähigkeit um 2 Sek. verringert.\n\n Samen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 . \n Geringe Macht:\n Samen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 15 Sek. lang bestehen bleibt.\n\n Samen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n[q]\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\""}
MultiLanguageItemData['de'][168927] = {name = "[q6]Samen farbenprächtiger Blüten", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nGroße Macht:\n Invokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 40 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\n Wenn Samen ungenutzt ablaufen, wird die Abklingzeit dieser Fähigkeit um 2 Sek. verringert.\n\n Samen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 . \n Geringe Macht:\n Samen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 15 Sek. lang bestehen bleibt.\n\n Samen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n[q]\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\""}
MultiLanguageItemData['de'][168928] = {name = "[q6]Tafel der ausgleichenden Fluten", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nErfordert einen freundlichen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen freundlichen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Mana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 3% erhöht.\n\n Während der Überladung steht Eure Manaregeneration still . \n Geringe Macht:\n Die unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch 477 Mana oder 10 Sek. lang 115 Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. (3.5s Abklingzeit)\n[q]\"Das Geflüster von Elune und Neptulon wirkt auf die Fluten ein. Ihre in Stein verewigten Worte sind ein Tribut an das Gleichgewicht ihrer Kräfte.\""}
MultiLanguageItemData['de'][168929] = {name = "[q6]Kodex der unendlichen Fluten", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nErfordert einen wohlwollenden Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen wohlwollenden Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Mana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 4% erhöht.\n\n Während der Überladung steht Eure Manaregeneration still . \n Geringe Macht:\n Die unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch [ 477 * (1.2)] Mana oder 10 Sek. lang [ 115 * (1.2)] Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. [Die unerschöpfliche Flut: Chance von 20%, beide Effekte zu erhalten ] (3.5s Abklingzeit)"}
MultiLanguageItemData['de'][168930] = {name = "[q6]Foliant der beschleunigenden Fluten", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Ruf in Nazjatar, um diese Essenz freizuschalten.\nErfordert einen respektvollen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen respektvollen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Mana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 4% erhöht.\n\n Während der Überladung steht Eure Manaregeneration still und Ihr erhaltet 10% Tempo. \n Geringe Macht:\n Die unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch [ 477 * (1.2)] Mana oder 10 Sek. lang [ 115 * (1.2)] Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. Chance von 20%, beide Effekte zu erhalten. (3.5s Abklingzeit)"}
MultiLanguageItemData['de'][168931] = {name = "[q6]Pergament der erleuchtenden Fluten", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nGroße Macht:\n Mana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 4% erhöht.\n\n Während der Überladung steht Eure Manaregeneration still und Ihr erhaltet 10% Tempo. \n Geringe Macht:\n Die unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch [ 477 * (1.2)] Mana oder 10 Sek. lang [ 115 * (1.2)] Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. Chance von 20%, beide Effekte zu erhalten. (3.5s Abklingzeit)"}
MultiLanguageItemData['de'][168932] = {name = "[q6]Batterie des reaktiven Seins", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nErfordert einen freundlichen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Erfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 20 % verstärkt. \n Geringe Macht:\n Der Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 40% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit."}
MultiLanguageItemData['de'][168933] = {name = "[q6]Kondensator des verbesserten Seins", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nErfordert einen wohlwollenden Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\n Erfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 50% verstärkt. \n Geringe Macht:\n Der Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 50% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit."}
MultiLanguageItemData['de'][168934] = {name = "[q6]Kalibrierte Anzeige des Seins", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nErfordert einen respektvollen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Rostbolzenwiderstand, um diese Essenz freizuschalten.\nGroße Macht:\n Erfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 50% verstärkt. Der Quell gibt nicht mehr Heilung ab, als nötig ist, um das Ziel vollständig zu heilen. \n Geringe Macht:\n Der Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 50% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit.\n\n Wenn der Quell weniger als 1398 Heilung enthält, absorbiert er Heilung doppelt so schnell."}
MultiLanguageItemData['de'][168935] = {name = "[q6]Intensitätsanzeige des Seins", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nGroße Macht:\n Erfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 50% verstärkt. Der Quell gibt nicht mehr Heilung ab, als nötig ist, um das Ziel vollständig zu heilen. \n Geringe Macht:\n Der Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 50% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit.\n\n Wenn der Quell weniger als 1398 Heilung enthält, absorbiert er Heilung doppelt so schnell."}
MultiLanguageItemData['de'][168936] = {name = "[q6]Schutz der unerschütterlichen Hoffnung", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nGroße Macht:\n Wächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert. \n Geringe Macht:\n Unnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit)]-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168937] = {name = "[q6]Schutz der Erwiderung", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nGroße Macht:\n Wächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\n Jedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit. \n Geringe Macht:\n Unnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu einem Maximum von [ 848 * (1 + Vielseitigkeit) * (1.2)] stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n[q]\"Wer anderen hilft...\""}
MultiLanguageItemData['de'][168938] = {name = "[q6]Schutz der gegenseitigen Hilfe", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nErlernt Rang 3 einer Essenz aus Verstörenden Visionen auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\n Wächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\n Jedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit.\n\n Wenn ein Verbündeter den Absorptionsschild erhält, werden Ihr und Euer Verbündeter um [ 346 * (1 + Vielseitigkeit)] Gesundheit geheilt. \n Geringe Macht:\n Unnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit) * (1.2)]-mal stapelbar.\n\n Von 'Unnachgiebiger Schutz' geschützte Ziele erleiden 3% weniger Schaden.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168939] = {name = "Osmenitsplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Einige kleine, nicht verwertbare Splitter Osmenit.\""}
MultiLanguageItemData['de'][168940] = {name = "[q6]Schutz der Unvorstellbaren Brillanz", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nGroße Macht:\n Wächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\n Jedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit.\n\n Wenn ein Verbündeter den Absorptionsschild erhält, werden Ihr und Euer Verbündeter um [ 346 * (1 + Vielseitigkeit)] Gesundheit geheilt. \n Geringe Macht:\n Unnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit) * (1.2)]-mal stapelbar.\n\n Von 'Unnachgiebiger Schutz' geschützte Ziele erleiden 3% weniger Schaden.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][168941] = {name = "[q6]Vitalitätsumverteilungsgitterwerk", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nGroße Macht:\n Vitalitätsverbindung\n40 Meter Reichweite Sofort 1 min Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern. \n Geringe Macht:\n Übertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren."}
MultiLanguageItemData['de'][168942] = {name = "[q6]Maschen dehnbarer Vitalität", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nGroße Macht:\n Vitalitätsverbindung\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern. \n Geringe Macht:\n Übertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren."}
MultiLanguageItemData['de'][168943] = {name = "[q6]Gitter überbordender Vitalität", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nErlernt Rang 3 der Kondensierten Lebenskraft, der Vitalitätsverbindung oder von Azeroths unsterblichem Geschenk auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\n Vitalitätsverbindung\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern.\n\n Wenn das Ziel seine volle Gesundheit erreicht, springt der Effekt für die verbleibende Dauer auf das Ziel mit der niedrigsten Gesundheit in der Nähe über. \n Geringe Macht:\n Übertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren.\n\n Gesundheitstransfers hinterlassen 5 Sek. lang einen Schild auf dem Ziel, der 575 Schaden absorbiert."}
MultiLanguageItemData['de'][168944] = {name = "[q6]Netz ungezügelter Vitalität", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin , Priester , Schamane , Mönch , Druide , Rufer\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nGroße Macht:\n Vitalitätsverbindung\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern.\n\n Wenn das Ziel seine volle Gesundheit erreicht, springt der Effekt für die verbleibende Dauer auf das Ziel mit der niedrigsten Gesundheit in der Nähe über. \n Geringe Macht:\n Übertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren.\n\n Gesundheitstransfers hinterlassen 5 Sek. lang einen Schild auf dem Ziel, der 575 Schaden absorbiert."}
