MultiLanguageItemData['de'][169299] = {name = "Trank der ungezügelten Wut", additional_info = "[q2]Benutzen: Verleiht Euch selbst ungezügelte Energie und gewährt Euren offensiven Zaubern und Angriffen eine Chance, Eurem Ziel zusätzlich 1344 Feuerschaden zuzufügen. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169300] = {name = "Trank der wilden Heilung", additional_info = "[q2]Benutzen: Ermächtigt Euren Verstand und gewährt Euren Heilfähigkeiten eine Chance, bei Eurem Ziel zusätzlich 2017 Gesundheit wiederherzustellen. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169301] = {name = "[q4]Hochgeborenenkompendium der wirbelnden Fluten", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Anlegen: Eure Heilzauber haben eine Chance, einem Verbündeten einen Absorptionsschild zu gewähren, der für 12 Sek. bis zu 153 Schaden absorbiert. Während der Schild besteht, ist der Primärwert des Ziels um 6 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169302] = {name = "[q4]Hochgeborenenkompendium des mystischen Bollwerks", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr um 78 Gesundheit geheilt werdet und 10 Sek. lang 9 Rüstung erhaltet. Bis zu ( 9 * 4) Rüstung stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169303] = {name = "[q3]Armschienen des Kraftprotzes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Gebt mit Euren Muskeln an und erhöht so 15 Min. lang die Armkraft. (45 Min Abklingzeit)\n[q]\"Muskelpakete nicht inbegriffen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][169304] = {name = "[q4]Köder des Leviathans", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Anlegen: Eure Schaden verursachenden Fähigkeiten haben eine sehr kleine Chance, einen Leviathan zu beschwören, der Eurem Ziel [ 165 * (1 + Vielseitigkeit)] körperlichen Schaden zufügt.\n\n Euer verursachter Schaden lässt auf Eurem Ziel außerdem leuchtende Algen wachsen, die Eure Beschwörungschance erhöhen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169305] = {name = "[q4]Äquipotenter Nautilus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Benutzen: Entfesselt eine Welle, die über Euer Ziel hereinbricht und zu Eurer Ausgangsposition zurückkehrt. Fügt Gegnern auf ihrem Weg im Verlauf von 4 Sek. [ 24 * (5) * (1 + Vielseitigkeit)] Frostschaden zu. Fangt die Welle ab, um die Abklingzeit um 30 Sek. zu verringern. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169306] = {name = "[q4]Za'quls Portalschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 10.\n[q2]Anlegen: Eure Fähigkeiten haben eine geringe Chance, in der Nähe für 30 Sek. einen Leerenriss zu erschaffen. Bewegt Euch zu einem Leerenriss, um für 10 Sek. ein Portal zu öffnen. Wenn Ihr im Portal steht, erhaltet Ihr 28 Intelligenz.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169307] = {name = "[q4]Vision des Untergangs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Offenbart das bevorstehende Ableben Eures Gegners und erhöht Euer Tempo 10 Sek. lang um 30 . Pro 10% Gesundheit, die Eurem Ziel fehlen, erhaltet Ihr zusätzlich 4 Tempo. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169308] = {name = "[q4]Kette des Leidens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Überträgt 25 Sek. lang 50% Eures eintreffenden Schadens auf einen Verbündeten innerhalb von 25 Metern, bis zu maximal 1644 Schaden. Der Effekt wird abgebrochen, wenn das Ziel sich außer Reichweite bewegt oder seine Gesundheit unter 25% fällt. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169309] = {name = "[q4]Zoatroideneiersack", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Anlegen: Beim Wirken einer Einzelzielheilung besteht die Chance, einen Zoatroiden auf Eurem Ziel zu beschwören, der [ 76 * (1 + Vielseitigkeit)] Schaden absorbiert und abhängig von der verbleibenden Absorption bis zu 11 Vielseitigkeit gewährt. Pro 10% Mana, die Ihr verbraucht, wird Euer Zoatroid genährt, was die Absorption um [ 8 * (1 + Vielseitigkeit)] und die Vielseitigkeit um 1 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169310] = {name = "[q4]Blutrünstiger Seeigel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Anlegen: 10% des erlittenen Schadens gewährt Euch Heilendes Blut, bis zu [ 315 * (1 + Vielseitigkeit)] insgesamt. Verbraucht alle 3 Sek. [ 41 * (1 + Vielseitigkeit)] Heilendes Blut, um Euch zu heilen, falls Ihr verwundet seid.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169311] = {name = "[q4]Aschenwinds Klingenkoralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Verursacht [ 25 * (1 + Vielseitigkeit)] körperlichen Schaden und belegt Euer Ziel mit 'Klingenkoralle'. Daraufhin haben Eure Schadensfähigkeiten gegen Euer Ziel eine hohe Chance, ihm [ 25 * (1 + Vielseitigkeit)] körperlichen Schaden zuzufügen und einen Stapel von 'Klingenkoralle' hinzuzufügen.\n\n Die erneute Aktivierung dieser Fähigkeit entfernt 'Klingenkoralle' von Eurem Ziel und gewährt Euch 20 Sek. lang 3 kritischen Trefferwert pro Stapel. (20 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169312] = {name = "[q4]Leuchtendes Quallenkraut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Anlegen: Eure Heilungen haben eine Chance, dem am schwersten verletzten Verbündeten innerhalb von 40 Metern 'Lumineszenz' zu verleihen. Verbündete, die mit Lumineszenz belegt sind, erhalten 10% zusätzliche Heilung, bis insgesamt [ 87 * (1 + Vielseitigkeit)] zusätzliche Heilung erreicht ist.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169313] = {name = "[q4]Phiole des arkanen Sturms", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Schaden verursachenden Fähigkeiten haben eine geringe Chance, Euch 20 Sek. lang in einen arkanen Sturm zu hüllen, der Gegnern in der Nähe alle 2 Sek. 5 Arkanschaden zufügt. Jedes Mal, wenn der Sturm einem einzelnen Gegner Schaden zufügt, erhöht sich seine Frequenz.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169314] = {name = "[q4]Azsharas Born der Macht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 10.\n[q2]Benutzen: Kanalisiert bis zu 4 Sek. lang latente Magie, was Euren Primärwert um 30 erhöht. Für jede Sekunde, die Ihr kanalisiert, wird die Dauer verlängert, bis zu maximal 30 Sek. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169315] = {name = "[q4]Erlasse der Ungläubigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Ihr erhaltet alle 40 Sek. einen Schild, der [ 262 * (1 + Vielseitigkeit)] körperlichen Schaden absorbiert. Wenn der Schild aufgebraucht wird, erhaltet Ihr Fanatismus. Dadurch absorbieren weitere Schilde 10% mehr Schaden, bis zu maximal 100%.\n[q2]Benutzen: Verkündet 'Edikt der Meereshexe'. Dadurch absorbiert diese Fähigkeit stattdessen Magieschaden. Setzt außerdem Fanatismus zurück. (40 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169316] = {name = "[q4]Aufgeschobenes Urteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Anlegen: Schiebt alle 3 Sek. [ 7 * (1 + Vielseitigkeit)] Heilung auf. Bewegung setzt die aufgeschobene Heilung frei und heilt Eure 3 am schwersten verletzten Verbündeten.\nVerkaufspreis:"}
