MultiLanguageItemData['de'][169318] = {name = "[q4]Schockbeißers Reißzahn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Erhöht Euer Tempo 30 Sek. lang um 23 . (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][169319] = {name = "[q4]Tröpfelnde Tintenkapsel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Schadensfähigkeiten haben bei Gegnern mit mehr als 30% Gesundheit eine sehr hohe Chance, sie mit 'Leitfähige Tinte' zu belegen. Wenn die Gesundheit des Gegners unter 30% fällt, verursacht 'Leitfähige Tinte' [ 26 * (1 + Vielseitigkeit)] Naturschaden pro Stapel.\nVerkaufspreis:"}
