MultiLanguageItemData['de'][169486] = {name = "[q4]Tuch der Shirakess", additional_info = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n[q2]Anlegen: Verringert den erlittenen Frostschaden in Nazjatar und im Ewigen Palast um 3%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169487] = {name = "[q4]Tiefenpirscherumhang", additional_info = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n[q2]Anlegen: Ihr habt eine Chance, zufällige Fische von Kreaturen in Nazjatar und im Ewigen Palast zu erbeuten.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169488] = {name = "[q4]Großumhang der Zanj'ir", additional_info = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]+ 3 Vielseitigkeit\n[q2]Anlegen: Erhöht Eure Gesundheit, nachdem Ihr in Nazjatar und im Ewigen Palast wiederbelebt werdet, um 30%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169489] = {name = "[q4]Sturmwogercape der Azsh'ari", additional_info = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Anlegen: Ihr habt Zugriff auf die besonderen Vorräte der Murlochändler.\nVerkaufspreis:"}
MultiLanguageItemData['de'][169490] = {name = "[q3]Relikt des Schwarzen Imperiums", additional_info = "[q2]Benutzen: Entfernt einen Stapel von N'Zoths Schutz von einem Gegner.\n[q]\"Ein geheimnisvolles und mächtiges Objekt, das Diener von N'Zoth bei sich tragen.\""}
MultiLanguageItemData['de'][169491] = {name = "[q4]Fokussierte Lebensanima", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: [ [ Kombiniert 3 fokussierte Lebensanima, um [den Fetisch der Dunkelhöhlen][die Pralle Saat des Lebens] zu erschaffen, womit das Herz von Azeroth mit ['Anima von Leben und Tod']['Invokation der Lebensbinderin'] verstärkt werden kann. Der erschaffene Gegenstand hängt von Eurer Beutespezialisierung ab. ] ]"}
MultiLanguageItemData['de'][169492] = {name = "[q4]Rezept: Trank der umzingelten Stärke", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der umzingelten Stärke effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(170)\nBenötigtAnkoaner der Meeresklinge\n- Respektvoll\nVerkaufspreis: \nTrank der umzingelten Stärke\n[q2]Benutzen: Ermächtigt Eure Fähigkeiten und erhöht Eure Hauptwert 25 Sek. lang um 108 . Euer Primärwert erhöht sich zusätzlich um die Zahl der Gegner innerhalb von 8 Metern von Euch, bis zu einem Maximum von ( 108 * 5). (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole"}
MultiLanguageItemData['de'][169493] = {name = "[q4]Rezept: Trank der Rekonstitution", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der Rekonstitution effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(170)\nBenötigtAnkoaner der Meeresklinge\n- Respektvoll\nVerkaufspreis: \nTrank der Rekonstitution\n[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 816 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Akundas Biss (3), Kristallphiole"}
MultiLanguageItemData['de'][169494] = {name = "[q4]Rezept: Trank der festen Entschlossenheit", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der festen Entschlossenheit effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(170)\nBenötigtAnkoaner der Meeresklinge\n- Respektvoll\nVerkaufspreis: \nTrank der festen Entschlossenheit\n[q2]Benutzen: Konzentriert Euren Blick auf einen einzelnen Gegner. Eure Schaden verursachenden Fähigkeiten markieren das Ziel und erhöhen Eure Chance auf kritische Treffer gegen dieses Ziel um bis zu 20%. Wenn Ihr einem neuen Ziel Schaden zufügt, wird Euer Fokus zurückgesetzt. Hält 25 Sek. lang an. Funktioniert nicht bei Zielen über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole"}
MultiLanguageItemData['de'][169495] = {name = "[q4]Rezept: Überlegener Kampftrank der Beweglichkeit", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen überlegenen Kampftrank der Beweglichkeit effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(175)\nVerkaufspreis: \nÜberlegener Kampftrank der Beweglichkeit\n[q2]Benutzen: Erhöht Eure Beweglichkeit 25 Sek. lang um 363 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Flussknospe (3), Kristallphiole"}
MultiLanguageItemData['de'][169496] = {name = "[q4]Rezept: Überlegener Stahlhauttrank", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen überlegenen Stahlhauttrank effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(175)\nVerkaufspreis: \nÜberlegener Stahlhauttrank\n[q2]Benutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 363 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Akundas Biss (3), Kristallphiole"}
