MultiLanguageItemData['de'][169600] = {name = "[q4]Rezept: Trank der umzingelten Stärke", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der umzingelten Stärke effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(170)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis: \nTrank der umzingelten Stärke\n[q2]Benutzen: Ermächtigt Eure Fähigkeiten und erhöht Eure Hauptwert 25 Sek. lang um 108 . Euer Primärwert erhöht sich zusätzlich um die Zahl der Gegner innerhalb von 8 Metern von Euch, bis zu einem Maximum von ( 108 * 5). (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole"}
MultiLanguageItemData['de'][169601] = {name = "[q4]Rezept: Trank der Rekonstitution", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der Rekonstitution effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(170)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis: \nTrank der Rekonstitution\n[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 816 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Akundas Biss (3), Kristallphiole"}
MultiLanguageItemData['de'][169602] = {name = "[q4]Rezept: Trank der festen Entschlossenheit", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der festen Entschlossenheit effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Tränke.\nBenötigtAlchemie von Kul Tiras\n(170)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis: \nTrank der festen Entschlossenheit\n[q2]Benutzen: Konzentriert Euren Blick auf einen einzelnen Gegner. Eure Schaden verursachenden Fähigkeiten markieren das Ziel und erhöhen Eure Chance auf kritische Treffer gegen dieses Ziel um bis zu 20%. Wenn Ihr einem neuen Ziel Schaden zufügt, wird Euer Fokus zurückgesetzt. Hält 25 Sek. lang an. Funktioniert nicht bei Zielen über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole"}
MultiLanguageItemData['de'][169603] = {name = "[q4]Rezept: Großer mystischer Kessel", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen großen mystischen Kessel effizienter herstellt.\n[q2]Chance auf die Herstellung mehrerer Kessel.\nBenötigtAlchemie von Kul Tiras\n(175)\nBenötigtDie Entfesselten\n- Ehrfürchtig\nVerkaufspreis: \nGroßer mystischer Kessel\n[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis: \nBenötigt Großes Fläschchen der Ströme (3), Großes Fläschchen der unendlichen Tiefe (3), Großes Fläschchen des weiten Horizonts (3), Großes Fläschchen des Tiefensogs (3), Expulsom (4)"}
MultiLanguageItemData['de'][169604] = {name = "[q3]Formel: Bündnis des kritischen Trefferwerts", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man 'Bündnis des kritischen Trefferwerts' effizienter herstellt.\n[q2]Einen Ring dauerhaft verzaubern, sodass der kritische Trefferwert um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (170)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][169605] = {name = "[q3]Formel: Bündnis des Tempos", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man 'Bündnis des Tempos' effizienter herstellt.\n[q2]Einen Ring dauerhaft verzaubern, sodass das Tempo um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (170)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][169606] = {name = "[q3]Formel: Bündnis der Meisterschaft", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man 'Bündnis der Meisterschaft' effizienter herstellt.\n[q2]Einen Ring dauerhaft verzaubern, sodass die Meisterschaft um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (175)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][169607] = {name = "[q3]Formel: Bündnis der Vielseitigkeit", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man 'Bündnis der Vielseitigkeit' effizienter herstellt.\n[q2]Einen Ring dauerhaft verzaubern, sodass die Vielseitigkeit um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (175)\nBenötigtDie Entfesselten\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][169608] = {name = "[q4]Reißende Sägezahnklinge", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Schwert}\n7 - 13 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+4 Stärke\n+5 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 110 / 110\nVerkaufspreis:"}
MultiLanguageItemData['de'][169609] = {name = "[q4]Bauplan: Motor mit Turbolader", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Motor mit Turbolader herstellt.\n[q2]Stellt einen Motor mit Turbolader her.\nBenötigt Ingenieurskunst von Kul Tiras (160)\n[q3]Motor mit Turbolader\n[q2]Benutzen: Kombiniert ein monelitverstärktes Chassis und einen Motor mit Turbolader, um ein Xiwyllag-Flugfahrboot herzustellen. Das ist ein sehr schnelles Reittier.\nBenötigt Moneliterz (100), Sturmsilbererz (50), Isoliertes Kabel (25), Chemische Sprengkapsel (12), Expulsom (8)"}
