MultiLanguageItemData['de'][170172] = {name = "[q2]Glanzstachelmuschel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Setzt Euch die glänzende, stachelige Muschel auf den Kopf. Sie fügt Gegnern, die Euch im Nahkampf angreifen, körperlichen Schaden zu, erhöht aber den Radius, in dem Gegner Euch entdecken.\n\n Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n4 Aufladungen\n[q]\"Die Muschel glitzert im Sonnenlicht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][170173] = {name = "Glyphe 'Killerbienen'", additional_info = "Klassen: Jäger\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Einsatz Eurer Fähigkeit 'Alphatier' ruft Bienen herbei! KILLERBIENEN!!! Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel'\nVerkaufspreis:"}
MultiLanguageItemData['de'][170174] = {name = "[q2]Schlammschleim", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht 20 Min. lang die Ausweichchance um 35% und gewährt erhöhtes Tempo, wenn Ihr einem Angriff ausweicht.\n\n Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (1s Abklingzeit) (10 Sek. Abklingzeit)\n[q]\"Wirkt ganz besonders schleimig.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][170175] = {name = "[q2]Technik: Glyphe 'Killerbienen'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man die Glyphe 'Killerbienen' schreibt.\nBenötigt Inschriftenkunde von Kul Tiras (150)\nVerkaufspreis:\nGlyphe 'Killerbienen'\nKlassen: Jäger\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Einsatz Eurer Fähigkeit 'Alphatier' ruft Bienen herbei! KILLERBIENEN!!! Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Blutrote Tinte (10), Chorhonig (10), Ultramarinblaue Tinte (30)"}
MultiLanguageItemData['de'][170176] = {name = "[q2]Tiefenrochenflügel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Das harte, gummiartige Äußere schützt das zarte Fleisch darin. Vielleicht kann einer Eurer neuen Verbündeten in Nazjatar damit etwas anfangen.\""}
MultiLanguageItemData['de'][170177] = {name = "[q2]Gestrandeter Fisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Legt den Fisch auf den Boden und befördert ihn mit Tritten durch die Gegend. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][170178] = {name = "[q2]Alphafinne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Beschwört einen reitbaren wilden Schnappdrachen für 20 Sek. Wenn Ihr absteigt, kämpft der Schnappdrache 1 Min. lang für Euch. Das ist ein sehr, SEHR schnelles Reittier.\n\n\n Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][170179] = {name = "[q3]Schnappdrachenduftdrüse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Zerquetscht die Drüse, werdet zum Rudelführer und beschwört so Schnappdrachen, die 1 Min. lang für Euch kämpfen.\n\n Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n[q]\"Die Drüse einer Schnappdrachenmatriarchin oder eines -patriarchen weist den Besitzer als Rudelführer aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][170180] = {name = "[q2]Klingenpanzer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört für 5 Min. einen reitbaren Panzer, der gegnerische Spielercharaktere zum Absteigen zwingt und sie betäubt.\n\n Kann nur im Kriegsmodus in Mechagon, Nazjatar, Zandalar und Kul Tiras verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][170181] = {name = "[q2]Gezeitenschutz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Gezeitenwächter, der Euch 2 Min. lang beisteht.\n\n Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][170182] = {name = "[q3]Voltschuppenschild", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Trifft Gegner in der Nähe mit Gezeitenwächterblitzen, die Naturschaden verursachen und den erlittenen Naturschaden erhöhen.\n\n Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n10 Aufladungen\nVerkaufspreis:"}
