MultiLanguageItemData['de'][170185] = {name = "[q3]Intaktes Nagaskelett", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Der Naga wurde wahrscheinlich im Ganzen verschlungen und scheint etwas zu umklammern.\"\n[q2]<Zum Öffnen rechtsklicken>"}
