MultiLanguageItemData['de'][171200] = {name = "Vantusrunentechnik: Ny'alotha, die Erwachte Stadt", additional_info = "Rang 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Ny'alotha, die Erwachte Stadt effizienter herstellt.\n[q2]Verringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Ny'alotha, die Erwachte Stadt.\nBenötigt Inschriftenkunde von Kul Tiras (165)\nVerkaufspreis: \nVantusrune: Ny'alotha, die Erwachte Stadt\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Ny'alotha, die Erwachte Stadt, ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Tiefrote Tinte (15), Ultramarinblaue Tinte (7)"}
MultiLanguageItemData['de'][171201] = {name = "Vantusrunentechnik: Ny'alotha, die Erwachte Stadt", additional_info = "Rang 2\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Ny'alotha, die Erwachte Stadt effizienter herstellt.\n[q2]Verringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Ny'alotha, die Erwachte Stadt.\nBenötigt Inschriftenkunde von Kul Tiras (165)\nVerkaufspreis: \nVantusrune: Ny'alotha, die Erwachte Stadt\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Ny'alotha, die Erwachte Stadt, ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Tiefrote Tinte (18), Ultramarinblaue Tinte (9)"}
MultiLanguageItemData['de'][171202] = {name = "Vantusrunentechnik: Ny'alotha, die Erwachte Stadt", additional_info = "Rang 1\nWird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Ny'alotha, die Erwachte Stadt herstellt.\n[q2]Erschafft eine Vantusrune: Ny'alotha, die Erwachte Stadt.\nBenötigt Inschriftenkunde von Kul Tiras (165)\nVerkaufspreis: \nVantusrune: Ny'alotha, die Erwachte Stadt\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Ny'alotha, die Erwachte Stadt, ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Tiefrote Tinte (20), Ultramarinblaue Tinte (10)"}
