MultiLanguageItemData['de'][171315] = {name = "[q2]Nachtschatten", additional_info = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][171316] = {name = "[q3]Pläne: Verstörende Osmenitbeinschützer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Stellt verstörende Osmenitbeinschützer her.\nBenötigt Schmiedekunst von Kul Tiras (165)\n[q]\"Lehrt Euch, wie man verstörende Osmenitbeinschützer herstellt.\""}
MultiLanguageItemData['de'][171317] = {name = "[q3]Pläne: Verstörende Osmenitgürtung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Stellt eine verstörende Osmenitgürtung her.\nBenötigt Schmiedekunst von Kul Tiras (165)\n[q]\"Lehrt Euch, wie man eine verstörende Osmenitgürtung herstellt.\""}
MultiLanguageItemData['de'][171318] = {name = "[q3]Rezept: Entfesselter Alchemistenstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen entfesselten Alchemistenstein herstellt.\n[q2]Stellt einen entfesselten Alchemistenstein her.\nBenötigtAlchemie von Kul Tiras\n(165)\n\n\n[q4]Entfesselter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n[q2]+ 12 Vielseitigkeit\n\n[q0]Prismatischer Sockel\n\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 31 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie von Kul Tiras\n(165)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis: \nBenötigt Zin'anthide (175), Ankerkraut (60), Expulsom (30)"}
MultiLanguageItemData['de'][171320] = {name = "[q3]Leerenfokus", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Dieser dunkle Kristall basiert auf einem bei N'Zoths Truppen erbeuteten Konzept. Die Energie, die er ausstrahlt, ermöglicht es dem Träger, mächtige Gegenstände herzustellen.\""}
MultiLanguageItemData['de'][171323] = {name = "[q3]Spiritueller Alchemiestein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 25 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 67 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie der Schattenlande\n(100)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:"}
