MultiLanguageItemData['de'][171344] = {name = "Venthyrkalligraphieset", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Kein Venthyrdokument ist gültig, bevor es über alle Maßen verziert wurde.\""}
MultiLanguageItemData['de'][171345] = {name = "Gefälschter Verurteilungsbrief", additional_info = "Questgegenstand\nEinzigartig\n[q]\"In Sachen Wortwahl und Formatierung musstet Ihr etwas raten, aber er sieht dennoch recht überzeugend aus.\""}
MultiLanguageItemData['de'][171346] = {name = "[q0]Briefe aus der Stadt", additional_info = "[q]\"Voller Tratsch über Adelige und Gerüchte über die Rebellion.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][171347] = {name = "Verderbtes Knochenfragment", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Segment des Gesichtslosenskeletts. Furorion hat vielleicht Verwendung dafür.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][171348] = {name = "[q0]Zerrissene Rolle der unweltlichen Rituale", additional_info = "[q]\"Die Wörter verschwimmen vor Euren Augen, sodass es schwierig ist, die fremdartigen Zauberformeln zu verstehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][171349] = {name = "Trank des Phantomfeuers", additional_info = "[q2]Benutzen: Eure Angriffe und Zauber haben eine Chance, eine feurige Projektion zum Ziel zu schicken, die ihm 6270 Schattenflammenschaden zufügt.\n\n Wenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der zusätzliche Schaden um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][171350] = {name = "Trank des göttlichen Erwachens", additional_info = "[q2]Benutzen: Eure Heilzauber heilen abhängig von der fehlenden Gesundheit des Ziels um bis zu 11765 Gesundheit mehr.\n\n Wenn Ihr diesen Trank benutzt, während Eure Waffe mit Einbalsamieröl verstärkt ist, wird die zusätzliche Heilung um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][171351] = {name = "Trank der tödlichen Fixierung", additional_info = "[q2]Benutzen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, Euer Ziel mit 'Tödliche Fixierung' zu belegen, was im Verlauf von 8 Sek. 172 Schattenschaden verursacht und bis zu 5-mal stapelbar ist. Beim Erreichen von 5 Stapeln explodiert 'Tödliche Fixierung' und fügt dem Ziel 3946 Schattenschaden zu.\n\n Wenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, wird der Explosionsschaden um 10% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][171352] = {name = "Trank des ermächtigten Exorzismus", additional_info = "[q2]Benutzen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, die Anima des Ziels ausbrechen zu lassen, was allen Gegnern innerhalb von 10 Metern um das Ziel bis zu 3740 Schattenschaden zufügt.\n\n Wenn Ihr diesen Trank benutzt, während Eure Waffe mit Schattenkernöl verstärkt ist, werden der zusätzliche Schaden und die Reichweite um 20% erhöht. Hält 25 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][171353] = {name = "[q5]Ausgerissene Seite von \"Der Fluch des Steins\"", additional_info = "Questgegenstand\n[q]\"Die auf der Seite festgehaltenen Worte und Bilder sind ziemlich verstörend.\""}
