MultiLanguageItemData['de'][171368] = {name = "Tonreine Legierung", additional_info = "Questgegenstand\nEinzigartig (30)\n[q2]Benutzen: Kombiniert 20 Stück tonreine Legierung und 3 Stück singendes Holz, um einen Tonhammer zu erschaffen.\n[q]\"Erzeugt einen klaren, angenehmen Ton, wenn man sie anschlägt.\""}
MultiLanguageItemData['de'][171369] = {name = "Singendes Holz", additional_info = "Questgegenstand\nEinzigartig (3)\n[q2]Benutzen: Kombiniert 20 Stück tonreine Legierung und 3 Stück singendes Holz, um einen Tonhammer zu erschaffen.\n[q]\"Teil einer Pflanze, die sanfte Töne erzeugt, wenn der Wind über sie hinwegweht.\""}
