MultiLanguageItemData['de'][172365] = {name = "[q2]Waffe - Aufgestiegene Lebenskraft", additional_info = "[q2]Benutzen: Eine Waffe dauerhaft verzaubern, sodass sie manchmal Eure erhaltene Heilung für 10 Sek. um 12% erhöht, wenn Ihr Schaden erleidet. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][172366] = {name = "[q2]Waffe - Himmlische Führung", additional_info = "[q2]Benutzen: Eine Waffe dauerhaft verzaubern, sodass bei Angriffen oder dem Einsatz von Zaubern und Fähigkeiten manchmal Euren Primärwert um 5% erhöht wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][172367] = {name = "[q2]Waffe - Ewige Anmut", additional_info = "[q2]Benutzen: Eine Waffe dauerhaft verzaubern, sodass sie manchmal beim Ziel Eurer hilfreichen Zauber und Fähigkeiten einen Heilungsschub in Höhe von [(97 / 100 * Max(Angriffskraft, Zaubermacht) * (1 + Vielseitigkeit))] Gesundheit bewirkt, die gleichmäßig auf Verbündete in der Nähe aufgeteilt wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][172368] = {name = "[q2]Waffe - Sündhafte Offenbarung", additional_info = "[q2]Benutzen: Eine Waffe dauerhaft verzaubern, sodass Eure Angriffe manchmal eine Sünde des Ziels offenbaren, durch die es 10 Sek. lang 6% mehr Schaden durch Euch erleidet. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][172370] = {name = "[q2]Waffe - Lichtlose Kraft", additional_info = "[q2]Benutzen: Eine Waffe dauerhaft verzaubern, sodass eine Chance besteht, beim Einsatz von Offensivzaubern und -fähigkeiten eine Welle aus Schattenenergie nach vorn zu entsenden, die die ersten 5 Gegner in ihrer Bahn trifft. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nVerkaufspreis:"}
