MultiLanguageItemData['de'][172912] = {name = "Schwungumverteilungsstiefel", additional_info = "Wird bei Benutzung gebunden\n[q2]Benutzen: Leitet einen beträchtlichen Teil des Fallschadens, den Ihr bei Eurem nächsten Sturz erleiden würdet, auf Gegner in der Nähe um. Hält 10 Sek. lang an.\n\n Kann nicht in Instanzen verwendet werden. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)\n[q]\"Ermöglicht Euch das Ausführen einer superheroischen Landung!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][172914] = {name = "Gravimetrische Störkanone", additional_info = "Wird bei Benutzung gebunden\n[q2]Benutzen: Destabilisiert die Schwerkraft um einen Zielort, was 10 Sek. lang die Bewegung von Gegnern in der Nähe behindert, sie in zufällige Richtungen schleudert oder sie in die Luft stößt...\n\n sofern keine Fehlzündung eintritt.\nBenötigt Ingenieurskunst der Schattenlande (1)\n[q]\"Wird gelegentlich als \"Schwarzes-Loch-Kanone\" bezeichnet, was jedoch ein unzutreffender Name ist. Eigentlich ist es eher ein Artilleriegeschütz.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][172915] = {name = "533L3N-F4LL3", additional_info = "Wird bei Benutzung gebunden\n[q2]Benutzen: Platziert ein Eindämmungsgerät auf dem Boden, das nach seiner Scharfmachung aktiviert wird, wenn ein Gegner darauf tritt. Der Gegner wird dann für 1 Min. gebannt.\n\n Es sei denn, es tritt eine Fehlzündung ein.\n\n Verringerte Wirksamkeit gegen Spielercharaktere. (3 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)\n[q]\"Mit wem werdet Ihr kommunizieren?!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][172917] = {name = "Gürtelmodifikation: Dimensionswechsler", additional_info = "[q2]Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\n Nur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden.\n[q]\"Man kann nicht angreifen, was man nicht visuell wahrnehmen kann!\""}
