MultiLanguageItemData['de'][173288] = {name = "[q6]Überquellende Azeritgeode", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\n{Große Macht:\n Ruhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden}, den sie mit Azeritessenzen verursachen, für die nächsten 10 Sek. um 45%. \n Geringe Macht:\n Vereinte Kräfte\n40 Meter Reichweite\n Ca. 3 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, [das {Tempo von Euch und 2 anderen Verbündeten][Euer {Tempo] 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei [Euch und 2 anderen Verbündeten][Euch] aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.}"}
MultiLanguageItemData['de'][173289] = {name = "[q6]Pulsierende Azeritgeode", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\n{Große Macht:\n Ruhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden}, den sie mit Azeritessenzen verursachen, für die nächsten 20 Sek. um 45%. \n Geringe Macht:\n Vereinte Kräfte\n40 Meter Reichweite\n Ca. 4 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das {Tempo von Euch und 1 anderem Verbündeten 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei Euch und 1 anderem Verbündeten aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.}"}
MultiLanguageItemData['de'][173290] = {name = "[q6]Beflügelnde Azeritgeode", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\nErlernt Rang 3 einer Essenz aus Verstörenden Visionen auf einem anderen Charakter, um diese Essenz freizuschalten.\n{Große Macht:\n Ruhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden}, den sie mit Azeritessenzen verursachen, für die nächsten 20 Sek. um 45%. Erhöht währenddessen außerdem ihre Geschwindigkeit um 64 . \n Geringe Macht:\n Vereinte Kräfte\n40 Meter Reichweite\n Ca. 4 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das {Tempo von Euch und 2 anderen Verbündeten 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei Euch und 2 anderen Verbündeten aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.}"}
MultiLanguageItemData['de'][173291] = {name = "[q6]Leuchtende Azeritgeode", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Inspirierender Funke'.\n{Große Macht:\n Ruhmreicher Moment\n40 Meter Reichweite Wirken in 1.5 sek. 1 min Abklingzeit Entfesselt eine Energiewelle aus Eurem Herz von Azeroth und erhöht bei allen Gruppenmitgliedern innerhalb von 15 Metern den Schaden}, den sie mit Azeritessenzen verursachen, für die nächsten 20 Sek. um 45%. Erhöht währenddessen außerdem ihre Geschwindigkeit um 64 . \n Geringe Macht:\n Vereinte Kräfte\n40 Meter Reichweite\n Ca. 4 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das {Tempo von Euch und 2 anderen Verbündeten 8 Sek. lang um 30 zu erhöhen und die Abklingzeit der bei Euch und 2 anderen Verbündeten aktuell eingesetzten großen Essenz um 1.0 Sek. zu verringern.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.}"}
