MultiLanguageItemData['de'][173703] = {name = "Reinheitskrug", additional_info = "Questgegenstand\n[q2]Benutzen: Der Affenkönig hat Euch diesen Krug für den Fall gegeben, dass Ihr Hilfe bei seinen Rätseln braucht. Wenn Ihr den Inhalt trinkt, findet Ihr vielleicht eher den richtigen Weg. Aber warum riecht er so seltsam?\n1 Aufladung\nVerkaufspreis:"}
MultiLanguageItemData['de'][173704] = {name = "Kornkammerkrug", additional_info = "Questgegenstand\n[q2]Benutzen: Der Affenkönig hat Euch diesen Krug für den Fall gegeben, dass Ihr Hilfe bei seinen Rätseln braucht. Wenn Ihr den Inhalt trinkt, findet Ihr vielleicht eher den richtigen Weg. Es hört sich an, als wäre Reis in dieses Getränk gemischt.\n1 Aufladung\nVerkaufspreis:"}
MultiLanguageItemData['de'][173705] = {name = "[q2]Die Venthyrtagebücher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Eine Sammlung persönlicher Tagebucheinträge namhafter Venthyr. Sehr begehrt bei Personen, die mehr über ihr Alltagsleben erfahren wollen.\""}
MultiLanguageItemData['de'][173706] = {name = "Jadekrug", additional_info = "Questgegenstand\n[q2]Benutzen: Der Affenkönig hat Euch diesen Krug für den Fall gegeben, dass Ihr Hilfe bei seinen Rätseln braucht. Wenn Ihr den Inhalt trinkt, findet Ihr vielleicht eher den richtigen Weg. Wie eine spektrale Version des Affenkönigs Euch dies geben konnte, ist wiederum auch ein Rätsel.\n1 Aufladung\nVerkaufspreis:"}
MultiLanguageItemData['de'][173707] = {name = "[q2]Seelenjägerklinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Klinge eines Venthyrrapiers. Ein Blick darauf verrät sofort seine mörderische Vergangenheit.\""}
MultiLanguageItemData['de'][173708] = {name = "Kyrianischer Schild", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Werfen!\n[q]\"Ein amüsanter Weg, eine Bindung mit Eurem Larion einzugehen.\""}
MultiLanguageItemData['de'][173709] = {name = "[q2]Phiole Gräberschlamm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Enthält Schlamm aus einer Schlammlache. Der Geruch ist abscheulich und versengt Eure Nasenhaare.\""}
MultiLanguageItemData['de'][173710] = {name = "[q2]Versteinertes Steinscheusal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Anima des Steinscheusals wurde gänzlich entzogen. Davon abgesehen ist es in sehr gutem Zustand.\""}
MultiLanguageItemData['de'][173711] = {name = "[q2]Porträt von Graf Denathrius", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Eine beinahe perfekte Darstellung von Denathrius.\""}
MultiLanguageItemData['de'][173712] = {name = "[q2]Seelenregister", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein Register, das die Namen tausender Seelen beinhaltet, die nach Revendreth geschickt wurden.\""}
MultiLanguageItemData['de'][173713] = {name = "[q4]Boshaftes weißes Knochenross", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares boshaftes weißes Knochenross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Kaum ein anderes Reittier ermöglicht einen Ritt in die Schlacht mit so vielen Stacheln und Knochen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1"}
MultiLanguageItemData['de'][173714] = {name = "[q4]Boshafter weißer Kriegssäbler", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren boshaften weißen Kriegssäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Streicheleinheiten am Bauch sind nicht erwünscht und bringen nur Ärger.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1"}
MultiLanguageItemData['de'][173715] = {name = "[q2]Gräberwerkzeugsatz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein Eimer voller Werkzeuge, die von den Gräbern von Revendreth verwendet werden.\""}
