MultiLanguageItemData['de'][173883] = {name = "[q6]Replizierende Leerentropfen", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nGroße Macht:\n Replikation des Wissens\n40 Meter Reichweite\n Wirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 1 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 50% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\n Funktioniert nicht bei passiven Essenzen. \n Geringe Macht:\n Symbiotische Präsenz\n40 Meter Reichweite Jedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr 20 Sek. lang 22 Hauptwert .\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n[q]\"Niederträchtig und doch äußerst machtvoll.\""}
MultiLanguageItemData['de'][173884] = {name = "[q6]Wachsender Leerentropfen", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nGroße Macht:\n Replikation des Wissens\n40 Meter Reichweite\n Wirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 2 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 40% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\n Funktioniert nicht bei passiven Essenzen. \n Geringe Macht:\n Symbiotische Präsenz\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr für 20 Sek. [ 22 * (1.25)] Hauptwert.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][173885] = {name = "[q6]Instabiler Leerentropfen", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nErlernt mit einem anderen Charakter 'Rang 3 - Die Formlose Leere', um diese Essenz freizuschalten.\nGroße Macht:\n Replikation des Wissens\n40 Meter Reichweite\n Wirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 3 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 30% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\n Funktioniert nicht bei passiven Essenzen. \n Geringe Macht:\n Symbiotische Präsenz\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr für 20 Sek. [ 22 * (1.25)] Hauptwert und 18 Tempo.\n\n Der Verbündete, der eine Azeritessenz eingesetzt hat, erhält ebenfalls für 20 Sek. 18 Tempo. Es kann immer nur ein Verbündeter diesen Tempoeffekt haben.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][173886] = {name = "[q6]Ausbrechender Leerentropfen", additional_info = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nGroße Macht:\n Replikation des Wissens\n40 Meter Reichweite\n Wirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 3 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 30% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\n Funktioniert nicht bei passiven Essenzen. \n Geringe Macht:\n Symbiotische Präsenz\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr für 20 Sek. [ 22 * (1.25)] Hauptwert und 18 Tempo.\n\n Der Verbündete, der eine Azeritessenz eingesetzt hat, erhält ebenfalls für 20 Sek. 18 Tempo. Es kann immer nur ein Verbündeter diesen Tempoeffekt haben.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht."}
MultiLanguageItemData['de'][173887] = {name = "[q4]Kralle von Ha-Li", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ha-Lis Brut ist am blauen Himmel Pandarias zu Hause und jagt dort arglose Beute.\"\nBeute von:\nHa-Li\nZone:\nTal der Ewigen Blüten"}
