MultiLanguageItemData['de'][173943] = {name = "[q4]Qual im Glas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Angriffe haben eine Chance, einen Rest von Azsharas Qual zu entfesseln, der allen Gegnern in der Nähe 1 Schattenschaden zufügt und Euch 'Entfesselte Qual' gewährt. 'Entfesselte Qual' erhöht den Schaden dieses Effekts um 100%. Wenn 12 Stapel erreicht werden, werden diese aufgebraucht, um allen Gegnern in der Nähe 45 Schattenschaden zuzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][173944] = {name = "[q4]Verbotene Obsidianklaue", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\n[q2]Benutzen: Entzieht dem Ziel seine Lebenskraft, fügt ihm so im Verlauf von 8.5 Sek. 130 Schattenschaden zu und stellt dabei [ 21 * (10)] Eures Manas wieder her. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][173945] = {name = "Schließt Euch dem Prinzen an!", additional_info = "Questgegenstand\n[q]\"In eleganter Handschrift verfasst.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][173946] = {name = "[q4]Zuckendes Segment von Drest'agath", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Verursacht eine Eruption abscheulicher Stacheln, die alle Gegner in der Nähe treffen und ihnen 349 körperlichen Schaden zufügen. (1 Min, 20 Sek. Abklingzeit)\nVerkaufspreis:"}
