MultiLanguageItemData['de'][174041] = {name = "Augenglibber", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her.\n Ihr müsst beim Essen sitzen bleiben.\n[q]\"Hat eine überraschend glatte Konsistenz.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][174042] = {name = "[q2]Prise Feenstaub", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 15 min (Realzeit)\n[q2]Benutzen: Feenstaub macht Euch leichter, sodass Ihr mithilfe eines Doppelsprungs fliegen könnt. Jegliche Aktion bricht diesen Effekt ab.\n Hält 1.5 Min. lang an."}
MultiLanguageItemData['de'][174043] = {name = "Phylakterium von Arin'gore", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Zertrümmert Arin'gores Phylakterium und beschwört den Lich in den Kampf.\n[q]\"Der winzige Dolch wurde schlicht und ohne Verzierungen gefertigt.\""}
MultiLanguageItemData['de'][174044] = {name = "[q4]Summende schwarze Drachenschuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Entfesselt die Macht von Ashjra'kamas, Tuch der Entschlossenheit, um Eure Fallgeschwindigkeit für 15 Sek. zu reduzieren. (2 Min Abklingzeit)\n[q2]Anlegen: Eure Angriffe und Fähigkeiten haben die Chance, Euch vergängliche Drachenflügel zu gewähren, die 15 Sek. lang Euer Tempo um 20 und Eure Geschwindigkeit um 9 erhöhen.\nVerkaufspreis:"}
