MultiLanguageItemData['de'][174050] = {name = "[q4]Verderbter Ring - Gewalt genießen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Eure Todesstöße lassen Euch die Gewalt genießen und machen Euch 6 Sek. lang bewegungsunfähig.\nVerkaufspreis:"}
MultiLanguageItemData['de'][174051] = {name = "[q4]Verderbter Ring - Spontaner Zorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Markiert regelmäßig einen zufälligen Gegner, der so zum Ziel Eures Zorns wird. Während Euer Zorn anhält, wird der Schaden, den Ihr anderen Gegnern zufügt, um 10% verringert. (45s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][174052] = {name = "[q4]Verderbter Ring - Masochistisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Wenn Eure Gesundheit unter 25% fällt, verspottet Ihr 5 Sek. lang alle Gegner in der Nähe.\nVerkaufspreis:"}
MultiLanguageItemData['de'][174053] = {name = "[q4]Verderbter Ring - Übermütig", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Wenn Ihr überschüssige Heilung erhaltet, lehnt Ihr die nächsten (Gesamtgesundheit * 25 / 100) Heilung innerhalb von 10 Sek. ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][174054] = {name = "[q4]Verderbter Ring - Letzter Griff", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Wenn Ihr einen Gegner tötet, wird an dessen Position ein feindliches Tentakel beschworen, das versucht, Euch mit 'Leerengriff' zu treffen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][174055] = {name = "[q4]Verderbter Ring - Ding aus dem Jenseits", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 16.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Das Ding aus dem Jenseits erhebt sich regelmäßig in Eurer Nähe und greift Euch an. Seine Bewegungsgeschwindigkeit erhöht sich entsprechend der Verderbnis.\nVerkaufspreis:"}
MultiLanguageItemData['de'][174056] = {name = "[q4]Verderbter Ring - Der Wahrheit ins Auge sehen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Eine unsägliche Schriftrolle erscheint in Eurer Nähe, die nur Ihr und andere mit dieser Verderbnis sehen können. Jede Sekunde, in der Ihr sie nicht anseht, erleidet Ihr 0 Schaden. Wenn sie Euch 5-mal Schaden zugefügt hat, werdet Ihr 6 Sek. lang in Angst und Schrecken versetzt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][174057] = {name = "[q4]Verderbter Ring - Hypnotisierend", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 15.\n[q2]Anlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\n[q2]Anlegen: Eure Schadenszauber und -fähigkeiten gegen dasselbe Ziel verringern Eure Bewegungsgeschwindigkeit 6 Sek. lang um 5%. Dieser Effekt ist bis zu 10-mal stapelbar.\nVerkaufspreis:"}
