MultiLanguageItemData['de'][174861] = {name = "[q4]Zuckender Parasit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Er ist ständig in Bewegung! Das wirkt chaotisch und beunruhigend auf den Beobachter.\"\nErfolg:\nRuhm des Schlachtzüglers von Ny'alotha\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageItemData['de'][174862] = {name = "[q4]Unverderbte Leerenschwinge", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Brut von Vexiona wurde von Furorion geläutert und entstammt einem Drachenschwarm mit einer zerrütteten Vergangenheit und einer ungewissen Zukunft.\"\nQuest:\nVerlorener Schwarm"}
MultiLanguageItemData['de'][174863] = {name = "[q4]Brut von Vexiona", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Stammt aus dem Gelege des gefallenen Drachen und wurde tief in N'Zoths Innerem gefunden.\""}
MultiLanguageItemData['de'][174864] = {name = "Jagdhorn des Dromanen", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Lasst das Dromanenhorn ertönen, um die Wilde Jagd zum Winterschlafbecken zu rufen. (4 Sek. Abklingzeit)\n[q]\"Ein uraltes hölzernes Horn.\""}
MultiLanguageItemData['de'][174865] = {name = "[q2]Ein winziger Winterhut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie Altvater Winter."}
MultiLanguageItemData['de'][174867] = {name = "Splitter der Verderbnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 1 tag (Realzeit)\nDieser Gegenstand startet eine Quest.\n[q]\"Ein dichtes Miasma der Verderbnis geht von dem Splitter aus. Er fühlt sich enorm schwer an, und wer ihn trägt, wird von Gefühlen der Unterdrückung und Boshaftigkeit überwältigt.\""}
