MultiLanguageItemData['de'][178567] = {name = "Kheins Runenklinge", additional_info = "Questgegenstand\n[q2]Benutzen: Causes an enemy to take 20% increased Physical damage for 3 Sek..\n Inflicts 10 Physical damage to an enemy every 5.2 sec for 3 Sek..\n Inflicts 10 Physical damage to an enemy.\n[q]\"Runen leuchten schwach entlang dieser mitgenommenen Klinge.\""}
MultiLanguageItemData['de'][178568] = {name = "Beutel voller gruseliger Krabbler", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Öffnet einen Beutel voller verstörender Kreaturen, die Gegner in der Nähe 30 Sek. lang ablenken. Kann nur im Freien in den Schattenlanden verwendet werden. (1 Min Abklingzeit)\n[q]\"Sie zappeln und fiepsen verstörend.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][178569] = {name = "Der Ursprung des Todes", additional_info = "Questgegenstand\n[q]\"Ein dicker Foliant mit Theorien über die Entstehung der verflochtenen Mechanismen der Schattenlande und darüber, wie sie miteinander in Verbindung stehen.\""}
MultiLanguageItemData['de'][178570] = {name = "Verblassendes Erinnerungsglas", additional_info = "Questgegenstand\n[q]\"Dieses Erinnerungsglas scheint sehr alt zu sein und die darin enthaltenen Erinnerungen werden bald verloren gehen.\""}
MultiLanguageItemData['de'][178571] = {name = "Schleimige Korrespondenz", additional_info = "Questgegenstand\n[q]\"Ein Brief von Markgräfin Stradama an einen unbekannten Empfänger. Er wurde in einer Geheimsprache verfasst, die Ihr nicht entschlüsseln könnt.\""}
MultiLanguageItemData['de'][178572] = {name = "Ring aus fremdartigen Metall", additional_info = "Questgegenstand\n[q]\"Ein Ring aus einem merkwürdigen Metall, das Euch an Oribos erinnert.\""}
MultiLanguageItemData['de'][178573] = {name = "Ungewöhnliche Mechanoidenteile", additional_info = "Questgegenstand\n[q]\"Es scheint sich um Teile des Kerns eines Mechanoiden zu handeln, doch Ihr habt so solche wie diese noch nie in den Schattenlanden erblickt.\""}
MultiLanguageItemData['de'][178574] = {name = "Seltsame Ritualmaske", additional_info = "Questgegenstand\n[q]\"Eine Maske mit einem Robotergesicht, die nichts ähnelt, was Ihr in den Schattenlanden je gesehen habt.\""}
MultiLanguageItemData['de'][178575] = {name = "Goldene Energiekugel", additional_info = "Questgegenstand\n[q]\"Eine komplexe und komplizierte Art goldener Kugel, die etwas Düsteres in ihrem Inneren beherbergt. Gelegentlich zeigt sie ein weißes Energieflackern, das jedoch nie lange anhält.\""}
MultiLanguageItemData['de'][178576] = {name = "Uraltes Mittlerkopfstück", additional_info = "Questgegenstand\n[q]\"Das Kopfstück eines Mittlers unbekannten Ursprungs. Es unterscheidet sich deutlich von denen anderer Mittler, die Ihr in Oribos begegnet seid.\""}
MultiLanguageItemData['de'][178577] = {name = "Nalthors Phylakteriumanleitung", additional_info = "Questgegenstand\n[q]\"Eine Anleitung zur Erschaffung eines Phylakteriums, ein nekrotisches Ritual, das Lichs bei seltenen Gelegenheiten gemeinsam durchführen.\""}
MultiLanguageItemData['de'][178578] = {name = "Seltsame Puppe", additional_info = "Questgegenstand\n[q]\"Es scheint sich um ein Spielzeug oder eine Puppe zu handeln. Sie hat eine merkwürdige Form und wird wohl von einem Ort außerhalb Azeroths stammen.\""}
MultiLanguageItemData['de'][178579] = {name = "Stradamas verschwundenes Geschäftsbuch", additional_info = "Questgegenstand\n[q]\"Mehrere sorgfältig geführte Listen von Objekten und den Schleimpfützen, in denen sie gelagert werden. Hier wird ein Koordinatensystem verwendet, das Ihr noch nie gesehen habt.\""}
MultiLanguageItemData['de'][178580] = {name = "Münze des Champions", additional_info = "Questgegenstand\n[q]\"Eine merkwürdige Münze, die Champions im Theater der Schmerzen für mehrere siegreiche Runden erhalten. Hat nur zeremonielle Zwecke und keinen Nutzen als Handelsmittel.\""}
MultiLanguageItemData['de'][178581] = {name = "Vollgefressene Gormlarve", additional_info = "Questgegenstand\n[q]\"Eine weiche, zappelnde Gormlarve, die schon fast ausgewachsen zu sein scheint.\""}
MultiLanguageItemData['de'][178582] = {name = "Goldene Totenmaske", additional_info = "Questgegenstand\n[q]\"Eine Maske, die das Gesicht von Mueh'zala darstellt. Stammt vermutlich aus einer Zivilisation, die ihn einst verehrt hat.\""}
MultiLanguageItemData['de'][178583] = {name = "Foliant der Gräberalchemie", additional_info = "Questgegenstand\n[q]\"Ein Buch, das die verschiedenen Methoden zur Erschaffung und Verwendung der Gräber beschreibt.\""}
MultiLanguageItemData['de'][178584] = {name = "Medaillon der Orientierung", additional_info = "Questgegenstand\n[q]\"Ein Medaillon, mit dem man in den Schattenlanden erkennt, in welcher Richtung Oribos liegt. Wertvoll für Generäle, um ihre Armeen zu leiten, doch von absolut unschätzbarem Wert für reisende Händler.\""}
MultiLanguageItemData['de'][178585] = {name = "Der vergessene Schlüssel", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest."}
MultiLanguageItemData['de'][178586] = {name = "[q2]Kyrianische Waffen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Provost, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern der Bastion zu gewinnen.\n[q]\"Vergoldete Waffen der Einwohner der Bastion. Wie sie beschafft wurden, ist unbekannt.\""}
MultiLanguageItemData['de'][178587] = {name = "[q2]Maldraxxische Waffen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Skelettdiener, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern von Maldraxxus zu gewinnen.\n[q]\"Mit Knochen versteifte Waffen der Einwohner von Maldraxxus. Wie sie beschafft wurden, ist unbekannt.\""}
MultiLanguageItemData['de'][178588] = {name = "[q2]Faewaffen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört eine Fee, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern des Ardenwalds zu gewinnen.\n[q]\"Aus Holz gefertigte Waffen der Einwohner des Ardenwalds. Wie sie beschafft wurden, ist unbekannt.\""}
MultiLanguageItemData['de'][178589] = {name = "[q2]Venthyrwaffen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Gräber, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern Revendreths zu gewinnen.\n[q]\"Reich verzierte Waffen der Einwohner von Revendreth. Wie sie beschafft wurden, ist unbekannt.\""}
MultiLanguageItemData['de'][178590] = {name = "[q3]Sagenumwobene maldraxxische Knochenklinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Skelettdiener, um den gestohlenen Gegenstand zurückzuholen und eine große Menge Ruf bei den Einwohnern von Maldraxxus zu gewinnen.\n[q]\"Blutgetränkt, aber unbeschadet hat diese Waffe auf den Schlachtfeldern von Maldraxxus schon Tausende Tode herbeigeführt.\""}
MultiLanguageItemData['de'][178591] = {name = "[q3]Uraltes Venthyrrelikt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Gräber, um den gestohlenen Gegenstand zurückzuholen und eine große Menge Ruf bei den Einwohnern Revendreths zu gewinnen.\n[q]\"Ein uraltes Relikt der Macht, das über viele Generationen hinweg von mächtigen Venthyr weitergereicht wurde.\""}
MultiLanguageItemData['de'][178592] = {name = "[q3]Ehrwürdiger kyrianischer Verteidiger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört einen Provost, um den gestohlenen Gegenstand zurückzuholen und eine große Menge Ruf bei den Einwohnern der Bastion zu gewinnen.\n[q]\"Ein schimmerndes goldenes Zeichen des Heldentums, das in all den Jahren nur ein paar wenige Aufgestiegene erhalten haben.\""}
MultiLanguageItemData['de'][178593] = {name = "[q3]Aufwendiges Faehaintuch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Beschwört eine Fee, um das gestohlene Relikt zurückzuholen und eine große Menge Ruf bei den Einwohnern des Ardenwalds zu gewinnen.\n[q]\"Über Jahrhunderte hinweg von den Sylvari verfeinert. Es strahlt es Ruhe und Anmut aus.\""}
