MultiLanguageItemData['de'][179938] = {name = "[q2]Zerbröckelnde Stolzextraktoren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\n[q2]Benutzen: Entzieht einem Gegner seine Vitalität, was ihm 20 Sek. lang alle 5 Sek. 3205 Schattenschaden zufügt und Euch dabei jeweils um 7363 Gesundheit heilt. Kann nur im Freien in den Schattenlanden verwendet werden. (1 Min Abklingzeit)\n5 Aufladungen\nVerkaufspreis:"}
