MultiLanguageItemData['de'][180721] = {name = "[q4]Verzauberter Traumlichtrunenhirsch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die majestätischen Runenhirsche sind mit ihren kunstvollen Geweihen in der Lage, dem Umgebungslicht des Ardenwalds Anima zu entziehen. Die Anima dient ihnen als Nahrung und verleiht ihnen Geschwindigkeit und Magie.\"\nPakt:\nNachtfae\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180722] = {name = "[q4]Verzauberter Schattenblattrunenhirsch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\nVerkaufspreis:\n[q]\"Ein Schattenblattrunenhirsch ist in der Lage, so mächtige Kreaturen wie eine Gormmatriarchin aufzuspießen, um seine Herde zu verteidigen. Die Wilde Jagd reitet auf ihnen in gefährliche Gegenden der Schattenlande, um ihr Reich vor jenen zu beschützen, die die Wildnis bedrohen.\"\nPakt:\nNachtfae\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180723] = {name = "[q4]Verzauberter Runenhirsch des Erweckers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Runenhirsche der Erwecker beschützen ihre Wildsamenhaine mit aller Kraft. Als der Niedergang der Haine begann, sind viele Runenhirsche in wilde Raserei verfallen.\"\nPakt:\nNachtfae\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180724] = {name = "[q4]Verzauberter Winterbornrunenhirsch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtMarasmius\n- Respektvoll\nVerkaufspreis:\n[q]\"Winterbornrunenhirsche sind das bevorzugte Reittier der Winterkönigin selbst. Sie erweist die besondere Gunst einer solchen Kreatur nur ihren ausgewählten Favoriten.\"\nPakt:\nNachtfae\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180725] = {name = "[q4]Stachelschlundhainmalmer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Sprigganreiter binden Stücke animafreier Überreste an Stockenden vor ihre Gormreittiere, um diese zu lenken. Es ist... keine hohe Kunst.\"\nBeute von:\nGormzähmer Tizo\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180726] = {name = "[q4]Blasser Säureschlund", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr benötigt einen ehrfürchtigen Ruf bei den Flickmeistern.\nVerdient den Erfolg \"Nur das Notwendigste\", um dieses Reittier zu kaufen.\nVerkaufspreis:\n[q]\"Die Säure, die im Sekret dieser Kreatur vorhanden ist, hat die Farbe ihres Panzers weggeätzt. Dadurch ist ein auffälliger schneeweißer Farbton entstanden.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords"}
MultiLanguageItemData['de'][180727] = {name = "[q4]Schimmernebelläufer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Boshafte Spriggans und die Talläufer verbindet eine natürliche Feindseligkeit. Kein Talläufer würde sich dazu herablassen, einen Sprigganreiter aufsitzen zu lassen, da sie deren innere Böswilligkeit spüren. Dies erzürnt die Spriggantrickser, die ein krankhaftes Vergnügen darin finden, diesen majestätischen Kreaturen grausame Streiche zu spielen.\"\nGebiet:\nNebelschleierdickicht\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180728] = {name = "[q4]Schneller Düsterhuf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die Balladen des Ardenwalds behaupten, dass die Geburt eines Finsterläufers die Ankunft eines besonders wohlwollenden wilden Gottes einläutet. Einen Finsterläufer zu sehen, ist aus diesem Grund Segen und Fluch zugleich.\"\nBeute von:\nNachtmähre\nZone:\nArdenwald"}
MultiLanguageItemData['de'][180729] = {name = "[q4]Dämmerflatterardenmotte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtDie Wilde Jagd\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Diese Ardenmotten bevorzugen die dunklen und feuchten Wälder im Nordwesten des Ardenwalds, in denen Pilzkolonien ohne Unterlass erblühen.\"\nVerkäufer:\nAithlyn\nZone:\nArdenwald\nFraktion:\nDie Wilde Jagd - Ehrfürchtig\nKosten:\n30."}
