MultiLanguageItemData['de'][180761] = {name = "[q4]Phalynx der Loyalität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Manche Aufgestiegene halten sich einen Phalynx als Haustier. Im Gegensatz zum Larion hat er zwar kein Fell, doch er besitzt den Vorteil, dass er wahrscheinlich nicht Eure anderen Haustiere frisst.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180762] = {name = "[q4]Phalynx der Demut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Phalynx verweigert das Apportieren. Woran das liegt, ist nicht bekannt.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180763] = {name = "[q4]Phalynx des Mutes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Phalynx gilt als würdiger Gefährte und als flinker Gegner, gegen den man seine Reflexe auf die Probe stellen kann.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180764] = {name = "[q4]Phalynx der Reinheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 23\n\n\n\"Über die Ursprünge der Phalynxtechnologie ist nur wenig bekannt, denn die Lehre ihrer Geheimnisse ähnelt eher einer Religion als einer Ingenieurskunst.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180765] = {name = "[q4]Ewiger Phalynx der Reinheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\n\n\n[q]\"Der gepanzerte Phalynx ist ein beliebter Gefährte der mächtigsten Krieger der Aufgestiegenen, da er im Kampf so furchtlos wie tödlich zu Werke geht.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180766] = {name = "[q4]Ewiger Phalynx des Mutes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Um eines dieser funkelnden Reittiere zu schmieden, sind viele Barren Güldenit erforderlich. Doch allein ihr Anblick ist die in das Sammeln des Güldenits investierte Zeit schon wert.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180767] = {name = "[q4]Ewiger Phalynx der Loyalität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerdient den Erfolg \"Todesvierschmähte\", um dieses Reittier zu kaufen.\n\n\n\"Gepanzerte Phalynx sind ein Wunderwerk provostscher Ingenieurskunst. Sie sind so selten wie atemberaubend.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageItemData['de'][180768] = {name = "[q4]Ewiger Phalynx der Demut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerdient den Erfolg \"Von den Meistern lernen\", um dieses Reittier zu kaufen.\n\n\n\"Wenn ein gepanzerter Phalynx geschmiedet wird, klatschen die Provosten ihre Hämmer zusammen, um ihre Hochachtung vor der dazu erforderlichen Ingenieurskunst zum Ausdruck zu bringen.\"\nPakt:\nKyrianer\nZone:\nBastion"}
