MultiLanguageItemData['de'][180969] = {name = "Spiralförmiges Horn eines Todesrocs", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese schwer zu findenden Hörner sind das Ergebnis einer extrem seltenen Mutation. Au'larrynar in Maldraxxus nutzt sie als Zahlungsmittel für seine begehrtesten Gegenstände.\""}
MultiLanguageItemData['de'][180970] = {name = "Teregeerkristall", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieser bernsteinfarbene Kristall ist eine der Kuriositäten, die von Akquisiteur Ta'gosh in Oribos gehortet werden. Er soll einzigartige Verzauberungskräfte besitzen, die seit Jahrtausenden aber niemand mehr zu nutzen wusste.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][180971] = {name = "Aquamarinfarbene Kartellmarke", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Marken werden oft als Schuldschein für einen Gefallen ausgegeben, doch bestimmte Mittler wie Ta'lan der Antiquar in Oribos bieten sie auch im Austausch gegen seltene Gegenstände an, die hoch auf ihrer Liste stehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][180972] = {name = "Makelloser Vulpinpelz", additional_info = "Wird beim Aufheben gebunden\n[q]\"Händler Bix in der Bastion hat den Markt für diese luxuriösen Pelze voll im Griff, sodass sie exklusiv über ihn verkauft werden.\""}
