MultiLanguageItemData['de'][181436] = {name = "[q2]Frisierspiegel", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft einen Frisierspiegel hinzu, mit dem Ihr das Abbild Eurer Gäste auf magische Weise einfangen könnt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][181437] = {name = "[q2]Trainingsattrappen", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft Trainingsattrappen hinzu, damit Ihr Eure Stärke zeigen und so die Aufregung erhöhen könnt.\n[q]\"Ein paar Seuchenflecken sind an ihnen zu erkennen, aber im Großen und Ganzen sind sie funktionstüchtig.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][181438] = {name = "[q2]Die Wilde Trommel", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft die Wilde Trommel hinzu, mit der Ihr Eure Gäste inspirieren und sie für gewisse Zeit deutlich effektiver im Kampf machen könnt.\n[q]\"Diese Trommel, deren Klang an das Grollen einer Bestie ihrer Heimatwelt erinnert, beflügelt selbst die größten Krieger.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][181439] = {name = "[q2]Beschützende Kohlenpfannen", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft beschützende Kohlenpfannen hinzu, mit denen Ihr Euren Gästen magischen Schutz gewähren könnt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][181440] = {name = "[q2]Schlüpfriger Schlamm", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft Glitschi hinzu, einen äußerst glitschigen Gräber, den Ihr dann versuchen könnt zu fangen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][181441] = {name = "[q2]Altar der Errungenschaften", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft einen Altar der Errungenschaften hinzu, mit dem Ihr Eure Erfolge in den Schattenlanden präsentieren und verschiedene Boni erhalten könnt!\nErfordert einen wohlwollenden Ruf beim Gluthof.\nVerkaufspreis:"}
MultiLanguageItemData['de'][181442] = {name = "[q4]Visionen von Graf Denathrius", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft eine Vision von Graf Denathrius hinzu, sodass Theotar die Vision beschwören kann, um Eure Gäste zu erschrecken.\nVerkaufspreis:"}
MultiLanguageItemData['de'][181443] = {name = "[q7]Der festliche Hut des Festherolds", additional_info = "Gluthof\n[q7]Wird an Kriegsmeute gebunden\nEinzigartig\n[q2]Benutzen: Fügt Eurem Gluthof dauerhaft Temels Festheroldhut hinzu, der Euren Rufzuwachs beim Gluthof um 30% erhöht.\nErfordert einen ehrfürchtigen Ruf beim Gluthof.\n[q]\"Selbst erfahrene Festherolde wie Temel müssen sich das Recht verdienen, diesen ultimativen festlichen Hut zu tragen!\"\nVerkaufspreis:"}
