MultiLanguageItemData['de'][181724] = {name = "[q0]Taktik, Band 83: Ausnutzung des Wetters", additional_info = "Wird beim Aufheben gebunden\n[q]\"Die materielle Beschaffenheit der Waffen Eures Feindes zu erkennen, und damit auch deren Ähnlichkeit mit einem Blitzableiter, kann Euch einen entscheidenden Hinweis zum effektivsten Einsatz wetterverändernder Magie geben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][181725] = {name = "[q0]Wertvoller Orden des Wächters", additional_info = "Wird beim Aufheben gebunden\n[q]\"Die Verteidiger von Maldraxxus erhalten einen Orden zu Ehren ihrer Verdienste um den Schutz der Schattenlande.\"\nVerkaufspreis:"}
