MultiLanguageItemData['de'][181727] = {name = "[q0]Leere verstärkte Flaschen", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dreiwandige Fläschchen sind entscheidend für die Aufbewahrung der tödlichen Flüssigkeiten, die das Haus der Seuchen für seine Experimente verwendet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][181728] = {name = "[q0]Makellose Fleischnähernadeln", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese aus den Knochen von Maldraxxus selbst geschnitzten Nadeln sind ein begehrtes Erzeugnis aus dem Haus der Konstrukte.\"\nVerkaufspreis:"}
