MultiLanguageItemData['de'][181815] = {name = "[q4]Gepanzerter Knochenhuftauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Tauralus ist das bevorzugte Reittier des Hauses der Auserwählten, denn er wird im Kampf noch wütender und bösartiger.\"\nBeute von:\nSabriel die Knochenspalterin\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][181816] = {name = "[q4]Siegel der Anpassung des sündigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\n[q]Auszeichnung des Gladiators (0/2)\n[q0]Emblem des Gladiators\nMedaillon des Gladiators\n[q0](2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][181817] = {name = "[q4]Fledderflügel des Todesbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten"}
MultiLanguageItemData['de'][181818] = {name = "[q4]Durchgekaute Zügel des kahlen Fledderflügels", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Fledderflügel sind notwendig für den Kreislauf des Lebens in den Schattenlanden. In der rauen Umgebung von Maldraxxus sind sie sowohl Räuber als auch Beute.\"\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][181819] = {name = "[q4]Markzahns Zügel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der unersättliche Appetit von Markzahn, Nachkomme von Knochenzahn, wurde von Amarth dem Ernter geschätzt, auch wenn er die Experimente des sadistischen Kommandanten störte.\"\nBeute:\nNalthor der Eisbinder\nZone:\nDie Nekrotische Schneise (Mythisch)\n\nBeute:\nSchatz des Herausforderers\nZone:\nDie Nekrotische Schneise"}
MultiLanguageItemData['de'][181820] = {name = "[q4]Gepanzerter auserwählter Tauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Tauralus hat zwei Schweife, die unentbehrlich sind, um lästiges herumschwirrendes Ungeziefer wie die Blutlaus wegzupeitschen.\"\nErfolg:\nAbhakliste für Tote\nKategorie:\nPaktsankten"}
MultiLanguageItemData['de'][181821] = {name = "[q4]Gepanzerter Seuchenfäulnistauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\n\n\n[q]\"Ein voll gepanzerter Tauralus kann unglaubliche Mengen an Schaden einstecken, bevor er zu Boden geht. Das macht ihn in jeder Schlacht zu einem wertvollen Verbündeten.\"\nPakt:\nNekrolords\nVerkäufer:\nSu Zettai\nZone:\nMaldraxxus\nKosten:\n3000"}
MultiLanguageItemData['de'][181822] = {name = "[q4]Gepanzerter kriegsgezüchteter Tauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Den Tauralussen, die den Armeen von Maldraxxus dienen, wurde jegliches Mitgefühl durch Züchtung ausgetrieben. Sie sind nur mit Rüstungen geschmückt, um zu demonstrieren, dass kein Schwert und kein Zauber sie daran hindern kann, ihre Reiter zum Sieg zu tragen.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
