MultiLanguageItemData['de'][182074] = {name = "[q4]Auserwählter Tauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Selbst ein ungepanzerter Tauralus ist im Kampf ein wertvoller Verbündeter, denn seine gewaltigen Hörner können sogar eine Plattenrüstung durchbohren.\"\nErfolg:\nMonströse Montage\nKategorie:\nPaktsankten"}
MultiLanguageItemData['de'][182075] = {name = "[q4]Knochenhuftauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Es gibt viele gute Gründe, warum man nicht hinter einem Tauralus stehen sollte. Ihre Hufe und peitschenartigen Schweife gehören dabei noch zu den kleineren Übeln.\"\nBeute von:\nTahonta\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182076] = {name = "[q4]Seuchenfäulnistauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 23\n\n\n[q]\"Die Tauralus gelten gemeinhin als mutige Wesen, doch die Gelehrten von Maldraxxus fragen sich schon länger, ob ihre Furchtlosigkeit nur ein Nebenprodukt ihrer winzigen Gehirne sein könnte.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182077] = {name = "[q4]Kriegsgezüchteter Tauralus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die Soldaten von Maldraxxus beschützen die Schattenlande und sind auf fähige Reittiere angewiesen, die selbst in scheinbar aussichtslosen Situationen die Ruhe bewahren.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182078] = {name = "[q4]Knochenvernähter Fleischroc", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur erfahrene Fleischnäher, die ihre meisterhafte Beherrschung der Magien von Maldraxxus unter Beweis gestellt haben, sind mächtig genug, einen Todesroc dieser Größe zu erschaffen.\"\nBeruf:\nMonstrositätenflickerei\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182079] = {name = "[q4]Schleimbedeckte Zügel des bulligen Todesrocs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen bulligen Todesroc beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Todesrocs sind Monstrositäten, zusammengeflickt aus Eingeweiden, Knochen und Organen, die nicht zum Bau von Soldaten im Haus der Konstrukte gebraucht wurden.\"\nBeute von:\nVioletter Fehler\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182080] = {name = "[q4]Räuberischer Seuchenroc", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Giegers unstillbarer Hunger ist im Haus der Konstrukte legendär, und kein Tier ist zu groß oder zu knochig, um in seinen riesigen Magen zu passen.\"\nBeute von:\nGieger\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182081] = {name = "[q4]Zügel der riesigen Massakerklaue", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man eine riesige Massakerklaue beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur die standhaftesten Stallmeister von Maldraxxus sind in der Lage, die riesigen Massakerklauen zu unterwerfen, und so allen Champions der Unvergänglichen Armee einen furchterregenden Verbündeten in den Schattenlanden zur Seite zu stellen.\"\nBeute von:\nVorräte der Unvergänglichen Armee\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182082] = {name = "[q4]Blutrünstiger Bluthauer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtDie Unvergängliche Armee\n- Ehrfürchtig\n\n\n[q]\"Nur Bluthauer, die den Wettstreit der Eroberung überleben, gelten als würdig, als Reittier der Unvergängliche Armee zu dienen.\"\nVerkäufer:\nNalcorn Talsen\nZone:\nMaldraxxus\nFraktion:\nDie Unvergängliche Armee - Ehrfürchtig\nKosten:"}
MultiLanguageItemData['de'][182083] = {name = "[q4]Schädeleber des Knochenspalters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Sabriel war für die ruchlose Effizienz bekannt, mit der sie ihre Gegner zerlegte, um deren Knochen an ihren loyalen Schädeleber zu verfüttern.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000"}
MultiLanguageItemData['de'][182084] = {name = "[q4]Blutstachel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nerissa ist mit Blutstachel über unzählige Leichen gegangen, um zur Kommandantin der lichverschworenen Streitkräfte im Haus der Rituale aufzusteigen.\"\nBeute:\nNerissa Herzlos\nZone:\nMaldraxxus"}
MultiLanguageItemData['de'][182085] = {name = "[q4]Pustelrückenbluthauer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das Haus der Auserwählten trainiert seine Reittiere unter verschiedensten widrigen Umständen, damit sie nie wanken, ganz gleich, in welcher Schlacht sie benötigt werden.\"\nBeute:\nKriegshetzer Mal'korak\nZone:\nMaldraxxus"}
