MultiLanguageItemData['de'][182625] = {name = "[q5]Erinnerung an den Griff des Ewigwährenden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nGriff des Ewigwährenden Runenschnitzmacht\nDie Abklingzeit von 'Todesgriff' ist um 3 Sek. verringert und innerhalb von 3 Sek. nach dem Einsatz von 'Todesgriff' könnt Ihr die Fähigkeit ein zweites Mal einsetzen, ohne dass die Abklingzeit eine Rolle spielt.\nRunenschnitzen: Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Todesritter"}
MultiLanguageItemData['de'][182626] = {name = "[q5]Erinnerung an die phobischen Pheromone", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nPhobische Pheromone Runenschnitzmacht\n{Euer {Tempo und das Eurer Diener wird um [ Blut : 10% /\n\nFrost, Unheilig\n15% ] erhöht, solange Ihr Euch innerhalb Eures Effekts 'Tod und Verfall' aufhaltet. Bei Gegnern, die durch den Effekt Schaden} erleiden, besteht eine Chance, dass sie 3 Sek. lang vor Angst erstarren.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Todesritter}"}
MultiLanguageItemData['de'][182627] = {name = "[q5]Erinnerung an einen Supervirus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSupervirus Runenschnitzmacht\nFrostfieber, Blutseuche und Virulente Seuche lösen jeweils auch die anderen beiden Krankheiten mit verringerter Effektivität aus.\nRunenschnitzen: Hals, Brust\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Todesritter"}
MultiLanguageItemData['de'][182628] = {name = "[q5]Erinnerung an Bryndaor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBryndaors Macht Runenschnitzmacht\nWenn Ihr durch 'Todesstoß' um mehr als 10% Eurer maximalen Gesundheit geheilt werdet, erhaltet Ihr 15% der verbrauchten Runenmacht zurück.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Todesritter (Blut)"}
MultiLanguageItemData['de'][182629] = {name = "[q5]Erinnerung an die blutroten Runen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBlutrote Runenwaffe Runenschnitzmacht\n'Tanzende Runenwaffe' erzeugt 5 Aufladungen von 'Knochenschild'. Wenn eine Aufladung von 'Knochenschild' aufgezehrt wird, wird die Abklingzeit von 'Tanzende Runenwaffe' um 5 Sek. verringert. Zusätzlich wird Eure Runenregenerationsrate 10 Sek. lang um 40% erhöht, wenn 'Tanzende Runenwaffe' schwindet.\nRunenschnitzen: Schulter, Taille, Hände\nQuelle: Dungeonbeute: Halkias, der Sündenbefleckte Goliath\nBenötigt: Todesritter (Blut)"}
MultiLanguageItemData['de'][182630] = {name = "[q5]Erinnerung an Blutschattens Herrschaft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBlutschattens Herrschaft Runenschnitzmacht\n'Vampirblut' erzeugt 45 Runenmacht. Zusätzlich verringert 'Herzstoß' die verbleibende Abklingzeit von 'Vampirblut' um 2 Sek.\nRunenschnitzen: Beine, Füße\nQuelle: Schlachtzugbeute: Hungernder Zerstörer\nBenötigt: Todesritter (Blut)"}
MultiLanguageItemData['de'][182631] = {name = "[q5]Erinnerung an eine Vampiraura", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVampiraura Runenschnitzmacht\n'Vampirblut' gewährt Euch 5% Lebensraub und die Dauer ist um 3 Sek. erhöht. Zusätzlich gewährt Euer 'Vampirblut' allen Gruppenmitgliedern 50% der Boni des Effekts.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Todesritter (Blut)"}
MultiLanguageItemData['de'][182632] = {name = "[q5]Erinnerung an den absoluten Nullpunkt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nAbsoluter Nullpunkt Runenschnitzmacht\nVerringert die Abklingzeit von 'Furor des Frostwyrms' um 50% und friert alle getroffenen Gegner 3 Sek. lang an Ort und Stelle fest.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Todesritter (Frost)"}
MultiLanguageItemData['de'][182633] = {name = "[q5]Erinnerung an die beißende Kälte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBeißende Kälte Runenschnitzmacht\nErhöht den Schaden von 'Unbarmherziger Winter' um 30%. Wenn 'Unbarmherziger Winter' zum ersten Mal 3 verschiedenen Gegnern Schaden zufügt, erhaltet Ihr 'Raureif'.\nRunenschnitzen: Kopf, Taille\nQuelle: Dungeonbeute: Nalthor der Eisbinder\nBenötigt: Todesritter (Frost)"}
MultiLanguageItemData['de'][182634] = {name = "[q5]Erinnerung an die Wut eines eisigen Champions", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nWut des eisigen Champions Runenschnitzmacht\n'Auslöschen' hat eine um 15% erhöhte Chance, 'Raureif' auszulösen, und 'Heulende Böe' erzeugt 12 Runenmacht, während 'Raureif' aktiv ist.\nRunenschnitzen: Handgelenk, Hände, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Todesritter (Frost)"}
MultiLanguageItemData['de'][182635] = {name = "[q5]Erinnerung an Koltira", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKoltiras Gunst Runenschnitzmacht\n'Auslöschen' verursacht 10% mehr Schaden und hat eine Chance von 12%, 2 Runen zurückzuerstatten. (Procchance: 12%, 700ms Abklingzeit)\nRunenschnitzen: Schulter, Finger\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Todesritter (Frost)"}
MultiLanguageItemData['de'][182636] = {name = "[q5]Erinnerung an den Mantel des sicheren Todes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nMantel des sicheren Todes Runenschnitzmacht\nVerringert die Runenmachtkosten von 'Todesmantel' um 10 und 'Todesmantel' erhöht die Dauer von 'Dunkle Transformation' um 1 Sek.\nRunenschnitzen: Brust, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Todesritter (Unheilig)"}
MultiLanguageItemData['de'][182637] = {name = "[q5]Erinnerung an die Gewissheit des Todes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGewissheit des Todes Runenschnitzmacht\n'Todesstoß' und 'Todesmantel' verursachen 35% mehr Schaden und verringern die verbleibende Abklingzeit von [ Entweihen : 'Entweihen' ] 'Tod und Verfall' um 2.0 Sek.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Todesritter (Unheilig)"}
MultiLanguageItemData['de'][182638] = {name = "[q5]Erinnerung an ein rasendes Monstrum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRasendes Monstrum Runenschnitzmacht\n'Dunkle Transformation' erhöht zusätzlich das Angriffstempo und den Schaden von Euch und Eurer Monstrosität um 12%.\nRunenschnitzen: Beine, Rücken\nQuelle: Weltbossbeute: Nurgash Schlammborn\nBenötigt: Todesritter (Unheilig)"}
