MultiLanguageItemData['de'][182660] = {name = "[q2]Rezept: Schattenstein", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Transmutation eines Schattensteins.\nBenötigtAlchemie der Schattenlande\n(170)\nErfordert einen wohlwollenden Ruf bei den Eingeschworenen.\nVerkaufspreis:\n[q2]Schattenstein\nHandwerksmaterial\n[q]\"Wird von Spielercharakteren erstellt, die den Beruf Alchemie ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis: \nBenötigt Gemahlene Todesblüte (5), Gemahlene Wachtfackel (2), Gemahlene Witwenblüte (2), Gemahlene Markwurzel (2), Gemahlener Ruhmesstieg (2)"}
MultiLanguageItemData['de'][182661] = {name = "[q2]Pilz-Li", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigtMarasmius\n- Freundlich"}
MultiLanguageItemData['de'][182662] = {name = "[q2]Blattschwärmer", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nNehmt an drei verschiedenen Auftritten im Sternseeamphitheater teil und seid Mitglied des Pakts der Nachtfae."}
MultiLanguageItemData['de'][182663] = {name = "[q3]Wurzli", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ruhmstufe 27"}
MultiLanguageItemData['de'][182664] = {name = "[q2]Stieling", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigtHof der Nacht\n- Freundlich\nIhr müsst Mitglied des Pakts der Nachtfae sein."}
MultiLanguageItemData['de'][182665] = {name = "Rezept: Sünden zu Tugend", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Transmutation von Sünden zu Tugend.\nBenötigtAlchemie der Schattenlande\n(150)\nVerkaufspreis:\nSchattenhafte Tasche voller Erz\nWird beim Aufheben gebunden\n[q]\"Eine Tasche voller Erz aus den Schattenlanden.\"\n[q2]<Zum Öffnen rechtsklicken>\nBenötigt Poröser Stein (4), Verdunkelter Stein (2)"}
MultiLanguageItemData['de'][182666] = {name = "[q3]Formel: Verzauberter Elethiumbarren", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen verzauberten Elethiumbarren herstellt.\nBenötigt Verzauberkunst der Schattenlande (115)\nVerkaufspreis:\n[q2]Verzauberter Elethiumbarren\nHandwerksmaterial\n\"Wird von Spielercharakteren hergestellt, die den Beruf Verzauberkunst ausüben.\"\nVerkaufspreis: \nBenötigt Seelenstaub , Elethiumerz (2)"}
