MultiLanguageItemData['de'][183210] = {name = "[q5]Erinnerung an ein Teufelsbombardement", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTeufelsbombardement Runenschnitzmacht\nDer Schaden von 'Feuerbrandaura' hat eine Chance, Euch einen Stapel von 'Teufelsbombardement' zu gewähren, was den Schaden Eures nächsten Einsatzes von 'Gleve werfen' bei Eurem Primärziel um 50% erhöht und dabei eine zusätzliche Gleve auf ein Ziel in der Nähe verschießt. Dieser Effekt ist bis zu 5-mal stapelbar.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][183211] = {name = "[q5]Erinnerung an die dunkelste Stunde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nDunkelste Stunde Runenschnitzmacht\nWenn Ihr unter 35% Gesundheit fallt, löst Ihr automatisch 'Dunkelheit' aus. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\nRunenschnitzen: Brust, Beine\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][183212] = {name = "[q5]Erinnerung an ein Dunkelblickmedaillon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDunkelblicksegen Runenschnitzmacht\nVerwüstung\n 'Augenstrahl' hat eine Chance von 40%, keine Abklingzeit auszulösen und 30 Jähzorn zu erstatten.\n\nRachsucht\n 'Dämonische Verwüstung' hat eine Chance von 40%, keine Abklingzeit auszulösen und 50 Jähzorn zu erstatten.\nRunenschnitzen: Hals, Taille\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][183213] = {name = "[q5]Erinnerung an die kollektive Qual", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKollektive Qual Runenschnitzmacht\nVerwüstung\n Beim Einsatz von 'Augenstrahl' wird ein verbündeter Rachsuchtdämonenjäger herbeigerufen, der 'Dämonische Verwüstung' einsetzt.\n\nRachsucht\n Beim Einsatz von 'Dämonische Verwüstung' wird ein verbündeter Verwüstungsdämonenjäger herbeigerufen, der 'Augenstrahl' einsetzt.\nRunenschnitzen: Handgelenk, Rücken\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][183214] = {name = "[q5]Erinnerung an die Chaostheorie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nChaostheorie Runenschnitzmacht\n'Klingentanz' hat eine Chance von 30%, Euch 'Chaotische Klingen' zu gewähren, was für 8 Sek. den Schaden von 'Chaosstoß' um 50% und die Chance der Fähigkeit, Jähzorn zurückzuerstatten, um zusätzlich 60% erhöht. (500ms Abklingzeit)\nRunenschnitzen: Taille, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Dämonenjäger (Verwüstung)"}
MultiLanguageItemData['de'][183215] = {name = "[q5]Erinnerung an einen unbeständigen Teufelskern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUnbeständiger Teufelskern Runenschnitzmacht\nVerringert die Abklingzeit von 'Teufelsrausch' um 30%.\nRunenschnitzen: Füße, Finger\nQuelle: Weltbossbeute: Nurgash Schlammborn\nBenötigt: Dämonenjäger (Verwüstung)"}
MultiLanguageItemData['de'][183216] = {name = "[q5]Erinnerung an eine Brennende Wunde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBrennende Wunde Runenschnitzmacht Nahkampfreichweite\n'Dämonenbiss' hinterlässt eine offene Wunde bei Eurem Gegner, die ihm im Verlauf von 15 Sek. (100% der Angriffskraft) Chaosschaden zufügt und seinen durch Eure 'Feuerbrandaura' erlittenen Schaden um 65% erhöht.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Die Manasturms\nBenötigt: Dämonenjäger (Verwüstung)"}
MultiLanguageItemData['de'][183217] = {name = "[q5]Erinnerung an meine Dunklere Natur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDunklere Natur Runenschnitzmacht\nGegner, die innerhalb von 4 Sek. sterben, nachdem sie Schaden von 'Augenstrahl' erlitten haben, haben eine Chance von 25%, dass ihre Seelenfragmente in Dämonenseelenfragmente umgewandelt werden.\nRunenschnitzen: Schulter, Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Dämonenjäger (Verwüstung)"}
MultiLanguageItemData['de'][183218] = {name = "[q5]Erinnerung an eine verstärkte Teufelsflamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTeufelsflammenverstärkung Runenschnitzmacht\nIhr erleidet 15% weniger Magieschaden, solange 'Feuerbrandaura' aktiv ist.\nRunenschnitzen: Taille, Finger\nQuelle: Schlachtzugbeute: Lady Inerva Dunkelader\nBenötigt: Dämonenjäger (Rachsucht)"}
MultiLanguageItemData['de'][183219] = {name = "[q5]Erinnerung an eine feurige Seele", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nFeurige Seele Runenschnitzmacht\nJedes durch 'Seelenspalter' verschlungene Seelenfragment verringert die Abklingzeit von 'Flammendes Brandmal' um 2 Sek.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Dämonenjäger (Rachsucht)"}
MultiLanguageItemData['de'][183220] = {name = "[q5]Erinnerung an Razelikhs Entweihung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRazelikhs Entweihung Runenschnitzmacht\n'Seelenspalter' verringert die Abklingzeit eines zufälligen Zeichens um 8 Sek. (500ms Abklingzeit)\nRunenschnitzen: Beine, Handgelenk\nQuelle: Dungeonbeute: Xav der Unbesiegte\nBenötigt: Dämonenjäger (Rachsucht)"}
MultiLanguageItemData['de'][183221] = {name = "[q5]Erinnerung an den Geist der Finsterflamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGeist der Finsterflamme Runenschnitzmacht\nEuer 'Flammendes Brandmal' heilt Euch jetzt im Verlauf von 8 Sek. um 100% des verursachten Initialschadens und jeder von Eurem 'Zeichen der Flamme' getroffene Gegner erhöht den sofortigen Schaden Eures nächsten Einsatzes von 'Flammendes Brandmal' um 15%. Bis zu 15-mal stapelbar.\nRunenschnitzen: Kopf, Hals\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Dämonenjäger (Rachsucht)"}
MultiLanguageItemData['de'][183222] = {name = "[q5]Erinnerung an den Druidenältesten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nEid des Druidenältesten Runenschnitzmacht\nErhöht die Effekte von 'Dickes Fell', 'Astraler Einfluss', 'Schnelligkeit der Wildnis' und 'Yseras Gabe' um 75%.\n\n Wenn Ihr in die zu Eurer Affinität gehörende Gestalt wechselt, erhaltet Ihr für 10 Sek. 'Herz der Wildnis'. Kann einmal alle 1 Min. auftreten.\nRunenschnitzen: Schulter, Handgelenk\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Druide"}
MultiLanguageItemData['de'][183223] = {name = "[q5]Erinnerung an den Kreislauf aus Leben und Tod", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKreislauf aus Leben und Tod Runenschnitzmacht\nEure regelmäßigen Schadenseffekte verursachen ihren Schaden in 25% kürzerer Zeit und Eure regelmäßigen Heileffekte ihre Heilung in 15% kürzerer Zeit.\nRunenschnitzen: Kopf, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Druide"}
MultiLanguageItemData['de'][183224] = {name = "[q5]Erinnerung an einen Trunk der tiefen Konzentration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTrunk der tiefen Konzentration Runenschnitzmacht\nWenn 'Mondfeuer', 'Krallenhieb', 'Zerfetzen' oder 'Verjüngung' auf einem einzelnen Ziel aktiv ist, wird der jeweilige Effekt um 40% erhöht.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Druide"}
MultiLanguageItemData['de'][183225] = {name = "[q5]Erinnerung an Lycara", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nLycaras flüchtiger Blick Runenschnitzmacht\nSetzt im Kampf alle 45 Sek. einen Zauber ein, der von Eurer Gestalt abhängt:\n\n Keine Gestalt: Wildwuchs\n Katzengestalt: Urzorn\n Bärengestalt: Baumrinde\n Mondkingestalt: Sternenregen\n Reisegestalt: Anstachelndes Gebrüll\nRunenschnitzen: Taille, Füße\nQuelle: Dungeonbeute: Mordretha, die Unendliche Kaiserin\nBenötigt: Druide"}
MultiLanguageItemData['de'][183226] = {name = "[q5]Erinnerung an das Gleichgewicht aller Dinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGleichgewicht aller Dinge Runenschnitzmacht\nWenn 'Finsternis' aktiv wird, wird Eure kritische Trefferchance mit Arkan- oder Naturzaubern um 24% erhöht. Dieser Effekt nimmt alle 1 Sek. um 3% ab.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Druide (Gleichgewicht)"}
MultiLanguageItemData['de'][183227] = {name = "[q5]Erinnerung an Oneth", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nOneths klare Vision Runenschnitzmacht\n'Sternensog' hat eine Chance von 20%, 'Sternenregen' kostenlos werden zu lassen. 'Sternenregen' hat eine Chance von 40%, 'Sternensog' kostenlos werden zu lassen.\nRunenschnitzen: Füße, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Druide (Gleichgewicht)"}
MultiLanguageItemData['de'][183228] = {name = "[q5]Erinnerung an Arkanpulsare", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUrzeitlicher Arkanpulsar Runenschnitzmacht\nPro 300 verbrauchter Astraler Macht erhaltet Ihr für 12 Sek. 'Himmlische Ausrichtung'.\nRunenschnitzen: Schulter, Hände, Finger\nQuelle: Beute von: Der Schlund, Zorn des Kerkermeisters\nBenötigt: Druide (Gleichgewicht)"}
MultiLanguageItemData['de'][183229] = {name = "[q5]Erinnerung an einen verwitterten Traumbinder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVerwitterter Traumbinder Runenschnitzmacht\n'Sternensog' und 'Sternenregen' verringern die Kosten von 'Sternensog' und 'Sternenregen' für 5 Sek. um 10% und erhöhen den Schaden um 10%. Bis zu 2-mal stapelbar.\nRunenschnitzen: Brust, Finger\nQuelle: Dungeonbeute: Tred'ova\nBenötigt: Druide (Gleichgewicht)"}
MultiLanguageItemData['de'][183230] = {name = "[q5]Erinnerung an das Eliteraubtier", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGelüst des Eliteraubtiers Runenschnitzmacht\nDer Schaden von 'Zerfetzen' hat eine Chance von 4%, dass Euer nächster Einsatz von 'Wilder Biss' kostenlos wird und den maximalen Schaden verursacht.\nRunenschnitzen: Schulter, Taille\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Druide (Wildheit)"}
MultiLanguageItemData['de'][183231] = {name = "[q5]Erinnerung an eine Katzenaugenkuriosität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKatzenaugenkuriosität Runenschnitzmacht\nWährend des Freizauberzustands eingesetzte Fähigkeiten erzeugen 30% ihrer Energiekosten und Eure maximale Energie ist um 60 erhöht.\nRunenschnitzen: Hals, Finger\nQuelle: Dungeonbeute: Kin-Tara\nBenötigt: Druide (Wildheit)"}
MultiLanguageItemData['de'][183232] = {name = "[q5]Erinnerung an ein symmetrisches Auge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nAuge der furchteinflößenden Symmetrie Runenschnitzmacht\n'Tigerfuror' lässt Eure nächsten 2 Finishing-Moves 2 Combopunkte wiederherstellen.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Druide (Wildheit)"}
MultiLanguageItemData['de'][183233] = {name = "[q5]Erinnerung an das Band der Raserei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBand der Raserei Runenschnitzmacht 100 Meter Reichweite\nFähigkeiten, die Combopunkte erzeugen, verringern die Abklingzeit von [ Inkarnation: Avatar von Ashamane : 'Inkarnation: König des Dschungels' um 0.3 / 'Berserker' um 0.3] Sek.\n\n Während [ Inkarnation: Avatar von Ashamane : 'Inkarnation: König des Dschungels' / 'Berserker'] aktiv ist, fügen sie dem Ziel zusätzlich 150% ihres Schadens im Verlauf von 8 Sek. als Blutungsschaden zu.\nRunenschnitzen: Taille, Handgelenk\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Druide (Wildheit)"}
MultiLanguageItemData['de'][183234] = {name = "[q5]Erinnerung an eine luffaversetzte Umarmung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nLuffaversetzte Umarmung Runenschnitzmacht\nErhöht den Schaden von 'Hauen' um 20% und die Reichweite der Fähigkeit um 30%. Der Effekt ist bis zu 1-mal zusätzlich stapelbar.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kryxis der Gefräßige\nBenötigt: Druide (Wächter)"}
MultiLanguageItemData['de'][183235] = {name = "[q5]Erinnerung an die natürliche Ordnung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nWille der natürlichen Ordnung Runenschnitzmacht\n'Baumrinde' verringert den Schaden um zusätzlich 10%. Wenn Ihr Euch in Bärengestalt befindet, wenn der Effekt beginnt oder endet, erhaltet Ihr 'Eisenfell' und 'Rasende Regeneration'.\nRunenschnitzen: Kopf, Handgelenk, Hände\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Druide (Wächter)"}
MultiLanguageItemData['de'][183236] = {name = "[q5]Erinnerung an Ursoc", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nAndenken an Ursocs Wut Runenschnitzmacht\nIn Bärengestalt hat 'Hauen' eine Chance von 15%, dass 'Hauen' erneut ausgelöst wird.\n\n 'Hauen' gewährt Euch einen Absorptionsschild in Höhe von 75% des verursachten Schadens.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Druide (Wächter)"}
MultiLanguageItemData['de'][183237] = {name = "[q5]Erinnerung an den Schläfer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVermächtnis des Schläfers Runenschnitzmacht\n[ Inkarnation: Wächter von Ursoc : 'Inkarnation: Wächter von Ursoc' erhöht / In Bärengestalt erhöht 'Berserker'] Euren Schaden um 0%, Euren Lebensraub um 25% und macht Euch immun gegen Kontrollverlusteffekte.\n\n Die Abklingzeit der Fähigkeit ist um 30 Sek. verringert.\nRunenschnitzen: Taille, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Druide (Wächter)"}
MultiLanguageItemData['de'][183238] = {name = "[q5]Erinnerung an die üppige Infusion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nÜppige Infusion Runenschnitzmacht\n'Rasche Heilung' verbraucht keinen regelmäßigen Heilungseffekt mehr und verlängert die Dauer Eurer aktiven regelmäßigen Heilungseffekte auf dem Ziel um 10 Sek.\nRunenschnitzen: Schulter, Hände, Rücken\nQuelle: Weltbossbeute: Oranomonos die Immersprießende\nBenötigt: Druide (Wiederherstellung)"}
MultiLanguageItemData['de'][183239] = {name = "[q5]Erinnerung an ein unendliches Wachstum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVision des unendlichen Wachstums Runenschnitzmacht\nHeilung von 'Verjüngung' hat eine Chance von 2.5%, dass ein weiteres Ziel in der Nähe mit 'Verjüngung' belegt wird. (Procchance: 3%)\nRunenschnitzen: Kopf, Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Druide (Wiederherstellung)"}
MultiLanguageItemData['de'][183240] = {name = "[q5]Erinnerung an den Mutterbaum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nErinnerung an den Mutterbaum Runenschnitzmacht\n'Wildwuchs' hat eine Chance von 40%, dass Euer nächster Einsatz von 'Verjüngung' oder 'Nachwachsen' sich auf 3 zusätzliche Verbündete innerhalb von 20 Metern um das Ziel auswirkt. (Procchance: 40%)\nRunenschnitzen: Beine, Handgelenk\nQuelle: Schlachtzugbeute: Lady Inerva Dunkelader\nBenötigt: Druide (Wiederherstellung)"}
MultiLanguageItemData['de'][183241] = {name = "[q5]Erinnerung an den Dunklen Titanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDie Lektion des Dunklen Titanen Runenschnitzmacht\n'Blühendes Leben' kann auf zwei Zielen gleichzeitig aktiv sein, aber die Heilung von 'Blühendes Leben' ist um 10% verringert.\nRunenschnitzen: Hals, Rücken\nQuelle: Dungeonbeute: Der Oberste Kämmerer\nBenötigt: Druide (Wiederherstellung)"}
MultiLanguageItemData['de'][183242] = {name = "[q5]Erinnerung an Eonar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf bei der Wilden Jagd und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\n\nEcho von Eonar Runenschnitzmacht Ca. 1 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine geringe Chance, einen Geisterfamiliar an Eure Seite zu beschwören, der für 10 Sek. abhängig von Eurer Rolle Euren Schaden um 10%, Eure Heilung um 10% oder Eure Schadensreduktion um 10% erhöht. 50% dieses Effekts werden auf bis zu 3 Verbündete dupliziert. Dabei werden Verbündete mit derselben Rolle bevorzugt.\nRunenschnitzen: Taille, Handgelenk, Finger\nQuelle: Ihr benötigt einen respektvollen Ruf bei der Wilden Jagd und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183243] = {name = "[q5]Erinnerung an das Urteil der Richterin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf bei den Aufgestiegenen und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\n\nUrteilsspruch der Richterin Stufe 80 Runenschnitzmacht Ca. 6 Procs pro Minute\nBeim Verursachen von Schaden besteht eine hohe Chance, dass eine Explosion spiritueller Energie freigesetzt wird, die 2003 Schattenschaden verursacht. Wenn sich ein weiterer mit 'Urteilsspruch der Richterin' belegter Verbündeter innerhalb von 5 bis 20 Metern von Euch befindet, springt die Explosion auch auf diesen über und fügt dabei Gegnern in ihrer Bahn 2003 Schattenschaden zu.\nRunenschnitzen: Handgelenk, Hände, Finger\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Aufgestiegenen und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183244] = {name = "[q5]Erinnerung an das Schlundröcheln", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf bei der Unvergänglichen Armee und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\n\nSchlundröcheln Stufe 80 Runenschnitzmacht Ca. 6 Procs pro Minute\nBeim Töten eines Gegners besteht eine hohe Chance, eine explosive Schlundratte an der Position der Leiche zu beschwören. Nach 6 Sek. explodiert die Schlundratte, fügt allen Gegnern in der Nähe 31747 Naturschaden zu, vergiftet sie und verringert ihren verursachten Schaden 10 Sek. lang um 5%.\nRunenschnitzen: Beine, Füße, Hände\nQuelle: Ihr benötigt einen respektvollen Ruf bei der Unvergänglichen Armee und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183245] = {name = "[q5]Erinnerung an Norgannon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf beim Hof der Ernter und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\n\nNorgannons Klugheit Runenschnitzmacht\nDer Einsatz eines Zaubers gewährt 'Klugheit'. Bis zu 10-mal stapelbar. Wenn Ihr Euch bewegt, könnt Ihr pro Stapel von 'Klugheit' 0.5 Sek. lang Zauber aus der Bewegung wirken. (100ms Abklingzeit)\nRunenschnitzen: Beine, Füße, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf beim Hof der Ernter und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183246] = {name = "[q5]Erinnerung an Sephuz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nSephuz' Proklamation Stufe 80 Runenschnitzmacht\nVerringert die Effektivität von Kontrollverlusteffekten um 10%. Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, werden alle Eure Sekundärwerte für 15 Sek. um 217 erhöht. Dieser Effekt kann nur einmal alle 30 Sek. auftreten. (30s Abklingzeit)\nRunenschnitzen: Hals, Schulter, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183247] = {name = "[q5]Erinnerung an einen stabilen Phantasmaköder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nStabiler Phantasmaköder Runenschnitzmacht Ca. 4 Procs pro Minute\nErhöht das verdiente Phantasma um 25%. Beim Erbeuten von Phantasma von Gegnern besteht eine Chance, einen Phantasmadämon zu beschwören, der in eine zufällige Richtung läuft. Ihn zu töten, erhöht das verdiente Phantasma für die ganze Gruppe 1 Min. lang um zusätzlich 10%.\nRunenschnitzen: Hals, Handgelenk, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten, Ebene 6+"}
MultiLanguageItemData['de'][183248] = {name = "[q5]Erinnerung an das Auge des Kerkermeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen zwiespältigen Ruf bei Ve'nari und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\n\nDrittes Auge des Kerkermeisters Runenschnitzmacht\nWenn Ihr einen Gegner tötet, erhaltet Ihr 'Drittes Auge', was Eure Hauptwert für 10 Sek. um 1% erhöht. Bis zu 7-mal stapelbar. Jeder zusätzliche Stapel erhöht die Dauer um 1 Sek. Im Schlund ist die Dauer von 'Drittes Auge' um 50% erhöht.\nRunenschnitzen: Kopf, Hals, Schulter, Taille\nQuelle: Ihr benötigt einen zwiespältigen Ruf bei Ve'nari und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183249] = {name = "[q5]Erinnerung an ein Vitalitätsopfer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nBenötigt Ruhmstufe 14\n\n\nVitalitätsopfer Runenschnitzmacht\nBeträchtlichen Schaden durch einen Spielercharakter oder Elitegegner zu erleiden, erhöht Euren Schaden und Eure Heilung für 20 Sek. um 3% des erlittenen Schadens, bis zu maximal 9%.\n\n Dieser Effekt kann nur einmal alle 30 Sek. ausgelöst werden. (30s Abklingzeit)\nRunenschnitzen: Kopf, Schulter, Brust, Finger\nQuelle: Gegen Anima vom Ruhmrüstmeister erhältlich. Ihr müsst Ruhmstufe 14 bei Eurem Pakt erreicht haben, um diese Erinnerung kaufen zu können."}
MultiLanguageItemData['de'][183250] = {name = "[q5]Erinnerung an den wilden Ruf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRuf der Wildnis Runenschnitzmacht\nVerringert die Abklingzeit aller Eurer Aspekte [ Treffsicherheit : und von 'Volltreffer' / Überleben : und von 'Koordinierter Angriff' ] um 35%.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Jäger"}
MultiLanguageItemData['de'][183251] = {name = "[q5]Erinnerung an ein feiges Strategem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nFeiges Strategem Runenschnitzmacht Sofort\nVerringert die Abklingzeit von 'Totstellen' um 15.0 Sek. und 'Totstellen' entfernt die meisten negativen Statuseffekte von Euch.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Jäger"}
MultiLanguageItemData['de'][183252] = {name = "[q5]Erinnerung an einen Fallenapparat", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nNesingwarys Fallenapparat Runenschnitzmacht\nWenn eine Falle ausgelöst wird, erzeugt Ihr 45 Fokus und Eure Fokuserzeugung wird für 5 Sek. um 100% erhöht.\nRunenschnitzen: Hals, Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Jäger"}
MultiLanguageItemData['de'][183253] = {name = "[q5]Erinnerung an die Seelenschmiedeglut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSeelenschmiedeglut Runenschnitzmacht\nWenn Ihr ein Leuchtfeuer in Eure Teerfalle schießt, gehen bis zu 5 Gegner in der Teerfalle in Flammen auf und erleiden im Verlauf von 12 Sek. (240% der Angriffskraft) Feuerschaden.\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Dungeonbeute: Ingra Maloch\nBenötigt: Jäger"}
MultiLanguageItemData['de'][183254] = {name = "[q5]Erinnerung an einen Alphabefehl", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nAlphabefehl Runenschnitzmacht\n'Tötungsbefehl' hat eine Chance von 30%, zusätzlich ein Alphatier zu beschwören, das Euer Ziel angreift.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Jäger (Tierherrschaft)"}
MultiLanguageItemData['de'][183255] = {name = "[q5]Erinnerung an den Flammenschürer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKobrastich des Flammenschürers Runenschnitzmacht\n'Kobraschuss' hat eine Chance von 50%, dass Euer nächster Einsatz von 'Tötungsbefehl' keinen Fokus kostet. (Procchance: 50%)\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Jäger (Tierherrschaft)"}
MultiLanguageItemData['de'][183256] = {name = "[q5]Erinnerung an den Kriegsbefehl der Eredar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nQa'pla, Kriegsbefehl der Eredar Runenschnitzmacht\n'Stachelpfeil' verursacht 10% mehr Schaden und bei der Anwendung von 'Stachelpfeil' wird die Abklingzeit von 'Tötungsbefehl' abgeschlossen.\nRunenschnitzen: Schulter, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Jäger (Tierherrschaft)"}
MultiLanguageItemData['de'][183257] = {name = "[q5]Erinnerung an die Fänge des Rylakjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDurchbohrende Fänge des Rylakjägers Runenschnitzmacht\nWährend 'Zorn des Wildtiers' aktiv ist, wird der verursachte kritische Schaden Eures Begleiters um 35% erhöht.\nRunenschnitzen: Beine, Füße, Rücken\nQuelle: Dungeonbeute: Devos, Paragon des Zweifels\nBenötigt: Jäger (Tierherrschaft)"}
MultiLanguageItemData['de'][183258] = {name = "[q5]Erinnerung an die Zielsicherheit der Adlerkralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nZielsicherheit der Adlerkralle Runenschnitzmacht\n'Volltreffer' hält 3.0 Sek. länger an und verringert die Fokuskosten all Eurer Fähigkeiten um 25%.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Jäger (Treffsicherheit)"}
MultiLanguageItemData['de'][183259] = {name = "[q5]Erinnerung an die unablässige Wacht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGeheimnisse der unablässigen Wacht Runenschnitzmacht\nWenn Ihr den Effekt 'Gekonnte Schüsse' erhaltet, besteht eine Chance von 50%, dass eine Aufladung von 'Gezielter Schuss' erstattet wird und Euer nächster Einsatz von 'Gezielter Schuss' keinen Fokus verbraucht.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Jäger (Treffsicherheit)"}
MultiLanguageItemData['de'][183260] = {name = "[q5]Erinnerung an die Täuschung des Schlangenpirschers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTäuschung des Schlangenpirschers Runenschnitzmacht\n'Gezielter Schuss' verschießt zusätzlich 'Schlangengift' auf das Primärziel.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Domina Giftklinge\nBenötigt: Jäger (Treffsicherheit)"}
MultiLanguageItemData['de'][183261] = {name = "[q5]Erinnerung an schnellende Schüsse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSchnellende Schüsse Runenschnitzmacht\n'Schnellfeuer' verursacht 35% mehr Schaden und 'Gezielter Schuss' hat eine Chance von 15%, die Abklingzeit von 'Schnellfeuer' abzuschließen. (Procchance: 15%)\nRunenschnitzen: Hals, Handgelenk\nQuelle: Weltbossbeute: Oranomonos die Immersprießende\nBenötigt: Jäger (Treffsicherheit)"}
MultiLanguageItemData['de'][183262] = {name = "[q5]Erinnerung an die Knochenfragmente des Schlächters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKnochenfragmente des Schlächters Runenschnitzmacht\n[ Mungobiss : 'Mungobiss' / 'Raptorstoß'] erhöht den Schaden Eures nächsten Einsatzes von [ Schlachten : 'Schlachten' / 'Zerlegen'] um 20%. Bis zu 6-mal stapelbar.\nRunenschnitzen: Brust, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Jäger (Überleben)"}
MultiLanguageItemData['de'][183263] = {name = "[q5]Erinnerung an giftige Injektoren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nInjektoren für latentes Gift Runenschnitzmacht\nDer Schaden von 'Schlangengift' ruft beim Ziel 'Latentes Gift' hervor. Dieser Effekt ist bis zu 10-mal stapelbar. Euer [ Mungobiss : 'Mungobiss' / 'Raptorstoß'] zehrt alle Stapel von 'Latentes Gift' auf und fügt dem Ziel pro Stapel (20.7% der Angriffskraft) Naturschaden zu.\nRunenschnitzen: Kopf, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Jäger (Überleben)"}
MultiLanguageItemData['de'][183264] = {name = "[q5]Erinnerung an die Stöße des Rylakjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVerwirrende Stöße des Rylakjägers Runenschnitzmacht\n[ Mungobiss : 'Mungobiss' / 'Raptorstoß'] hat eine Chance von 15%, die Abklingzeit von 'Lauffeuerbombe' abzuschließen . (Procchance: 15%)\nRunenschnitzen: Beine, Rücken\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Jäger (Überleben)"}
MultiLanguageItemData['de'][183265] = {name = "[q5]Erinnerung an eine Lauffeuerstreubombe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nLauffeuerstreubombe Runenschnitzmacht\nDurch 'Lauffeuerbombe' werden zusätzliche Bomben um das Ziel herum abgeworfen, die bei der Explosion jeweils (33% der Angriffskraft) Feuerschaden verursachen. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\nRunenschnitzen: Taille, Beine\nQuelle: Dungeonbeute: Händlerin Xy'exa\nBenötigt: Jäger (Überleben)"}
MultiLanguageItemData['de'][183266] = {name = "[q5]Erinnerung an die Beherrschung der Disziplinen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBeherrschung der Disziplinen Runenschnitzmacht\nWenn Ihr je einen Frost-, Feuer- und Arkanzauber innerhalb von 10 Sek. voneinander einsetzt, wird der kritische Schaden aller Eurer Zauber um 20% erhöht. Dieser Effekt kann nur einmal alle 30 Sek. auftreten.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Nebelruferin"}
MultiLanguageItemData['de'][183267] = {name = "[q5]Erinnerung an ein erweitertes Potenzial", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nErweitertes Potenzial Runenschnitzmacht Ca. 2 Procs pro Minute\nEure Zauber 'Feuerball', 'Frostblitz' und 'Arkanschlag' haben eine Chance, Euch 'Erweitertes Potenzial' zu gewähren, wodurch Euer nächster Effekt von 'Kampfeshitze', 'Hirnfrost' oder 'Freizaubern' nicht verbraucht wird.\nRunenschnitzen: Taille, Füße\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Magier"}
MultiLanguageItemData['de'][183268] = {name = "[q5]Erinnerung an einen grausigen Eiszapfen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nGrausiger Eiszapfen Runenschnitzmacht\nEure Zauber brechen 'Frostnova' nicht mehr und Gegner, die von 'Frostnova' Schaden erlitten haben, erleiden 8 Sek. lang 15% mehr Schaden von Euren Feuer- und Arkanzaubern.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Magier"}
MultiLanguageItemData['de'][183269] = {name = "[q5]Erinnerung an den dreieinigen Schutz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDreieiniger Schutz Runenschnitzmacht\nDas Wirken eines beliebigen Barrierenzaubers gewährt die Effekte von 'Lodernde Barriere', 'Eisbarriere' und 'Prismatische Barriere'. Jeder Absorptionsschild verfügt über 65% Effektivität. (750ms Abklingzeit)\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Magier"}
MultiLanguageItemData['de'][183270] = {name = "[q5]Erinnerung an ein arkanes Bombardement", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nArkanes Bombardement Runenschnitzmacht\n'Arkanbeschuss' fügt Zielen mit weniger als 35% Gesundheit 130% mehr Schaden zu.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Magier (Arkan)"}
MultiLanguageItemData['de'][183271] = {name = "[q5]Erinnerung an die arkane Unendlichkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nArkane Harmonie Runenschnitzmacht\nJedes Mal, wenn 'Arkane Geschosse' einen Gegner trifft, wird der Schaden Eures nächsten Einsatzes von 'Arkanbeschuss' um 8% erhöht. Dieser Effekt ist bis zu 18-mal stapelbar.\nRunenschnitzen: Schulter, Hände\nQuelle: Dungeonbeute: Die Manasturms\nBenötigt: Magier (Arkan)"}
MultiLanguageItemData['de'][183272] = {name = "[q5]Erinnerung an eine Sturmladung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSturmladung Runenschnitzmacht\n'Hervorrufung' gewährt Euch 1 Arkane Aufladung, und während der Kanalisierung von 'Hervorrufung' wird Eure Intelligenz alle 0.5 Sek. um 2% erhöht. Hält 30 Sek. lang an.\nRunenschnitzen: Beine, Füße, Hände\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Magier (Arkan)"}
MultiLanguageItemData['de'][183273] = {name = "[q5]Erinnerung an eine temporale Krümmung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTemporale Krümmung Runenschnitzmacht\nWährend 'Temporale Verzerrung' oder ein ähnlicher Effekt bei Euch aktiv ist, könnt Ihr 'Zeitkrümmung' einsetzen und erhaltet so 40 Sek. lang 30% Tempo.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+"}
MultiLanguageItemData['de'][183274] = {name = "[q5]Erinnerung an eine fiebernde Zauberformel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nFiebernde Zauberformel Runenschnitzmacht\nJeder Eurer aufeinanderfolgenden kritischen Treffer erhöht Euren kritischen Schaden um 3%, bis zu maximal 15%.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Weltbossbeute: Oranomonos die Immersprießende\nBenötigt: Magier (Feuer)"}
MultiLanguageItemData['de'][183275] = {name = "[q5]Erinnerung an den Feuersturm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFeuersturm Runenschnitzmacht Ca. 1.66 Procs pro Minute\nWenn 'Kampfeshitze' aktiviert wird, besteht eine geringe Chance, dass sämtliche Einsätze von 'Pyroschlag' und 'Flammenstoß' 4 Sek. lang Spontanzauber werden und garantiert einen kritischen Treffer erzielen.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Der Oberste Kämmerer\nBenötigt: Magier (Feuer)"}
MultiLanguageItemData['de'][183276] = {name = "[q5]Erinnerung an den geschmolzenen Himmel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGeschmolzener Himmelssturz Runenschnitzmacht\nNachdem Ihr 18-mal einem Gegner mit 'Feuerball' oder 'Pyroschlag' Schaden zugefügt habt, lässt Euer nächster 'Feuerball' einen Meteor auf Euer Ziel niedergehen. Treffer gegen gegnerische Spielercharaktere zählen doppelt.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Magier (Feuer)"}
MultiLanguageItemData['de'][183277] = {name = "[q5]Erinnerung an den Sonnenkönig", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSegen des Sonnenkönigs Runenschnitzmacht\nNachdem Ihr 8-mal 'Kampfeshitze' verbraucht habt, gewährt Euer nächster nicht spontaner, innerhalb von 15 Sek. gewirkter 'Pyroschlag' Euch 6 Sek. lang 'Einäschern'.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Rettung des Sonnenkönigs\nBenötigt: Magier (Feuer)"}
MultiLanguageItemData['de'][183278] = {name = "[q5]Erinnerung an die Kaltfront", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKaltfront Runenschnitzmacht\nNachdem Ihr 30-mal 'Frostblitz' oder 'Hagel' gewirkt habt, geht eine 'Gefrorene Kugel' auf Euer Ziel nieder. Treffer gegen gegnerische Spielercharaktere zählen doppelt.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Nalthor der Eisbinder\nBenötigt: Magier (Frost)"}
MultiLanguageItemData['de'][183279] = {name = "[q5]Erinnerung an die eiskalten Winde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEiskalte Winde Runenschnitzmacht\nWährend 'Gefrorene Kugel' aktiv ist, erhaltet Ihr alle 2 Sek. 'Eisige Finger'.\nRunenschnitzen: Kopf, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Magier (Frost)"}
MultiLanguageItemData['de'][183280] = {name = "[q5]Erinnerung an Gletscherfragmente", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGletscherfragmente Runenschnitzmacht\n'Eislanze' hat eine Chance von 20%, in Eissplitter zu zerspringen, wenn ein Ziel getroffen wird, und allen Gegnern in der Nähe Eures Ziels (40% der Zaubermacht) Frostschaden zuzufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Diese Chance erhöht sich auf 100%, wenn Euer Ziel sich in einem 'Blizzard' befindet.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Magier (Frost)"}
MultiLanguageItemData['de'][183281] = {name = "[q5]Erinnerung an rutschiges Eis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRutschiges Eis Runenschnitzmacht\nWährend 'Eisige Adern' aktiv ist, verringert jeder von Euch eingesetzte 'Frostblitz' die Zauberzeit von 'Frostblitz' um 2% und erhöht den Schaden der Fähigkeit um 2%. Bis zu 10-mal stapelbar.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Magier (Frost)"}
MultiLanguageItemData['de'][183282] = {name = "[q5]Erinnerung an die tödliche Berührung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTödliche Berührung Runenschnitzmacht Sofort\nVerringert die Abklingzeit von 'Berührung des Todes' um 120 Sek.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Mueh'zala\nBenötigt: Mönch"}
MultiLanguageItemData['de'][183283] = {name = "[q5]Erinnerung an den Beschwörer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nFreude des Beschwörers Runenschnitzmacht\nNachdem Ihr Euren Erhabenen beschworen habt, erhaltet Ihr für 20 Sek. 33% Tempo.\nRunenschnitzen: Kopf, Schulter, Rücken\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Mönch"}
MultiLanguageItemData['de'][183284] = {name = "[q5]Erinnerung an die Flucht aus der Realität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nFlucht aus der Realität Runenschnitzmacht\nNach dem Einsatz von 'Transzendenz: Transfer' könnt Ihr 'Transzendenz: Transfer' innerhalb von 10 Sek. ungeachtet der Abklingzeit erneut einsetzen.\n\n Wenn Ihr während dieser Zeit 'Beleben' bei Euch selbst einsetzt, ist die Heilung um 70% erhöht und 50% der Kosten werden erstattet.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Mönch"}
MultiLanguageItemData['de'][183285] = {name = "[q5]Erinnerung an die flinkgewissen Wickel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nTolle Rolle Runenschnitzmacht Sofort\nWährend [ Chitorpedo : 'Chitorpedo' / 'Rollen'] seid Ihr immun gegen bewegungseinschränkende und Bewegungsunfähigkeitseffekte.\nRunenschnitzen: Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Mönch"}
MultiLanguageItemData['de'][183286] = {name = "[q5]Erinnerung an Shaohao", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nShaohaos Macht Runenschnitzmacht\n'Tigerklaue' hat eine Chance von 40%, 300% des normalen Schadens zu verursachen und die verbleibende Abklingzeit Eurer Gebräue um zusätzlich 2 Sek. zu verringern.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Mönch (Braumeister)"}
MultiLanguageItemData['de'][183287] = {name = "[q5]Erinnerung an versengte Leidenschaften", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVersengte Leidenschaften Runenschnitzmacht\nEuer 'Feuerodem' hüllt Euer rechtes Bein für 8 Sek. in Flammen, sodass Euer 'Blackout-Tritt' und 'Wirbelnder Kranichtritt' zusätzlich 100% Schaden als Feuerschaden verursachen und die Dauer Eures Effekts 'Feuerodem' beim Ziel zurücksetzen.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Mönch (Braumeister)"}
MultiLanguageItemData['de'][183288] = {name = "[q5]Erinnerung an eine himmlische Infusion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nMächtiger Ausschank Runenschnitzmacht\n'Reinigendes Gebräu' hat eine Chance von 35%, keine Aufladung zu verbrauchen, und 'Himmlisches Gebräu' erhöht Eure Rüstung für 8 Sek. um 50%.\nRunenschnitzen: Beine, Füße\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Mönch (Braumeister)"}
MultiLanguageItemData['de'][183289] = {name = "[q5]Erinnerung an Sturmbräu", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSturmbräus letztes Fass Runenschnitzmacht\n'Fasshieb' verursacht 30% zusätzlichen Schaden und hat 1 zusätzliche [Aufladung][Aufladungen].\nRunenschnitzen: Schulter, Taille, Hände\nQuelle: Dungeonbeute: General Kaal\nBenötigt: Mönch (Braumeister)"}
MultiLanguageItemData['de'][183290] = {name = "[q5]Erinnerung an uralte Lehren", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUralte Lehren des Klosters Runenschnitzmacht\nNach dem Einsatz von 'Essenzborn' heilen Eure Fähigkeiten 'Tigerklaue', 'Blackout-Tritt' und 'Tritt der aufgehenden Sonne' einen verletzten Verbündeten innerhalb von 20 Metern um 250% des verursachten Schadens. Hält 15 Sek. lang an.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Dungeonbeute: Devos, Paragon des Zweifels\nBenötigt: Mönch (Nebelwirker)"}
MultiLanguageItemData['de'][183291] = {name = "[q5]Erinnerung an Yu'lon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nYu'lons Flüstern Runenschnitzmacht 100 Meter Reichweite\nWenn Ihr 'Donnerfokustee' aktiviert, atmet Ihr den Atem von Yu'lon aus, der bis zu 6 Verbündete innerhalb von 15 Metern im Verlauf von 2 Sek. um [(60% der Zaubermacht) * (3)] Gesundheit heilt.\nRunenschnitzen: Schulter, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Mönch (Nebelwirker)"}
MultiLanguageItemData['de'][183292] = {name = "[q5]Erinnerung an den umwölkten Fokus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUmwölkter Fokus Runenschnitzmacht\nHeilungen mit 'Einhüllender Nebel' oder 'Beleben', während Ihr 'Beruhigender Nebel' kanalisiert, erhöhen die verursachte Heilung der beiden Fähigkeiten um 20% und verringern ihre Manakosten um 20%. Bis zu 3-mal stapelbar.\n\n Wenn das Kanalisieren von 'Beruhigender Nebel' endet, wird dieser Effekt aufgehoben.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Mönch (Nebelwirker)"}
MultiLanguageItemData['de'][183293] = {name = "[q5]Erinnerung an die Träne des Morgens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTräne des Morgens Runenschnitzmacht\nWenn ihr 'Beleben' oder 'Einhüllender Nebel' bei einem mit 'Erneuernder Nebel' belegten Ziel einsetzt, besteht eine Chance von 10%, 'Erneuernder Nebel' auf ein weiteres Ziel anzuwenden.\n\n Eure bei mit 'Erneuernder Nebel' belegten Zielen durch 'Beleben' hervorgerufene Heilung ist um 20% erhöht und Euer 'Einhüllender Nebel' heilt diese Ziele zusätzlich um 20% seiner hervorgerufenen Heilung.\nRunenschnitzen: Kopf, Taille\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Mönch (Nebelwirker)"}
MultiLanguageItemData['de'][183294] = {name = "[q5]Erinnerung an die Jadezündung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nJadezündung Runenschnitzmacht\nWenn Ihr einem Ziel mit 'Furorfäuste' Schaden zufügt, erhaltet Ihr einen Stapel Chienergie, bis zu maximal 30 Stapel.\n\n Wenn Ihr 'Wirbelnder Kranichtritt' einsetzt, detoniert die Energie in einer 'Chiexplosion', die allen Gegnern innerhalb von 8 Metern (65% der Angriffskraft) Schaden zufügt. Der Schaden erhöht sich pro Stapel Chienergie um 5%.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Mönch (Windläufer)"}
MultiLanguageItemData['de'][183295] = {name = "[q5]Erinnerung an Kiefer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKiefers Himmelsgriff Runenschnitzmacht\nErhöht die Reichweite von 'Tigerklaue' auf 10 Meter und beim Einsatz springt Ihr sofort zum Ziel.\n\n 'Tigerklaue' belegt das Ziel zusätzlich mit einem Effekt, der Eure kritische Trefferchance gegen das Ziel für 6 Sek. um 50% erhöht. Dieser Effekt kann pro Ziel nur einmal alle 1 Min. auftreten.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Weltbossbeute: Mortanis\nBenötigt: Mönch (Windläufer)"}
MultiLanguageItemData['de'][183296] = {name = "[q5]Erinnerung an den letzten Kaiser", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKondensator des letzten Kaisers Runenschnitzmacht\nChi verbrauchende Fähigkeiten erhöhen den Schaden Eures nächsten Einsatzes von 'Knisternder Jadeblitz' um 100% und verringern seine Kosten um 5%. Bis zu 20-mal stapelbar.\nRunenschnitzen: Taille, Beine\nQuelle: Schlachtzugbeute: Konstrukteur Xy'mox\nBenötigt: Mönch (Windläufer)"}
MultiLanguageItemData['de'][183297] = {name = "[q5]Erinnerung an Xuen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nXuens Schlachtrüstung Runenschnitzmacht\nKritische Treffer mit 'Tritt der aufgehenden Sonne' verringern die Abklingzeit von 'Furorfäuste' um 5.0 Sek.\n\n Beim Ablauf von 'Furorfäuste' wird die kritische Trefferchance von 'Tritt der aufgehenden Sonne' 5 Sek. lang um 40% erhöht.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kryxis der Gefräßige\nBenötigt: Mönch (Windläufer)"}
MultiLanguageItemData['de'][183298] = {name = "[q5]Erinnerung an das Wahnsinnige Paragon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDas Wahnsinnige Paragon Runenschnitzmacht\n'Hammer des Zorns' verursacht 30% mehr Schaden und verlängert die Dauer von [ Kreuzzug : 'Kreuzzug' ] [ Kreuzzug der Vergeltung : 'Kreuzzug der Vergeltung' / 'Zornige Vergeltung' ] um 1 Sek.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Paladin"}
MultiLanguageItemData['de'][183299] = {name = "[q5]Erinnerung an die Zyklen der Sonne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nAbendrot und Morgenrot Runenschnitzmacht\nWenn Ihr 5 Heilige Kraft erreicht, erhaltet Ihr 'Segen des Morgens'. Wenn Ihr 0 Heilige Kraft erreicht, erhaltet Ihr 'Segen des Abends'.\n\nSegen des Morgens\nErhöht Schaden und Heilung 12 Sek. lang um 6%.\n\nSegen des Abends\nErlittener Schaden wird 12 Sek. lang um 4% verringert.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Paladin"}
MultiLanguageItemData['de'][183300] = {name = "[q5]Erinnerung an das Richturteil des Magistrats", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDas Richturteil des Magistrats Runenschnitzmacht\n'Richturteil' hat eine Chance von [ Heilig : 60% / Schutz : 45% /\n\nVergeltung\n 75% ] die Kosten Eures nächsten Einsatzes einer Fähigkeit, die Heilige Kraft verbraucht, um 1 zu verringern. (700ms Abklingzeit)\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Xav der Unbesiegte\nBenötigt: Paladin"}
MultiLanguageItemData['de'][183301] = {name = "[q5]Erinnerung an Uther", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nUthers Hingabe Runenschnitzmacht\nVerringert die Abklingzeit Eurer Fähigkeiten 'Segen der Freiheit' [ Segen der Aufopferung : 'Segen der Aufopferung' ] und [ Segen des Zauberschutzes : 'Segen des Zauberschutzes' / 'Segen des Schutzes'] pro verbrauchter Heiliger Kraft um 1 Sek.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Paladin"}
MultiLanguageItemData['de'][183302] = {name = "[q5]Erinnerung an die Blüte des Sonnenbrunnens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nInfloreszenz des Sonnenbrunnens Runenschnitzmacht\n'Lichtinfusion' verfügt über 1 zusätzliche Aufladung und die Effekte sind um 30% erhöht.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Paladin (Heilig)"}
MultiLanguageItemData['de'][183303] = {name = "[q5]Erinnerung an Maraads letzten Atemzug", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nMaraads letzter Atemzug Runenschnitzmacht\n'Licht der Morgendämmerung' erhöht die Heilung Eures nächsten Einsatzes von 'Licht des Märtyrers' um 10% pro geheiltem Verbündeten und bewirkt, dass dieser Einsatz zusätzlich Eure 'Flamme des Glaubens' heilt.\n\n Ihr erleidet den Schaden von 'Licht des Märtyrers' im Verlauf von 5 Sek. anstatt sofort.\nRunenschnitzen: Brust, Finger\nQuelle: Dungeonbeute: Großaufseherin Beryllia\nBenötigt: Paladin (Heilig)"}
MultiLanguageItemData['de'][183304] = {name = "[q5]Erinnerung an den Schattenbrecher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchattenbrecher, der Sonnenaufgang Runenschnitzmacht\nErhöht die Reichweite von 'Licht der Morgendämmerung' auf 40 Meter. Alle Verbündeten innerhalb des Effekts profitieren 8 Sek. lang so von Eurer 'Meisterschaft: Lichtbringer', als ob sie sich innerhalb von 10 Metern befinden würden.\n\n 'Wort der Herrlichkeit' profitiert 50% mehr von Eurer Meisterschaft.\nRunenschnitzen: Schulter, Taille, Hände\nQuelle: Schlachtzugbeute: Rettung des Sonnenkönigs\nBenötigt: Paladin (Heilig)"}
MultiLanguageItemData['de'][183305] = {name = "[q5]Erinnerung an die Schockbarriere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSchockbarriere Runenschnitzmacht\n'Heiliger Schock' schützt das Ziel für 18 Sek. mit einem Schild aus heiligem Licht. Der Schild absorbiert alle 6 Sek. Schaden in Höhe von 20% des Heiligen Schocks. Kann bis zu 5 Ziele schützen.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Paladin (Heilig)"}
MultiLanguageItemData['de'][183306] = {name = "[q5]Erinnerung an das rechtschaffene Bollwerk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBollwerk des Rechtschaffenen Zorns Runenschnitzmacht\n'Schild des Rächers' erhöht den Schaden Eures nächsten Einsatzes von 'Schild der Rechtschaffenen' pro von 'Schild des Rächers' getroffenem Ziel um 30% (bis zu 5 - mal stapelbar) und erhöht den Radius der Fähigkeit um 6 Meter.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Hochadjudikatorin Aleez\nBenötigt: Paladin (Schutz)"}
MultiLanguageItemData['de'][183307] = {name = "[q5]Erinnerung an ein heiliges Siegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGraviertes Siegel des heiligen Rächers Runenschnitzmacht\nEuer 'Schild des Rächers' hat eine Chance von 35%, dass seine Abklingzeit nach dem Einsatz sofort abgeschlossen wird. (Procchance: 35%)\nRunenschnitzen: Kopf, Taille\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Paladin (Schutz)"}
MultiLanguageItemData['de'][183308] = {name = "[q5]Erinnerung an die endlosen Könige", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nHerrschaft der Endlosen Könige Runenschnitzmacht\nWenn Eure Gesundheit unter 20% fällt, werdet Ihr für 4 Sek. lang mit dem Wächter der Uralten Könige geschützt. Dieser Effekt kann nur einmal alle 45 Sek. auftreten.\nRunenschnitzen: Hals, Brust, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Paladin (Schutz)"}
MultiLanguageItemData['de'][183309] = {name = "[q5]Erinnerung an den unermüdlichen Beschützer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nZuflucht des Unermüdlichen Beschützers Runenschnitzmacht\nWenn 'Unermüdlicher Verteidiger' Euch vor dem Tod rettet, stellt Ihr zusätzlich 40% Gesundheit wieder her.\n\n Wenn die Effektdauer von 'Unermüdlicher Verteidiger' abläuft, ohne dass Ihr vor dem Tod gerettet wurdet, wird die verbleibende Abklingzeit um 40% verringert.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Paladin (Schutz)"}
MultiLanguageItemData['de'][183310] = {name = "[q5]Erinnerung an den Schwung des Frontkämpfers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSchwung des Frontkämpfers Runenschnitzmacht\n'Hammer des Zorns' hat 1 zusätzliche Aufladung und erhöht den verursachten Heiligschaden für 10 Sek. um 4%. Bis zu 3-mal stapelbar.\nRunenschnitzen: Kopf, Füße, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Paladin (Vergeltung)"}
MultiLanguageItemData['de'][183311] = {name = "[q5]Erinnerung an das letzte Urteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nLetztes Urteil Runenschnitzmacht 10 Meter Reichweite\nBenötigt Stufe 1"}
MultiLanguageItemData['de'][183312] = {name = "[q5]Erinnerung an einen unnachgiebigen Inquisitor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUnnachgiebiger Inquisitor Runenschnitzmacht\nBeim Verbrauch von Heiliger Kraft wird Euer Tempo pro Finishing-Move für 12 Sek. um 1% erhöht. Bis zu 5-mal stapelbar. (500ms Abklingzeit)\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Paladin"}
MultiLanguageItemData['de'][183313] = {name = "[q5]Erinnerung an den Sturm des Lichtbringers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSturm des Lichtbringers Runenschnitzmacht\n'Göttlicher Sturm' projiziert eine zusätzliche Lichtwelle vorwärts, die allen Gegnern 20 Meter vor Euch 20% des Schadens von 'Göttlicher Sturm' zufügt.\nRunenschnitzen: Taille, Beine\nQuelle: Dungeonbeute: Oryphrion\nBenötigt: Paladin (Vergeltung)"}
MultiLanguageItemData['de'][183314] = {name = "[q5]Erinnerung an kauterisierende Schatten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKauterisierende Schatten Runenschnitzmacht\nWenn [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] bei einem Ziel abläuft, werden 3 Verbündete innerhalb von 30 Metern um das betroffene Ziel um (75% der Zaubermacht) Gesundheit geheilt.\nRunenschnitzen: Taille, Füße\nQuelle: Dungeonbeute: Mordretha, die Unendliche Kaiserin\nBenötigt: Priester"}
MultiLanguageItemData['de'][183315] = {name = "[q5]Erinnerung an ein bedächtiges Nachsinnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBedächtiges Nachsinnen Runenschnitzmacht\nPro 15 Sek., in denen Ihr 'Blitzheilung' nicht einsetzt, wird die Heilung Eures nächsten Einsatzes von 'Blitzheilung' um 50% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Priester"}
MultiLanguageItemData['de'][183316] = {name = "[q5]Erinnerung an die Zwillinge der Sonnenpriesterin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nZwillinge der Sonnenpriesterin Runenschnitzmacht\n'Seele der Macht' gewährt auch bei Anwendung auf Verbündete 100% seines Effekts.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Priester"}
MultiLanguageItemData['de'][183317] = {name = "[q5]Erinnerung an einen himmlischen Sprung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nSprung der Himmel Runenschnitzmacht\n'Glaubenssprung' lässt Euch zu Eurem Ziel springen und hat 2 Aufladungen.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Priester"}
MultiLanguageItemData['de'][183318] = {name = "[q5]Erinnerung an klare Gedanken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKlarheit der Gedanken Runenschnitzmacht\n[ Geisthülle : 'Geisthülle' erhöht die Dauer bestehender Effekte von 'Abbitte' um 3 Sek. und verringert die Manakosten von Schadenszaubern um 30% / Während 'Euphorie' aktiv ist, kostet 'Machtwort: Schild' 20% weniger Mana und der damit angewendete Effekt 'Abbitte' hält 6 Sek. länger an.] (Procchance: 50%)\nRunenschnitzen: Brust, Finger\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Priester (Disziplin)"}
MultiLanguageItemData['de'][183319] = {name = "[q5]Erinnerung an meine kristalline Reflexion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKristalline Reflexion Runenschnitzmacht\n'Machtwort: Schild' heilt das Ziel sofort um (42% der Zaubermacht) Gesundheit und reflektiert 20% des absorbierten Schadens.\nRunenschnitzen: Schulter, Hände\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Priester (Disziplin)"}
MultiLanguageItemData['de'][183320] = {name = "[q5]Erinnerung an den Kuss des Todes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nKuss des Todes Runenschnitzmacht\nVerringert die Abklingzeit von 'Schattenwort: Tod' um 12 Sek. und lässt den Schaden dieser Fähigkeit 'Abbitte' auslösen, wenn sie gegen Ziele mit weniger als (85% der Zaubermacht)% Gesundheit eingesetzt wird.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Priester (Disziplin)"}
MultiLanguageItemData['de'][183321] = {name = "[q5]Erinnerung an den Bußfertigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDer Bußfertige Runenschnitzmacht\n'Machtwort: Glanz' hat eine Chance von 60%, Euren nächsten Einsatz von 'Sühne' kostenlos zu machen und ihn 3 zusätzliche Geschosse verschießen zu lassen.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Priester (Disziplin)"}
MultiLanguageItemData['de'][183322] = {name = "[q5]Erinnerung an ein göttliches Abbild", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGöttliches Abbild Runenschnitzmacht\nBeim Einsatz eines Segensworts besteht eine Chance, dass ein Abbild eines Naaru an Eure Seite beschworen wird. Für die nächsten 15 Sek. imitiert der Naaru alle von Euch gewirkten Zauber. (Procchance: 25%)\nRunenschnitzen: Kopf, Taille, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Priester (Heilig)"}
MultiLanguageItemData['de'][183323] = {name = "[q5]Erinnerung an eine Blitzkonzentration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBlitzkonzentration Runenschnitzmacht\nJedes Mal, wenn Ihr 'Blitzheilung' wirkt, wird für 20 Sek. die Zauberzeit Eures Zaubers 'Heilung' um 0.2 Sek. verringert und seine Heilung um 3% erhöht. Bis zu 5-mal stapelbar.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Dungeonbeute: Großaufseherin Beryllia\nBenötigt: Priester (Heilig)"}
MultiLanguageItemData['de'][183324] = {name = "[q5]Erinnerung an einen harmonischen Apparat", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nHarmonischer Apparat Runenschnitzmacht\n'Kreis der Heilung' verringert die Abklingzeit von 'Segenswort: Heiligung', 'Gebet der Besserung' verringert die Abklingzeit von 'Segenswort: Epiphanie' und 'Heiliges Feuer' verringert die Abklingzeit von 'Segenswort: Züchtigung' um 4 Sek.\nRunenschnitzen: Schulter, Finger\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Priester (Heilig)"}
MultiLanguageItemData['de'][183325] = {name = "[q5]Erinnerung an Erzbischof Benedictus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nX'anshi, Rückkehr von Erzbischof Benedictus Runenschnitzmacht\nWenn Euer Geist der Erlösung abläuft, werdet Ihr mit bis zu 100% Gesundheit wiederbelebt, abhängig davon, wie effektiv Ihr als Geist der Erlösung wart. Nach Eurer Wiederbelebung kann der Geist der Erlösung 10 Min. lang nicht erneut ausgelöst werden.\nRunenschnitzen: Beine, Rücken\nQuelle: Weltbossbeute: Valinor, das Licht der Äonen\nBenötigt: Priester (Heilig)"}
MultiLanguageItemData['de'][183326] = {name = "[q5]Erinnerung an die ewige Anrufung der Leere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEwige Anrufung der Leere Runenschnitzmacht Ca. 1.3 Procs pro Minute\n'Gedankenschinden' und 'Gedankenexplosion' haben eine Chance, ein Leerententakel oder einen Leerenpeitscher zu erschaffen, das/der 15 Sek. lang auf Euer Ziel kanalisiert und dabei alle 1 Sek. 3 Wahnsinn erzeugt.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Der Rat des Blutes\nBenötigt: Priester (Schatten)"}
MultiLanguageItemData['de'][183327] = {name = "[q5]Erinnerung an den schmerzbrechenden Psalm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSchmerzbrechender Psalm Runenschnitzmacht\n'Schattenwort: Tod' verbraucht 8 Sek. Eurer Effekte 'Schattenwort: Schmerz' und 'Vampirberührung' auf dem Ziel, fügt dem Ziel diesen Schaden sofort zu und erzeugt bis zu 30 Wahnsinn.\nRunenschnitzen: Brust, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Priester (Schatten)"}
MultiLanguageItemData['de'][183328] = {name = "[q5]Erinnerung an Talbadar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTalbadars Strategie Runenschnitzmacht\nWenn Eure Zauber 'Schattenwort: Schmerz', 'Verschlingende Seuche' und 'Vampirberührung' gleichzeitig auf demselben Ziel aktiv sind, verursacht Euer Zauber 'Gedankenschlag' 55% mehr Schaden.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Priester (Schatten)"}
MultiLanguageItemData['de'][183329] = {name = "[q5]Erinnerung an ein Prisma aus Schatten und Flammen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSchattenflammenprisma Runenschnitzmacht\n'Gedankenschlag' und 'Schattenwort: Tod' veranlassen Euren Schattengeist dazu, sich hinter Euer Ziel zu teleportieren und bis zu 5 Gegnern in der Nähe [ Geistbeuger : [.442 * (190% der Zaubermacht)] / [.408 * (190% der Zaubermacht)]] Schattenflammenschaden zuzufügen. Jedes Mal, wenn ein Riss ausgelöst wird, wird die Dauer des Schattengeists um 1.0 Sek. erhöht.\nRunenschnitzen: Kopf, Hände\nQuelle: Dungeonbeute: Mueh'zala\nBenötigt: Priester (Schatten)"}
MultiLanguageItemData['de'][183330] = {name = "[q5]Erinnerung an die Essenz des Blutzahns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEssenz des Blutzahns Runenschnitzmacht\nEure Combopunkte erzeugenden Fähigkeiten haben eine Chance, das Ziel mit 'Blutzahn' zu infizieren, was ihm 0 Blutungsschaden im Verlauf von 6 Sek. zufügt und Euch um 50% des verursachten Schadens heilt. (Procchance: 30%, 200ms Abklingzeit)\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Schurke"}
