MultiLanguageItemData['de'][183342] = {name = "[q5]Erinnerung an Akaaris Seelenfragment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nAkaaris Seelenfragment Runenschnitzmacht\n2 Sek. nach dem Einsatz von 'Schattenschlag' oder 'Fieser Trick' erleidet Euer Ziel einen weiteren Schattenschlag mit 25% Effektivität.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Schurke (Täuschung)"}
MultiLanguageItemData['de'][183343] = {name = "[q5]Erinnerung an die tödlichen Schatten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTödliche Schatten Runenschnitzmacht\n'Verschwinden' erzeugt 5 Combopunkte und erhöht sämtlichen verursachten Schaden für [ Täuschung : 15 Sek. um 20% /\n\nMeucheln, Gesetzlosigkeit\n12 Sek. um 15% ] (500ms Abklingzeit)\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Schurke"}
MultiLanguageItemData['de'][183344] = {name = "[q5]Erinnerung an die Endgültigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEndgültigkeit Runenschnitzmacht\n'Ausweiden', 'Blutung' und 'Schwarzpulver' erhöhen den Schaden Eures nächsten Einsatzes dieses Finishing-Moves um 25%.\nRunenschnitzen: Brust, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Schurke (Täuschung)"}
MultiLanguageItemData['de'][183345] = {name = "[q5]Erinnerung an die Verdorbenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDie Verdorbenen Runenschnitzmacht\nNach der Aktivierung von 'Symbole des Todes' verursacht Euer nächster Einsatz von 'Schattenschlag' oder [ Düstere Klinge : 'Düstere Klinge' / 'Meucheln'] 50% mehr Schaden und erzeugt 4 zusätzliche Combopunkte.\nRunenschnitzen: Beine, Rücken\nQuelle: Dungeonbeute: Domina Giftklinge\nBenötigt: Schurke (Täuschung)"}
MultiLanguageItemData['de'][183346] = {name = "[q5]Erinnerung an die Ahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nErinnerung der Ahnen Runenschnitzmacht\n[ Heldentum : 'Heldentum' / 'Kampfrausch'] und ähnliche Effekte halten bei Euch 20.0 Sek. länger an und Effekte wie [ Heldentum : 'Heldentum' / 'Kampfrausch'] erhöhen Euer Tempo um zusätzlich 10%.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Schamane"}
MultiLanguageItemData['de'][183347] = {name = "[q5]Erinnerung an die Ketten der Verheerung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nKetten der Verheerung Runenschnitzmacht Sofort\nElementar\n 'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber und lässt ihn 50% mehr Schaden verursachen. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber und lässt ihn kein Mana verbrauchen.\n\nVerstärkung, Wiederherstellung\n 'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Schamane"}
MultiLanguageItemData['de'][183348] = {name = "[q5]Erinnerung an tief verwurzelte Elemente", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTief verwurzelte Elemente Runenschnitzmacht\nElementar\n Der Einsatz von 'Lavaeruption' hat eine Chance von 7%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\n\nWiederherstellung\n Der Einsatz von 'Springflut' hat eine Chance von 7%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\n\nVerstärkung\n Der Einsatz von 'Sturmschlag' hat eine Chance von 8%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\nRunenschnitzen: Kopf, Schulter, Handgelenk\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Schamane"}
