MultiLanguageItemData['de'][183357] = {name = "[q5]Erinnerung an den Hexendoktor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nWolfsknochen des Hexendoktors Runenschnitzmacht\nErhöht die Chance, einen Stapel von 'Waffe des Mahlstroms' zu erhalten, um 3%. Außerdem wird jedes Mal, wenn Ihr einen Stapel von 'Waffe des Mahlstroms' erhaltet, die Abklingzeit von 'Wildgeist' um 2.0 Sek. verringert.\nRunenschnitzen: Schulter, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Schamane (Verstärkung)"}
MultiLanguageItemData['de'][183358] = {name = "[q5]Erinnerung an eine irdene Harmonie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nIrdene Harmonie Runenschnitzmacht\nDie Heilung von 'Erdschild' wird um 150% erhöht, wenn das Ziel Eures Erdschilds weniger als 75% Gesundheit hat. Zusätzlich gewährt 'Welle der Heilung' dem Ziel einen Stapel von 'Erdschild', bis zu maximal 9 Stapeln.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: General Kaal\nBenötigt: Schamane (Wiederherstellung)"}
MultiLanguageItemData['de'][183359] = {name = "[q5]Erinnerung an Jonat", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nJonats Naturfokus Runenschnitzmacht\n'Welle der Heilung' und 'Heilende Woge' erhöhen die Heilung Eures nächsten Einsatzes von 'Kettenheilung' um 20%. Dieser Effekt ist bis zu 5-mal stapelbar.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Schamane (Wiederherstellung)"}
MultiLanguageItemData['de'][183360] = {name = "[q5]Erinnerung an den urzeitlichen Flutenkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUrzeitlicher Flutenkern Runenschnitzmacht\nAlle 4 Einsätze von 'Springflut' wird 'Springflut' einem zusätzlichen verbündeten Ziel in der Nähe des Ziels der Fähigkeit gewährt.\nRunenschnitzen: Kopf, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Schamane (Wiederherstellung)"}
MultiLanguageItemData['de'][183361] = {name = "[q5]Erinnerung an das Gezeitentotem des Geistwandlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGezeitentotem des Geistwandlers Runenschnitzmacht\nNach dem Aufstellen Eures Totems der Manaflut wird die Zauberzeit von 'Welle der Heilung' und 'Kettenheilung' um 50% verringert und die Manakosten von 'Kettenheilung' und 'Welle der Heilung' werden um 40% verringert. Hält 10 Sek. lang an.\nRunenschnitzen: Beine, Rücken\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Schamane (Wiederherstellung)"}
MultiLanguageItemData['de'][183362] = {name = "[q5]Erinnerung an den bösartigen Zorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBösartiger Zorn Runenschnitzmacht\nDer Einsatz von 'Unheilvolle Euphorie' erhöht den Schaden von [ Seelendieb : 'Seelendieb' / 'Schattenblitz'] für 10 Sek. um 35%. Dieser Effekt ist bis zu 3-mal stapelbar. (100ms Abklingzeit)\nRunenschnitzen: Schulter, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Hexenmeister (Gebrechen)"}
MultiLanguageItemData['de'][183363] = {name = "[q5]Erinnerung an die Agonie von Azj'Aqir", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEwige Agonie von Azj'Aqir Runenschnitzmacht\n'Agonie' hat eine um 20% erhöhte Chance, einen Seelensplitter zu erzeugen.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Hexenmeister (Gebrechen)"}
MultiLanguageItemData['de'][183364] = {name = "[q5]Erinnerung an Sacrolashs Dunkelstoß", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSacrolashs Dunkelstoß Runenschnitzmacht\nDer Schaden von 'Verderbnis' ist um 25% erhöht und jedes Mal, wenn die Fähigkeit Schaden verursacht, werden Eure Flüche auf dem Ziel um 2 Sek. verlängert.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Hexenmeister (Gebrechen)"}
MultiLanguageItemData['de'][183365] = {name = "[q5]Erinnerung an den Zorn der Aufzehrung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nZorn der Aufzehrung Runenschnitzmacht\nWenn ein Ziel stirbt, während 'Verderbnis' oder 'Agonie' auf ihm aktiv ist, gewähren die beiden Zauber jeweils eine Anwendung von 'Zorn der Aufzehrung', was sämtlichen verursachten regelmäßigen Schaden 30 Sek. lang um 6% erhöht. Bis zu 5-mal stapelbar.\nRunenschnitzen: Füße, Rücken\nQuelle: Dungeonbeute: Ventunax\nBenötigt: Hexenmeister (Gebrechen)"}
