MultiLanguageItemData['de'][183367] = {name = "[q5]Erinnerung an die dämonische Synergie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRelikt der dämonischen Synergie Runenschnitzmacht Ca. 3 Procs pro Minute\nWenn Ihr oder Euer Primärdämon Schaden verursacht, besteht eine Chance, dass der jeweils andere 15 Sek. lang eine Schadenserhöhung von [ Dämonologie : 15% /\n\nGebrechen, Zerstörung\n10% ] erhält.\nRunenschnitzen: Kopf, Schulter, Rücken\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Hexenmeister"}
MultiLanguageItemData['de'][183368] = {name = "[q5]Erinnerung an das Dunkle Portal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nSäulen des Dunklen Portals Runenschnitzmacht\nMacht 'Dämonisches Tor' zu einem Spontanzauber und lässt Euren ersten Einsatz des Tors keine Abklingzeit auslösen.\n\n Zusätzlich werden Gegner, durch die Ihr reist, von Netherenergie gepeitscht und zurückgestoßen.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Hexenmeister\nModifies Cast Time -100%:\nDämonisches Tor"}
MultiLanguageItemData['de'][183369] = {name = "[q5]Erinnerung an Wilfreds Siegel der überlegenen Beschwörung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWilfreds Siegel der überlegenen Beschwörung Runenschnitzmacht\nGebrechen\n Jeder verbrauchte Seelensplitter verringert die Abklingzeit von 'Dunkelblick beschwören' um 2.0 Sek.\n\nDämonologie\n Jeder verbrauchte Seelensplitter verringert die Abklingzeit von 'Dämonischen Tyrannen beschwören' um 0.6 Sek.\n\nZerstörung\n Jeder verbrauchte Seelensplitter verringert die Abklingzeit von 'Höllenbestie beschwören' um 1.5 Sek.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Die Manasturms\nBenötigt: Hexenmeister"}
MultiLanguageItemData['de'][183370] = {name = "[q5]Erinnerung an den Kern der Spinnenbedrohung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBrennender Kern der Spinnenbedrohung Runenschnitzmacht\n'Schattenblitz' erhöht den Schaden von 'Dämonenblitz' um 15%. Bis zu 4-mal stapelbar. Hält 20 Sek. lang an.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Konstrukteur Xy'mox\nBenötigt: Hexenmeister (Dämonologie)"}
