MultiLanguageItemData['de'][183376] = {name = "[q5]Erinnerung an den Wahnsinn der Azj'Aqir", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nWahnsinn der Azj'Aqir Runenschnitzmacht\n'Chaosblitz' erhöht den Schaden von 'Chaosblitz' um 25% und verringert die Zauberzeit von 'Chaosblitz' um 20%. Hält 4 Sek. lang an.\nRunenschnitzen: Kopf, Hände\nQuelle: Weltbossbeute: Nurgash Schlammborn\nBenötigt: Hexenmeister (Zerstörung)"}
MultiLanguageItemData['de'][183377] = {name = "[q5]Erinnerung an die Ymirjar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nOdr, Schal der Ymirjar Runenschnitzmacht\nGegner, die von Eurer 'Verwüstung' markiert wurden, erleiden durch Eure Einzelzielzauber 25% mehr Schaden.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Hexenmeister (Zerstörung)"}
MultiLanguageItemData['de'][183378] = {name = "[q5]Erinnerung an den Springer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\n\nSpringer Runenschnitzmacht\n'Heldenhafter Sprung' erhält 2 zusätzliche Aufladungen.\nRunenschnitzen: Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Krieger"}
MultiLanguageItemData['de'][183379] = {name = "[q5]Erinnerung an den verformten Spiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVerformter Spiegel Runenschnitzmacht\n'Zauberreflexion' hält 60% länger an und wirkt sich auf Euren nächsten Verbündeten aus. (1s Abklingzeit)\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Krieger"}
MultiLanguageItemData['de'][183380] = {name = "[q5]Erinnerung an einen seismischen Nachhall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSeismischer Nachhall Runenschnitzmacht\nFuror\n Wenn 'Wirbelwind' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen und erleiden dabei 100% des Schadens.\n\nWaffen\n Wenn 'Wirbelwind' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen und erleiden dabei 80% des Schadens.\n\nSchutz\n Wenn 'Wirbelwind' oder 'Rache' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen und erleiden dabei 75% des Schadens.\nRunenschnitzen: Kopf, Schulter, Füße\nQuelle: Dungeonbeute: Halkias, der Sündenbefleckte Goliath\nBenötigt: Krieger"}
MultiLanguageItemData['de'][183381] = {name = "[q5]Erinnerung an die gequälten Könige", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSignet der Gequälten Könige Runenschnitzmacht\nDas Aktivieren von 'Klingensturm', 'Tollkühnheit' oder 'Avatar' setzt zufällig eine der beiden anderen Fähigkeiten mit verringerter Effektivität ein.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Krieger"}
