MultiLanguageItemData['de'][184013] = {name = "[q4]Boshafte Kriegsspinne", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Wenn ein mächtiges Mitglied der Horde zu sein nicht ausreicht, dass Euer Gegner vor Angst erzittert, fügt einfach eine Riesenspinne hinzu.\"\nPvP:\nShadowlands: Saison 1\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder"}
MultiLanguageItemData['de'][184014] = {name = "[q4]Boshafte Kriegsspinne", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Wenn ein mutiges Mitglied der Allianz zu sein nicht ausreicht, um das Herz Eures Gegners mit Angst zu erfüllen, fügt einfach eine Riesenspinne hinzu.\"\nPvP:\nShadowlands: Saison 1\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder"}
MultiLanguageItemData['de'][184015] = {name = "Gestohlenes Andenken", additional_info = "Questgegenstand\n[q]\"Ein verlorenes Andenken, das nach dem Tod des Hains zurückgelassen wurde.\""}
MultiLanguageItemData['de'][184016] = {name = "[q4]Schleicherflügel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Werdet 10 Sek. lang zum lauernden Raubtier, was Eure Geschwindigkeit um 69 erhöht. Ihr stürzt Euch außerdem auf den nächsten Gegner, der sich auf 8 Meter nähert, was ihm 3874 körperlichen Schaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184017] = {name = "[q4]Bargasts Leine", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Geht für 30 Sek. ein Band des Jägersmanns mit dem anvisierten Verbündeten ein. 25% des von Euch erlittenen Schadens werden auf diesen Verbündeten umgeleitet, bis zu insgesamt [ 11389 * (1 + Vielseitigkeit)] Schaden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184018] = {name = "[q4]Zersplittertes Herz von Al'ar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Absorbiert bis zu 10234 Schaden eines sonst tödlichen Angriffs. Wenn dieser Effekt auftritt, brecht Ihr in Flammen aus, fügt Verbündeten und Gegnern in der Nähe [ 2433 * (1 + Vielseitigkeit)] Feuerschaden zu und stellt [ 7025 * (1 + Vielseitigkeit)] Gesundheit wieder her.\n\n Dieser Effekt kann nur einmal alle 8 Min. auftreten.\nVerkaufspreis:"}
MultiLanguageItemData['de'][184019] = {name = "[q4]Seelenzünder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\n[q2]Benutzen: Aktiviert den Seelenzünder und opfert bis zu 2157 Gesundheit im Verlauf von 15 Sek., um 'Lodernde Woge' zu ermächtigen.\n\n Aktiviert ihn erneut, um 'Lodernde Woge' einzusetzen, was Gegnern in einem kegelförmigen Bereich von 40 Metern [ 1541 * (1 + Vielseitigkeit)] Feuerschaden zufügt, die gleichmäßig aufgeteilt werden, und abhängig davon, wie lang der Seelenzünder aktiv war, ihnen zusätzlich bis zu 40% Schaden zufügt.\n\n Der Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern. (1 Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184020] = {name = "[q4]Büschel schwelendes Gefieder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\n[q2]Benutzen: Stärkt Euren Verbündeten mit einem Büschel Phönixfedern, das ihn nach 6 Sek. um [ 5199 * (1 + Vielseitigkeit)] Gesundheit heilt. Dieser Wert erhöht sich abhängig von der fehlenden Gesundheit des Ziels um bis zu 25%. Wenn Euer Verbündeter tödlichen Schaden erleidet, wird dieser Effekt sofort ausgelöst. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184021] = {name = "[q4]Glyphe der Assimilierung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\n[q2]Benutzen: Fügt einem Gegner im Verlauf von 10 Sek. 1786 Arkanschaden zu.\n\n Wenn Euer Ziel stirbt, während es mit 'Glyphe der Assimilierung' belegt ist, wird Eure Meisterschaft für das 2-Fache der verbleibenden Dauer der Glyphe um 160 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184022] = {name = "[q4]Zehrende Infusion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\n[q2]Anlegen: Wenn Ihr einen Schadenszauber einsetzt, gewährt Eure nächste Einzelzielheilung für 30 Sek. 138 Lebensraub. Dieser Effekt kann nur einmal alle 10 Sek. auftreten.\nVerkaufspreis:"}
MultiLanguageItemData['de'][184023] = {name = "[q4]Gefräßiger Stachel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Stärke\n[q2]Anlegen: Eure Schadensfähigkeiten haben eine hohe Chance, 116 körperlichen Schaden zu verursachen und Euch um 300% des verursachten Schadens zu heilen. Bei überschüssiger Heilung dieses Effekts fügt Ihr Gegnern in der Nähe im Verlauf von 15 Sek. [ 98 * 5 * (1 + Vielseitigkeit)] körperlichen Schaden zu, der auf die Gegner aufgeteilt wird. Dies unterdrückt jedoch den Lebensdiebstahleffekt.\n\n Der Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern.\nVerkaufspreis:"}
MultiLanguageItemData['de'][184024] = {name = "[q4]Makabres Notenblatt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Vier Tanzpartner erscheinen in einer zufälligen Aufstellung um Euch herum. Jeder von ihnen gewährt Euch stapelbar 20 Sek. lang 40 Tempo und 23 Geschwindigkeit, wenn Ihr Euch zu ihm hinbewegt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184025] = {name = "[q4]Erinnerung an vergangene Sünden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Eure nächsten 5 Schaden verursachenden Fähigkeiten rufen 'Kollabierte Psyche' hervor, was 651 Schattenschaden verursacht und den durch 'Kollabierte Psyche' erlittenen Schaden des Ziels für 5 Sek. um 1% erhöht. Bis zu 25-mal stapelbar. (1.5s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][184026] = {name = "[q4]Hasserfüllte Kette", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Beweglichkeit\n[q2]Anlegen: Wenn Eure prozentuale Gesundheit höher ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, [ 181 * (1 + Vielseitigkeit)] körperlichen Schaden zu verursachen.\n\n Wenn Eure prozentuale Gesundheit niedriger ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, Euch um [ 247 * (1 + Vielseitigkeit)] Gesundheit zu heilen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][184027] = {name = "[q4]Wappenbuch der Steinlegion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Verkündet Eure Treue zur Steinlegion, was Eure Vielseitigkeit um 43 erhöht. Dieser Wert erhöht sich pro Steinlegionär in Eurer Gruppe um 5%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][184028] = {name = "[q4]Gesangbuch des Kabalisten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 Intelligenz\n[q2]Anlegen: Tretet dem blutroten Chor bei. Jede Minute schwillt Euer kritischer Trefferwert im Verlauf von 30 Sek. um ( 43 * 3) an, bevor er auf den normalen Wert zurücksinkt. Dieser Effekt erhöht sich pro Mitglied des blutroten Chors in Eurer Gruppe um 5%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][184029] = {name = "[q4]Managebundener Spiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 Intelligenz\n[q2]Anlegen: Speichert pro 3240 verbrauchtem Mana [ 277 * (1 + Vielseitigkeit)] Heilung für 30 Sek. im Spiegel, bis zu [ 2307 * (1 + Vielseitigkeit)] Heilung.\n[q2]Benutzen: Heilt Euer Ziel um [ 1586 * (1 + Vielseitigkeit)] Gesundheit und zusätzlich um sämtliche im Spiegel gespeicherte Heilung. (1 Min Abklingzeit)\nVerkaufspreis:"}
