MultiLanguageItemData['de'][184615] = {name = "[q2]Außerdimensionale Taschen", additional_info = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt in Torghast zusätzlichen Lagerplatz, sodass mehr Obleronausrüstung gefunden werden kann.\nVe'nari muss Euch gegenüber besorgt oder positiver eingestellt sein.\n[q]\"Der Innenraum dieser Taschen ist viel größer als ihr äußeres Erscheinungsbild.\""}
MultiLanguageItemData['de'][184617] = {name = "[q3]Reif des Vorrangs", additional_info = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: In Torghast besteht eine Chance, dass Mittlerhändler Euch ungewöhnliche Optionen anbieten.\nVe'nari muss Euch gegenüber unverbindlich oder positiver eingestellt sein.\n[q]\"Dieser Reif verdeutlichte einst den Status Ve'naris im Kartell Ve. Nun gehört er Euch.\""}
MultiLanguageItemData['de'][184618] = {name = "[q4]Rangabzeichen: Akquisiteur", additional_info = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: In Torghast besteht eine Chance, dass Mittlerhändler Euch eine seltene Option anbieten.\nVe'nari muss Euch gegenüber herzlich oder positiver eingestellt sein.\n[q]\"Dies weist Euch als ein Stellvertreter des Kartells Ve aus. Dies seid Ihr definitiv nicht, aber das wissen sie ja nicht.\""}
MultiLanguageItemData['de'][184619] = {name = "[q4]Lupe des bezaubernden Charmes", additional_info = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: In Torghast bietet Euch ein Mittlerhändler gelegentlich Animaschätze zu vergünstigten Preisen an.\nVe'nari muss Euch gegenüber herzlich oder positiver eingestellt sein.\n[q]\"Ve'nari hat diese Juwelierslupe mit einem Anziehungszauber versehen, der manche Mittler dazu bewegt, Euch Sonderangebote zu unterbreiten.\""}
MultiLanguageItemData['de'][184620] = {name = "[q2]Gefäß der unglückseligen Geister", additional_info = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Euer erster Tod in Torghast zählt nicht.\nVe'nari muss Euch gegenüber besorgt oder positiver eingestellt sein.\n[q]\"Gefährliche Magie verknüpft das Schicksal desjenigen, der dieses Gefäß ergreift, mit demjenigen des Geistes, der darin wohnt.\""}
MultiLanguageItemData['de'][184621] = {name = "[q4]Ritualprisma der Wahrsagung", additional_info = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: In Torghast ist Eure Chance, epische Animaboni zu erhalten, dauerhaft erhöht.\nVe'nari muss Euch gegenüber zwiespältig oder positiver eingestellt sein.\n[q]\"Ve'nari hat in diesen Kristall Glyphen eingraviert, die angeblich gegen die Launen des Schicksals schützen.\""}
