MultiLanguageItemData['de'][186099] = {name = "[q4]Apparat für räumliche Neuausrichtung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt einem Gegenstand der Saison 1 von Shadowlands, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Halsketten, Armschienen, Gürtel und Ringe angewandt werden.\n[q]\"Dieses Gerät lässt in Eurer Ausrüstung einen räumlichen Miniaturriss entstehen, in den ein Edelstein genau passt.\""}
MultiLanguageItemData['de'][186101] = {name = "Schlüssel des Verhörers", additional_info = "Questgegenstand\n[q]\"Für jedes Schloss gibt es einen Schlüssel. Dieser Schlüssel ist für den Käfig, in dem Archivarin Roh-Senara gefangen ist.\""}
MultiLanguageItemData['de'][186102] = {name = "Lady Mondbeeres Zauberstab", additional_info = "Questgegenstand\n[q2]Benutzen: Verwendet den Zauberstab, um den anvisierten Gegner zu schrumpfen oder die anvisierte Schlundratte zu vergrößern. (10 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][186103] = {name = "[q4]Geschirr des unvergänglichen Schattenhunds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Teile des unvergänglichen Schattenhunds haben schon viele Schlachtfelder geziert, doch dieser jüngste Kampf war womöglich das erste Mal, dass sie alle zusammen gekämpft haben.\"\nBeute von:\nKriegskasse der Unvergänglichen Armee\nZone:\nDer Schlund"}
