MultiLanguageItemData['de'][186421] = {name = "[q4]Verbotener nekromantischer Foliant", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Intelligenz\n[q2]Anlegen: Eure Schaden verursachenden Zauber haben eine Chance, Euren kritischen Trefferwert für 15 Sek. um 48 zu erhöhen. Bis zu 3-mal stapelbar.\n[q2]Benutzen: Belebt die Überreste eines gefallenen Verbündeten für 30 Sek. als Skelettkrieger wieder. (10 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][186422] = {name = "[q4]Foliant der monströsen Konstruktionen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Benutzen: Studiert den Folianten und findet so die Schwäche des anvisierten Gegners heraus. Eure Schaden verursachenden Fähigkeiten haben eine sehr hohe Chance, Eurem studierten Gegner zusätzlich 229 Schattenschaden zuzufügen.\n\n Beim Studieren eines neuen Gegners gehen die Vorteile früherer Studien verloren. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][186423] = {name = "[q4]Titanische Okulardrüse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Solange Eure Gesundheit über 50% liegt, werdet Ihr als 'Würdig' erachtet, was Euren höchsten Sekundärwert um 73 erhöht. Wenn Eure Gesundheit unter 50% liegt, werdet Ihr als 'Unwürdig' erachtet, was Euren höchsten Sekundärwert um 73 verringert.\n[q]\"Ein Preis, der vor langer Zeit für Wissen und Macht gezahlt wurde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][186424] = {name = "[q4]Splitter von Annhyldes Aegis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Schützt Euch mit Annhyldes Aegis, die 8 Sek. lang den Schaden, den Ihr durch Gegner vor Euch erleidet, um 2015 verringert.\n\n Wenn die Aegis mindestens 7052 Schaden absorbiert, wird sie überladen und stößt bei ihrem Ablauf gebündelte Macht aus, die allen Gegnern vor Euch 1123 Heiligschaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][186425] = {name = "[q4]Hingekritzeltes Wort des Rückrufs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Benutzen: Verringert die verbleibende Abklingzeit Eures passenden Heilzaubers um 4 Sek.\n\nGilt nur für Heilerspezialisierungen. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][186427] = {name = "[q4]Flüsternder Splitter der Macht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Stärke\n[q2]Anlegen: Eine Stimme flüstert Euch zu und zwingt Euch regelmäßig, ihren Anordnungen Folge zu leisten. Wenn Ihr dies tut, werdet Ihr für 20 Sek. mit einer Erhöhung Eures höchsten Sekundärwerts um 210 belohnt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][186428] = {name = "[q4]Schattenkugel der Qual", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Benutzen: Blickt in die Kugel, was Eure Meisterschaft für bis zu 40 Sek. um 301 erhöht, Euch aber im Verlauf von 2 Sek. ( 1263 * 4) Schattenschaden zufügt. Je länger Ihr hineinblickt, desto mehr werdet Ihr gequält und desto mehr Einsicht erhaltet Ihr. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][186429] = {name = "[q4]Karaffe des endlosen Heulens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 63.\n[q2]Anlegen: Eure kritischen Treffer haben eine Chance, Eure Stärke oder Beweglichkeit für 15 Sek. um 162 zu erhöhen. Falls Ihr dabei weniger als 50% Gesundheit habt, werdet Ihr zusätzlich im Verlauf von 6 Sek. um ( 525 * 4) Gesundheit geheilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][186430] = {name = "[q4]Streckbankfragment der Pein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, im Verlauf von 15 Sek. [ 218 * (4)] zusätzlichen Schattenschaden zu verursachen.\n\n Wenn ein Ziel stirbt, während es vom Streckbankfragment des Peinigers betroffen ist, hinterlässt es eine zerfetzte Seele, die Ihr einsammeln könnt, um Euren kritischen Trefferwert für 20 Sek. um 19 zu erhöhen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][186431] = {name = "[q4]Schwarzseelenzwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Benutzen: Verflucht einen Gegner und fügt ihm 12 Sek. lang alle 2 Sek. 307 Schattenschaden zu. Die Dauer erhöht sich abhängig von der fehlenden Gesundheit des Ziels um bis zu 100%. (1 Min. 30 Sek. Abklingzeit) (1 Min, 30 Sek. Abklingzeit)\n[q2]Anlegen: Wenn ein Ziel stirbt, während es von der Schwarzseelenzwinge betroffen ist, hinterlässt es eine zerfetzte Seele, die Ihr einsammeln könnt, um Euren kritischen Trefferwert für 20 Sek. um 19 zu erhöhen.\nVerkaufspreis:"}
