MultiLanguageItemData['de'][186433] = {name = "[q4]Reaktive Verteidigungsmatrix", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Beim Erleiden von Schaden besteht eine Chance, dass Eure reaktive Verteidigungsmatrix ausgelöst wird und die nächsten 2293 erlittenen Schaden auf den Angreifer zurückwirft.\n\n Die reaktive Verteidigungsmatrix wird automatisch ausgelöst, wenn Eure Gesundheit unter 20% fällt. Dieser Effekt kann nur einmal alle 30 Sek. ausgelöst werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][186434] = {name = "[q4]Gespinst aus verzerrten Schicksalen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Wenn Ihr getötet werdet und dabei maximal 16413 Schaden über den Tod hinaus erleidet, spult das Gespinst aus verzerrten Schicksalen Euer Schicksal zurück, ruft Euch so ins Leben zurück und heilt Euch um [ 16549 * (1 + Vielseitigkeit)] Gesundheit.\n\n Dieser Effekt kann einmal alle 8 Min. auftreten.\nVerkaufspreis:"}
