MultiLanguageItemData['de'][186565] = {name = "[q5]Erinnerung an die rasende Übertragung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRasende Übertragung Runenschnitzmacht Sofort\nDie durch 'Recht des Todes' erhaltene Stärke ist um 3% erhöht und hält 2 Sek. länger an. Während Ihr Euch im Effektbereich von 'Recht des Todes' aufhaltet, ist Eure Runenmachterzeugung um 20% erhöht.\nRunenschnitzen: Brust, Taille\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Todesritter"}
MultiLanguageItemData['de'][186566] = {name = "[q5]Erinnerung an das endgültige Urteil", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEndgültiges Urteil Runenschnitzmacht Sofort\nWenn ein Gegner mit 'Fesseln der Unwürdigen' belegt wird, erhaltet Ihr sofort eine Rune und Euer Schaden wird um 4% erhöht. Hält 15 Sek. lang an und ist bis zu 20% stapelbar.\nRunenschnitzen: Kopf, Schulter, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Todesritter"}
MultiLanguageItemData['de'][186567] = {name = "[q5]Erinnerung an den unstillbaren Hunger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nUnstillbarer Hunger Runenschnitzmacht Sofort\nWenn 'Schwärmender Nebel' endet, fügt die Fähigkeit 5 Gegnern in der Nähe (86.42% der Angriffskraft) Schattenschaden zu und heilt Euch um 25% des verursachten Schadens. Der Schaden erhöht sich pro 1 Runenmacht, die Ihr verbraucht habt, während 'Schwärmender Nebel' aktiv war, um 2%.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Todesritter"}
MultiLanguageItemData['de'][186568] = {name = "[q5]Erinnerung an die Raserei der Monstrosität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRaserei der Monstrosität Runenschnitzmacht Sofort\nDie Dauer von 'Monströse Gliedmaße' ist um 4 Sek. erhöht und die Fähigkeit gewährt [ Blut : 'Knochenschild' / Frost : 'Raureif' / Unheilig : 'Runenverderbnis' ] mit 2 Sek. schnellerer Frequenz. Zusätzlich erleiden Gegner, nachdem sie das erste Mal Schaden durch 'Monströse Gliedmaße' erlitten haben, 12 Sek. lang 20% mehr Schaden durch Euch. (20s Abklingzeit)\nRunenschnitzen: Füße, Handgelenk, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Todesritter"}
MultiLanguageItemData['de'][186569] = {name = "Aufgewühltes Nadlernest", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft das Nest auf einen Herold, was seine Konzentration stört und ihn verwundbar durch Angriffe macht. (15 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][186570] = {name = "[q5]Erinnerung an den Ruhm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nRuhm Runenschnitzmacht Sofort\n'Banner des Eroberers' wirkt sich auf 1 zusätzlichen Verbündeten aus und pro [ Waffen : 20 ] [ Furor : 25 /\n\nSchutz\n10 ] Wut, die Ihr verbraucht, während das Banner aktiv ist, wird seine Dauer um 0.5 Sek. verlängert.\nRunenschnitzen: Brust, Taille\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Krieger"}
MultiLanguageItemData['de'][186572] = {name = "[q5]Erinnerung an die sündhafte Woge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSündhafte Woge Runenschnitzmacht Sofort\n'Verurteilen' erhöht die Effektdauer von [ Waffen : 'Kolossales Schmettern' um 1.5 Sek ] [ Furor : 'Tollkühnheit' um 2.0 Sek /\n\nSchutz\n'Avatar' um 2.5 Sek ] (500ms Abklingzeit)\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Krieger"}
