MultiLanguageItemData['de'][186637] = {name = "[q4]Gleitscheibe von Tazavesh", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Mittler aller Art benutzen diese Gleiter, um durch Tazavesh und zu ähnlichen nahegelegenen Außenposten zu reisen. Auch Waren lassen sich damit transportieren.\"\nErfolg:\nGut gefälscht ist halb gewonnen\nKategorie:\nDungeon von Shadowlands"}
MultiLanguageItemData['de'][186638] = {name = "[q4]Gleitscheibe des Kartellmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur die reichsten Kartellführer können sich die Metalle leisten, die für die Herstellung der Gleitscheibe des Kartellmeisters benötigt werden.\"\nBeute von:\nSo'leah\nZone:\nTazavesh, der Verhüllte Markt"}
MultiLanguageItemData['de'][186639] = {name = "[q4]Gleitscheibe des Treuhänders Xy", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Kartell Xy handelt mit allerlei Währungen, doch keine davon ist ihrem inneren Zirkeln mehr Wert als Loyalität.\"\nQuelle:\n[ZENSIERT]"}
MultiLanguageItemData['de'][186640] = {name = "[q4]Vandals Gleitscheibe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein seltener, speziell angepasster Gleiter, der besonders bei heimlichen Treffen zum Einsatz kommt. Er ist so leise, dass er kaum auszumachen ist, was ihn zu einem beliebten Werkzeug jener macht, die aus den Schatten heraus arbeiten.\"\nFraktion:\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt"}
MultiLanguageItemData['de'][186641] = {name = "[q4]Harnisch des gezähmten Zerfleischers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Um Verschlinger zu zähmen, braucht man nur ein wenig Anima und eine Menge Geduld. Und eine Menge Heiltränke.\"\nBeute von:\nVorräte des Archivarskodex\nZone:\nKorthia"}
MultiLanguageItemData['de'][186642] = {name = "[q4]Zügel von Rache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Sylvanas verlor einen Teil ihrer selbst, als Arthas ihr das Leben nahm, und die Dunkelheit in ihr wuchs an, um die Leere auszufüllen.\"\nBeute von:\nFürstin Sylvanas Windläufer\nZone:\nSanktum der Herrschaft\nSchwierigkeitsgrad:\nMythisch"}
MultiLanguageItemData['de'][186643] = {name = "[q4]Zügel der Wanderin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese neugierige und wissbegierige Hirschkuh will ihren Besitzer nicht beunruhigen, aber sie lässt sich eben leicht ablenken. Besonders bei all den neuen Dingen, die es in Korthia zu sehen gibt.\"\nZone:\nKorthia"}
MultiLanguageItemData['de'][186644] = {name = "[q4]Beryllsplitterfell", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Splitterfelle können sich gut im Unterholz verstecken und gezähmte Exemplare sind besonders selten.\"\nBeute von:\nVorräte des Vorstoßes des Todes\nZone:\nKorthia"}
MultiLanguageItemData['de'][186645] = {name = "[q4]Blutrotes Splitterfell", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als Korthia in den Schlund gezogen wurde, überlebten nur wenige besonders widerstandsfähige Arten.\"\nBeute von:\nMalbog\nZone:\nKorthia"}
MultiLanguageItemData['de'][186646] = {name = "[q4]Finsterpranke", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Finsterpranke ist ein älteres Splitterfell und trat den Korthianern zumeist recht zahm und freundlich gegenüber. Man glaubte, er sei in der Katastrophe verloren gegangen.\"\nZone:\nKorthia"}
MultiLanguageItemData['de'][186647] = {name = "[q4]Bernsteinsplitterfell", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtVorstoß des Todes\n- Respektvoll\n\n\n[q]\"Die leuchtenden Farben der korthianischen Wildtiere deuten darauf hin, dass ihnen entweder nur wenige Raubtiere auflauern oder sie sich zu wehren wissen.\"\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nFraktion:\nVorstoß des Todes - Respektvoll\nKosten:\n5.000"}
MultiLanguageItemData['de'][186648] = {name = "[q4]Segelnde Klingenschwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtDer Archivarskodex\n- Stufe 6\n\n\n[q]\"Die Haut der Klingenschwinge ist einerseits leicht, was ihr das Fliegen ermöglicht, aber andererseits auch recht robust, wodurch sie den Weg in den Schlund zu überleben vermag.\"\nVerkäufer:\nArchivar Roh-Suir\nZone:\nKorthia\nFraktion:\nDer Archivarskodex - Stufe 6\nKosten:\n5000"}
MultiLanguageItemData['de'][186649] = {name = "[q4]Grimmige Klingenschwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Klingenschwingen halten sich im Allgemeinen von anderen korthianischen Spezies fern, aber mit etwas Zeit und Geduld lassen auch sie sich zähmen.\"\nBeute von:\nVorräte des Vorstoßes des Todes\nZone:\nKorthia"}
MultiLanguageItemData['de'][186650] = {name = "[q3]Vorräte des Vorstoßes des Todes", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][186651] = {name = "[q4]Dämmerlichtklingenschwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Klingenschwingen sind in ganz Korthia beheimatet. Sie bauen ihre Nester auf hohen Hügeln und in Bäumen.\"\nZone:\nKorthia"}
MultiLanguageItemData['de'][186652] = {name = "[q4]Granatklingenschwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Korthia war einst für seine leuchtend roten Blumen bekannt. Von mehreren Wildtieren weiß man, dass sie diese verzehrten oder sich darin wälzten, um eine leuchtend rote Färbung anzunehmen.\"\nBeute von:\nReliwik der Trotzige\nZone:\nKorthia"}
MultiLanguageItemData['de'][186653] = {name = "[q4]Armschiene von Hrestimorak", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der niederträchtige Verrat von Hrestimorak, der ihn auf Kosten seines Volkes an die Macht brachte, ist fast schon legendär. Als ihm die Verdammnis im Schlund drohte, versuchte er, den Kerkermeister zu stürzen... Ein törichtes Unterfangen, das ihm eine Ewigkeit voller Qualen einbrachte.\"\nErfolg:\nRuhm des herrschenden Schlachtzüglers\nZone:\nSanktum der Herrschaft"}
MultiLanguageItemData['de'][186654] = {name = "[q4]Armreif von Salaranga", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Salaranga war die gerissenste ihrer Art und versteckte sich im Bestienlabyrinth. Sie griff den Verbannten mit einer Horde aus verbündeten Bestien an, auch wenn dies letztendlich keinen Unterschied machte.\"\nErfolg:\nDie Ketten durchbrechen\nZone:\nKorthia und der Schlund"}
MultiLanguageItemData['de'][186655] = {name = "[q4]Zügel des schlundgebundenen Streitrosses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das Schicksal aller Pferdereittiere.\"\nErfolg:\nMakelloser Meister\nZone:\nTorghast, Turm der Verdammten"}
MultiLanguageItemData['de'][186656] = {name = "[q4]Zügel des Sanktumdämmerstreitrosses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur die mächtigsten Leutnants des Kerkermeisters erhalten diese Rösser, um durch die Hallen des Turms zu reiten.\"\nBeute von:\nDie Neun\nZone:\nSanktum der Herrschaft"}
MultiLanguageItemData['de'][186657] = {name = "[q4]Zügel des seelengebundenen Dämmerstreitrosses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ve'nari hat viele Methoden, im Schlund herumzuschleichen und die Pläne des Kerkermeisters zu durchkreuzen, darunter auch das Binden seiner Diener.\"\nBeute von:\nGeheimnisvolles Geschenk von Ve'nari\nZone:\nDer Schlund"}
MultiLanguageItemData['de'][186659] = {name = "[q4]Zügel des gefallenen Streitrosses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Schreie des Streitrosses hallen durch den Schlund, während es seinen endlosen Ritt durch das Land fortsetzt, immer auf der Suche nach einem Ausweg aus den endlosen Qualen, denen es ausgesetzt ist.\"\nBeute von:\nGefallenes Streitross\nZone:\nDer Schlund"}
