MultiLanguageItemData['de'][186671] = {name = "Vantusrunentechnik: Sanktum der Herrschaft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine Vantusrune: Sanktum der Herrschaft herstellt.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis: \nVantusrune: Sanktum der Herrschaft\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Sanktum der Herrschaft ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leuchtende Tinte (10), Umbraltinte (10), Stille Tinte , Dunkles Pergament"}
MultiLanguageItemData['de'][186672] = {name = "Vergängliche Schwingen", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Springt auf vergänglichen Schwingen vorwärts, die die Fallgeschwindigkeit 10 Sek. lang verringern. Springt dann zu einer Position in der Nähe. (6 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][186673] = {name = "[q5]Erinnerung an die Seelenaffinität", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSeelenaffinität Stufe 80 Runenschnitzmacht Sofort\nIhr und die Euch verwandte Seele erhaltet jeweils einen Bonus auf einen Sekundärwert, der von ihrem Pakt abhängt. Für Eure verwandte Seele wird dieser Bonus halbiert, jedoch werden beide Boni verdoppelt, während Eure Verbindung ermächtigt ist.\n\nKyrianer : Meisterschaft um 571 erhöht.\nNachtfae : Tempo um 6% erhöht.\nVenthyr : Kritische Trefferchance um 6% erhöht.\nNekrolords : Vielseitigkeit um 6% erhöht.\nRunenschnitzen: Hals, Schulter\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Druide"}
MultiLanguageItemData['de'][186676] = {name = "[q5]Erinnerung an die toxische Offensive", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nToxische Offensive Runenschnitzmacht Sofort\nWenn 'Sepsis' bei Eurem Ziel abläuft, erhaltet Ihr für 10 Sek. [ Meucheln : 'Adrenalinrausch' und 'Schattenklingen' ] [ Gesetzlosigkeit : 'Schattenklingen' und belegt Euer aktuelles Ziel für diese Dauer mit 'Vendetta' ] [ Täuschung : 'Adrenalinrausch' und belegt Euer aktuelles Ziel für diese Dauer mit 'Vendetta' ]\nRunenschnitzen: Brust, Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke"}
