MultiLanguageItemData['de'][186679] = {name = "[q3]Schriftrolle der Herrschaft", additional_info = "Torghast, Turm der Verdammten\n[q2]Benutzen: Lässt Euch ein gegnerisches Nicht-Eliteziel für 2 Min. kontrollieren. Wenn die Rune schwindet, explodiert das kontrollierte Ziel und fügt allen Zielen in der Nähe Schaden zu. (5 Min Abklingzeit)\n[q]\"Starrt besser nicht zu lange auf die Runen.\""}
