MultiLanguageItemData['de'][186708] = {name = "[q2]Goldgefüllter Pinselbecher", additional_info = "Wird beim Aufheben gebunden\n[q]\"Normalerweise stellt niemand irgendwelche Fragen zu den seltsamen Interessen von Gräbern. Erst recht nicht, wenn ein Gräber so unverzichtbare Dienste anbietet wie die Reparatur von Ausrüstung.\"\n[q2]<Zum Öffnen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][186710] = {name = "[q5]Erinnerung an die Gehorsamen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGehorsam Runenschnitzmacht Sofort\n'Geißelung' erhöht zusätzlich Eure Vielseitigkeit um 0.5%. Jeder Combopunkt, der verbraucht wird, während 'Geißelung' aktiv ist, verringert die Abklingzeit der Fähigkeit um 1 Sek. (100ms Abklingzeit)\nRunenschnitzen: Kopf, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke"}
MultiLanguageItemData['de'][186712] = {name = "[q5]Erinnerung an den Todesstachel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTodesstachel Runenschnitzmacht Sofort\n'Gezackter Knochenstachel' hat 2 zusätzliche Aufladungen und verschießt 1 zusätzlichen Knochenstachel auf Gegner in der Nähe.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke"}
MultiLanguageItemData['de'][186713] = {name = "[q4]Nilganihmahts Steuerungsring", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Von allen Riesen, die es wagten, dem Kerkermeister zu trotzen, war Nilganihmaht der arroganteste. Für sein Vergehen wurde die abgetrennte Hand des Riesen in einem Schleier der Qualen verborgen und die Ringe, die sie zurückbringen könnten, wurden über den ganzen Schlund verstreut.\"\nZone:\nDer Schlund"}
MultiLanguageItemData['de'][186714] = {name = "[q3]Untersuchungsbericht: Allsehender Kristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht Euch dauerhaft, Kreaturen zu sehen und zu finden, die Reliktfragmente tragen.\nErfordert Forschungsstufe 2 beim Archivarskodex.\n[q]\"Es ist Roh-Suir gelungen, die Forschung zum allsehenden Kristall zu replizieren, sodass Ihr nun einen dieser Kristalle an einem Leitstab befestigen könnt, um andere Relikte aufzuspüren.\""}
MultiLanguageItemData['de'][186715] = {name = "[q3]Untersuchungsbericht: Verbesserte Legierungen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht Euch, Eure Gegenstände aus Korthia und dem Schlund auf Rang 10 aufzuwerten.\n[q]\"Die Analyse der Auswirkungen der Herrschaftsmagie auf Gegenstände aus Korthia und dem Schlund hat zur Entwicklung verbesserter Legierungen geführt, durch die wir unsere eigenen Gegenstände widerstandsfähiger und mächtiger machen können.\""}
MultiLanguageItemData['de'][186716] = {name = "[q3]Untersuchungsbericht: Uralte Schreine", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht Euch, mit Schwertern in der Nähe von uralten Schreinen zu interagieren, die Euch auf ansonsten nicht zugängliche Reliktschätze zugreifen lassen.\nErfordert Forschungsstufe 5 beim Archivarskodex.\n[q]\"Weitere Untersuchungen der mysteriösen Chiffre des Erkenntnis, die Ihr aus dem Riss geborgen habt, haben es uns ermöglicht, die Wechselwirkung mit den uralten Schreinschwertern zu verstehen, die man in ganz Korthia findet.\""}
MultiLanguageItemData['de'][186717] = {name = "[q3]Untersuchungsbericht: Adaptive Legierungen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht Euch, Eure Gegenstände aus Korthia und dem Schlund auf Rang 5 aufzuwerten.\nErfordert Forschungsstufe 6 beim Archivarskodex und Ruhmstufe 61 oder höher.\n[q]\"Weitere Untersuchungen im Zuge der Reliktwiederbeschaffung haben zur Entdeckung neuer adaptiver Legierungen geführt, die es uns ermöglichen werden, die Macht der von Herrschaftsmagie berührten Objekte in Korthia und im Schlund zu erhöhen.\""}
MultiLanguageItemData['de'][186718] = {name = "[q2]Reparaturset für Teleporter", additional_info = "Wird beim Aufheben gebunden\nErfordert Forschungsstufe 3 beim Archivarskodex.\n[q]\"Eine Sache scheint wohl überall im Universum gleich zu sein: Schon so lang die Zeit vergeht, wird stets nach rechts fest zugedreht. Wird benötigt, um uralte Teleporter in Korthia zu reparieren, sodass Ihr Zugang zu verborgenen Kammern erhaltet.\""}
MultiLanguageItemData['de'][186721] = {name = "[q3]Abhandlung: Die Fülle an Relikten in den Schattenlanden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Euch dauerhaft die Fähigkeit, Relikte zu finden, die Euch Bonusruf bei den Zonenfraktionen der Schattenlande gewähren, wenn Ihr in ihren Reichen Weltquests und tägliche Quests abschließt, Schätze plündert oder seltene Kreaturen besiegt.\nErfordert Forschungsstufe 6 beim Archivarskodex."}
MultiLanguageItemData['de'][186722] = {name = "[q3]Abhandlung: Das Studium der Anima und die Nutzung jedes Tropfens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Euch dauerhaft die Fähigkeit, 25 zusätzliche Anima zu finden, wenn Ihr in den Schattenlanden Weltquests und tägliche Quests abschließt, Schätze plündert oder seltene Kreaturen besiegt.\nErfordert Forschungsstufe 5 beim Archivarskodex."}
MultiLanguageItemData['de'][186724] = {name = "[q2]Technik: Vertrag: Vorstoß des Todes", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Vertrag: Vorstoß des Todes herstellt.\nBenötigt Inschriftenkunde der Schattenlande (60)\nBenötigtVorstoß des Todes\n- Respektvoll\nVerkaufspreis: \nVertrag: Vorstoß des Todes\n[q2]Benutzen: Schließt einen Vertrag mit dem Vorstoß des Todes ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\nBenötigtVorstoß des Todes\n- Freundlich\nBenötigt Leuchtende Tinte , Umbraltinte , Dunkles Pergament"}
MultiLanguageItemData['de'][186725] = {name = "Knochenmehlbrot", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben."}
