MultiLanguageItemData['de'][187056] = {name = "[q4]Die verschlingende Kälte", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Schwert}\n55 - 92 Schaden Geschwindigkeit 2.60\n(28.3 Schaden pro Sekunde)\n+25 Stärke\n+37 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 35.\n[q2]+ 14 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:"}
MultiLanguageItemData['de'][187057] = {name = "[q4]Splitter von Bek", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Blutsplitter von Bek (1)\nIm Schlund wird Euer Schaden um ( 6046 / 100)% erhöht, wenn Ihr mindestens 50% mehr Gesundheit habt als Euer Ziel.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187059] = {name = "[q4]Splitter von Jas", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Blutsplitter von Jas (1)\nErhöht im Schlund Eure erhaltene Heilung um ( 302 / 10)% und Eure maximale Gesundheit um 44844 .\nVerkaufspreis:"}
MultiLanguageItemData['de'][187061] = {name = "[q4]Splitter von Rev", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Blutsplitter von Rev (1)\nIm Schlund ist Euer Lebensraub um 1209 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187063] = {name = "[q4]Splitter von Cor", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Cor (1)\nWenn Ihr im Schlund einen Gegner angreift, dem Ihr zuvor noch keinen Schaden zugefügt habt, wird Euer Schaden 20 Sek. lang um ( 6046 / 100)% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187065] = {name = "[q4]Splitter von Kyr", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Kyr (1)\nGewährt im Schlund alle 5 Sek. ( 98657 * (1 + Vielseitigkeit)) Absorption, bis zu maximal 493286 .\nVerkaufspreis:"}
MultiLanguageItemData['de'][187071] = {name = "[q4]Splitter von Tel", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Tel (1)\nIm Schlund lassen Eure kritischen Treffer einen Verbündeten in der Nähe die nächsten ( 25561 * (1 + Vielseitigkeit)) Schaden absorbieren, die er innerhalb von 6 Sek. erleidet.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187073] = {name = "[q4]Splitter von Dyz", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Dyz (1)\nWenn Ihr im Schlund einem Ziel Schaden zufügt, wird Euer diesem Ziel zugefügter Schaden 4 Sek. lang um ( 1008 / 100)% erhöht. Bis zu 3-mal stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187075] = {name = "[q3]Kiste mit rasselnden Ketten", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Entfesselt den Minigrue, der einige Spielzeuge in der Nähe zerstören wird. (30 Min Abklingzeit)"}
MultiLanguageItemData['de'][187076] = {name = "[q4]Splitter von Oth", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Oth (1)\nIm Schlund ist Eure Geschwindigkeit ist um 1209 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187077] = {name = "[q7]Verpackte Seelenasche", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Öffnen, um 250 Seelenasche zu erhalten.\nIhr müsst die 9. Ebene von Torghast freigeschaltet haben.\n[q]\"Für einfachen Transport verpackt. Eine beträchtliche Menge Seelenasche ging aufgrund ihrer flüchtigen Natur verloren.\""}
