MultiLanguageItemData['de'][187103] = {name = "[q3]Ewiglebende Statuette", additional_info = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Ereignisse, die diese Statuette miterlebt hat, spotten jeder Vorstellungskraft. Man könnte viel daraus lernen, wenn sie nur nicht so doppelzüngig wäre.\""}
MultiLanguageItemData['de'][187104] = {name = "[q3]Obelisk düsterer Kunde", additional_info = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"In der Nähe des Obelisken flüstert eine Stimme in Eurem Kopf Euch liebliche Lügen und erzürnende Wahrheiten zu.\""}
MultiLanguageItemData['de'][187105] = {name = "[q5]Erinnerung an den Blick der Agonie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBlick der Agonie Runenschnitzmacht Sofort\n'Sündhaftes Brandzeichen' verursacht 10% mehr Schaden und Schaden durch [ Verwüstung : 'Augenstrahl' /\n\nRachsucht\n'Dämonische Verwüstung' ] erhöht die Dauer von 'Sündhaftes Brandzeichen' um 0.75 Sek.\nRunenschnitzen: Kopf, Beine\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][187106] = {name = "[q5]Erinnerung an die göttliche Resonanz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nGöttliche Resonanz Runenschnitzmacht 30 Meter Reichweite\n Sofort\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. [ Schutz : 'Schild des Rächers' ] [ Heilig : 'Heiliger Schock' /\n\nVergeltung\n'Richturteil' ] ein. Dieser Effekt hält 15 Sek. lang an. (3s Abklingzeit)\nRunenschnitzen: Brust, Taille\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin"}
MultiLanguageItemData['de'][187107] = {name = "[q5]Erinnerung an den pflichtgebundenen Hammer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nPflichtgebundener Hammer Runenschnitzmacht Sofort\nVergeltung\n 'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Urteil des Templers' löst automatisch 'Göttlicher Sturm' aus.\n\nHeilig\n 'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Licht der Morgendämmerung' aus.\n\nSchutz\n 'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Schild der Rechtschaffenen' aus.\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin"}
MultiLanguageItemData['de'][187109] = {name = "[q5]Erinnerung an das lodernde Gemetzel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nLoderndes Gemetzel Runenschnitzmacht Sofort\n'Die Jagd' hüllt Euch in 'Feuerbrandaura', wenn Ihr Euer Ziel erreicht, und Eure Beweglichkeit wird pro getroffenem Gegner 12 Sek. lang um 4% erhöht.\nRunenschnitzen: Schulter, Füße, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][187111] = {name = "[q5]Erinnerung an den blinden Glauben", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBlinder Glaube Runenschnitzmacht Sofort\n'Elysischer Erlass' spaltet zusätzlich 2 geringe Seelenfragmente ab und gewährt Euch für 20 Sek. 'Blinder Glaube'. Jedes geringe Seelenfragment, das Ihr aufzehrt, während 'Blinder Glaube' aktiv ist, gewährt Euch 10 Jähzorn und 1% Vielseitigkeit, bis zu maximal 20%.\nRunenschnitzen: Brust, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][187113] = {name = "[q3]Persönliche Kugelfessel", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Erstellt Eure persönliche Kugelfessel, die Ihr mit Euch herumschleppen könnt. (5 Min Abklingzeit)\n[q]\"Es gibt viele andere, aber diese ist meine.\"\nVerkaufspreis:"}
