MultiLanguageItemData['de'][187116] = {name = "Zielattrappe", additional_info = "[q2]Benutzen: Bringt dauerhaft ein winziges Gerät an Eurem Gürtel an. Damit könnt Ihr einen Pappkameraden erstellen, der von den Gegnern angegriffen wird. (5 Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][187117] = {name = "Azurblaue Seiten", additional_info = "Questgegenstand\n[q]\"Ausgerissene Seiten voller Energie.\""}
MultiLanguageItemData['de'][187118] = {name = "[q5]Erinnerung an den dämonischen Schwur", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDämonischer Schwur Runenschnitzmacht Sofort\nWenn der Dämon von 'Futter für die Flamme' explodiert, belegt er 5 Gegner in der Nähe für 5 Sek. mit 'Flammendes Brandmal'. Zusätzlich ist die Dauer von 'Zerschmetterte Seele' um 8 Sek. erhöht.\nRunenschnitzen: Taille, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger"}
MultiLanguageItemData['de'][187119] = {name = "[q3]Ring der Selbstreflexion", additional_info = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Wenn man den in den Ring eingesetzten Edelstein aus einem schrägen Winkel ansieht, erblickt man ein schimmerndes Spiegelbild des Ringes.\""}
MultiLanguageItemData['de'][187120] = {name = "[q4]Blutheilungssplitter 1 - Rang 5", additional_info = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nIm Schlund ist Euer Lebensraub um 1209 erhöht."}
