MultiLanguageItemData['de'][187124] = {name = "Medaillon des Zorns", additional_info = "Questgegenstand\n[q]\"Wurde den Venthyr von Graf Denathrius selbst verliehen. Ermöglicht es dem Träger, teilweise über Revendreth zu herrschen.\""}
MultiLanguageItemData['de'][187126] = {name = "Weggeworfenes Tagebuch", additional_info = "Questgegenstand\n[q]\"Von Mittler Xevveth verfasst. Scheint wohl verlegt worden zu sein.\""}
MultiLanguageItemData['de'][187127] = {name = "[q5]Erinnerung an die strahlende Glut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nStrahlende Glut Runenschnitzmacht Sofort\nErhöht die Dauer von 'Ascheweihung' um 50%. Wenn Ihr den Effekt vorzeitig aufhebt, wird die Abklingzeit abhängig von der verbleibenden Dauer um bis zu 50% verringert.\nRunenschnitzen: Handgelenk, Hände, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin"}
MultiLanguageItemData['de'][187128] = {name = "Spiondetektor", additional_info = "Questgegenstand\n[q2]Benutzen: Ruft die Spionfängerkatze Fiona zu Hilfe. (6 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][187131] = {name = "Automainnereien", additional_info = "Questgegenstand\n[q]\"...schmierig?\""}
MultiLanguageItemData['de'][187132] = {name = "[q5]Erinnerung an die Jahreszeiten der Fülle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nJahreszeiten der Fülle Runenschnitzmacht Sofort\nDer Einsatz von 'Segen des Sommers' gewährt nach 10 Sek. 'Äquinoktium'.\n\nÄquinoktium: Erhöht die Effektivität von 'Segen des Sommers' 10 Sek. lang um 100%.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin"}
MultiLanguageItemData['de'][187133] = {name = "[q3]Bezaubernder kleiner Hut", additional_info = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n[q]\"Schenkt dies Eurem Gräberbutler, damit er die Möglichkeit erhält, einen Hexenhut zu tragen.\""}
MultiLanguageItemData['de'][187134] = {name = "[q4]Legierungskrümmender Facettierer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fügt einem Gegenstand der Saison 2 von Shadowlands, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Halsketten, Armschienen, Gürtel und Ringe angewandt werden."}
MultiLanguageItemData['de'][187136] = {name = "[q7]Untersuchungsbericht: Reliktuntersuchungstechniken", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\n[q2]Benutzen: Ihr erhaltet 50% mehr Ruf beim Archivarskodex, wenn Ihr Relikte beim Archivar abgebt.\nErfordert Forschungsstufe 6 beim Archivarskodex.\n[q]\"Durch die Verbesserung seiner Forschungstechniken ist der Archivar in der Lage, mehr Wissen über jedes Fragment zu erlangen, das ihm gebracht wird.\""}
MultiLanguageItemData['de'][187137] = {name = "[q3]Untersuchungsbericht: Reliktsuchtechniken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Euch eine Chance von 20%, beim Plündern von seltenen Gegnern und Schätzen in Korthia mehr Reliktfragmente zu finden.\n[q]\"Zu wissen, wie man fehlende Relikte identifiziert, ist für unsere Bemühungen von entscheidender Bedeutung. Dieser Bericht umfasst daher Tipps und Tricks, die in manchen Fällen dabei helfen können, mehr Reliktfragmente aus gewöhnlichen Ressourcen zu gewinnen.\""}
MultiLanguageItemData['de'][187138] = {name = "[q3]Untersuchungsbericht: Erste Legierungen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht Euch, Eure Gegenstände aus Korthia und dem Schlund auf Rang 6 aufzuwerten.\nErfordert Forschungsstufe 6 beim Archivarskodex und Ruhmstufe 75 oder höher.\n[q]\"Durch den vollständigen Zugang zum Archivarskodex verstehen wir nun die bindende Macht der Herrschaftsmagie und deren Verhältnis zu den ersten Legierungen, die es in den Schattenlanden gab und die es uns ermöglichen, Eure Gegenstände aus Korthia und dem Schlund weiter zu verbessern.\""}
MultiLanguageItemData['de'][187139] = {name = "[q3]Abgefülltes Schemenherz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Bricht das Siegel an der Flasche und erlaubt so dem darin enthaltenen Schemen, für kurze Zeit Besitz von Euch zu ergreifen. (1 Stunde Abklingzeit)\n[q]\"Den Inhalt sollte man am besten ruhen lassen.\""}
MultiLanguageItemData['de'][187140] = {name = "[q3]Ring der Duplizität", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Nutzt einen Teil der im Ring verbleibenden Magie, um ein Spiegelbild zu beschwören, das Eure Handlungen kopiert. (1 Stunde Abklingzeit)"}
