MultiLanguageItemData['de'][187185] = {name = "[q3]Vesperglocke des Glaubens", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Platziert eine Vesperglocke des Glaubens vor Euch. (30 Min Abklingzeit)"}
MultiLanguageItemData['de'][187186] = {name = "[q3]Täuschungskugel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kopiert das Erscheinungsbild eines Gegners, um ihn und seine Verbündeten hereinzulegen. Während Ihr verkleidet seid, verursacht Euer nächster Angriff 500% mehr Schaden.\n[q]\"Verdächtig...\""}
MultiLanguageItemData['de'][187187] = {name = "[q7]Korthianische Ausrüstung", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Erschafft einen seelengebundenen korthianischen Gegenstand, der für Eure Beutespezialisierung nützlich ist.\nErfordert einen freundlichen Ruf beim Vorstoß des Todes."}
MultiLanguageItemData['de'][187188] = {name = "[q0]D'roos bodenloser Schlucker", additional_info = "[q]\"So sehr Ihr Euch auch abmüht, es will Euch einfach nicht gelingen, ihn zu füllen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187189] = {name = "[q0]Hyperlichtmultifunktionswerkzeug", additional_info = "[q]\"Erfunden von Di'lks vom Kartell Xy. Dieses unentbehrliche Werkzeug kommt überall zum Einsatz, wo Mittlertechnologie hergestellt wird.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187190] = {name = "[q0]Knopfhemd mit Blumendruck", additional_info = "[q]\"Ein klassisches und doch stilvolles Kleidungsstück, entworfen von N'uth vom Kartell Al.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187191] = {name = "[q0]Vi'llers bewahrtes Auge", additional_info = "[q]\"Es scheint Euch den Weg zu weisen, falls Ihr einmal vom Pfad abkommen solltet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187192] = {name = "[q0]Urne des Wissens", additional_info = "[q]\"Die bewahrten Erinnerungen von Ny'lad vom Kartell Ta. Sie wurden sorgfältig redigiert und in die Urne gelegt, um weitere Studien vor dem Übergang in die nächste Daseinsebene zu ermöglichen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187193] = {name = "[q0]Signierte Plüschmöwe", additional_info = "[q]\"Ein Paradebeispiel für atemberaubende Handwerkskunst. Auf den Schnabel wurde der Name \"K'en\" aufgestickt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187194] = {name = "[q0]Stern im Glas", additional_info = "[q]\"Der Stern wurde von Sternzähmer Ja'z vom Kartell Zo vom Himmel gepflückt und dann sorgfältig in einem Glas platziert, damit auch andere ihn bewundern können.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187195] = {name = "[q0]Goldenes Saxophon", additional_info = "[q]\"Ein Instrument, das einst von Ta'ylor gespielt wurde, einem legendären Künstler, der in Myzas Oase aufgetreten ist.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187196] = {name = "[q0]Marke des endlosen Spielens", additional_info = "[q]\"Ta'piper hat einen unsichtbaren Faden an dieser Marke befestigt, was ihm und seinen Freunden endlose Stunden voller Spaß beschert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187197] = {name = "[q0]D'roos Spukschlagzeug", additional_info = "[q]\"Dieses Schlagzeug scheint von einem charismatischen Geist heimgesucht zu werden, der immer dann zum Leben erwacht, wenn jemand in der Nähe einen Witz erzählt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187198] = {name = "[q0]Xy'le-Dattel", additional_info = "[q]\"Dieser gängige Imbiss des Kartells Xy lässt sich ganz unkompliziert mit anderen genießen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187199] = {name = "[q0]Pa'hix' Runenrätsel", additional_info = "[q]\"Ein kompliziertes Spiel, das man am besten mit Freunden löst. Wurde von der berühmten Codeknackerin höchstpersönlich erschaffen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][187200] = {name = "[q3]Singstahlbarren", additional_info = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n[q]\"Entrüstet, beleidigt und auch sonst davon irritiert, dass die schlundgebundenen Stahlformer auf ihn einprügeln.\""}
MultiLanguageItemData['de'][187201] = {name = "[q3]Himmelskarte der Schattenlande", additional_info = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n[q]\"Über der Schriftrolle schwebt eine wirbelnde multidimensionale Darstellung der relativen Positionen verschiedener jenseitiger Leben der Schattenlande.\""}
MultiLanguageItemData['de'][187202] = {name = "[q3]Instabile Sprengstoffkugel", additional_info = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n[q]\"Dieses leuchtende und summende Gerät hat eindeutig noch das Potenzial, katastrophale Zerstörung zu verursachen.\""}
MultiLanguageItemData['de'][187203] = {name = "[q3]Chiffre der Erkenntnis", additional_info = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n[q]\"Mehrere Textabschnitte wurden in verschiedenen Sprachen in den Stein geätzt. Jedoch handelt es sich bei keiner der Sprachen um eine Euch bekannte.\""}
MultiLanguageItemData['de'][187204] = {name = "[q3]Trommel des Todesloas", additional_info = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n[q]\"Das Trommelfell, das über den Rahmen gespannt ist, fühlt sich ungewöhnlich kühl an.\""}
MultiLanguageItemData['de'][187205] = {name = "[q3]Sack voller fremdartiger Erde", additional_info = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n[q]\"Die Erde in diesem Beutel ist von einem tiefen, kräftigen Braun... beinahe schon Schwarz.\""}
MultiLanguageItemData['de'][187206] = {name = "[q3]Buch der Bindung: Die wahnsinnige Hexe", additional_info = "Korthianische Relikte\nQuestgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Dieses Buch ist unvollständig. Eine verwirrte Stimme erklingt aus seinem Inneren und bittet wiederholt und nachdrücklich um die Wiederbeschaffung der blutroten Seiten.\""}
