MultiLanguageItemData['de'][187223] = {name = "[q5]Erinnerung an den Samen des ungezügelten Wachsens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSamen des ungezügelten Wachsens Runenschnitzmacht Sofort\nJeder Impuls des Schadenseffekts von 'Faetransfusion' verringert die Abklingzeit von 'Wildgeist' um 9.0 Sek. und erhöht Eure kritische Trefferchance für 15 Sek. um 4%.\nRunenschnitzen: Kopf, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke"}
MultiLanguageItemData['de'][187224] = {name = "[q5]Erinnerung an die Elementarverbundenheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nElementarverbunden Runenschnitzmacht Sofort\nAuf bis zu 5 verbündete Ziele, die mit 'Kettenernte' geheilt wurden, wird 'Springflut' gewirkt. Auf bis zu 5 gegnerische Ziele, denen mit 'Kettenernte' Schaden zugefügt wurde, wird 'Flammenschock' gewirkt. Kritische Treffer mit 'Flammenschock' verringern die Abklingzeit von 'Kettenernte' um 1.0 Sek.\nRunenschnitzen: Brust, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt."}
MultiLanguageItemData['de'][187225] = {name = "[q5]Erinnerung an den darbenden Seelendetritus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nDarbender Seelendetritus Runenschnitzmacht Sofort\nWenn 'Geißelnder Obolus' Seelensplitter erzeugt, wird 8 Sek. lang Eure Bewegungsgeschwindigkeit um 100% und Eure kritische Trefferchance um 45% erhöht. Wenn 'Geißelnder Obolus' abläuft, wird stattdessen Eure Bewegungsgeschwindigkeit um 33% und Eure kritische Trefferchance um 15% erhöht.\nRunenschnitzen: Brust, Handgelenk, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister"}
MultiLanguageItemData['de'][187226] = {name = "[q5]Erinnerung an die Splitter der Vernichtung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nSplitter der Vernichtung Runenschnitzmacht Sofort\n'Dezimierungsblitz' erhöht zusätzlich die kritische Trefferchance um 100% sowie den kritischen Schaden von [ Zerstörung : 'Verbrennen' / Seelendieb : 'Seelendieb' ] [ Dämonologie : 'Dämonenblitz' /\n\nGebrechen\n 'Schattenblitz' ] um 50%.\nRunenschnitzen: Taille, Beine\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister"}
MultiLanguageItemData['de'][187227] = {name = "[q5]Erinnerung an das verrottende Seelensäckchen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nVerrottendes Seelensäckchen Runenschnitzmacht Sofort\nJedes von 'Seelenfäule' betroffene Ziel erhöht Euer Tempo und Eure kritische Trefferchance 8 Sek. lang um 5%.\nRunenschnitzen: Füße, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister"}
MultiLanguageItemData['de'][187228] = {name = "[q5]Erinnerung an die eingedämmte endlose Explosion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nEingedämmte endlose Explosion Runenschnitzmacht Sofort\nDer regelmäßige Schaden von 'Drohende Katastrophe' erhöht sich um 125% sowie zusätzlich um 15% pro auf dem Weg zum letzten Ziel getroffenem gegnerischen Ziel, bis zu maximal 275%.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister"}
MultiLanguageItemData['de'][187229] = {name = "[q5]Erinnerung an den Pakt der Seelenpirscher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nPakt der Seelenpirscher Runenschnitzmacht Sofort\nWenn Euer 'Resonierender Pfeil' einem Ziel Schaden zufügt, wird die kritische Trefferchance Eurer Gruppe für 10 Sek. um 10% erhöht. (1s Abklingzeit)\nRunenschnitzen: Taille, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger"}
MultiLanguageItemData['de'][187230] = {name = "[q5]Erinnerung an die Tasche mit Munition", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nTasche mit Munition Runenschnitzmacht Sofort\nBis zu 2 der von Eurem 'Todeschakram' getroffenen Ziele werden zusätzlich von 'Explosivschuss' getroffen.\nRunenschnitzen: Kopf, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger"}
MultiLanguageItemData['de'][187231] = {name = "[q5]Erinnerung an die Fragmente des Ältestengeweihs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nFragmente des Ältestengeweihs Runenschnitzmacht Sofort\nWenn 'Wilde Geister' weniger als 5 Ziele trifft, besteht eine Chance von 100%, dass der Schaden von 'Wilde Geister' erneut verursacht wird.\nRunenschnitzen: Hals, Brust\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger"}
MultiLanguageItemData['de'][187232] = {name = "[q5]Erinnerung an den Beutel mit Klingenbruchstücken", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\n\nBeutel mit Klingenbruchstücken Runenschnitzmacht\nDurch 'Schinderschuss' ausgelöste Bonuseinsätze von 'Tödlicher Schuss' lassen 6 Ziele innerhalb von 12 Metern bluten, was ihnen 60% des von 'Tödlicher Schuss' verursachten Schadens im Verlauf von 6 Sek. zufügt.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger"}
