MultiLanguageItemData['de'][187638] = {name = "[q4]Todesläufer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese wilden Cerviden finden nur dann wahrlich Frieden, wenn sie durch die Länder des Todes streifen oder zwischen ihnen umherziehen.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187639] = {name = "[q4]Blasser majestätischer Cervid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Beim Anblick dieser majestätischen Wesen ist es nicht schwer, sich auszumalen, wie die Idee der Cerviden sich zu den Hirschen entwickelt hat, die jetzt Azeroth und andere sterbliche Welten durchstreifen.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187640] = {name = "[q4]Zügel des geweihten Protohirsches", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen geweihten Protohirsch als Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtDie Erleuchteten\n- Respektvoll\n\n\n[q]\"Nur die, die das höchste Ansehen der Erleuchteten genießen, bekommen die Zügel dieses seltenen Cerviden anvertraut.\"\nVerkäufer:\nVilo\nZone:\nZereth Mortis\nFraktion:\nDie Erleuchteten - Respektvoll\nKosten:\n5.000"}
MultiLanguageItemData['de'][187641] = {name = "[q4]Zügel des gemarterten Zerethhirschs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Was auch immer ihr Zweck dieser Cerviden einst war, er ist seit Langem vergessen. Sie werden zwar nicht beherrscht, aber sie wurden durch die unvorgesehene Präsenz der Schlundgebundenen im heiligen Reich von Zereth Mortis verderbt.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187642] = {name = "[q4]Boshafter Kriegspirscher", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man einen boshaften Kriegspirscher beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Lasst die Allianz Staub schmecken, während Ihr einen majestätischen Protoformwolf reitet! Für die Horde!\"\nPvP:\nShadowlands: Saison 4\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder"}
MultiLanguageItemData['de'][187644] = {name = "[q4]Boshafter Kriegspirscher", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man einen boshaften Kriegspirscher beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Lasst die Horde Staub schmecken, während Ihr einen majestätischen Protoformwolf reitet! Für die Allianz!\"\nPvP:\nShadowlands: Saison 4\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder"}
MultiLanguageItemData['de'][187648] = {name = "Leerer Steinsuppenkessel", additional_info = "[q2]Benutzen: Richtet einen Kessel Steinsuppe her, der mit köstlichen Zutaten gefüllt werden kann. Stellt die Suppe fertig, damit sie bis zu 70 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\n Die fertige Suppe stellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 53 erhöht.\nVerkaufspreis:"}
