MultiLanguageItemData['de'][187660] = {name = "[q4]Vespidenflatterer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Flatterer ist ein übergroßer Vespidarbeiter, erschaffen, um einen Reiter auf seinem Rücken zu tragen. Anstatt einer Königin zu folgen, verlässt er sich in allen Lebenslagen auf die Führung seines Reiters.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187662] = {name = "Seltsamer Schleim", additional_info = "Einzigartig\n[q]\"Diese Substanz scheint auf die Aureliden von Zereth Mortis eine gewisse Anziehungskraft auszuüben, aber sie lässt sich mit keinem Köder verbinden. Jemand, der sich mit Tiefseekreaturen auskennt, weiß womöglich, was man damit machen kann.\""}
MultiLanguageItemData['de'][187663] = {name = "[q4]Bronzeflügelvespid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Bronzeflügelvespiden sind ein Ergebnis des Versuchs, eine Vespidenkönigin ohne weitere Mitglieder eines neuen Schwarms zu synthetisieren. Obwohl bisher noch kein Sterblicher herausgefunden hat, wie man einen Stock synthetisiert, stellen die Bronzeflügel selbst in ihrem aktuellen Zustand verlässliche Reittiere dar.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187664] = {name = "[q4]Geschmiedeter Tückenflügler", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Es gibt kaum etwas, das einen das Leben so sehr spüren lässt wie ein Ritt durch das Reich des Todes auf dem Rücken eines Wesens, das einen hasst.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187665] = {name = "[q4]Summ", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Summ summ summ, summ summ! Summ summ summ summ summ. Summ summ summ, summ summ summ.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187666] = {name = "[q4]Wüstenschwingenjäger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Wüstenschwingenjäger wurden im Dienste der großen Vorhersehung erschaffen, um die weiten Himmel der vergessenen Reiche der Schattenlande zu erfüllen.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187667] = {name = "[q4]Schlundadaptierter Raptora", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Seit dem Übergriff des Kerkermeisters sind neue Raptoras durch Zereth Mortis synthetisiert worden, die dem verderbenden Einfluss des Schlunds widerstehen können.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187668] = {name = "[q4]Raptorasturzflieger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Raptorasturzflieger ist eine der grausamsten Ausprägungen dieser Art, perfekt an seine ökologische Nische angepasst. Die Sturzflieger, die heutzutage synthetisiert werden, benötigen keine weitere Anpassungen und sind identisch mit denen, die in der Vergangenheit erschaffen wurden.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187669] = {name = "[q4]Serenade", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese wunderschönen Heliciden zeigen sich nur bei Nacht. Sind sie wohlgestimmt, lassen ihre Schneckenhäuser eine fröhliche Melodie erklingen.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187670] = {name = "[q4]Bronzener Helicid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Einige Heliciden von Zereth Mortis haben von Natur aus seltsam metallische Schneckenhäuser. Sie sind üblicherweise bronzefarben, und ihr Metall unterscheidet sich nicht von dem, mit dem sogar Anfänger unter den Minenarbeitern umgehen können, mit der Einschränkung, dass die Konstruktion dieser Kreatur die Fähigkeiten von Anfängern mehr als überfordern würde.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187671] = {name = "[q4]Gescheiterter Flitzopodenprototyp", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Kreatur ist nicht von den Ersten entworfen worden, sondern stattdessen von einem unbekannten Wesen in dem Versuch, einen sehr schnellen Läufer zu kreieren. Es blieb bei dem Versuch, da dieses Reittier doch sehr langsam ist.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187672] = {name = "[q4]Scharlachroter Helicid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die ungewöhnliche rötliche Färbung dieses Heliciden ist eindeutig beabsichtigt, und der einzige andere Unterschied zwischen diesem und anderen Heliciden ist das ungewöhnliche Fehlen von Schleim.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187673] = {name = "[q4]Kryptischer Aurelid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Chiffren der Ersten entziehen sich dem Verständnis der Sterblichen. Ein seltsamer Effekt dieser Sprache ist, dass sich einige Aureliden aus unbekannten Gründen zu jenen Sterblichen hingezogen fühlen, die danach streben, das Mysterium zu ergründen.\"\nErfolg:\nVon A bis Zereth\nKategorie:\nSchattenlande"}
MultiLanguageItemData['de'][187674] = {name = "[q4]Tiefenpirscher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen Tiefenpirscher beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein paar dieser Quallen wurden in Zereth Mortis gewildert und sind über Bord gegangen, als das Schiff der Wilderer sank. Sie haben in den Tiefen des Großen Meeres ein neues Zuhause gefunden.\"\nHandelsposten"}
MultiLanguageItemData['de'][187675] = {name = "[q4]Schimmernder Aurelid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Obschon er einst geschaffen wurde, das Mausoleum der Ersten zu verteidigen, folgt er jetzt nach der Erfüllung seiner Primärfunktion gehorsam Euren Befehlen.\"\nErfolg:\nRuhm des Mausoleumsschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageItemData['de'][187676] = {name = "[q4]Tiefensternpolyp", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen Tiefensternaureliden beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als einer der letzten verbleibenden Polypen eines scheuen Wesens fühlt sich dieser Aurelid sowohl im Wasser als auch in der Luft gleichermaßen wohl.\"\nBeute von:\nHirukon\nZone:\nZereth Mortis"}
MultiLanguageItemData['de'][187677] = {name = "[q4]Genesiskrabbler", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Jene Erleuchteten, die Tarachniden beobachtet haben, glauben, dass diese Art zu den ersten Wesen gehörte, die durch die Länder von Zereth Mortis streiften.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187678] = {name = "[q4]Tarachnidenkriecher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Tarachniden hausen in den finstersten Ecken von Zereth Mortis und verlassen sie nur, um zu jagen (oder um manchmal einen Reiter auf ihrem Rücken zu tragen).\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187679] = {name = "[q4]Unergründlicher Krabbler", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Tarachniden bewegen sich mit einer Absicht, die niemand nachvollziehen kann, und scheinen nur einem höheren Ruf zu folgen. Was auch immer sich dahinter verbergen mag, es scheint regelmäßige Hilfe für Sterbliche zu beinhalten, die ein Reittier benötigen. Für den Moment zumindest.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageItemData['de'][187680] = {name = "[q4]Boshafter Kriegsquaker", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man einen boshaften Kriegsquaker beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Diese Kreaturen stürzen sich mit so viel Begeisterung in den Kampf, dass sich ihr Quaken fast schon wie ein \"FÜR DIE HORDE!\" anhört.\"\nPvP:\nSchattenlande: Saison 3\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder"}
MultiLanguageItemData['de'][187681] = {name = "[q4]Boshafter Kriegsquaker", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man einen boshaften Kriegsquaker beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Diese Kreaturen stürzen sich mit so viel Begeisterung in den Kampf, dass sich ihr Quaken fast schon wie ein \"FÜR DIE ALLIANZ!\" anhört.\"\nPvP:\nSchattenlande: Saison 3\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder"}
MultiLanguageItemData['de'][187682] = {name = "[q4]Verlustverzerrter Todeswandler", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese raue, wirbelnde Energie ist in kohäsiver Form gebunden und unterwirft sich nur dem Willen derjenigen, die stark und entschlossen genug sind, sie zu binden.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 3\nKategorie:\nDungeons"}
MultiLanguageItemData['de'][187683] = {name = "[q4]Goldplattenbufonid", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser gepanzerte Bufonid ist immer bereit, ins Kampfgetümmel zu springen... vorausgesetzt, der Kampf ist wirklich ganz in der Nähe. Im Notfall kann er mehrere Male springen und so letztendlich den Kampf erreichen.\"\nBeruf:\nProtoformsynthese"}
