MultiLanguageItemData['de'][188261] = {name = "[q4]Zudringlicher Gedankenkäfig", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Erschafft eine Verbindung tief in den Gedanken Eures Ziels, die Euer Ausweichen um 222 erhöht und ihm im Verlauf von 6 Sek. [ 525 * (12)] Gesundheit entzieht.\n\n Wenn die Verbindung bei Ablauf des Effekts noch intakt ist, zersplittern die Gedanken des Ziels, was Gegnern innerhalb von 8 Metern um das Ziel 1091 Schattenschaden zufügt und sie für 3 Sek. entsetzt. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188262] = {name = "[q4]Der Brüllende Löwe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nKlassen: Paladin , Priester , Schamane , Mönch , Druide , Rufer\n[q2]Benutzen: Kanalisiert für 3 Sek. Licht und erschafft einen Schutzbereich um Euch herum, der 30% des sämtlichen durch Verbündete darin erlittenen Schadens bis zu maximal 27443 Schaden absorbiert.\n\n Eure kritischen Heilungen haben eine Chance, die Abklingzeit um 6 Sek. zu verringern.\n\nGilt nur für Heilerspezialisierungen. (10 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188263] = {name = "[q4]Intensitätskern des Rückgewinners", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Anlegen: Wenn ein Automa in der Nähe stirbt, gebt Ihr Ephemera ab und heilt bis zu 5 Verbündete in der Nähe im Verlauf von 30 Sek. um ( 45 * 30) Gesundheit.\n[q2]Benutzen: Ruft einen Automasanitäter herbei, der bei Euch im Verlauf von 10 Sek. ( 14 * 10) Mana wiederherstellt, bevor er abläuft. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188264] = {name = "[q4]Einschlag des Erdbrechers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Lässt den Boden unter Euren Füßen erzittern, was im Verlauf von 12 Sek. 4445 Naturschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Der Schaden erhöht sich pro getroffenem Gegner.\n\n Während des Bebens könnt Ihr tektonische Schwachstellen in der Nähe wahrnehmen. Wenn Ihr Euch an eine solche Schwachstelle bewegt, fügt Ihr allen Gegnern in der Nähe 635 Naturschaden zu. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188265] = {name = "[q4]Truhe mit erhaltenen Schätzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Beweglichkeit\n[q2]Anlegen: Durchwühlt die Truhe regelmäßig nach einer neuen gestohlenen Waffe.\n[q2]Benutzen: Nehmt Euch eine Waffe aus der Truhe und erhaltet ihre Vorteile. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188266] = {name = "[q4]Pulsierender Kluftsplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Platziert ein Rissportal vor Euch, das sich 1.5 Sek. lang auflädt und dann [ 1739 * (1 + Vielseitigkeit)] kosmischen Schaden in einer Linie auf alle Gegnern aufteilt. Das Portal stiehlt von der Realität an sich, wodurch Ihr einen Schild erhaltet, der 20 Sek. lang anhält und [ 4016 * (1 + Vielseitigkeit)] Schaden absorbiert.\n\n Der Schaden und die Absorption werden für jeden getroffenen Gegner erhöht, für bis zu 5 Gegner. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188267] = {name = "[q4]Glocken des endlosen Festmahls", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Schadensfähigkeiten haben eine hohe Chance, den Duft köstlicher Seelenenergie auszumachen. Bis zu 100-mal stapelbar. Bei maximalen Stapeln bricht ein Schwarm Verschlinger hervor, die Euer Ziel beißen und ihm so 5733 körperlichen Schaden zufügen.\n\n Effekte, durch die sich Euer Ziel bewegt, erzeugen Bonusstapel.\nVerkaufspreis:"}
MultiLanguageItemData['de'][188268] = {name = "[q4]Einfallsreichtumskern des Architekten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Anlegen: Wenn ein Automa in der Nähe stirbt, werden Eure Abklingzeiten 30 Sek. lang um 5% schneller abgeschlossen.\n[q2]Benutzen: Ruft ein Bedienstetenautoma herbei, das im Verlauf von 8 Sek. ( 53 * 8) kosmischen Schaden auf Euer Ziel kanalisiert und dann zugrunde geht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188269] = {name = "[q4]Taschenprotoschmiede", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Beim Erleiden von Schaden besteht eine Chance, dass Ihr einen Verbündeten in der Taschenprotoschmiede fertigt, der Eure Gegner am Angreifen hindert, Euch im Kampf unterstützt und 5858 Schaden absorbiert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][188270] = {name = "[q4]Elegie der Ewigen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Vor den Ewigen weinend, verschreibt Ihr Euch ihren Diensten.\n\n Erhöht Euren höchsten Sekundärwert um 40 und gewährt allen Gruppenmitgliedern, die ebenfalls Eurem Pakt dienen, 10% dieses Bonus.\nVerkaufspreis:"}
MultiLanguageItemData['de'][188271] = {name = "[q4]Das erste Siegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Gewährt die Macht der Signaturfähigkeit Eures Pakts und erhöht die Vielseitigkeit für 20 Sek. um 645 . (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188272] = {name = "[q4]Resonierender Kessel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Benutzen: Feuert ein widerhallendes Geschoss auf Euer Ziel und löst damit einen Desintegrationskranz aus, der von der Position des Ziels ausgeht. Verursacht 6 Sek. lang alle 2 Sek. 189 Schaden. Schwillt 3-mal an, bevor der Effekt erneut einsetzt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188273] = {name = "[q4]Glockenspiel des Bediensteten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n[q2]Anlegen: Eure Heilzauber und -fähigkeiten haben eine Chance, einen vorgefertigten Assistenten zu aktivieren, der 10 Sek. lang alle 1 Sek. eine Absorption in Höhe von 259 auf den am schwersten verletzten Verbündeten in Eurer Nähe anwendet.\nVerkaufspreis:"}
