MultiLanguageItemData['de'][188766] = {name = "[q4]Resonator des kosmischen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Werft den kosmischen Resonator. Dieser explodiert nach 4 Sek. und verursacht 2039 kosmischen Schaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\n Der Schaden erhöht sich pro getroffenem Gegner, für bis zu 5 Gegner. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188775] = {name = "[q4]Ewige Aegis des kosmischen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Aktiviert die Verteidigung und absorbiert für 15 Sek. 50% sämtlichen erlittenen Magieschadens, bis zu maximal [ 2339 * (1 + Vielseitigkeit)] Schaden. Kosmischer Schaden wird vollständig absorbiert. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][188778] = {name = "[q4]Verschlingende Verwünschung des kosmischen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 42 Vielseitigkeit\n[q2]Benutzen: Entzieht allen Gegnern in der Nähe im Verlauf von 3 Sek. bis zu ( 752 * 4) Absorption und entfesselt sie in einem kegelförmigen Bereich von 20 Metern vor Euch als heilende Absorption. (3 Min Abklingzeit)\nVerkaufspreis:"}
