MultiLanguageItemData['de'][189623] = {name = "[q4]10.0 Raid Template - Generic - Finger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+100 Ausdauer\n[q2]+ 242 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 90.\nVerkaufspreis:"}
MultiLanguageItemData['de'][189624] = {name = "[q4]10.0 Raid Template - Generic - Neck", additional_info = "Wird beim Aufheben gebunden\nHals\n+100 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 85.\n[q2]Erhöht Eure Meisterschaftswertung um + 246.\n[q2]Benutzen: Bezaubert den Geist eines Wildtiers im Freien der Schattenlande. Bei Erfolg unterstützt Euch Euer Ziel für 5 Min. (1 Stunde Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189625] = {name = "[q4]10.0 Raid Template - Melee DPS - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Werdet 10 Sek. lang zum lauernden Raubtier, was Eure Geschwindigkeit um 278 erhöht. Ihr stürzt Euch außerdem auf den nächsten Gegner, der sich auf 8 Meter nähert, was ihm 19822 körperlichen Schaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189626] = {name = "[q4]10.0 Raid Template - Tank - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Geht für 30 Sek. ein Band des Jägersmanns mit dem anvisierten Verbündeten ein. 25% des von Euch erlittenen Schadens werden auf diesen Verbündeten umgeleitet, bis zu insgesamt [ 58281 * (1 + Vielseitigkeit)] Schaden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189627] = {name = "[q4]10.0 Raid Template - Int DPS - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Intelligenz\n[q2]Benutzen: Aktiviert den Seelenzünder und opfert bis zu 11037 Gesundheit im Verlauf von 15 Sek., um 'Lodernde Woge' zu ermächtigen.\n\n Aktiviert ihn erneut, um 'Lodernde Woge' einzusetzen, was Gegnern in einem kegelförmigen Bereich von 40 Metern [ 7884 * (1 + Vielseitigkeit)] Feuerschaden zufügt, die gleichmäßig aufgeteilt werden, und abhängig davon, wie lang der Seelenzünder aktiv war, ihnen zusätzlich bis zu 40% Schaden zufügt.\n\n Der Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern. (1 Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189628] = {name = "[q4]10.0 Raid Template - Healer - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Intelligenz\n[q2]Benutzen: Stärkt Euren Verbündeten mit einem Büschel Phönixfedern, das ihn nach 6 Sek. um [ 26603 * (1 + Vielseitigkeit)] Gesundheit heilt. Dieser Wert erhöht sich abhängig von der fehlenden Gesundheit des Ziels um bis zu 25%. Wenn Euer Verbündeter tödlichen Schaden erleidet, wird dieser Effekt sofort ausgelöst. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189629] = {name = "[q4]10.0 Raid Template - STR - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Stärke\n[q2]Anlegen: Eure Schadensfähigkeiten haben eine hohe Chance, 595 körperlichen Schaden zu verursachen und Euch um 300% des verursachten Schadens zu heilen. Bei überschüssiger Heilung dieses Effekts fügt Ihr Gegnern in der Nähe im Verlauf von 15 Sek. [ 501 * 5 * (1 + Vielseitigkeit)] körperlichen Schaden zu, der auf die Gegner aufgeteilt wird. Dies unterdrückt jedoch den Lebensdiebstahleffekt.\n\n Der Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern.\nVerkaufspreis:"}
MultiLanguageItemData['de'][189630] = {name = "[q4]10.0 Raid Template - Omni  - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Vier Tanzpartner erscheinen in einer zufälligen Aufstellung um Euch herum. Jeder von ihnen gewährt Euch stapelbar 20 Sek. lang 163 Tempo und 91 Geschwindigkeit, wenn Ihr Euch zu ihm hinbewegt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189631] = {name = "[q4]10.0 Raid Template - Physical DPS - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Eure nächsten 5 Schaden verursachenden Fähigkeiten rufen 'Kollabierte Psyche' hervor, was 3330 Schattenschaden verursacht und den durch 'Kollabierte Psyche' erlittenen Schaden des Ziels für 5 Sek. um 1% erhöht. Bis zu 25-mal stapelbar. (1.5s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][189632] = {name = "[q4]10.0 Raid Template - AGI - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Beweglichkeit\n[q2]Anlegen: Wenn Eure prozentuale Gesundheit höher ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, [ 925 * (1 + Vielseitigkeit)] körperlichen Schaden zu verursachen.\n\n Wenn Eure prozentuale Gesundheit niedriger ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, Euch um [ 1263 * (1 + Vielseitigkeit)] Gesundheit zu heilen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][189633] = {name = "[q4]10.0 Raid Template - INT - Trinket", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Intelligenz\n[q2]Anlegen: Tretet dem blutroten Chor bei. Jede Minute schwillt Euer kritischer Trefferwert im Verlauf von 30 Sek. um ( 158 * 3) an, bevor er auf den normalen Wert zurücksinkt. Dieser Effekt erhöht sich pro Mitglied des blutroten Chors in Eurer Gruppe um 5%.\nVerkaufspreis:"}
