MultiLanguageItemData['de'][190450] = {name = "[q3]Erweckte Zorneskraft", additional_info = "[q2]Benutzen: Verwandelt erweckte Zorneskraft in 10 Einheiten tobende Zorneskraft.\nHandwerksmaterial\n[q]\"Kann aus verschiedenen Quellen auf den Dracheninseln gewonnen werden, während der Kriegsmodus aktiv ist oder durch Teilnahme an instanziiertem PvP. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
