MultiLanguageItemData['de'][190765] = {name = "[q4]Iskas Schlundrattenleine", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man eine kolossale Schlundratte beschwört.\n[q2]Beschwört Eure riesige Seuchenschlundratte oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Nagetiere wurden zu Iskas berüchtigten Wächtern, die den Schlund auskundschaften und ihn mit ihrer Seuche überziehen. Wo sie auftreten, folgt nur das Verderben.\"\nBeute von:\nRhuv, Verschlinger des Ruins"}
MultiLanguageItemData['de'][190766] = {name = "[q4]Schwanz der Spektralschlundratte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man eine kolossale Schlundratte beschwört.\n[q2]Beschwört eure kolossale gespenstergebundene Schlundratte oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese von den Energien gequälter Seelen durchdrungenen Kreaturen haben gespenstische Fähigkeiten entwickelt, wodurch sie ziemlich schwer zu fassen sind.\"\nBeute von:\nSchlundgebundene Vorratstruhe"}
MultiLanguageItemData['de'][190767] = {name = "[q4]Gepanzerter goldener Pterrordax", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Diese bemalten und mit Gold verzierten Pterrordaxe streifen durch Lüfte über der Gruft von Atal'Dazar.\"\nHandelsposten"}
MultiLanguageItemData['de'][190768] = {name = "[q4]Fraktalchiffre des Zerethaufsehers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses rätselhafte und unnahbare Konstrukt der Ersten fliegt auf einem anmutigen Strom absoluten geometrischen Wissens.\"\nBeute von:\nDer Kerkermeister\nZone:\nMausoleum der Ersten\nSchwierigkeitsgrad:\nMythisch"}
MultiLanguageItemData['de'][190769] = {name = "Instabiles Arkana", additional_info = "Questgegenstand\n[q]\"Zu einem Edelstein verdichtetes instabiles Arkana. Könnte jeden Moment explodieren... also schüttelt es nicht zu sehr.\""}
MultiLanguageItemData['de'][190771] = {name = "[q4]Fraktalchiffre des carzinisierten Zerethhirsches", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die wenigen, die von diesen mysteriösen Wesen noch verblieben sind, erscheinen unmöglich alt, fast schon zeitlos. Vielleicht wurden sie von den Ersten selbst erschaffen, da noch kein Bauplan gefunden wurde, um sie zu synthetisieren.\"\nQuest:\nLeitmotive"}
