MultiLanguageItemData['de'][191670] = {name = "Perlengeschmücktes Federband", additional_info = "Questgegenstand\n[q]\"Mit Perlen und Lederbändern verflochtene Adlerfedern, die gutes Urteilsvermögen symbolisieren. Im Leder sind Bissspuren zu sehen und mehrere der Perlen sind gebrochen.\""}
