MultiLanguageItemData['de'][191672] = {name = "Siegel des Ernährers", additional_info = "Questgegenstand\n[q]\"Ein hervorragend geschnitztes Knochentotem, das einen erfolgreichen Fischer der Tuskarr darstellt. Durch tiefe Bissspuren haben sich Risse im Knochen gebildet.\""}
