MultiLanguageItemData['de'][192300] = {name = "[q4]Siegel der Anpassung des ewigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\n[q]Auszeichnung des Gladiators (0/2)\n[q0]Emblem des Gladiators\nMedaillon des Gladiators\n[q0](2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][192301] = {name = "[q4]Akribische Entschlossenheit des ewigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Aktiviert die Mittlerverteidigung und schützt Euch so vor Zauberunterbrechungen und Kontrollverlusteffekten. Die Verteidigung hält bis zu 2 Effekte ab und bleibt 12 Sek. lang bestehen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][192302] = {name = "[q4]Hallende Entschlossenheit des ewigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Erhöht die Dauer eintreffender Kontrollverlusteffekte um 25%. Nicht mit ähnlichen Effekten stapelbar. Schützt Betroffene für 12 Sek. vor dem nächsten Kontrollverlusteffekt. (500ms Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][192303] = {name = "[q4]Resonator des ewigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Werft den kosmischen Resonator. Dieser explodiert nach 4 Sek. und verursacht 2039 kosmischen Schaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\n Der Schaden erhöht sich pro getroffenem Gegner, für bis zu 5 Gegner. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][192304] = {name = "[q4]Ewige Aegis des ewigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Aktiviert die Verteidigung und absorbiert für 15 Sek. 50% sämtlichen erlittenen Magieschadens, bis zu maximal [ 2339 * (1 + Vielseitigkeit)] Schaden. Kosmischer Schaden wird vollständig absorbiert. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][192305] = {name = "[q4]Verschlingende Verwünschung des ewigen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 42 Vielseitigkeit\n[q2]Benutzen: Entzieht allen Gegnern in der Nähe im Verlauf von 3 Sek. bis zu ( 752 * 4) Absorption und entfesselt sie in einem kegelförmigen Bereich von 20 Metern vor Euch als heilende Absorption. (3 Min Abklingzeit)\nVerkaufspreis:"}
