MultiLanguageItemData['de'][192745] = {name = "Die titanische Komödie", additional_info = "Questgegenstand\n[q]\"Eine satirische Reise durch den Kosmos vom Smaragdgrünen Traum bis zu den Schattenlanden, angeführt vom Titanenhüter Dantyr. Weder die Titanen noch die Aspekte sind vor des Autors Grimm sicher und ihre erkannten Sünden werden offen zur Schau gestellt.\""}
