MultiLanguageItemData['de'][192751] = {name = "[q4]Sturmberührter Brüffelch", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n[q]\"Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\""}
MultiLanguageItemData['de'][192752] = {name = "Stabkopfstück", additional_info = "Questgegenstand\n[q]\"Der abgetrennte Fokus eines zerbrochenen Zeitwandererstabs.\""}
MultiLanguageItemData['de'][192753] = {name = "Die Schuppen des Zorns", additional_info = "Questgegenstand\n[q]\"Eine schonungslose und messerscharfe Widerlegung der Ordnung, die von den Aspekten und ihren Titanenverbündeten verhängt wurde. Erzählt aus der Perspektive eines Protodrachen, der sich schließlich gezwungen sieht zu rebellieren, nachdem man ihn an den Rand der drakonischen Gesellschaft getrieben hatte.\""}
MultiLanguageItemData['de'][192754] = {name = "Dracuixote", additional_info = "Questgegenstand\n[q]\"Die Geschichte eines uralten grünen Drachen, der seine Träume nicht mehr von der Wirklichkeit unterscheiden konnte. In Begleitung der Drachenbrut Dracuixote, die selbst eine lange Leidensgeschichte hat, macht er sich an die abstruse Mission, ein vermeintliches goldenes Zeitalter zurückzubringen.\""}
MultiLanguageItemData['de'][192755] = {name = "Der Fürst der Schwingen", additional_info = "Questgegenstand\n[q]\"Eine Truppe aus kampferprobten Drakoniden und tapferen Welpen findet zusammen, um ein Artefakt von schrecklicher Macht zu zerstören. Vernichten lässt sich das unheilvolle Artefakt jedoch nur in der Schmiede des wahnsinnigen Aspekts, der es einst erschuf...\""}
MultiLanguageItemData['de'][192756] = {name = "Der rote und der schwarze Schwarm", additional_info = "Questgegenstand\n[q]\"Ein schwarzer Drache von niederem Stand hadert damit, seine militärische Herkunft mit seiner Wertschätzung für Intelligenz und Wortgewandtheit zu vereinen. Unerwiderte Liebe und der Materialismus, der in der Drachenheit grassiert, treiben ihn am Ende zur Verzweiflung.\""}
MultiLanguageItemData['de'][192757] = {name = "Stolz und Protodrachen", additional_info = "Questgegenstand\n[q]\"Die ultimative Liebesgeschichte aus einer Zeit vor den Aspekten. Ein forscher junger Protodrache legt sich mit einem unnahbaren Ältesten an. Aus Feindseligkeit wird Wertschätzung und irgendwann Liebe, als sie beginnen, einander zu verstehen.\""}
MultiLanguageItemData['de'][192758] = {name = "Rolle mit schwerem Seil", additional_info = "Questgegenstand\n[q]\"Schwer für die Drachkin. Ihr könntet mit einer einzigen Rolle vermutlich ganze Felsbrocken abschleppen.\""}
MultiLanguageItemData['de'][192759] = {name = "Magmagebundener Speer", additional_info = "Questgegenstand\n[q]\"Auf den Gegner richten und fest zustoßen.\""}
MultiLanguageItemData['de'][192761] = {name = "[q4]Gezähmte Flatterlibelle", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 25 bei der Drachenschuppenexpedition.\n\n\n[q]\"Es dauerte nicht lang, bis Opa Schnurrbart die Flatterlibellen um das Drachenschuppenbasislager gezähmt und dazu gebracht hatte, Personal und Fracht der Expedition zu transportieren.\"\nFraktion:\nDrachenschuppenexpedition\nRuhmstufe:\n25\nVerkäufer:\nOpa Schnurrbart\nOrt:\nDrachenschuppenbasislager"}
MultiLanguageItemData['de'][192762] = {name = "[q4]Azurflatterlibelle", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 25 bei der Drachenschuppenexpedition.\n\n\n[q]\"Nachdem Opa Schnurrbart ihnen endlich beigebracht hatte, jemanden zu tragen, haben die Azurflatterlibellen sich als äußerst loyal ihren Reitern gegenüber erwiesen, mit denen sie eine enge Bindung eingehen.\"\nFraktion:\nDrachenschuppenexpedition\nRuhmstufe:\n25\nVerkäufer:\nOpa Schnurrbart\nOrt:\nDrachenschuppenbasislager\nKosten:\n5\n20\n750"}
MultiLanguageItemData['de'][192764] = {name = "[q4]Tiefgrüne Flatterlibelle", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Tiefgrüne Flatterlibellen sind die perfekten Reittiere für die Späher der Drachenschuppenexpedition, da sie schnell sind und mit dem Blätterdach der Dracheninseln verschmelzen.\"\nFraktion:\nDrachenschuppenexpedition\nRuhmstufe:\n25\nSchatz:\nExpeditionsspäherpack"}
MultiLanguageItemData['de'][192765] = {name = "[q4]Überlassener Sandhuscher", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese unberechenbaren Flatterlibellen waren ein Geschenk von Opa Schnurrbart und helfen den Zeitwanderern, die gegenwärtigen (und zukünftigen) sandbezogenen Zeitkatastrophen aufzuräumen.\"\nErfolg:\nSperrstunde\nKategorie:\nErkundung"}
MultiLanguageItemData['de'][192766] = {name = "[q4]Bernsteingelbe Flatterlibelle", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Geschenk von Opa Schnurrbart an den Handelsposten. Bernsteingelbe Flatterlibellen sind erstaunlich zahm.\"\nHandelsposten"}
