MultiLanguageItemData['de'][192772] = {name = "[q4]Uralter Salamanther", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Aufgrund ihrer Vorliebe für dunkle Höhlen und trübe Gewässer wird diese einzigartige Spezies der Salamanther so selten gesehen, dass viele Forscher dachten, sie sei ausgestorben.\"\nBeute von:\nVerbotene Insel"}
MultiLanguageItemData['de'][192774] = {name = "[q4]Korallenschuppensalamanther", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als Raszageths Stürme sich legten, war diese Art aquatischer Salamanther eines der vielen Wunder, die sich an den Küsten in ihrer Spur ansiedelten.\"\nErfolg:\nIn den Sturm\nKategorie:\nErkundung"}
MultiLanguageItemData['de'][192775] = {name = "[q4]Sturmbalgsalamanther", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wenn Sturmenergie eine Kreatur erfüllt, wird sie manchmal einfach... größer und gelassener. Nur wenige Salamanther lassen sich reiten, doch diese Kinder des Sturms sind eine bemerkenswerte Ausnahme.\"\nVerkäufer:\nMythressa\nKosten:\n2.000"}
MultiLanguageItemData['de'][192776] = {name = "Inaktiver Glutkegel", additional_info = "Questgegenstand\n[q]\"Dieser Samen fühlt sich warm an und enthält genug Energie, um in schwindelnde Höhen zu wachsen.\""}
MultiLanguageItemData['de'][192777] = {name = "[q4]Magmahäuschen", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Na, wer ist denn hier eine neue ganz aus Elementarlava geschmiedete Schnecke? Das bist ganz allein du! Ja!\"\nGegenstand:\nLeerer Magmapanzer\nZone:\nKüste des Erwachens"}
MultiLanguageItemData['de'][192779] = {name = "[q4]Brodelnde Schnecke", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Durch die Wut der Zaqali aus ihrem Abgrund hervorgerissen.\"\nSchatz:\nBrodelnde Truhe\nZone:\nZaralekhöhle"}
MultiLanguageItemData['de'][192783] = {name = "Frontkämpferbefehle der Nokhud", additional_info = "Questgegenstand\n[q]\"Vom Leichnam einer Assassine der Nokhud genommen.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][192784] = {name = "[q4]Panzerklatscher", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die von Siegen genährte und von Ruhm gestählte Schnecke repräsentiert die Huldigung der Meisterschaft.\"\nErfolg:\nRuhm des Helden von Dragonflight"}
MultiLanguageItemData['de'][192785] = {name = "[q4]Schleimiger Schneckelementar", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses magische Weichtier ist aus der übrig gebliebenen Elementarenergie der Urstürme geformt und schneller als erwartet.\"\nBeute von:\nVerbotene Insel"}
MultiLanguageItemData['de'][192786] = {name = "[q4]Schneckenhaus einer schlummernden Weltenschnecke", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Für die Weltenbrecher ist es ein tragbarer Schemel, für Euch ist es ein widerstandsfähiges Reittier.\"\nVerkäufer:\nHändlerin Vexil\nZone:\nKüste des Erwachens\nKosten:\n1.000"}
MultiLanguageItemData['de'][192788] = {name = "[q4]Überlassenes Fischermammut", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Geschenk von Späherin Tomul, damit die Festmahle von Iskaara immer genug Fisch zur Verfügung haben mögen, um die Bedürftigen zu nähren.\"\nErfolg:\nArmee der Genährten\nKategorie:\nErkundung"}
MultiLanguageItemData['de'][192790] = {name = "[q4]Moosmammut", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses Mammut wurde über Tausende von Jahren in Stein konserviert und durch Bronzemagie beinahe zurück in ein Fossil gealtert.\"\nBeute von:\nGewölbe von Zskera"}
MultiLanguageItemData['de'][192791] = {name = "[q4]Ebenenschreiterträger", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Mammuts der Ebenen von Ohn'ahra sind es nicht gewohnt, jemanden zu tragen, da ihre Nachbarn, die Zentauren, üblicherweise nicht reiten. Doch sie können lernen, Reiter zu tragen. Manche tun es sogar sehr gerne.\"\nWeltereignis:\nZentaurenjagd (erste Jagd jeder Woche)"}
MultiLanguageItemData['de'][192792] = {name = "[q4]Überlassenes Leittier der Donnerrückgrate", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Geschenk von Merithra, die diese Donnerrückgrate gesegnet hat, damit sie stets unter dem Schutz des grünen Drachenschwarms stehen, egal, wohin es die Klans der Maruuk treibt.\"\nErfolg:\nZentaur der Aufmerksamkeit\nKategorie:\nErkundung"}
