MultiLanguageItemData['de'][194021] = {name = "[q2]Verziertes Pergament: Untere Hälfte", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n[q]\"Die linke Seite der Karte ist absolut unleserlich, bedeckt von einem dunklen Fleck, als ob jemand seine tintenverschmierte Hand absichtlich über den Bereich gezogen hat, um etwas zu verdecken.\""}
MultiLanguageItemData['de'][194022] = {name = "[q2]Verziertes Pergament: Obere Hälfte", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n[q]\"Weitreichende Gewässer bedecken den oberen Bereich des Pergaments mit verschiedenen Vulkanabbildungen und sich hindurchschlängelnden Flüssen.\""}
MultiLanguageItemData['de'][194023] = {name = "[q3]Schatzkarte: Die Küste des Erwachens", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zeichnet auf der Karte der Küste des Erwachens die Positionen mehrerer Schätze ein.\n[q]\"Der dunkle Fleck im unteren linken Bereich der Karte verbleibt. Was immer sich auch in dieser Gegend befindet, soll sicherlich nicht gefunden werden.\""}
MultiLanguageItemData['de'][194024] = {name = "[q2]Runengebundenes Pergament: Obere Hälfte", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n[q]\"Sich schlängelnde Flüsse, gekennzeichnet mit großen, kopfförmigen Symbolen, sind über das Pergament verteilt.\""}
MultiLanguageItemData['de'][194025] = {name = "[q2]Runengebundenes Pergament: Untere Hälfte", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n[q]\"Der Text unter der Karte ist größtenteils verblasst und nicht erkennbar. Eine große von Energie umwirbelte Säule erscheint in der unteren linken Ecke des Pergaments.\""}
MultiLanguageItemData['de'][194026] = {name = "[q3]Schatzkarte: Das Azurblaue Gebirge", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zeichnet auf der Karte des Azurblauen Gebirges die Positionen mehrerer Schätze ein.\n[q]\"Sich schlängelnde Flüsse bedecken die Karte. Mehrere kopfförmige Symbole erscheinen an verschiedenen Orten. Eine überaus große von Energie umwirbelte Säule steht alleine im Südwesten.\""}
MultiLanguageItemData['de'][194027] = {name = "[q2]Uraltes Pergament: Obere Hälfte", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n[q]\"Die obere linke Ecke ist vom Abdruck einer Scheibe gekennzeichnet. In der Mitte der Karte befindet sich ein großes, tempelähnliches Gebäude.\""}
MultiLanguageItemData['de'][194028] = {name = "[q2]Uraltes Pergament: Untere Hälfte", additional_info = "Wird beim Anlegen gebunden\nEinzigartig\n[q2]Benutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n[q]\"Die Tinte auf der Karte scheint sich zu bewegen, als schwarze Wirbel langsam durch eine Bergregion ziehen.\""}
MultiLanguageItemData['de'][194029] = {name = "[q3]Schatzkarte: Thaldraszus", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zeichnet auf der Karte von Thaldraszus die Positionen mehrerer Schätze ein.\n[q]\"Die herumwirbelnde Tinte verfestigt sich und eine große Fläche manifestiert sich mit einem großen, tempelähnlichen Gebäude in der Mitte, umringt von mehreren Gebäuden. In der oberen linken Ecke ist eine Scheibe mit geometrischen Formen zu sehen.\""}
