MultiLanguageItemData['de'][194296] = {name = "[q3]Muster: Mit Drakoniumstoffschere spielen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man mit einer Drakoniumstoffschere spielt.\n[q2]Da Ihr Euer Handwerk gemeistert habt, stimuliert es vielleicht Euren Geist, wenn Ihr an Eurem Werkzeug herumtüftelt? Die einzige Garantie, die es dabei gibt, ist allerdings seine Zerstörung.\nBenötigt Schneiderei der Dracheninseln (50)\nVerkaufspreis:\nMit Drakoniumstoffschere spielen\n[q]\"Was würde passieren, wenn dort Druck ausgeübt würde, während man hier zieht?\"\nBenötigt Federgetriebene Drakoniumstoffschere , Drakoniumnadelsatz"}
MultiLanguageItemData['de'][194297] = {name = "[q3]Muster: Mit Khaz'goritstoffschere spielen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man mit einer Khaz'goritstoffschere spielt.\n[q2]Da Ihr Euer Handwerk gemeistert habt, stimuliert es vielleicht Euren Geist, wenn Ihr an Eurem Werkzeug herumtüftelt? Die einzige Garantie, die es dabei gibt, ist allerdings seine Zerstörung.\nBenötigt Schneiderei der Dracheninseln (50)\nVerkaufspreis:\nMit Khaz'goritstoffschere spielen\n[q]\"Was würde passieren, wenn dort Druck ausgeübt würde, während man hier zieht?\"\nBenötigt Federgetriebene Khaz'goritstoffschere , Drakoniumnadelsatz"}
MultiLanguageItemData['de'][194298] = {name = "[q3]Muster: Tristes Sargtuch", additional_info = "[q2]Benutzen: Lehrt Euch, wie man ein tristes Sargtuch herstellt.\nBenötigt Schneiderei der Dracheninseln (45)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194299] = {name = "[q4]Flammendekoration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Stampft auf den Boden und lasst Flammen von Eurer Position ausstrahlen. Diese verursachen 30948 Feuerschaden, der auf alle getroffenen Gegner aufgeteilt wird, und gewähren Euch für 30 Sek. einen Schild in Höhe von 57788 . Nach einer Verzögerung kehren die Flammen zurück, verursachen den gleichen Schaden erneut und frischen den Schild auf.\n\n Schaden und Absorption werden für jeden getroffenen Gegner bis maximal 5 Gegner erhöht. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194300] = {name = "[q4]Herbeigezauberte Frostkugel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 Intelligenz\n[q2]Benutzen: Wenn Euer Mana über 65% ist, wird die Frostkugel auf Euer Ziel geworfen und verursacht 55707 Frostschaden.\n\n Wenn Euer Mana unter 65% ist, trinkt Ihr stattdessen von der Frostkugel, um sofort 4523 Mana wiederherzustellen. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194301] = {name = "[q4]Flüsterndes Symbol der Inkarnation", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Gebt Euch dem Flüstern des Symbols hin und werdet mit Frost erfüllt, was Euren kritischen Trefferwert um 478 erhöht.\n\n Wenn Ihr an der Seite von Verbündeten kämpft, die mit Erde oder Feuer erfüllt sind, besteht eine Chance, dass Ihr 12 Sek. lang 131 des Werts ihrer jeweiligen Infusion erhaltet.\n\n Die Infusion ist von Eurer aktuellen Spezialisierung abhängig. (1.5s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194302] = {name = "[q4]Segen der Sturmfresserin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Nehmt den Sturm an und werdet für 10 Sek. zu einem unbeweglichen Urluftelementar.\n\n In dieser Gestalt fügen die Winde um Euch allen Gegnern innerhalb von 10 Metern pro Sekunde 6309 Naturschaden zu, der sich pro Sekunde um 10% erhöht, bis die Verwandlung endet. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194303] = {name = "[q4]Rasselnder Rubin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 Stärke\n[q2]Anlegen: Eure Angriffe bauen langsam Stapel von 'Erschütternde Kraft' auf, die Euch pro Stapel 21 Angriffskraft gewähren.\n\n Bei 10 Stapeln entfesseln Eure nächsten 3 Nahkampffähigkeiten eine Schockwelle vor Euch, die allen Gegnern in einer Linie zusätzlich 16542 Naturschaden zufügt. Die Schockwellen fügen Gegnern mit hoher Gesundheit mehr Schaden zu. (500ms Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194304] = {name = "[q4]Eisbluttodesfessel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 Intelligenz\n[q2]Benutzen: Fügt Eurem Ziel 40232 Frostschaden zu und wickelt es sowie Gegner in der Nähe für 15 Sek. in ein Kristallnetz. Im Netz gefangene Gegner sind um 15% verlangsamt und erleiden 3185 Frostschaden, wenn ein Gegner im Netz getroffen wird.\n\n Der Schaden erhöht sich für jeden im Netz gefangenen Gegner, bis zu 5 Gegner. Der Schaden pro Ziel ist bei mehr als 5 Gegnern verringert. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194305] = {name = "[q4]Kontrollierte Strömungstechnik", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 Beweglichkeit\n[q2]Anlegen: Eure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\n Bei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 6470 Naturschaden zu.\n\n Wenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen. (1.5s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194306] = {name = "[q4]Alltotem des Meisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\n Dieser Effekt kann nur einmal alle 30 Sek. auftreten. (30s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194307] = {name = "[q4]Versprechen der Bruthüterin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\n[q2]Benutzen: Wählt einen Spielercharakter aus, mit dem Ihr eine Bindung eingehen möchtet, und werdet für 1 Stunde zu seinem Wächter.\n\n Während Ihr verbunden seid, erhaltet Ihr und Euer Verbündeter [ 94 * (0.8)] Vielseitigkeit und stellt pro Sekunde [ 964 * (0.6)] Gesundheit wieder her. Solange Ihr Euch innerhalb von 15 Metern zueinander aufhaltet, werden diese Boni erhöht.\n\nGilt nur für Heilerspezialisierungen. (5 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194308] = {name = "[q4]Manische Trauerfackel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Kanalisiert für 2 Sek. und entfesselt eine wilde Salve aus Flammen um Euer Ziel herum, die ihm bis zu [ 20285 * (8) * (1 + Vielseitigkeit)] Feuerschaden zufügt und eine Chance hat, zusätzlich Gegnern in der Nähe Schaden zuzufügen.\n\n Durch den Tod eines verbündeten Spielercharakters wird die Abklingzeit um 90 Sek. verringert. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194309] = {name = "[q4]Boshafter Sturm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Der Einsatz von Zaubern und Fähigkeiten erzeugt Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [ 1828 * (6) * (1 + Vielseitigkeit)] Naturschaden.\n\n Bei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' zugefügten Schaden permanent, bis einer von Euch stirbt. (1s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][194310] = {name = "[q4]Kodex des verzweifelten Herbeirufers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\n[q2]Anlegen: Das Wirken von Zaubern gewährt Stapel von Hass, durch die die Abklingzeit dieses Schmuckstücks bis zum Ende des Kampfes um 1 Sek. verringert wird. Dieser Effekt ist bis zu 180-mal stapelbar. (1s Abklingzeit)\n[q2]Benutzen: Entfesselt gefährliche Blitze und fügt Eurem Ziel 125328 Naturschaden und Euch 665 Naturschaden zu. Der Euch selbst zugefügte Schaden wird durch Stapel von Hass erhöht. (4 Min Abklingzeit)\nVerkaufspreis:"}
