MultiLanguageItemData['de'][194511] = {name = "[q2]Lebende Verpflegung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig"}
MultiLanguageItemData['de'][194512] = {name = "Defektes arkanes Gerät", additional_info = "Questgegenstand\n[q]\"Etwas arkane Magie sprüht immer noch aus diesem Teil des Geräts.\""}
MultiLanguageItemData['de'][194513] = {name = "Foliantensammlung", additional_info = "Questgegenstand\n[q]\"Diese Folianten schildern detailliert, wie des Lager Antonidas vor 10.000 Jahren war.\""}
MultiLanguageItemData['de'][194514] = {name = "Antiquierte Gästeliste", additional_info = "Questgegenstand\n[q]\"In diesem alten Folianten stehen die Namen von Drachen, die diese Gegend besucht haben. Zwei Namen sind auf fast jeder Seite: Malygos und Sindragosa.\""}
MultiLanguageItemData['de'][194515] = {name = "Zerbröckelnder Ereigniskalender", additional_info = "Questgegenstand\n[q]\"Dieses Buch schildert detailliert verschiedene Ereignisse, die in dieser Gegend stattgefunden haben. Alle schienen mit Zurschaustellungen von Arkana für andere Drachenschwärme und Aspekte einherzugehen.\""}
MultiLanguageItemData['de'][194516] = {name = "Gealtertes Tagebuch", additional_info = "Questgegenstand\n[q]\"Auf diesen Seiten finden sich Details über die Balz zweier blauer Drachen, Malygos und Sindragosa. Eine Anmerkung deutet darauf hin, dass es \"Teil eins einer Serie\" sei.\""}
MultiLanguageItemData['de'][194517] = {name = "Bruchstückhafte Texte", additional_info = "Questgegenstand\n[q]\"Dieses Buch schildert detailliert die Drakoniden und Drachenbrut, die sich um diese Gegend gekümmert haben, nachdem die blauen Drachen verschwunden sind. Auf vielen Seiten wird beklagt, dass auch die \"Freude\" mit dem Weggang von Sindragosa und Malygos verloren ging.\""}
MultiLanguageItemData['de'][194519] = {name = "Osorias Unterstützung", additional_info = "Questgegenstand\n[q2]Benutzen: Ruft Osoria, um Euch in die Lüfte zu tragen und Gegner anzugreifen. Nur in der Obsidianzitadelle. (5 Sek. Abklingzeit)\n70 ( 70)"}
MultiLanguageItemData['de'][194520] = {name = "Schriftrolle des Wissens der Zeitwanderer", additional_info = "Questgegenstand\n[q]\"Die Schriftrolle beinhaltet eine Fülle an Wissen über Zeitmagie. Ihr spürt, wie sie Eure Gedanken verzerrt, wenn Ihr das Pergament zu lange anstarrt.\""}
MultiLanguageItemData['de'][194521] = {name = "[q4]Klippenwilddrache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Klippenwilddrachen oder gibt ihn wieder frei.\n\n Bei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Sie nisten häufig an den steilen Klippen von Thaldraszus und steigen bei Gefahr schnell in den Himmel auf.\"\nErfolg:\nDracheninseln: Klippenwilddrache"}
