MultiLanguageItemData['de'][198073] = {name = "Karha, der stille Wind", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Karha war der Stab von Ganmat dem Weisen, einem alten Windweisen von Ohn'ahra, der vor Jahrhunderten unzählige Verbündete heilte und noch mehr Gegner besiegte.\""}
MultiLanguageItemData['de'][198074] = {name = "Josanak der sichere Sieg", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Josanak gehörte dem unbezwungenen Krieger Zaphil. Zaphil konnte sich stets auf seine Hellebarde verlassen, so wie auch sein Klan sich stets auf ihn verlassen konnte.\""}
MultiLanguageItemData['de'][198075] = {name = "Tsegzaya der Dornenbogen", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Als Dihar noch den Bogen gespannt hat, haben unzählige Pfeile von Tsegzaya ihr Ziel gefunden, egal, ob es sich dabei um Wildtiere oder die Feinde des Klans Teerai gehandelt hat.\""}
MultiLanguageItemData['de'][198076] = {name = "[q2]Ungeziefervernebler", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft einen Ungeziefervernebler, der eine giftige Explosion auslöst, die allen Gegnern innerhalb von 6 Metern 15 Naturschaden zufügt, sie zurückstößt und ihre Bewegungsgeschwindigkeit für 8 Sek. um 30% verringert.\n\n Der Rückstoßeffekt ist bei gegnerischen Spielercharakteren wirksamer."}
MultiLanguageItemData['de'][198078] = {name = "Rekrutierungsliste", additional_info = "Questgegenstand\n70 ( 70)\n[q]\"Seiten voller Rekrutierungsstrategien und Anweisungen, um ein Artefakt in den Ruinen von Nelthazan zu finden.\""}
MultiLanguageItemData['de'][198079] = {name = "Befehle von Sarkareth", additional_info = "Questgegenstand\n70 ( 70)\n[q]\"Die Aspekte tragen ihre Schuld als Komplizen bei den Verbrechen des Zerstörers. Findet Beweise für ihr Vorhaben, uns zu kontrollieren. Erhebt Eure Stimme! Widersteht! - Schuppenkommandant Sarkareth\""}
MultiLanguageItemData['de'][198080] = {name = "[q3]Siegel der Stürme", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Mit den nicht entzifferbaren Inschriften und seiner schwankenden Temperatur ist dieses Siegel ein höchst interessanter Fund.\""}
MultiLanguageItemData['de'][198081] = {name = "[q2]Amulett des Pflegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\n[q2]Benutzen: Wacht aufmerksam über das Ziel, was eine hohe Chance gewährt, dieses um 1847 Gesundheit zu heilen, wenn es in den nächsten 30 Sek. Heilung erhält. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198082] = {name = "Vorbewusste Felsgruppe", additional_info = "[q]\"Nur ein Hauch von elementarem Bewusstsein verbleibt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][198083] = {name = "[q3]Expeditionsversorgungspaket", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\n[q2]Benutzen: Greift auf Euer Expeditionsversorgungspaket zu. Benutzt Vorräte der Dracheninseln, um Eure Erkundungs-, Kletter- und Katalogisierungsfähigkeiten aufzuwerten.\nBenötigt Ruhmrang 6 bei der Drachenschuppenexpedition.\n[q]\"Ihr habt dieses Paket erhalten, weil Ihr Euch bei der Drachenschuppenexpedition Ruhm verdient habt.\""}
MultiLanguageItemData['de'][198085] = {name = "[q3]Schlüssel der verlorenen Obsidiantruhe", additional_info = "Wird beim Aufheben gebunden\n[q]\"Der Schlüssel zur verlorenen Obsidiantruhe.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][198086] = {name = "[q4]Dunkelmondkartenset: Inferno", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Schleudert ein schwelendes Inferno auf das Ziel, das ( 78083 * .3)- 78083 Feuerschaden verursacht. Der Schaden wird von der obenliegenden Karte des Kartensets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198087] = {name = "[q4]Dunkelmondkartenset: Raureif", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Fügt Eurem Ziel 15897 Frostschaden zu und belegt es für 4-12 Sek. mit 'Erwachender Raureif'. Stirbt das Ziel, solange 'Erwachender Raureif' aktiv ist, explodiert es und verursacht 39743 Frostschaden, der auf Gegner innerhalb eines Radius von 10 Metern aufgeteilt wird. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198088] = {name = "[q4]Dunkelmondkartenset: Tanz", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Ein 'Erfrischender Tanz' springt 6-13-mal zwischen Freunden und Gegnern innerhalb von 25 Metern hin und her und verursacht 9545 Naturschaden oder heilt um 5200 Gesundheit. Die Anzahl der Sprünge wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198089] = {name = "[q4]Dunkelmondkartenset: Behüter", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Gewährt 5-12 Sek. lang den 'Segen des Behüters' und einen Absorptionsschild in Höhe von 62801 Schaden.\n Wenn der Schild verbraucht wird, während 'Segen des Behüters' aktiv ist, wird für dieselbe Dauer 1469 Vielseitigkeit gewährt. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
