MultiLanguageItemData['de'][198452] = {name = "Prototyp V", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 4 std.\n[q2]Benutzen: Rüstet Prototyp V aus.\n\n Kann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden.\n[q]\"Eine der zahlreichen experimentellen Waffen, die nie über das Prototypstadium hinauskamen.\"\nVerkaufspreis:"}
