MultiLanguageItemData['de'][198474] = {name = "[q3]Staffelei des Künstlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Lasst Euch inspirieren. (30 Sek. Abklingzeit)\n[q]\"Nicht jeder hat das Zeug zum großen Künstler, aber jede Region hat das Potenzial solche hervorzubringen.\""}
MultiLanguageItemData['de'][198475] = {name = "[q3]Abgebrochene Leiste", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Ein Stück einer Goldleiste, das von einer deutlich größeren Statue abgebrochen ist.\""}
MultiLanguageItemData['de'][198476] = {name = "Gemälde der Vorstellung", additional_info = "Questgegenstand\n[q]\"Die groben Striche zeigen die Azurarchive aus der Ferne, eingehüllt in dichten Schnee. Das Werk strahlt eine gewisse Wehmut aus.\""}
MultiLanguageItemData['de'][198477] = {name = "[q4]Dunkelmondkartensetschachtel: Raureif", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Fügt Eurem Ziel 10372 Frostschaden zu und belegt es für 4-12 Sek. mit 'Erwachender Raureif'. Stirbt das Ziel, solange 'Erwachender Raureif' aktiv ist, explodiert es und verursacht 25929 Frostschaden, der auf Gegner innerhalb eines Radius von 10 Metern aufgeteilt wird. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198478] = {name = "[q4]Dunkelmondkartensetschachtel: Tanz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Ein 'Erfrischender Tanz' springt 6-13-mal zwischen Freunden und Gegnern innerhalb von 25 Metern hin und her und verursacht 6228 Naturschaden oder heilt um 4133 Gesundheit. Die Anzahl der Sprünge wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198479] = {name = "Böenreiter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fliegt mit dem Gleiter und verringert 2 Min. lang Eure Fallgeschwindigkeit. Nur in Kul Tiras verwendbar. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198480] = {name = "Die prachtvollen Becken", additional_info = "Questgegenstand\n[q]\"Dieses halbfertige Gemälde der Lebensbecken wird von einer fein abgestimmten Farbpalette aus Rosa, Rubinrot und sattem Grün dominiert.\""}
MultiLanguageItemData['de'][198481] = {name = "[q4]Dunkelmondkartensetschachtel: Behüter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\n[q2]Benutzen: Benutzen: Gewährt 5-12 Sek. lang den 'Segen des Behüters' und einen Absorptionsschild in Höhe von 51162 Schaden.\n Wenn der Schild verbraucht wird, während 'Segen des Behüters' aktiv ist, wird für dieselbe Dauer 1230 Vielseitigkeit gewährt. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198482] = {name = "Die Spirale der Kurgane", additional_info = "Questgegenstand\n[q]\"In diesem Gemälde der Ebenen von Ohn'ahra schmiegen sich gewundene Spiralmuster um sanfte grüne Hügel. Weiße Windböen neigen derweil die Bäume zur Seite.\""}
MultiLanguageItemData['de'][198484] = {name = "Der Verfall von Brackenfell", additional_info = "Questgegenstand\n[q]\"Das Gemälde zeigt einen verrottenden Wald, bedeckt von dichtem grünen Nebel. Selbst die Leinwand riecht faulig.\""}
MultiLanguageItemData['de'][198485] = {name = "[q0]Zurückgelassene Schriftrolle", additional_info = "Einzigartig\n[q]\"Auf Drakonisch geschrieben. Das hat wohl jemand fallen lassen.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][198486] = {name = "Windschuppenreiter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Fliegt mit dem Gleiter und verringert 2 Min. lang Eure Fallgeschwindigkeit. Nur auf den Dracheninseln verwendbar. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][198487] = {name = "Schillerndes Wasser", additional_info = "Handwerksmaterial\n[q]\"Eine leichte, blubbernde Flüssigkeit, die oft von Inschriftenkundigen verwendet wird. Kann von Händlern gekauft werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][198488] = {name = "[q2]Stab der Entdeckung", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n33 - 46 Schaden Geschwindigkeit 3.60\n(11.0 Schaden pro Sekunde)\n+130 Intelligenz\n+44 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 28.\n[q2]+ 30 Vielseitigkeit\nHaltbarkeit 85 / 85\nVerkaufspreis:"}
MultiLanguageItemData['de'][198489] = {name = "[q2]Traumlandschaftprisma", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\n[q2]Anlegen: Eure Heilzauber haben eine Chance, Euch in einen Wachtraum zu versetzen, was Euch erhöhte Manaregeneration gewährt und Eure Meisterschaft um 1402 erhöht. Hält 20 Sek. lang an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][198490] = {name = "[q2]Kompass des Buschräubers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Angriffe haben eine Chance, den Kompass eine Richtung anzeigen zu lassen, was Euren kritischen Trefferwert, Euer Tempo, Eure Meisterschaft oder Eure Vielseitigkeit 12 Sek. lang um 2043 erhöht.\n[q]\"Forscherveteranen wissen, dass ein Kompass der beste Weg ist, aus einer brenzligen Lage zu entkommen (oder in eine hineinzugeraten).\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][198510] = {name = "[q3]Drakonische Ingenieurskunstabhandlung", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Enthält Notizen über verschiedene Berufsgeheimnisse von Ingenieuren. Kann nur einmal pro Woche gelesen werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][198511] = {name = "Baumaterialien", additional_info = "Questgegenstand\n[q]\"Die zerbröckelten Überreste eines Erdelementars. Das als Baumaterialien zu bezeichnen, ist schon sehr großzügig.\""}
MultiLanguageItemData['de'][198512] = {name = "Die großen Hallen", additional_info = "Questgegenstand\n[q]\"Kaum mehr als eine Skizze. Hohe Säulen und helle Lichter schmücken dieses halbfertige Gemälde der Hallen der Infusion.\""}
MultiLanguageItemData['de'][198513] = {name = "Die Akademie", additional_info = "Questgegenstand\n[q]\"In diesem Gemälde der Akademie von Algeth'ar spielen Drakoniden unter farbenprächtigen Drachenschwarmbannern, welche an einer gewaltigen Mauer hängen.\""}
MultiLanguageItemData['de'][198514] = {name = "Das versiegelte Gewölbe", additional_info = "Questgegenstand\n[q]\"Große blaue und lila Spritzer stellen Explosionen arkaner Magie in diesem Gemälde des Azurblauen Gewölbes dar.\""}
MultiLanguageItemData['de'][198515] = {name = "Die Feuerlabore", additional_info = "Questgegenstand\n[q]\"Dieses Gemälde von Neltharus ist kaum mehr als eine vage Ansammlung roter, orangener und schwarzer Kleckse.\""}
MultiLanguageItemData['de'][198516] = {name = "Hudsons finale Zeichnung", additional_info = "Questgegenstand\n[q]\"Eine unvollendete Zeichnung von Hudson und Ranpiata. Ihre Köpfe sind eng beieinander, während sie lächeln.\""}
MultiLanguageItemData['de'][198517] = {name = "Pelz von Konkhular", additional_info = "Questgegenstand\n[q]\"Die Farbe dieses Pelzes fügt sich gut in die Felsen und die Erde in der Umgebung.\""}
MultiLanguageItemData['de'][198518] = {name = "[q3]Professor Dozentaurs streng geheimer Leitfaden für die Welt der Schmiedekunst", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt 1000 Spezialisierungspunkte für die Schmiedekunst der Dracheninseln.\nBenötigt Schmiedekunst der Dracheninseln (15)\n[q]\"Ihr fühlt Euch wie ein mieser Betrüger, während Ihr dieses Buch in der Hand haltet, aber es spricht sicher nichts dagegen, kurz einen Blick hineinzuwerfen.\""}
