MultiLanguageItemData['de'][198529] = {name = "[q2]Eiserne Fackel des Wanderers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass die Fackel Euch in Licht hüllt und Euch um 22705 Gesundheit heilt. Die Heilung der Fackel ist umso stärker, je niedriger Eure Gesundheit ist.\nVerkaufspreis:"}
MultiLanguageItemData['de'][198530] = {name = "Rohe Zandalichilis", additional_info = "Questgegenstand\n[q2]Benutzen: Werft dies auf die Kochfeuerstelle im Drachenschuppenbasislager, um gegrillte Zandalichilis herzustellen. (3 Sek. Abklingzeit)\n70 ( 70)\n[q]\"Ungekocht hart und unangenehm scharf.\""}
MultiLanguageItemData['de'][198532] = {name = "[q2]Die Messschieber des Kartografen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\n[q2]Anlegen: Eure Zauber haben eine Chance, einem der Ziele mit der niedrigsten Gesundheit innerhalb von 10 Metern 7802 Schaden zuzufügen oder das Ziel um 11717 Gesundheit zu heilen, je nachdem, welchen Zauber Ihr wirkt.\n[q]\"Es gibt eine Sache, die einen Meister vom Rest der Kartografen abhebt: Präzision.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][198533] = {name = "[q3]Rezept: Luftgetränkte Phiole der schnellen Hände", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man eine luftgetränkte Phiole der schnellen Hände herstellt.\nBenötigtAlchemie der Dracheninseln\n(10)\nBenötigt die Rufstufe \"Respektiert\" beim Handwerkerkonsortium.\nVerkaufspreis:"}
MultiLanguageItemData['de'][198537] = {name = "[q3]Taivans Trompete", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört Taivan an Eure Seite. Taivan erhöht die Vielseitigkeit aller in der Nähe um 1 . (5 Min Abklingzeit)\n[q]\"Taivan liebt den Klang dieser aus Riesenwildschafhorn gefertigten Trompete.\""}
MultiLanguageItemData['de'][198538] = {name = "[q3]Magisch gebundene Nachricht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Ein hypnotisierender, violetter Staub strömt langsam aus dem mysteriösen Pergament und zerstreut sich nach einem flüchtigen Moment.\""}
