MultiLanguageItemData['de'][198852] = {name = "[q2]Bärentötungsbefehle", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zeichnet auf Eurer Karte die Position eines Schatzes in Thaldraszus ein.\n[q]\"Die Bernsteine, nach denen wir gesucht haben, wurden in einer Höhle entdeckt. Leider scheint dies die Höhle eines ziemlich übellaunigen Bären zu sein. Erlegt ihn, damit wir endlich zu den Edelsteinen gelangen können.\""}
MultiLanguageItemData['de'][198854] = {name = "[q2]Artefaktaufzeichnungen des Archäologen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Zeichnet auf Eurer Karte die Position eines Schatzes an der Küste des Erwachens ein.\n[q]\"Detaillierte Forschungsergebnisse, die auf einen möglichen Schatz nahe der Botschaft von Schwingenrast hinweisen.\""}
MultiLanguageItemData['de'][198855] = {name = "Wurfnetz", additional_info = "Questgegenstand\n[q2]Benutzen: Auf Fischvorräte innerhalb von 15 Metern werfen. (5 Sek. Abklingzeit)\n[q]\"Dieses Netz kann zum Fangen vieler Fische und zum Auffüllen des Angellochs benutzt werden.\""}
